'@

$script:PillTones = @{
    ok   = @('#15291F', '#5EE3AE')
    warn = @('#2E2616', '#FFC46B')
    crit = @('#2E1A1E', '#FF7A86')
    info = @('#1A2640', '#8CC0FF')
}

function New-ModuleView {
    # Tworzy wizualną część modułu i podłącza zdarzenia tabeli
    param([Parameter(Mandatory)][hashtable]$Module)
    $root = New-UiElement $script:ModuleViewXaml
    $Module.Root = $root
    foreach ($n in 'paramsCard', 'paramsStack', 'statsGrid', 'busyChip', 'busyText', 'countText', 'btnFilters', 'resultHint', 'filterBox', 'chkReveal',
        'btnDetail', 'btnCopy', 'btnExport', 'grid', 'emptyState', 'emptyIcon', 'emptyText', 'emptyHint', 'detailCol', 'detailSplit',
        'detailPane', 'detailText', 'btnDetailCopy', 'btnCollapse', 'btnStopOp') {
        $Module.View_[$n] = $root.FindName($n)
    }
    $Module.ParamsCard = $Module.View_['paramsCard']
    $Module.ParamsStack = $Module.View_['paramsStack']
    $Module.StatsGrid = $Module.View_['statsGrid']
    $Module.Grid = $Module.View_['grid']
    $Module.FilterBox = $Module.View_['filterBox']

    $root.FindName('hdrIcon').Text = Get-Glyph $Module.Icon
    $root.FindName('hdrTitle').Text = $Module.Title
    $root.FindName('hdrCategory').Text = $(if ($Module.WorkspaceTitle) { $Module.WorkspaceTitle + '  •  ' + $Module.Category } else { $Module.Category })
    $desc = $root.FindName('hdrDesc')
    if ($Module.Description) { $desc.Text = $Module.Description } else { $desc.Visibility = 'Collapsed' }

    $v = $Module.View_
    $v.btnDetail.Content = New-IconContent -Text '' -Icon 'E8A1'
    $v.btnCopy.Content = New-IconContent -Text '' -Icon 'E8C8'
    $v.btnExport.Content = New-IconContent -Text 'Eksport' -Icon 'EDE1'
    $v.btnDetailCopy.Content = New-IconContent -Text '' -Icon 'E8C8' -IconSize 11
    $v.btnCollapse.Content = New-IconContent -Text '' -Icon 'E70E' -IconSize 12
    $v.btnCollapse.Visibility = 'Collapsed'
    $v.btnStopOp.Content = New-IconContent -Text 'Przerwij' -Icon 'E71A' -IconSize 10
    Register-ControlHandler -Control $v.btnStopOp -EventName 'Click' -Module $Module -Action { param($m) Stop-ModuleOperations -Module $m }
    Register-ControlHandler -Control $v.btnCollapse -EventName 'Click' -Module $Module -Action {
        param($m)
        $m.ParamsCollapsed = -not $m.ParamsCollapsed
        Update-ParamsCollapse -Module $m
    }

    Register-ControlHandler -Control $v.filterBox -EventName 'TextChanged' -Module $Module -Action { param($m) Request-ResultFilter -Module $m }
    Register-ControlHandler -Control $v.btnCopy -EventName 'Click' -Module $Module -Action { param($m) Copy-ResultView -Module $m }
    Register-ControlHandler -Control $v.btnExport -EventName 'Click' -Module $Module -Action { param($m) Export-ResultView -Module $m }
    Register-ControlHandler -Control $v.btnFilters -EventName 'Click' -Module $Module -Action { param($m) Clear-ColumnFilters -Module $m; Show-Toast 'Wyczyszczono filtry kolumn.' 'info' 2 }
    Register-ControlHandler -Control $v.btnDetail -EventName 'Click' -Module $Module -Action {
        param($m)
        $script:Settings.DetailVisible = -not $script:Settings.DetailVisible
        foreach ($other in $script:UI.Modules.Values) { if ($other.Root) { Update-DetailPane -Module $other } }
    }
    Register-ControlHandler -Control $v.btnDetailCopy -EventName 'Click' -Module $Module -Action {
        param($m)
        $t = $m.View_['detailText'].Text
        if ($t) { Set-ClipboardText $t; Show-Toast 'Skopiowano szczegóły wiersza.' 'ok' }
    }
    Register-ControlHandler -Control $v.chkReveal -EventName 'Checked' -Module $Module -Action { param($m) Set-SecretReveal -Module $m -Reveal $true }
    Register-ControlHandler -Control $v.chkReveal -EventName 'Unchecked' -Module $Module -Action { param($m) Set-SecretReveal -Module $m -Reveal $false }

    $grid = $Module.Grid
    $script:GridModules[$grid] = $Module
    $grid.add_SelectionChanged($script:GridEvents.SelectionChanged)
    $grid.add_MouseDoubleClick($script:GridEvents.MouseDoubleClick)
    $grid.add_ContextMenuOpening($script:GridEvents.ContextMenuOpening)
    $grid.ContextMenu = New-Object System.Windows.Controls.ContextMenu
    # Ctrl+C w tabeli: własne kopiowanie (nazwy kolumn w nagłówku, maskowanie wartości poufnych, kolejność widocznych kolumn)
    [void]$grid.CommandBindings.Add((New-Object System.Windows.Input.CommandBinding([System.Windows.Input.ApplicationCommands]::Copy, [System.Windows.Input.ExecutedRoutedEventHandler]$script:GridEvents.Copy)))
    Reset-ResultTable -Module $Module
    Update-DetailPane -Module $Module
}

$script:GridModules = New-Object 'System.Collections.Generic.Dictionary[object,hashtable]'
$script:GridEvents = @{
    SelectionChanged   = {
        param($s, $e)
        try {
            $m = $null
            if ($script:GridModules.TryGetValue($s, [ref]$m)) { Update-DetailText -Module $m }
        }
        catch { }
    }
    MouseDoubleClick   = {
        param($s, $e)
        try {
            $m = $null
            if (-not $script:GridModules.TryGetValue($s, [ref]$m)) { return }
            # Tylko podwójne kliknięcie na wierszu (nie na nagłówku ani pasku przewijania)
            $dep = $e.OriginalSource
            while ($dep -and -not ($dep -is [System.Windows.Controls.DataGridRow])) {
                if ($dep -is [System.Windows.Controls.Primitives.DataGridColumnHeader] -or $dep -is [System.Windows.Controls.Primitives.ScrollBar]) { return }
                # Dwuklik w edytowalnej komórce rozpoczyna edycję - bez okna szczegółów
                if ($dep -is [System.Windows.Controls.DataGridCell] -and $dep.Column -and -not $dep.Column.IsReadOnly) { return }
                if ($dep -is [System.Windows.Media.Visual] -or $dep -is [System.Windows.Media.Media3D.Visual3D]) { $dep = [System.Windows.Media.VisualTreeHelper]::GetParent($dep) }
                else { $dep = $null }
            }
            if (-not $dep) { return }
            $drv = $dep.Item
            if (-not ($drv -is [System.Data.DataRowView])) { return }
            if ($m.RowDoubleClick) { Invoke-UiAction -Module $m -Action $m.RowDoubleClick -Source $drv }
            else { Show-RowDetails -Module $m -Row $drv }
        }
        catch { Write-Log "Nie można wyświetlić szczegółów: $($_.Exception.Message)" 'ERROR' }
    }
    Copy               = {
        param($s, $e)
        try {
            $m = $null
            if (-not $script:GridModules.TryGetValue($s, [ref]$m)) { return }
            $e.Handled = $true
            Copy-ResultView -Module $m -SelectedOnly
        }
        catch { Write-Log "Nie można skopiować wierszy: $($_.Exception.Message)" 'ERROR' }
    }
    ContextMenuOpening = {
        param($s, $e)
        try {
            $m = $null
            if (-not $script:GridModules.TryGetValue($s, [ref]$m)) { return }
            # Nagłówek kolumny - menu kolumny; komórka - zapamiętana do szybkiego filtra po wartości
            $m.MenuCell = $null
            $hdr = Find-VisualParent -Element $e.OriginalSource -Type ([System.Windows.Controls.Primitives.DataGridColumnHeader])
            if ($hdr) {
                if (-not $hdr.Column) { $e.Handled = $true; return }
                $m.MenuCell = @{ Column = [string]$hdr.Column.SortMemberPath; Row = $null; Header = $true }
            }
            else {
                $cell = Find-VisualParent -Element $e.OriginalSource -Type ([System.Windows.Controls.DataGridCell])
                if ($cell -and $cell.Column -and $cell.DataContext -is [System.Data.DataRowView]) { $m.MenuCell = @{ Column = [string]$cell.Column.SortMemberPath; Row = $cell.DataContext; Header = $false } }
            }
            Update-GridMenu -Module $m
        }
        catch { }
    }
}

function New-MenuItem {
    param([string]$Text, [string]$Icon = '', [hashtable]$Module, [scriptblock]$Action, [switch]$Danger, [bool]$Enabled = $true)
    $mi = New-Object System.Windows.Controls.MenuItem
    $mi.Header = $Text
    if ($Icon) { $mi.Icon = New-GlyphBlock -Code $Icon -Size 13 -Color $(if ($Danger) { '#FF8A95' } else { '#8791A5' }) }
    if ($Danger) { $mi.Foreground = Get-Brush '#FF8A95' }
    $mi.IsEnabled = $Enabled
    if ($Action) { Register-ControlHandler -Control $mi -EventName 'Click' -Module $Module -Action $Action }
    return $mi
}

function New-MenuSeparator {
    $sep = New-Object System.Windows.Controls.Separator
    $sep.Style = Get-ThemeResource 'MenuSeparator'
    return $sep
}

function Update-GridMenu {
    # Menu kontekstowe budowane przy otwarciu: akcje modułu + kopiowanie/eksport
    param([hashtable]$Module)
    $menu = $Module.Grid.ContextMenu
    foreach ($old in @($menu.Items)) {
        [void]$script:MenuActions.Remove($old)
        [void]$script:Handlers.Remove($old)
    }
    $menu.Items.Clear()
    if ($Module.MenuCell -and $Module.MenuCell.Header) { Update-HeaderMenu -Module $Module -Menu $menu -Column $Module.MenuCell.Column; return }
    $rows = @(Get-SelectedResultRows -Module $Module)
    $hasRows = $rows.Count -gt 0
    foreach ($a in $Module.RowActions) {
        if ($a.Separator -and $menu.Items.Count -gt 0) { [void]$menu.Items.Add((New-MenuSeparator)) }
        $item = New-MenuItem -Text $a.Text -Icon $a.Icon -Module $Module -Danger:$a.Danger -Enabled ($hasRows -and -not $Module.Busy) -Action {
            param($m, $s)
            $entry = $null
            [void]$script:MenuActions.TryGetValue($s, [ref]$entry)
            if (-not $entry) { return }
            $selected = @(Get-SelectedResultRows -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Status') -ne 'Błąd' })
            if ($selected.Count -eq 0) { Show-Warning 'Zaznacz wiersze w tabeli wyników.'; return }
            $null = & $entry $m $selected
        }
        $script:MenuActions[$item] = $a.Action
        [void]$menu.Items.Add($item)
    }
    if ($menu.Items.Count -gt 0) { [void]$menu.Items.Add((New-MenuSeparator)) }
    [void]$menu.Items.Add((New-MenuItem -Text 'Szczegóły wiersza' -Icon 'E8A1' -Module $Module -Enabled $hasRows -Action {
                param($m)
                $r = @(Get-SelectedResultRows -Module $m)
                if ($r.Count -gt 0) { Show-RowDetails -Module $m -Row $r[0] }
            }))
    [void]$menu.Items.Add((New-MenuItem -Text 'Kopiuj wartość komórki' -Icon 'E8C8' -Module $Module -Enabled $hasRows -Action {
                param($m)
                $cell = $m.Grid.CurrentCell
                if (-not $cell.Column -or -not ($cell.Item -is [System.Data.DataRowView])) { return }
                $name = [string]$cell.Column.SortMemberPath
                $value = Get-ExportValue -Module $m -Row $cell.Item -Column $name
                Set-ClipboardText ([string]$value)
                Show-Toast "Skopiowano: $name" 'ok' 2
            }))
    [void]$menu.Items.Add((New-MenuItem -Text 'Kopiuj zaznaczone wiersze' -Icon 'E8C8' -Module $Module -Enabled $hasRows -Action { param($m) Copy-ResultView -Module $m -SelectedOnly }))
    [void]$menu.Items.Add((New-MenuItem -Text 'Eksport…' -Icon 'EDE1' -Module $Module -Action { param($m) Export-ResultView -Module $m }))
    if ($Module.MenuCell -or $Module.ColumnFilters.Count -gt 0) {
        [void]$menu.Items.Add((New-MenuSeparator))
        if ($Module.MenuCell) { Add-QuickFilterMenu -Module $Module -Menu $menu }
        elseif ($Module.ColumnFilters.Count -gt 0) { [void]$menu.Items.Add((New-MenuItem -Text 'Wyczyść filtry kolumn' -Icon 'E894' -Module $Module -Action { param($m) Clear-ColumnFilters -Module $m })) }
    }
}
$script:MenuActions = New-Object 'System.Collections.Generic.Dictionary[object,scriptblock]'

function Update-ParamsCollapse {
    param([hashtable]$Module)
    $v = $Module.View_
    $collapsed = [bool]$Module.ParamsCollapsed
    $v.paramsCard.Visibility = if ($collapsed -or $Module.ParamsStack.Children.Count -eq 0) { 'Collapsed' } else { 'Visible' }
    $v.statsGrid.Visibility = if ($collapsed -or $Module.StatsGrid.Children.Count -eq 0) { 'Collapsed' } else { 'Visible' }
    $v.btnCollapse.Content = New-IconContent -Text $(if ($collapsed) { 'Parametry' } else { '' }) -Icon $(if ($collapsed) { 'E70D' } else { 'E70E' }) -IconSize 12
}

function Request-ResultSpace {
    # Po przygotowaniu podglądu: gdy tabela wyników jest za niska, zwija panel parametrów (przycisk «Parametry» go rozwinie)
    param([hashtable]$Module, [double]$MinHeight = 240)
    if ($Module.ParamsCollapsed -or -not $Module.Grid -or -not $Module.Root.IsVisible) { return }
    try { $Module.Root.UpdateLayout() } catch { }
    if ($Module.Grid.ActualHeight -gt 0 -and $Module.Grid.ActualHeight -lt $MinHeight) {
        $Module.ParamsCollapsed = $true
        Update-ParamsCollapse -Module $Module
        Show-Toast 'Zwinięto panel parametrów, aby zmieścić wyniki – przycisk «Parametry» u góry go rozwinie.' 'info' 5
    }
}

function Complete-ModuleView {
    # Po zbudowaniu modułu: elementy zależne od ustawień nadanych w Build
    param([Parameter(Mandatory)][hashtable]$Module)
    $v = $Module.View_
    if ($Module.ParamsStack.Children.Count -gt 0) { $v.btnCollapse.Visibility = 'Visible' }
    if ($Module.SecretColumns.Count -gt 0) { $v.chkReveal.Visibility = 'Visible' }
    if ($Module.EditableColumns.Count -gt 0) { $Module.Grid.IsReadOnly = $false }
    $v.emptyIcon.Text = Get-Glyph $(if ($Module.EmptyIcon) { $Module.EmptyIcon } else { $Module.Icon })
    if (-not $Module.EmptyHint -and $Module.PrimaryButton) {
        $label = $Module.PrimaryButton.Content
        if ($label -is [System.Windows.Controls.Panel]) { $label = $label.Children[$label.Children.Count - 1].Text }
        $Module.EmptyHint = switch ($Module.Target) {
            'Computer' { "Zaznacz komputery na liście po lewej i kliknij «$label» (F5)." }
            'User' { "Zaznacz konta na liście po lewej i kliknij «$label» (F5)." }
            'Group' { "Zaznacz grupy na liście po lewej i kliknij «$label» (F5)." }
            default { "Kliknij «$label» (F5), aby pobrać dane." }
        }
    }
    if ($Module.ResultHint) { $v.resultHint.Text = $Module.ResultHint }
    elseif ($Module.EditableColumns.Count -gt 0) { $v.resultHint.Text = 'Kolumny z ołówkiem można edytować (dwuklik lub F2) • prawy przycisk – akcje' }
    elseif ($Module.RowActions.Count -gt 0) { $v.resultHint.Text = 'Prawy przycisk myszy na wierszach – akcje' }
    else { $v.resultHint.Text = 'Dwuklik na wierszu – szczegóły' }
    Update-ResultCount -Module $Module
}

function Reset-ResultTable {
    param([Parameter(Mandatory)][hashtable]$Module)
    $table = New-Object System.Data.DataTable 'Wyniki'
    foreach ($c in '__search', '__flag', '__tone', '__cf') { [void]$table.Columns.Add($c, [string]) }
    # Nowe wyniki - nowe kolumny: filtry kolumn i ich lejki zaczynają od zera (pole «Filtruj wyniki» zostaje)
    foreach ($b in @($Module.FilterButtons.Values)) { [void]$script:Handlers.Remove($b) }
    $Module.FilterButtons = @{}
    $Module.ColumnFilters.Clear()
    if ($Module.View_ -and $Module.View_['btnFilters']) { $Module.View_['btnFilters'].Visibility = 'Collapsed' }
    $view = [System.Data.DataView]::new($table)
    if ($Module.Table) { [void]$script:TableModules.Remove($Module.Table) }
    if ($Module.EditableColumns.Count -gt 0) {
        $script:TableModules[$table] = $Module
        $table.add_ColumnChanged($script:TableEvents.ColumnChanged)
    }
    $Module.Table = $table
    $Module.View = $view
    $Module.ColumnIndex = @{}
    $g = $Module.Grid
    if ($g) {
        $g.ItemsSource = $null
        $g.Columns.Clear()
        $g.ItemsSource = $view
    }
    Update-ResultFilter -Module $Module
}

function Add-GridColumn {
    param([hashtable]$Module, [string]$Name)
    $g = $Module.Grid
    if (-not $g -or $Module.ColumnIndex.ContainsKey($Name)) { return }
    $Module.ColumnIndex[$Name] = $true
    if ($Name.StartsWith('__') -or $Module.HiddenColumns -contains $Name) { return }
    $path = '[' + $Name + ']'
    $editable = $Module.EditableColumns -contains $Name
    if ($Module.PillColumns -contains $Name) {
        $xaml = @"
<DataTemplate xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Border x:Name="pill" CornerRadius="9" Padding="9,2" HorizontalAlignment="Left" Background="#1E252F">
    <TextBlock x:Name="txt" Text="{Binding $(ConvertTo-XmlText $path)}" Foreground="#AEB6C4" FontSize="12" FontWeight="SemiBold"/>
  </Border>
  <DataTemplate.Triggers>
"@
        foreach ($tone in $script:PillTones.Keys) {
            $xaml += "<DataTrigger Binding=`"{Binding [__tone]}`" Value=`"$tone`"><Setter TargetName=`"pill`" Property=`"Background`" Value=`"$($script:PillTones[$tone][0])`"/><Setter TargetName=`"txt`" Property=`"Foreground`" Value=`"$($script:PillTones[$tone][1])`"/></DataTrigger>"
        }
        $xaml += '<DataTrigger Binding="{Binding ' + (ConvertTo-XmlText $path) + '}" Value="{x:Null}"><Setter TargetName="pill" Property="Visibility" Value="Collapsed"/></DataTrigger>'
        $xaml += '</DataTemplate.Triggers></DataTemplate>'
        $col = New-Object System.Windows.Controls.DataGridTemplateColumn
        $col.CellTemplate = [System.Windows.Markup.XamlReader]::Parse($xaml)
        $col.ClipboardContentBinding = New-Object System.Windows.Data.Binding $path
    }
    else {
        $col = New-Object System.Windows.Controls.DataGridTextColumn
        $binding = New-Object System.Windows.Data.Binding $path
        if ($editable) {
            $binding.Mode = [System.Windows.Data.BindingMode]::TwoWay
            $col.EditingElementStyle = Get-ThemeResource 'GridEditText'
        }
        $col.Binding = $binding
        $style = New-Object System.Windows.Style ([System.Windows.Controls.TextBlock])
        $style.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.TextBlock]::TextTrimmingProperty, [System.Windows.TextTrimming]::CharacterEllipsis)))
        # Wartości wielowierszowe (wynik polecenia, wpis logu ze stosem wywołań): w tabeli pierwsza linia, całość w panelu szczegółów
        $style.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.TextBlock]::LineStackingStrategyProperty, [System.Windows.LineStackingStrategy]::BlockLineHeight)))
        $style.Setters.Add((New-Object System.Windows.Setter([System.Windows.Controls.TextBlock]::LineHeightProperty, [double]18)))
        $style.Setters.Add((New-Object System.Windows.Setter([System.Windows.FrameworkElement]::MaxHeightProperty, [double]18)))
        $col.ElementStyle = $style
        if ($Module.GoodWhenNo -contains $Name) { $col.CellStyle = Get-ThemeResource 'BoolCellInv' }
        elseif ($Module.ColorBools) { $col.CellStyle = Get-ThemeResource 'BoolCell' }
    }
    $col.IsReadOnly = -not $editable
    # Nagłówek: nazwa (+ ołówek dla kolumn edytowalnych) i lejek filtra (bez filtra dla wartości poufnych)
    $col.Header = New-ColumnHeader -Module $Module -Name $Name -Editable:$editable -NoFilter:($Module.SecretColumns -contains $Name)
    $col.SortMemberPath = $Name
    $col.MaxWidth = 520
    $col.MinWidth = 54
    $g.Columns.Add($col)
}

function Add-ResultRows {
    # Dodaje obiekty jako wiersze tabeli modułu; nowe właściwości tworzą nowe kolumny.
    # -Computer wypełnia pierwszą kolumnę (-TargetColumn, domyślnie "Komputer").
    param([hashtable]$Module, [string]$Computer = '', [object[]]$Objects, [string]$TargetColumn = 'Komputer')
    $table = $Module.Table
    if ($null -eq $table) { return }
    $Module.Loading = $true
    $table.BeginLoadData()
    try {
        foreach ($obj in $Objects) {
            if ($null -eq $obj) { continue }
            $values = New-Object System.Collections.Specialized.OrderedDictionary
            if ($Computer -and $TargetColumn) { $values[$TargetColumn] = $Computer }
            $base = if ($obj -is [System.Management.Automation.PSObject]) { $obj.PSObject.BaseObject } else { $obj }
            if ($base -is [string] -or $base -is [System.ValueType]) {
                $values['Wynik'] = ConvertTo-CellValue $base
            }
            elseif ($base -is [System.Collections.IDictionary]) {
                foreach ($k in $base.Keys) {
                    if ($Computer -and [string]$k -eq $TargetColumn) { continue }
                    $values[[string]$k] = ConvertTo-CellValue $base[$k]
                }
            }
            else {
                foreach ($p in $obj.PSObject.Properties) {
                    if ($script:HiddenProperties -contains $p.Name) { continue }
                    if ($Computer -and $p.Name -eq $TargetColumn) { continue }
                    $values[$p.Name] = ConvertTo-CellValue $p.Value
                }
            }
            foreach ($name in @($values.Keys)) {
                if (-not $table.Columns.Contains($name)) { [void]$table.Columns.Add($name, [object]) }
                if ($Module.SecretColumns -contains $name -and -not $table.Columns.Contains("__secret_$name")) { [void]$table.Columns.Add("__secret_$name", [object]) }
                Add-GridColumn -Module $Module -Name $name
            }
            $row = $table.NewRow()
            $search = New-Object System.Text.StringBuilder
            foreach ($name in $values.Keys) {
                $v = $values[$name]
                if ($Module.SecretColumns -contains $name) {
                    $row["__secret_$name"] = $v
                    if (-not $Module.RevealSecrets -and $v -isnot [System.DBNull] -and [string]$v -ne '') { $v = '••••••••••' }
                    $row[$name] = $v
                    continue
                }
                $row[$name] = $v
                if ($v -isnot [System.DBNull] -and -not $name.StartsWith('__')) { [void]$search.Append([string]$v).Append(' ') }
            }
            $row['__search'] = $search.ToString().ToLowerInvariant()
            if ($Module.ColumnFilters.Count -gt 0) { $row['__cf'] = $(if (Test-RowColumnFilters -Module $Module -Row $row) { '1' } else { '0' }) }
            if (-not $values.Contains('__flag')) {
                $status = [string]$values['Status']
                if ($status.StartsWith('Błąd')) { $row['__flag'] = 'crit' }
            }
            $table.Rows.Add($row)
        }
    }
    finally {
        $table.EndLoadData()
        $Module.Loading = $false
    }
    Update-ResultCount -Module $Module
}

function Set-ResultValue {
    # Zmienia wartość w istniejącym wierszu (np. Status po wykonaniu akcji) i odświeża tekst wyszukiwania
    param([hashtable]$Module, [Parameter(Mandatory)]$Row, [Parameter(Mandatory)][string]$Column, $Value)
    if ($Row -is [System.Data.DataRowView]) { $Row = $Row.Row }
    $table = $Row.Table
    if (-not $table.Columns.Contains($Column)) {
        [void]$table.Columns.Add($Column, [object])
        Add-GridColumn -Module $Module -Name $Column
    }
    $wasLoading = $Module.Loading
    $Module.Loading = $true
    try {
        if ($Module.SecretColumns -contains $Column) {
            if (-not $table.Columns.Contains("__secret_$Column")) { [void]$table.Columns.Add("__secret_$Column", [object]) }
            $real = ConvertTo-CellValue $Value
            $Row["__secret_$Column"] = $real
            $Row[$Column] = if ($Module.RevealSecrets -or $real -is [System.DBNull] -or [string]$real -eq '') { $real } else { '••••••••••' }
        }
        else { $Row[$Column] = ConvertTo-CellValue $Value }
        Update-RowSearch -Module $Module -Row $Row
    }
    finally { $Module.Loading = $wasLoading }
}

function Update-RowSearch {
    # Tekst do filtrowania wiersza (po zmianie wartości w kodzie albo edycji komórki)
    param([hashtable]$Module, $Row)
    if ($Row -is [System.Data.DataRowView]) { $Row = $Row.Row }
    $search = New-Object System.Text.StringBuilder
    foreach ($c in $Row.Table.Columns) {
        $n = $c.ColumnName
        if ($n.StartsWith('__') -or $Module.SecretColumns -contains $n) { continue }
        $v = $Row[$n]
        if ($v -isnot [System.DBNull]) { [void]$search.Append([string]$v).Append(' ') }
    }
    $Row['__search'] = $search.ToString().ToLowerInvariant()
    Set-RowFilterFlag -Module $Module -Row $Row
}

function Complete-GridEdit {
    # Zatwierdza trwającą edycję komórki/wiersza (przed odczytem tabeli przez akcję modułu)
    param([hashtable]$Module)
    $g = $Module.Grid
    if (-not $g -or $g.IsReadOnly) { return }
    try { [void]$g.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true) } catch { }
}

$script:TableModules = New-Object 'System.Collections.Generic.Dictionary[object,hashtable]'
$script:TableEvents = @{
    ColumnChanged = {
        param($s, $e)
        try {
            $m = $null
            if (-not $script:TableModules.TryGetValue($s, [ref]$m)) { return }
            if ($m.Loading -or $m.InCellEdit) { return }
            $name = $e.Column.ColumnName
            if ($name.StartsWith('__') -or $m.EditableColumns -notcontains $name) { return }
            $row = $e.Row
            if ($row.RowState -eq [System.Data.DataRowState]::Detached) { return }
            $m.InCellEdit = $true
            $previous = $script:LogContext
            $script:LogContext = $m.Title
            try {
                if ($m.OnCellEdit) { $null = & $m.OnCellEdit $m $row $name }
                Update-RowSearch -Module $m -Row $row
            }
            finally {
                $m.InCellEdit = $false
                $script:LogContext = $previous
            }
        }
        catch { Write-Log "Błąd edycji komórki: $($_.Exception.Message)" 'ERROR' }
    }
}

function Find-ResultRow {
    # Wiersze tabeli wyników z wartością w kolumnie (np. ukryty identyfikator __id)
    param([hashtable]$Module, [string]$Column, [string]$Value)
    $table = $Module.Table
    if (-not $table -or -not $table.Columns.Contains($Column)) { return @() }
    $expr = "[{0}] = '{1}'" -f $Column.Replace(']', '\]'), $Value.Replace("'", "''")
    return @($table.Select($expr))
}

function Set-RowState {
    # Kolumny Stan (+ kolor pigułki) i Uwagi wiersza planu / podglądu
    param([hashtable]$Module, $Row, [string]$State, [ValidateSet('', 'ok', 'warn', 'crit', 'info')][string]$Tone = '', $Note = $null, [string]$StateColumn = 'Stan')
    Set-ResultValue -Module $Module -Row $Row -Column $StateColumn -Value $State
    Set-ResultValue -Module $Module -Row $Row -Column '__tone' -Value $Tone
    if ($null -ne $Note) { Set-ResultValue -Module $Module -Row $Row -Column 'Uwagi' -Value ([string]$Note) }
}

function Get-ResultRowsAll {
    # Wszystkie wiersze tabeli (DataRow) w kolejności dodania
    param([hashtable]$Module)
    if (-not $Module.Table) { return @() }
    return @($Module.Table.Rows | Where-Object { $_.RowState -ne [System.Data.DataRowState]::Deleted })
}

function Remove-ResultRows {
    param([hashtable]$Module, [object[]]$Rows)
    foreach ($r in $Rows) {
        $dr = if ($r -is [System.Data.DataRowView]) { $r.Row } else { $r }
        if ($dr -and $dr.RowState -ne [System.Data.DataRowState]::Detached -and $dr.RowState -ne [System.Data.DataRowState]::Deleted) {
            $dr.Table.Rows.Remove($dr)
        }
    }
    Update-ResultCount -Module $Module
}

function Set-SecretReveal {
    param([hashtable]$Module, [bool]$Reveal)
    $Module.RevealSecrets = $Reveal
    $table = $Module.Table
    foreach ($name in $Module.SecretColumns) {
        if (-not $table.Columns.Contains($name)) { continue }
        foreach ($row in $table.Rows) {
            $real = $row["__secret_$name"]
            if ($real -is [System.DBNull] -or [string]$real -eq '') { continue }
            $row[$name] = if ($Reveal) { $real } else { '••••••••••' }
        }
    }
    if ($Reveal) { Write-Log 'Odkryto wartości poufne w tabeli wyników.' 'WARN' -Module $Module.Title }
    Update-DetailText -Module $Module
}

$script:FilterTimer = $null
function Request-ResultFilter {
    # Filtr z opóźnieniem (wpisywanie nie przelicza tabeli przy każdym znaku)
    param([hashtable]$Module)
    if (-not $script:FilterTimer) {
        $script:FilterTimer = New-Object System.Windows.Threading.DispatcherTimer
        $script:FilterTimer.Interval = [TimeSpan]::FromMilliseconds(220)
        $script:FilterTimer.add_Tick({
                param($s, $e)
                $s.Stop()
                $m = $script:FilterPending
                $script:FilterPending = $null
                if ($m) { Update-ResultFilter -Module $m }
            })
    }
    if ($script:FilterPending -and -not [object]::ReferenceEquals($script:FilterPending, $Module)) { Update-ResultFilter -Module $script:FilterPending }
    $script:FilterPending = $Module
    $script:FilterTimer.Stop()
    $script:FilterTimer.Start()
}
$script:FilterPending = $null

function Update-ResultFilter {
    param([hashtable]$Module)
    # Uwaga: DataView jest dla PowerShella listą - pusty widok byłby fałszem, stąd porównanie z $null
    if ($null -eq $Module.View) { return }
    $text = if ($Module.FilterBox) { $Module.FilterBox.Text.Trim().ToLowerInvariant() } else { '' }
    $terms = @($text -split '\s+' | Where-Object { $_ })
    $parts = foreach ($t in $terms) {
        if ($t.StartsWith('-') -and $t.Length -gt 1) { "__search NOT LIKE '*{0}*'" -f (ConvertTo-LikeLiteral $t.Substring(1)) }
        else { "__search LIKE '*{0}*'" -f (ConvertTo-LikeLiteral $t) }
    }
    if ($Module.ExtraFilter) { $parts = @($parts) + @('(' + $Module.ExtraFilter + ')') }
    if ($Module.ColumnFilters.Count -gt 0) { $parts = @($parts) + @("[__cf] = '1'") }
    $filter = (@($parts) -join ' AND ')
    try { $Module.View.RowFilter = $filter } catch { $Module.View.RowFilter = '' }
    Update-ResultCount -Module $Module
}

function Update-ResultCount {
    param([hashtable]$Module)
    if ($null -eq $Module.View -or -not $Module.View_) { return }
    $total = $Module.Table.Rows.Count
    $visible = $Module.View.Count
    $g = $Module.Grid
    if ($g) { $g.HeadersVisibility = if ($g.Columns.Count -gt 0) { 'Column' } else { 'None' } }
    $count = $Module.View_['countText']
    if ($count) { $count.Text = if ($visible -eq $total) { [string]$total } else { "$visible z $total" } }
    $empty = $Module.View_['emptyState']
    if ($empty) {
        if ($visible -gt 0) { $empty.Visibility = 'Collapsed' }
        else {
            $empty.Visibility = 'Visible'
            if ($Module.Busy -and $total -eq 0) {
                $Module.View_['emptyText'].Text = 'Trwa pobieranie danych…'
                $Module.View_['emptyHint'].Text = 'Wyniki pojawią się tu na bieżąco dla kolejnych obiektów.'
            }
            elseif ($total -gt 0) {
                $Module.View_['emptyText'].Text = 'Nic nie pasuje do filtra'
                $Module.View_['emptyHint'].Text = $(if ($Module.ColumnFilters.Count -gt 0) { 'Zmień lub wyczyść filtry kolumn (przycisk «Filtry kolumn» obok licznika) albo pole «Filtruj wyniki».' } else { 'Zmień lub wyczyść filtr. Słowo poprzedzone minusem wyklucza wiersze.' })
            }
            else {
                $Module.View_['emptyText'].Text = $(if ($Module.EmptyText) { $Module.EmptyText } else { 'Brak wyników' })
                $Module.View_['emptyHint'].Text = [string]$Module.EmptyHint
            }
        }
    }
}

function Update-DetailPane {
    param([hashtable]$Module)
    $v = $Module.View_
    if (-not $v -or -not $v['detailPane']) { return }
    if ($script:Settings.DetailVisible) {
        $v.detailPane.Visibility = 'Visible'
        $v.detailSplit.Visibility = 'Visible'
        if ($v.detailCol.Width.Value -lt 120) { $v.detailCol.Width = New-Object System.Windows.GridLength 340 }
    }
    else {
        $v.detailPane.Visibility = 'Collapsed'
        $v.detailSplit.Visibility = 'Collapsed'
        $v.detailCol.Width = New-Object System.Windows.GridLength 0
    }
}

function Format-RowDetails {
    param([hashtable]$Module, $Row)
    $sb = New-Object System.Text.StringBuilder
    foreach ($col in $Module.Table.Columns) {
        $name = $col.ColumnName
        if ($name.StartsWith('__')) { continue }
        $v = Get-ExportValue -Module $Module -Row $Row -Column $name
        if ([string]$v -eq '') { continue }
        $text = [string]$v
        if ($text -match "[\r\n]") { [void]$sb.AppendLine("${name}:").AppendLine($text.Trim()).AppendLine() }
        else { [void]$sb.AppendLine(('{0}:  {1}' -f $name, $text)) }
    }
    return $sb.ToString()
}

function Update-DetailText {
    param([hashtable]$Module)
    $box = $Module.View_['detailText']
    if (-not $box) { return }
    $item = $Module.Grid.SelectedItem
    if ($item -is [System.Data.DataRowView]) { $box.Text = Format-RowDetails -Module $Module -Row $item }
    else { $box.Text = '' }
}

function Show-RowDetails {
    param([hashtable]$Module, $Row)
    if (-not ($Row -is [System.Data.DataRowView])) { return }
    $title = 'Szczegóły'
    foreach ($c in 'Komputer', 'Login', 'Nazwa', 'Name') {
        $v = Get-ObjectValue $Row $c
        if ($v) { $title = "Szczegóły – $v"; break }
    }
    Show-TextDialog -Title $title -Subtitle $Module.Title -Text (Format-RowDetails -Module $Module -Row $Row)
}

function Get-VisibleColumnNames {
    param([hashtable]$Module)
    $cols = @($Module.Grid.Columns | Where-Object { $_.Visibility -eq 'Visible' } | Sort-Object DisplayIndex)
    return @($cols | ForEach-Object { [string]$_.SortMemberPath })
}

function Get-ExportValue {
    # Wartość komórki do eksportu/kopiowania (z maskowaniem wartości poufnych)
    param([hashtable]$Module, $Row, [string]$Column)
    if ($Module.SecretColumns -contains $Column) {
        $real = Get-ObjectValue $Row "__secret_$Column"
        if ($null -eq $real -or [string]$real -eq '') { return '' }
        if ($Module.RevealSecrets) { return $real }
        return '********'
    }
    $v = Get-ObjectValue $Row $Column
    if ($null -eq $v) { return '' }
    return $v
}

function Get-RowValue {
    # Prawdziwa wartość kolumny (także poufnej) - do użycia w akcjach modułów
    param($Row, [string]$Column)
    $secret = Get-ObjectValue $Row "__secret_$Column"
    if ($null -ne $secret) { return $secret }
    return (Get-ObjectValue $Row $Column)
}

function Get-SelectedResultRows {
    # Zaznaczone wiersze tabeli (DataRowView)
    param([hashtable]$Module)
    return @($Module.Grid.SelectedItems | Where-Object { $_ -is [System.Data.DataRowView] })
}

function Get-SelectedRowsByHost {
    # Grupuje zaznaczone wiersze po kolumnie Komputer: host -> lista hashtabel z wartościami kolumn
    param([hashtable]$Module, [string[]]$Columns, [object[]]$Rows = $null, [string]$TargetColumn = 'Komputer')
    $result = [ordered]@{}
    $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $Module })
    foreach ($drv in $source) {
        $computer = [string](Get-ObjectValue $drv $TargetColumn)
        if (-not $computer -or (Get-ObjectValue $drv 'Status') -eq 'Błąd') { continue }
        $item = @{ __row = $drv }
        $valid = $true
        foreach ($c in $Columns) {
            $v = Get-RowValue $drv $c
            if ($null -eq $v -or [string]$v -eq '') { $valid = $false }
            $item[$c] = $v
        }
        if (-not $valid) { continue }
        if (-not $result.Contains($computer)) { $result[$computer] = New-Object System.Collections.ArrayList }
        [void]$result[$computer].Add($item)
    }
    return $result
}

function Export-ResultView {
    param([hashtable]$Module)
    if ($null -eq $Module.View -or $Module.View.Count -eq 0) { Show-Warning 'Brak danych do eksportu.'; return }
    $dlg = New-Object Microsoft.Win32.SaveFileDialog
    $dlg.Filter = 'CSV (*.csv)|*.csv|Raport HTML (*.html)|*.html'
    $dlg.FileName = '{0}_{1:yyyyMMdd_HHmm}' -f (Get-SafeFileName $Module.Title), (Get-Date)
    $dlg.AddExtension = $true
    $dlg.DefaultExt = '.csv'
    $answer = if ($script:UI.Window) { $dlg.ShowDialog($script:UI.Window) } else { $dlg.ShowDialog() }
    if ($answer -ne $true) { return }
    $path = $dlg.FileName
    $columns = Get-VisibleColumnNames -Module $Module
    $rows = @($Module.View | ForEach-Object { $_ })
    if ($path -match '\.html?$') {
        $html = ConvertTo-HtmlReport -Module $Module -Columns $columns -Rows $rows
        [System.IO.File]::WriteAllText($path, $html, (New-Object System.Text.UTF8Encoding($true)))
    }
    else {
        $objects = foreach ($drv in $rows) {
            $o = [ordered]@{}
            foreach ($c in $columns) { $o[$c] = Get-ExportValue -Module $Module -Row $drv -Column $c }
            [pscustomobject]$o
        }
        $encoding = if ($PSVersionTable.PSVersion.Major -ge 6) { 'utf8BOM' } else { 'UTF8' }
        $objects | Export-Csv -LiteralPath $path -NoTypeInformation -UseCulture -Encoding $encoding
    }
    Write-Log "Zapisano $($rows.Count) wierszy do pliku $path" 'OK' -Module $Module.Title
    Show-Toast "Zapisano $($rows.Count) wierszy: $([System.IO.Path]::GetFileName($path))" 'ok'
}

function ConvertTo-HtmlReport {
    # Samodzielny raport HTML (ciemny motyw jak w programie) z widocznych wierszy: wyszukiwarka, filtr i sortowanie
    # kolumn, kopiowanie wiersza lub widocznych wierszy, otwieranie wiersza w osobnym oknie (32-htmlreport.ps1)
    param([hashtable]$Module, [string[]]$Columns, [object[]]$Rows)
    $enc = { param($t) ConvertTo-HtmlText $t }
    $filter = if ($Module.FilterBox) { $Module.FilterBox.Text.Trim() } else { '' }
    $meta = 'Domain Ops {0} • {1:yyyy-MM-dd HH:mm} • {2} • wierszy: {3}' -f $script:AppVersion, (Get-Date), $env:USERNAME, $Rows.Count
    if ($filter) { $meta += " • filtr: $filter" }
    if ($Module.ColumnFilters.Count -gt 0) { $meta += ' • filtry kolumn: ' + (Get-ColumnFiltersText -Module $Module) }
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append((Get-ReportHead -Title $Module.Title -Meta $meta))
    [void]$sb.Append((Get-ReportBar -Mode 'rows' -Placeholder 'Szukaj we wszystkich kolumnach…' -Buttons @('copy', 'clear', 'print') -Extra ('<span class="cnt">wiersze: <b data-count-for="t1">' + $Rows.Count + '</b></span>')))
    [void]$sb.Append('<div class="box"><table class="dt" id="t1"><thead><tr>')
    foreach ($c in $Columns) { [void]$sb.Append('<th>').Append((& $enc $c)).Append('</th>') }
    [void]$sb.Append('</tr></thead><tbody>')
    foreach ($drv in $Rows) {
        $flag = [string](Get-ObjectValue $drv '__flag')
        $tone = [string](Get-ObjectValue $drv '__tone')
        [void]$sb.Append($(if ($flag) { "<tr class=`"$flag`">" } else { '<tr>' }))
        foreach ($c in $Columns) {
            $v = & $enc (Get-ExportValue -Module $Module -Row $drv -Column $c)
            if ($Module.PillColumns -contains $c -and $v) {
                $cls = switch ($tone) { 'ok' { 'ok' } 'warn' { 'warn' } 'crit' { 'crit' } 'info' { 'info' } default { '' } }
                $v = "<span class=`"pill $cls`">$v</span>"
            }
            [void]$sb.Append('<td>').Append($v).Append('</td>')
        }
        [void]$sb.Append('</tr>')
    }
    [void]$sb.Append('</tbody></table></div>')
    [void]$sb.Append((Get-ReportTail))
    return $sb.ToString()
}

function Copy-ResultView {
    # Kopiuje zaznaczone wiersze (albo wszystkie widoczne) jako tekst rozdzielany tabulatorami (Excel)
    param([hashtable]$Module, [switch]$SelectedOnly)
    if ($null -eq $Module.View -or $Module.View.Count -eq 0) { Show-Warning 'Brak danych do skopiowania.'; return }
    $columns = Get-VisibleColumnNames -Module $Module
    $rows = @(Get-SelectedResultRows -Module $Module)
    if (-not $SelectedOnly -and $rows.Count -le 1) { $rows = @($Module.View | ForEach-Object { $_ }) }
    if ($rows.Count -eq 0) { return }
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine(($columns -join "`t"))
    foreach ($drv in $rows) {
        $cells = foreach ($c in $columns) { ([string](Get-ExportValue -Module $Module -Row $drv -Column $c)) -replace '[\t\r\n]+', ' ' }
        [void]$sb.AppendLine((@($cells) -join "`t"))
    }
    Set-ClipboardText $sb.ToString()
    Show-Toast "Skopiowano $($rows.Count) wierszy do schowka." 'ok'
}

function Show-GridDialog {
    # Dowolne obiekty w tabeli z filtrem, eksportem i kopiowaniem (okno z widokiem modułu)
    param([string]$Title, [object[]]$Rows, [string[]]$SecretColumns = @(), [string]$Subtitle = '', [string[]]$PillColumns = @())
    $m = New-ModuleContext -Definition @{ Key = 'Dialog_' + [guid]::NewGuid().ToString('N'); Title = $Title; Description = $Subtitle; Category = 'Podgląd'; Icon = 'E8FD'; Workspace = '' }
    $m.SecretColumns = @($SecretColumns)
    $m.PillColumns = @($PillColumns)
    New-ModuleView -Module $m
    Complete-ModuleView -Module $m
    foreach ($r in $Rows) { Add-ResultRows -Module $m -Objects @($r) }
    $w = New-Dialog -Title $Title -Subtitle $Subtitle -Body '' -Icon 'E8FD' -OkText 'Zamknij' -NoCancel -Width 1100 -Height 700 -Resizable
    # Nagłówek modułu jest zbędny w oknie - zostaje pasek wyników i tabela
    $m.Root.RowDefinitions[0].Height = New-Object System.Windows.GridLength 0
    $m.Root.Children[0].Visibility = 'Collapsed'
    [void]$w.FindName('dlgBody').Children.Add($m.Root)
    [void](Invoke-Dialog $w)
    [void]$script:GridModules.Remove($m.Grid)
    foreach ($b in @($m.FilterButtons.Values)) { [void]$script:Handlers.Remove($b) }
}
#endregion

#region Filtry kolumn tabeli wyników (jak autofiltr w Excelu)
# $Module.ColumnFilters: kolumna -> @{ Values = HashSet[string] (wybrane wartości) albo $null; Op = warunek; Text = argument }.
# Wynik oceny wszystkich filtrów kolumn trafia do ukrytej kolumny __cf ('1' = wiersz pasuje), a RowFilter widoku
# dokłada warunek [__cf] = '1' - porównania liczb, pustych komórek i tekstu działają więc tak, jak widać je w siatce,
# a filtr działa razem z polem «Filtruj wyniki». Nowe i zmienione wiersze są oceniane na bieżąco.
$script:FilterOps = [ordered]@{
    'zawiera'        = 'contains'
    'nie zawiera'    = 'notcontains'
    'równa się'      = 'eq'
    'różne od'       = 'ne'
    'zaczyna się od' = 'starts'
    'kończy się na'  = 'ends'
    'większe niż'    = 'gt'
    'mniejsze niż'   = 'lt'
    'puste'          = 'empty'
    'niepuste'       = 'notempty'
}
$script:FilterListLimit = 500

function Get-FilterText($Value) {
    # Tekst wartości komórki do porównań (jak w siatce: liczby bez formatowania regionalnego, puste = '')
    if ($null -eq $Value -or $Value -is [System.DBNull]) { return '' }
    return [string]$Value
}

function Get-FilterOpLabel([string]$Op) {
    foreach ($k in $script:FilterOps.Keys) { if ($script:FilterOps[$k] -eq $Op) { return $k } }
    return $Op
}

function ConvertTo-FilterNumber([string]$Text, [ref]$Number) {
    $t = $Text.Trim().Replace(' ', '').Replace(',', '.')
    if ($t -eq '') { return $false }
    $n = 0.0
    if ([double]::TryParse($t, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$n)) { $Number.Value = $n; return $true }
    return $false
}

function Test-FilterCondition {
    # Warunek tekstowy filtra kolumny (bez rozróżniania wielkości liter; większe/mniejsze - liczbowo, gdy obie strony są liczbami)
    param([string]$Text, [string]$Op, [string]$Arg)
    if ($Op -eq 'empty') { return ($Text.Trim() -eq '') }
    if ($Op -eq 'notempty') { return ($Text.Trim() -ne '') }
    if ($Arg -eq '') { return $true }
    $ci = [System.Globalization.CultureInfo]::CurrentCulture.CompareInfo
    $ic = [System.Globalization.CompareOptions]::IgnoreCase
    switch ($Op) {
        'contains' { return ($ci.IndexOf($Text, $Arg, $ic) -ge 0) }
        'notcontains' { return ($ci.IndexOf($Text, $Arg, $ic) -lt 0) }
        'eq' { return ($ci.Compare($Text.Trim(), $Arg.Trim(), $ic) -eq 0) }
        'ne' { return ($ci.Compare($Text.Trim(), $Arg.Trim(), $ic) -ne 0) }
        'starts' { return $ci.IsPrefix($Text, $Arg, $ic) }
        'ends' { return $ci.IsSuffix($Text.TrimEnd(), $Arg, $ic) }
    }
    if ($Op -eq 'gt' -or $Op -eq 'lt') {
        if ($Text.Trim() -eq '') { return $false }
        $a = 0.0
        $b = 0.0
        if ((ConvertTo-FilterNumber $Text ([ref]$a)) -and (ConvertTo-FilterNumber $Arg ([ref]$b))) { $c = $a.CompareTo($b) }
        else { $c = [string]::Compare($Text.Trim(), $Arg.Trim(), [StringComparison]::OrdinalIgnoreCase) }
        if ($Op -eq 'gt') { return ($c -gt 0) }
        return ($c -lt 0)
    }
    return $true
}

function Get-FilterPassSet {
    # Teksty spełniające warunek - liczone raz dla każdej różnej wartości kolumny (a nie dla każdego wiersza)
    param($Texts, [string]$Op, [string]$Arg)
    $pass = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
    $ci = [System.Globalization.CultureInfo]::CurrentCulture.CompareInfo
    $ic = [System.Globalization.CompareOptions]::IgnoreCase
    $a = $Arg.Trim()
    switch ($Op) {
        'empty' { foreach ($x in $Texts) { if ($x.Trim() -eq '') { [void]$pass.Add($x) } } }
        'notempty' { foreach ($x in $Texts) { if ($x.Trim() -ne '') { [void]$pass.Add($x) } } }
        'contains' { foreach ($x in $Texts) { if ($ci.IndexOf($x, $Arg, $ic) -ge 0) { [void]$pass.Add($x) } } }
        'notcontains' { foreach ($x in $Texts) { if ($ci.IndexOf($x, $Arg, $ic) -lt 0) { [void]$pass.Add($x) } } }
        'eq' { foreach ($x in $Texts) { if ($ci.Compare($x.Trim(), $a, $ic) -eq 0) { [void]$pass.Add($x) } } }
        'ne' { foreach ($x in $Texts) { if ($ci.Compare($x.Trim(), $a, $ic) -ne 0) { [void]$pass.Add($x) } } }
        'starts' { foreach ($x in $Texts) { if ($ci.IsPrefix($x, $Arg, $ic)) { [void]$pass.Add($x) } } }
        'ends' { foreach ($x in $Texts) { if ($ci.IsSuffix($x.TrimEnd(), $Arg, $ic)) { [void]$pass.Add($x) } } }
        { $_ -eq 'gt' -or $_ -eq 'lt' } {
            $b = 0.0
            $argNum = ConvertTo-FilterNumber $Arg ([ref]$b)
            $inv = [System.Globalization.CultureInfo]::InvariantCulture
            $sty = [System.Globalization.NumberStyles]::Float
            $gt = ($Op -eq 'gt')
            foreach ($x in $Texts) {
                $xt = $x.Trim()
                if ($xt -eq '') { continue }
                $n = 0.0
                if ($argNum -and [double]::TryParse($xt.Replace(' ', '').Replace(',', '.'), $sty, $inv, [ref]$n)) { $c = $n.CompareTo($b) }
                else { $c = [string]::Compare($xt, $a, [StringComparison]::OrdinalIgnoreCase) }
                if (($gt -and $c -gt 0) -or (-not $gt -and $c -lt 0)) { [void]$pass.Add($x) }
            }
        }
        default { foreach ($x in $Texts) { [void]$pass.Add($x) } }
    }
    return , $pass
}

function Get-CompiledColumnFilters {
    # Filtry kolumn do szybkiej oceny wielu wierszy: dla każdej kolumny jeden zbiór dozwolonych tekstów
    # (wybrane wartości ∩ wartości spełniające warunek) - w pętli po wierszach zostaje tylko sprawdzenie zbioru
    param([hashtable]$Module, $Table, [string]$Skip = '')
    $cols = $Table.Columns
    $deleted = [System.Data.DataRowState]::Deleted
    return @(foreach ($col in $Module.ColumnFilters.Keys) {
            if ($col -eq $Skip) { continue }
            $f = $Module.ColumnFilters[$col]
            $dc = if ($cols.Contains($col)) { $cols[$col] } else { $null }
            $set = $f.Values
            if ($f.Op) {
                $texts = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
                if ($null -ne $dc) {
                    foreach ($r in $Table.Rows) {
                        if ($r.RowState -eq $deleted) { continue }
                        $v = $r[$dc]
                        [void]$texts.Add($(if ($null -eq $v -or $v -is [System.DBNull]) { '' } else { [string]$v }))
                    }
                }
                else { [void]$texts.Add('') }
                $pass = Get-FilterPassSet -Texts $texts -Op $f.Op -Arg $f.Text
                if ($null -ne $set) { $pass.IntersectWith($set) }
                $set = $pass
            }
            @{ Column = $dc; Values = $set }
        })
}

function Test-RowColumnFilters {
    # Czy wiersz (DataRow) spełnia filtry kolumn; -Skip pomija filtr jednej kolumny
    param([hashtable]$Module, $Row, [string]$Skip = '')
    if ($Row -is [System.Data.DataRowView]) { $Row = $Row.Row }
    $cols = $Row.Table.Columns
    foreach ($col in $Module.ColumnFilters.Keys) {
        if ($col -eq $Skip) { continue }
        $f = $Module.ColumnFilters[$col]
        $text = if ($cols.Contains($col)) { Get-FilterText $Row[$col] } else { '' }
        if ($null -ne $f.Values -and -not $f.Values.Contains($text)) { return $false }
        if ($f.Op -and -not (Test-FilterCondition -Text $text -Op $f.Op -Arg $f.Text)) { return $false }
    }
    return $true
}

function Set-RowFilterFlag {
    # Ocena filtrów kolumn dla jednego wiersza (po dodaniu albo zmianie wartości)
    param([hashtable]$Module, $Row)
    if ($Module.ColumnFilters.Count -eq 0) { return }
    $v = if (Test-RowColumnFilters -Module $Module -Row $Row) { '1' } else { '0' }
    if ([string]$Row['__cf'] -ne $v) { $Row['__cf'] = $v }
}

function Update-ColumnFilterFlags {
    # Ponowna ocena wszystkich wierszy po zmianie filtrów (pętla bez wywołań funkcji dla filtrów wartości - szybko także przy tysiącach wierszy)
    param([hashtable]$Module)
    $t = $Module.Table
    if ($null -eq $t -or $Module.ColumnFilters.Count -eq 0) { return }
    $filters = @(Get-CompiledColumnFilters -Module $Module -Table $t)
    $cf = $t.Columns['__cf']
    $deleted = [System.Data.DataRowState]::Deleted
    $wasLoading = $Module.Loading
    $Module.Loading = $true
    $t.BeginLoadData()
    try {
        foreach ($r in $t.Rows) {
            if ($r.RowState -eq $deleted) { continue }
            $ok = $true
            foreach ($f in $filters) {
                $v = if ($null -ne $f.Column) { $r[$f.Column] } else { $null }
                if (-not $f.Values.Contains($(if ($null -eq $v -or $v -is [System.DBNull]) { '' } else { [string]$v }))) { $ok = $false; break }
            }
            $flag = if ($ok) { '1' } else { '0' }
            if ([string]$r[$cf] -ne $flag) { $r[$cf] = $flag }
        }
    }
    finally {
        $t.EndLoadData()
        $Module.Loading = $wasLoading
    }
}

function Get-ColumnFilterText {
    # Opis filtra kolumny do podpowiedzi, raportu HTML i dziennika
    param([hashtable]$Module, [string]$Column)
    $f = $Module.ColumnFilters[$Column]
    if (-not $f) { return '' }
    $parts = @()
    if ($null -ne $f.Values) {
        $vals = @($f.Values | Sort-Object | ForEach-Object { if ($_ -eq '') { '(puste)' } else { $_ } })
        $shown = @($vals | Select-Object -First 6) -join ', '
        if ($vals.Count -gt 6) { $shown += " … (+$($vals.Count - 6))" }
        $parts += $(if ($vals.Count -eq 0) { 'żadna wartość' } else { $shown })
    }
    if ($f.Op) {
        $label = Get-FilterOpLabel $f.Op
        $parts += $(if ($f.Op -eq 'empty' -or $f.Op -eq 'notempty') { $label } else { "$label «$($f.Text)»" })
    }
    return ('{0}: {1}' -f $Column, ($parts -join '; '))
}

function Get-ColumnFiltersText {
    param([hashtable]$Module)
    return (@($Module.ColumnFilters.Keys | ForEach-Object { Get-ColumnFilterText -Module $Module -Column $_ }) -join ' • ')
}

function Set-ColumnFilter {
    # Ustawia (albo usuwa, gdy brak wartości i warunku) filtr kolumny i odświeża widok
    param([Parameter(Mandatory)][hashtable]$Module, [Parameter(Mandatory)][string]$Column, $Values = $null, [string]$Op = '', [string]$Text = '')
    if ($Op -and $Op -ne 'empty' -and $Op -ne 'notempty' -and $Text -eq '') { $Op = '' }
    $set = $null
    if ($null -ne $Values) {
        $set = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
        foreach ($v in @($Values)) { [void]$set.Add([string]$v) }
    }
    if ($null -eq $set -and -not $Op) { [void]$Module.ColumnFilters.Remove($Column) }
    else { $Module.ColumnFilters[$Column] = @{ Values = $set; Op = $Op; Text = $Text } }
    Update-ColumnFilterState -Module $Module
    if ($Module.ColumnFilters.Contains($Column)) { Write-Log ('Filtr kolumny – ' + (Get-ColumnFilterText -Module $Module -Column $Column)) -Module $Module.Title }
}

function Clear-ColumnFilters {
    param([Parameter(Mandatory)][hashtable]$Module, [string]$Column = '')
    if ($Column) { [void]$Module.ColumnFilters.Remove($Column) } else { $Module.ColumnFilters.Clear() }
    Update-ColumnFilterState -Module $Module
}

function Update-ColumnFilterState {
    # Flagi wierszy, wyróżnienie lejków w nagłówkach, przycisk «Filtry kolumn» i filtr widoku
    param([hashtable]$Module)
    Update-ColumnFilterFlags -Module $Module
    foreach ($col in @($Module.FilterButtons.Keys)) {
        $Module.FilterButtons[$col].Tag = $(if ($Module.ColumnFilters.Contains($col)) { 'on' } else { $null })
    }
    $chip = $Module.View_['btnFilters']
    if ($chip) {
        $n = $Module.ColumnFilters.Count
        if ($n -gt 0) {
            $chip.Content = New-IconContent -Text ("Filtry kolumn: {0}" -f $n) -Icon 'E71C' -IconSize 11
            $chip.ToolTip = (Get-ColumnFiltersText -Module $Module).Replace(' • ', [Environment]::NewLine) + [Environment]::NewLine + '(kliknij, aby wyczyścić filtry kolumn)'
            $chip.Visibility = 'Visible'
        }
        else { $chip.Visibility = 'Collapsed' }
    }
    Update-ResultFilter -Module $Module
}

function New-ColumnHeader {
    # Nagłówek kolumny: nazwa (+ ołówek dla kolumn edytowalnych) i lejek filtra
    param([hashtable]$Module, [string]$Name, [switch]$Editable, [switch]$NoFilter)
    $g = New-Object System.Windows.Controls.Grid
    [void]$g.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::new(1, 'Star') }))
    [void]$g.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::Auto }))
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Orientation = 'Horizontal'
    $sp.VerticalAlignment = 'Center'
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $Name
    [void]$sp.Children.Add($t)
    if ($Editable) {
        $pen = New-GlyphBlock -Code 'E70F' -Size 10 -Color '#6F8FD8'
        $pen.Margin = '6,1,0,0'
        [void]$sp.Children.Add($pen)
    }
    [void]$g.Children.Add($sp)
    if (-not $NoFilter) {
        $b = New-Object System.Windows.Controls.Button
        $b.Style = Get-ThemeResource 'HeaderFilterButton'
        $b.Margin = '8,0,-6,0'
        $b.CommandParameter = $Name
        [System.Windows.Controls.Grid]::SetColumn($b, 1)
        Register-ControlHandler -Control $b -EventName 'Click' -Module $Module -Action { param($m, $s) Show-ColumnFilter -Module $m -Column ([string]$s.CommandParameter) -Anchor $s }
        [void]$g.Children.Add($b)
        $Module.FilterButtons[$Name] = $b
        if ($Module.ColumnFilters.Contains($Name)) { $b.Tag = 'on' }
    }
    return $g
}

function Get-ColumnValueCounts {
    # Wartości kolumny z liczbą wierszy - z wierszy spełniających filtry pozostałych kolumn
    param([hashtable]$Module, [string]$Column)
    $counts = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([StringComparer]::Ordinal)
    $t = $Module.Table
    if ($null -eq $t -or -not $t.Columns.Contains($Column)) { return @() }
    $numeric = $true
    $filters = @(Get-CompiledColumnFilters -Module $Module -Table $t -Skip $Column)
    $dc = $t.Columns[$Column]
    $deleted = [System.Data.DataRowState]::Deleted
    foreach ($r in $t.Rows) {
        if ($r.RowState -eq $deleted) { continue }
        if ($filters.Count -gt 0) {
            $ok = $true
            foreach ($f in $filters) {
                $fv = if ($null -ne $f.Column) { $r[$f.Column] } else { $null }
                if (-not $f.Values.Contains($(if ($null -eq $fv -or $fv -is [System.DBNull]) { '' } else { [string]$fv }))) { $ok = $false; break }
            }
            if (-not $ok) { continue }
        }
        $v = $r[$dc]
        if ($null -eq $v -or $v -is [System.DBNull]) { $text = '' }
        else {
            $text = [string]$v
            if ($numeric -and -not ($v -is [System.ValueType])) { $numeric = $false }
        }
        $n = 0
        [void]$counts.TryGetValue($text, [ref]$n)
        $counts[$text] = $n + 1
    }
    # Puste na końcu; liczby rosnąco liczbowo, tekst alfabetycznie (polska kolejność)
    $keys = New-Object 'System.Collections.Generic.List[string]'
    foreach ($k in $counts.Keys) { if ($k -ne '') { $keys.Add($k) } }
    if ($numeric) {
        $nums = New-Object 'double[]' $keys.Count
        for ($i = 0; $i -lt $keys.Count; $i++) { $x = 0.0; [void](ConvertTo-FilterNumber $keys[$i] ([ref]$x)); $nums[$i] = $x }
        $arr = $keys.ToArray()
        [Array]::Sort($nums, $arr)
    }
    else {
        $arr = $keys.ToArray()
        [Array]::Sort($arr, [StringComparer]::Create([System.Globalization.CultureInfo]::GetCultureInfo('pl-PL'), $true))
    }
    $result = New-Object System.Collections.ArrayList
    foreach ($k in $arr) { [void]$result.Add([pscustomobject]@{ Text = $k; Count = $counts[$k] }) }
    if ($counts.ContainsKey('')) { [void]$result.Add([pscustomobject]@{ Text = ''; Count = $counts[''] }) }
    return $result.ToArray()
}

function Set-ResultSort {
    # Sortowanie siatki po kolumnie (jak kliknięcie nagłówka)
    param([hashtable]$Module, [string]$Column, [switch]$Descending)
    $g = $Module.Grid
    $dir = if ($Descending) { [System.ComponentModel.ListSortDirection]::Descending } else { [System.ComponentModel.ListSortDirection]::Ascending }
    foreach ($c in $g.Columns) { $c.SortDirection = $(if ([string]$c.SortMemberPath -eq $Column) { $dir } else { $null }) }
    $g.Items.SortDescriptions.Clear()
    $g.Items.SortDescriptions.Add((New-Object System.ComponentModel.SortDescription($Column, $dir)))
}

$script:ColumnFilterXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Background="#1B212A" BorderBrush="#2F3846" BorderThickness="1" CornerRadius="10" Padding="14,12,14,12" Width="330" Margin="0,4,14,14">
  <Border.Effect>
    <DropShadowEffect BlurRadius="18" ShadowDepth="4" Opacity="0.5" Color="#000000"/>
  </Border.Effect>
  <StackPanel>
    <Grid Margin="0,0,0,8">
      <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,76,0">
        <TextBlock Style="{StaticResource Glyph}" Text="&#xE71C;" FontSize="12" Foreground="#8CB0FF" Margin="0,0,8,0"/>
        <TextBlock x:Name="fTitle" FontWeight="SemiBold" Foreground="#E4E8EF" TextTrimming="CharacterEllipsis"/>
      </StackPanel>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
        <Button x:Name="fSortAsc" Style="{StaticResource GhostButton}" Padding="7,3" MinHeight="26" ToolTip="Sortuj rosnąco (A → Z, 0 → 9)"/>
        <Button x:Name="fSortDesc" Style="{StaticResource GhostButton}" Padding="7,3" MinHeight="26" ToolTip="Sortuj malejąco (Z → A, 9 → 0)"/>
      </StackPanel>
    </Grid>
    <TextBlock Text="WARUNEK" Foreground="#5E6779" FontSize="10.5" FontWeight="SemiBold" Margin="1,2,0,5"/>
    <Grid Margin="0,0,0,12">
      <Grid.ColumnDefinitions>
        <ColumnDefinition Width="138"/>
        <ColumnDefinition Width="*"/>
      </Grid.ColumnDefinitions>
      <ComboBox x:Name="fOp" Margin="0,0,6,0"/>
      <TextBox x:Name="fText" Grid.Column="1" Tag="tekst lub liczba…"/>
    </Grid>
    <Grid Margin="1,0,0,5">
      <TextBlock Text="WARTOŚCI" Foreground="#5E6779" FontSize="10.5" FontWeight="SemiBold"/>
      <TextBlock x:Name="fCount" Foreground="#5E6779" FontSize="10.5" HorizontalAlignment="Right"/>
    </Grid>
    <TextBox x:Name="fSearch" Tag="Szukaj wartości…" Margin="0,0,0,6"/>
    <Border BorderBrush="#2A323F" BorderThickness="1" CornerRadius="6" Background="#161B22">
      <StackPanel>
        <CheckBox x:Name="fAll" Content="(Zaznacz wszystkie)" Margin="10,7,8,5" FontWeight="SemiBold"/>
        <Border Height="1" Background="#242B36" Margin="8,0"/>
        <ScrollViewer x:Name="fScroll" Height="200" VerticalScrollBarVisibility="Auto" Padding="10,4,6,6">
          <StackPanel x:Name="fList"/>
        </ScrollViewer>
      </StackPanel>
    </Border>
    <TextBlock x:Name="fNote" Foreground="#7B8496" FontSize="11.5" TextWrapping="Wrap" Margin="1,6,0,0" Visibility="Collapsed"/>
    <Grid Margin="0,12,0,0">
      <Button x:Name="fClear" Style="{StaticResource GhostButton}" HorizontalAlignment="Left" ToolTip="Usuń filtr tej kolumny"/>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
        <Button x:Name="fCancel" Style="{StaticResource GhostButton}" Content="Anuluj" Margin="0,0,6,0"/>
        <Button x:Name="fApply" Style="{StaticResource PrimaryButton}" Content="Filtruj"/>
      </StackPanel>
    </Grid>
  </StackPanel>
</Border>
'@

$script:ColumnFilterUi = $null
$script:ColumnFilterEvents = @{
    ItemToggled = {
        param($s, $e)
        try {
            $ui = $script:ColumnFilterUi
            if ($ui.Rendering) { return }
            $cb = $e.OriginalSource
            if (-not ($cb -is [System.Windows.Controls.CheckBox]) -or $null -eq $cb.Tag) { return }
            if ($cb.IsChecked -eq $true) { [void]$ui.Checked.Add([string]$cb.Tag) } else { [void]$ui.Checked.Remove([string]$cb.Tag) }
            Update-ColumnFilterAllBox
        }
        catch { }
    }
    KeyDown     = {
        param($s, $e)
        try {
            if ($e.Key -eq [System.Windows.Input.Key]::Escape) { $script:ColumnFilterUi.Popup.IsOpen = $false; $e.Handled = $true }
            elseif ($e.Key -eq [System.Windows.Input.Key]::Enter -and -not ($e.OriginalSource -is [System.Windows.Controls.ComboBox] -or $e.OriginalSource -is [System.Windows.Controls.ComboBoxItem])) {
                $e.Handled = $true
                Invoke-UiAction -Module $script:ColumnFilterUi.Module -Action { param($m) Complete-ColumnFilterUi }
            }
        }
        catch { }
    }
}

function Initialize-ColumnFilterUi {
    # Jedno okienko filtra (Popup) używane przez wszystkie tabele
    if ($script:ColumnFilterUi) { return $script:ColumnFilterUi }
    $root = New-UiElement $script:ColumnFilterXaml
    $ui = @{ Root = $root; Module = $null; Column = ''; Values = @(); Matches = @(); Rendering = $false; Checked = $null; AllState = $true }
    foreach ($n in 'fTitle', 'fSortAsc', 'fSortDesc', 'fOp', 'fText', 'fCount', 'fSearch', 'fAll', 'fScroll', 'fList', 'fNote', 'fClear', 'fCancel', 'fApply') { $ui[$n] = $root.FindName($n) }
    foreach ($k in $script:FilterOps.Keys) { [void]$ui.fOp.Items.Add($k) }
    $ui.fSortAsc.Content = New-IconContent -Text '' -Icon 'E74A' -IconSize 12
    $ui.fSortDesc.Content = New-IconContent -Text '' -Icon 'E74B' -IconSize 12
    $ui.fClear.Content = New-IconContent -Text 'Wyczyść' -Icon 'E894' -IconSize 11
    $popup = New-Object System.Windows.Controls.Primitives.Popup
    $popup.Child = $root
    $popup.StaysOpen = $false
    $popup.AllowsTransparency = $true
    $popup.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
    $popup.PopupAnimation = [System.Windows.Controls.Primitives.PopupAnimation]::None
    $ui.Popup = $popup
    $script:ColumnFilterUi = $ui
    $ui.fList.AddHandler([System.Windows.Controls.Primitives.ToggleButton]::CheckedEvent, [System.Windows.RoutedEventHandler]$script:ColumnFilterEvents.ItemToggled)
    $ui.fList.AddHandler([System.Windows.Controls.Primitives.ToggleButton]::UncheckedEvent, [System.Windows.RoutedEventHandler]$script:ColumnFilterEvents.ItemToggled)
    $root.add_PreviewKeyDown($script:ColumnFilterEvents.KeyDown)
    Register-ControlHandler -Control $ui.fSearch -EventName 'TextChanged' -Module $null -Action { param($m) Update-ColumnFilterList }
    Register-ControlHandler -Control $ui.fAll -EventName 'Click' -Module $null -Action {
        param($m)
        $ui = $script:ColumnFilterUi
        # Stan sprzed kliknięcia: częściowy albo pusty -> zaznacz wszystkie (jak w Excelu), pełny -> odznacz
        $on = ($ui.AllState -ne $true)
        foreach ($v in $ui.Matches) { if ($on) { [void]$ui.Checked.Add($v) } else { [void]$ui.Checked.Remove($v) } }
        $ui.Rendering = $true
        try { foreach ($cb in $ui.fList.Children) { if ($cb -is [System.Windows.Controls.CheckBox]) { $cb.IsChecked = $on } } }
        finally { $ui.Rendering = $false }
        Update-ColumnFilterAllBox
    }
    Register-ControlHandler -Control $ui.fApply -EventName 'Click' -Module $null -Action { param($m) Complete-ColumnFilterUi }
    Register-ControlHandler -Control $ui.fCancel -EventName 'Click' -Module $null -Action { param($m) $script:ColumnFilterUi.Popup.IsOpen = $false }
    Register-ControlHandler -Control $ui.fClear -EventName 'Click' -Module $null -Action {
        param($m)
        $ui = $script:ColumnFilterUi
        $ui.Popup.IsOpen = $false
        Clear-ColumnFilters -Module $ui.Module -Column $ui.Column
    }
    Register-ControlHandler -Control $ui.fSortAsc -EventName 'Click' -Module $null -Action { param($m) $ui = $script:ColumnFilterUi; $ui.Popup.IsOpen = $false; Set-ResultSort -Module $ui.Module -Column $ui.Column }
    Register-ControlHandler -Control $ui.fSortDesc -EventName 'Click' -Module $null -Action { param($m) $ui = $script:ColumnFilterUi; $ui.Popup.IsOpen = $false; Set-ResultSort -Module $ui.Module -Column $ui.Column -Descending }
    return $ui
}

function Show-ColumnFilter {
    # Okienko filtra kolumny pod lejkiem w nagłówku (albo pod nagłówkiem siatki, gdy wywołane z menu)
    param([Parameter(Mandatory)][hashtable]$Module, [Parameter(Mandatory)][string]$Column, $Anchor = $null)
    Complete-GridEdit -Module $Module
    $ui = Initialize-ColumnFilterUi
    $ui.Module = $Module
    $ui.Column = $Column
    $ui.Values = @(Get-ColumnValueCounts -Module $Module -Column $Column)
    $f = $Module.ColumnFilters[$Column]
    $ui.Checked = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::Ordinal)
    foreach ($v in $ui.Values) { if ($null -eq $f -or $null -eq $f.Values -or $f.Values.Contains($v.Text)) { [void]$ui.Checked.Add($v.Text) } }
    $ui.fTitle.Text = $Column
    $ui.fOp.SelectedItem = $(if ($f -and $f.Op) { Get-FilterOpLabel $f.Op } else { 'zawiera' })
    $ui.fText.Text = $(if ($f -and $f.Op) { [string]$f.Text } else { '' })
    $ui.fClear.IsEnabled = ($null -ne $f)
    $ui.Rendering = $true
    try { $ui.fSearch.Text = '' } finally { $ui.Rendering = $false }
    Update-ColumnFilterList
    if (-not $Anchor) { $Anchor = $(if ($Module.FilterButtons.ContainsKey($Column)) { $Module.FilterButtons[$Column] } else { $Module.Grid }) }
    if (-not $Anchor.IsVisible) { $Anchor = $Module.Grid }
    $ui.Popup.PlacementTarget = $Anchor
    $ui.Popup.IsOpen = $true
    [void]$ui.fSearch.Focus()
}

function Update-ColumnFilterList {
    # Lista pól wyboru wartości (z wyszukiwaniem; najwyżej $script:FilterListLimit pozycji naraz)
    $ui = $script:ColumnFilterUi
    if (-not $ui -or $ui.Rendering) { return }
    $q = $ui.fSearch.Text.Trim()
    $hits = @(if ($q) { $ui.Values | Where-Object { $_.Text.IndexOf($q, [StringComparison]::CurrentCultureIgnoreCase) -ge 0 -or ($_.Text -eq '' -and '(puste)'.Contains($q.ToLowerInvariant())) } } else { $ui.Values })
    $ui.Matches = @($hits | ForEach-Object { $_.Text })
    $ui.Rendering = $true
    try {
        $ui.fList.Children.Clear()
        foreach ($v in @($hits | Select-Object -First $script:FilterListLimit)) {
            $cb = New-Object System.Windows.Controls.CheckBox
            $cb.Tag = $v.Text
            $cb.Margin = '0,3,0,3'
            $cb.IsChecked = $ui.Checked.Contains($v.Text)
            $sp = New-Object System.Windows.Controls.StackPanel
            $sp.Orientation = 'Horizontal'
            $label = New-Object System.Windows.Controls.TextBlock
            if ($v.Text -eq '') { $label.Text = '(puste)'; $label.FontStyle = 'Italic'; $label.Foreground = Get-Brush '#8791A5' }
            else { $label.Text = $(if ($v.Text.Length -gt 80) { $v.Text.Substring(0, 80) + '…' } else { $v.Text }) -replace '[\r\n]+', ' ' }
            $label.MaxWidth = 230
            $label.TextTrimming = 'CharacterEllipsis'
            [void]$sp.Children.Add($label)
            $count = New-Object System.Windows.Controls.TextBlock
            $count.Text = '  ' + $v.Count
            $count.Foreground = Get-Brush '#5E6779'
            $count.FontSize = 11
            $count.VerticalAlignment = 'Center'
            [void]$sp.Children.Add($count)
            $cb.Content = $sp
            if ($v.Text.Length -gt 30) { $cb.ToolTip = $v.Text }
            [void]$ui.fList.Children.Add($cb)
        }
    }
    finally { $ui.Rendering = $false }
    $ui.fScroll.ScrollToTop()
    $ui.fCount.Text = $(if ($q) { "{0} z {1}" -f $hits.Count, $ui.Values.Count } else { [string]$ui.Values.Count })
    if ($hits.Count -gt $script:FilterListLimit) {
        $ui.fNote.Text = "Pokazano $script:FilterListLimit z $($hits.Count) wartości – zawęź listę wyszukiwaniem albo użyj warunku. «Zaznacz wszystkie» obejmuje także niewidoczne."
        $ui.fNote.Visibility = 'Visible'
    }
    elseif ($q) {
        $ui.fNote.Text = 'Filtr obejmie tylko zaznaczone wartości spośród wyszukanych.'
        $ui.fNote.Visibility = 'Visible'
    }
    else { $ui.fNote.Visibility = 'Collapsed' }
    Update-ColumnFilterAllBox
}

function Update-ColumnFilterAllBox {
    $ui = $script:ColumnFilterUi
    $on = 0
    foreach ($v in $ui.Matches) { if ($ui.Checked.Contains($v)) { $on++ } }
    $ui.AllState = $(if ($ui.Matches.Count -gt 0 -and $on -eq $ui.Matches.Count) { $true } elseif ($on -eq 0) { $false } else { $null })
    $ui.Rendering = $true
    try {
        $ui.fAll.IsChecked = $ui.AllState
        $ui.fAll.Content = $(if ($ui.fSearch.Text.Trim()) { '(Zaznacz wszystkie wyszukane)' } else { '(Zaznacz wszystkie)' })
    }
    finally { $ui.Rendering = $false }
}

function Complete-ColumnFilterUi {
    # «Filtruj»: wybrane wartości + warunek -> filtr kolumny
    $ui = $script:ColumnFilterUi
    $all = @($ui.Values | ForEach-Object { $_.Text })
    $source = if ($ui.fSearch.Text.Trim()) { $ui.Matches } else { $all }
    $selected = @($source | Where-Object { $ui.Checked.Contains($_) })
    # Bezpośrednie przypisanie: pusta tablica (nic nie zaznaczono) nie może zamienić się w $null (= brak filtra)
    $values = $null
    if ($selected.Count -ne $all.Count) { $values = $selected }
    $op = if ($ui.fOp.SelectedItem) { $script:FilterOps[[string]$ui.fOp.SelectedItem] } else { '' }
    $text = $ui.fText.Text
    if ($op -ne 'empty' -and $op -ne 'notempty' -and $text.Trim() -eq '') { $op = '' }
    $ui.Popup.IsOpen = $false
    Set-ColumnFilter -Module $ui.Module -Column $ui.Column -Values $values -Op $op -Text $text.Trim()
}

function Add-QuickFilterMenu {
    # Pozycje menu kontekstowego: filtr po wartości klikniętej komórki
    param([hashtable]$Module, $Menu)
    $cell = $Module.MenuCell
    if (-not $cell -or -not $cell.Column -or $Module.SecretColumns -contains $cell.Column -or -not $Module.Table.Columns.Contains($cell.Column)) { return }
    $text = Get-FilterText (Get-ObjectValue $cell.Row $cell.Column)
    $shown = if ($text -eq '') { '(puste)' } elseif ($text.Length -gt 40) { $text.Substring(0, 40) + '…' } else { $text }
    $shown = $shown -replace '[\r\n]+', ' '
    [void]$Menu.Items.Add((New-MenuItem -Text ("Pokaż tylko «{0}»" -f $shown) -Icon 'E71C' -Module $Module -Action {
                param($m)
                $c = $m.MenuCell
                Set-ColumnFilter -Module $m -Column $c.Column -Values @(Get-FilterText (Get-ObjectValue $c.Row $c.Column))
            }))
    [void]$Menu.Items.Add((New-MenuItem -Text ("Ukryj «{0}»" -f $shown) -Icon 'E8F6' -Module $Module -Action {
                param($m)
                $c = $m.MenuCell
                $hide = Get-FilterText (Get-ObjectValue $c.Row $c.Column)
                $current = $m.ColumnFilters[$c.Column]
                $keep = @(Get-ColumnValueCounts -Module $m -Column $c.Column | ForEach-Object { $_.Text } | Where-Object { $_ -ne $hide -and ($null -eq $current -or $null -eq $current.Values -or $current.Values.Contains($_)) })
                Set-ColumnFilter -Module $m -Column $c.Column -Values $keep -Op $(if ($current) { $current.Op } else { '' }) -Text $(if ($current) { $current.Text } else { '' })
            }))
    [void]$Menu.Items.Add((New-MenuItem -Text ("Filtruj kolumnę «{0}»…" -f $cell.Column) -Icon 'E71C' -Module $Module -Action { param($m) Show-ColumnFilter -Module $m -Column $m.MenuCell.Column }))
    if ($Module.ColumnFilters.Count -gt 0) {
        [void]$Menu.Items.Add((New-MenuItem -Text 'Wyczyść filtry kolumn' -Icon 'E894' -Module $Module -Action { param($m) Clear-ColumnFilters -Module $m }))
    }
}

function Update-HeaderMenu {
    # Menu pod prawym przyciskiem na nagłówku kolumny
    param([hashtable]$Module, $Menu, [string]$Column)
    $name = $Column
    $canFilter = $Module.SecretColumns -notcontains $name
    [void]$Menu.Items.Add((New-MenuItem -Text 'Sortuj rosnąco' -Icon 'E74A' -Module $Module -Action { param($m) Set-ResultSort -Module $m -Column $m.MenuCell.Column }))
    [void]$Menu.Items.Add((New-MenuItem -Text 'Sortuj malejąco' -Icon 'E74B' -Module $Module -Action { param($m) Set-ResultSort -Module $m -Column $m.MenuCell.Column -Descending }))
    [void]$Menu.Items.Add((New-MenuSeparator))
    [void]$Menu.Items.Add((New-MenuItem -Text 'Filtruj…' -Icon 'E71C' -Module $Module -Enabled $canFilter -Action { param($m) Show-ColumnFilter -Module $m -Column $m.MenuCell.Column }))
    [void]$Menu.Items.Add((New-MenuItem -Text 'Wyczyść filtr kolumny' -Icon 'E894' -Module $Module -Enabled ($Module.ColumnFilters.Contains($name)) -Action { param($m) Clear-ColumnFilters -Module $m -Column $m.MenuCell.Column }))
    [void]$Menu.Items.Add((New-MenuItem -Text 'Wyczyść wszystkie filtry kolumn' -Icon 'E894' -Module $Module -Enabled ($Module.ColumnFilters.Count -gt 0) -Action { param($m) Clear-ColumnFilters -Module $m }))
    [void]$Menu.Items.Add((New-MenuSeparator))
    [void]$Menu.Items.Add((New-MenuItem -Text 'Ukryj kolumnę' -Icon 'ED1A' -Module $Module -Action {
                param($m)
                foreach ($c in $m.Grid.Columns) { if ([string]$c.SortMemberPath -eq $m.MenuCell.Column) { $c.Visibility = 'Collapsed' } }
                Show-Toast "Ukryto kolumnę «$($m.MenuCell.Column)» – nie trafi do eksportu. «Pokaż wszystkie kolumny» w menu nagłówka ją przywróci." 'info'
            }))
    $hidden = @($Module.Grid.Columns | Where-Object { $_.Visibility -ne 'Visible' }).Count
    [void]$Menu.Items.Add((New-MenuItem -Text $(if ($hidden) { "Pokaż wszystkie kolumny (ukryte: $hidden)" } else { 'Pokaż wszystkie kolumny' }) -Icon 'E7B3' -Module $Module -Enabled ($hidden -gt 0) -Action {
                param($m)
                foreach ($c in $m.Grid.Columns) { $c.Visibility = 'Visible' }
            }))
}

function Find-VisualParent {
    param($Element, [type]$Type)
    $e = $Element
    while ($e) {
        if ($e -is $Type) { return $e }
        if ($e -is [System.Windows.Media.Visual] -or $e -is [System.Windows.Media.Media3D.Visual3D]) { $e = [System.Windows.Media.VisualTreeHelper]::GetParent($e) }
        elseif ($e -is [System.Windows.FrameworkContentElement]) { $e = $e.Parent }
        else { $e = $null }
    }
    return $null
}
#endregion

#region Wspólne elementy raportów HTML (style, skrypt, nagłówek i pasek narzędzi)
# Wszystkie raporty HTML programu korzystają z tych samych stylów i jednego skryptu:
#  - przyciski działają przez atrybut data-act (bez onclick - w atrybutach onclick nazwy takie jak «all»
#    trafiają na document.all zamiast na funkcję raportu),
#  - tabele class="dt": sortowanie po kliknięciu nagłówka, filtr pod każdą kolumną, akcje wiersza
#    (kopiuj, otwórz w osobnym oknie), kopiowanie widocznych wierszy do Excela,
#  - karty class="card" i gałęzie drzewa: kopiowanie i otwieranie w osobnym oknie,
#  - wyszukiwarka #q w trybie cards / rows / tree, zwijanie i rozwijanie list, druk z rozwiniętymi listami.
# Raport nie pobiera niczego z sieci.
$script:ReportCss = @'
:root{--bg:#0F1318;--card:#161B22;--card2:#1B212A;--line:#242B36;--line2:#222935;--text:#E4E8EF;--muted:#8791A5;--faint:#5E6779;--ok:#5EE3AE;--warn:#FFC46B;--crit:#FF7A86;--info:#8CC0FF;--accent:#3E6FE0}
*{box-sizing:border-box}body{margin:0;padding:28px 32px;background:var(--bg);color:var(--text);font:13.5px/1.5 "Segoe UI",system-ui,sans-serif}body.popup{padding:20px 22px}a{color:var(--info);text-decoration:none}a:hover{text-decoration:underline}
h1{font-size:24px;margin:0 0 4px}.meta{color:var(--muted);margin-bottom:18px}
.tiles{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px}.tile{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 18px;min-width:140px}.tile b{display:block;font-size:22px;font-weight:600}.tile span{color:var(--muted);font-size:12px}
.tile.ok b{color:var(--ok)}.tile.warn b{color:var(--warn)}.tile.crit b{color:var(--crit)}.tile.info b{color:var(--info)}
.bar{position:sticky;top:0;z-index:5;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}
input,select{background:var(--card2);color:var(--text);border:1px solid #2A323F;border-radius:7px;padding:7px 10px;font:inherit}.bar input#q{flex:0 1 380px}input[type=checkbox]{width:16px;height:16px;padding:0;margin:0;accent-color:#3E6FE0}
button{background:var(--accent);color:#fff;border:0;border-radius:7px;padding:7px 14px;font:inherit;cursor:pointer}button.g{background:#1E252F;color:#C9D0DC}button:hover{filter:brightness(1.12)}.cnt{color:var(--muted);margin-left:auto}
label.opt{display:inline-flex;align-items:center;gap:7px;color:#C9D0DC;cursor:pointer;white-space:nowrap}
.box{background:var(--card);border:1px solid var(--line);border-radius:12px;margin-bottom:18px;overflow:auto;max-height:80vh}
table{border-collapse:collapse;width:100%}th{background:#1B212A;color:var(--muted);text-align:left;font-weight:600;padding:8px 12px;border-bottom:1px solid var(--line);white-space:nowrap;font-size:12.5px;position:sticky;top:0;z-index:2}
td{padding:6px 12px;border-bottom:1px solid #1F2530;vertical-align:top;white-space:pre-wrap}tr:nth-child(even) td{background:#181E26}
table.dt th.s{cursor:pointer;user-select:none}table.dt th.s:hover{color:var(--text)}table.dt th.asc::after{content:" ▲";color:var(--info)}table.dt th.desc::after{content:" ▼";color:var(--info)}
table.dt tr.fl th{top:35px;padding:4px 6px;background:#181E26}table.dt tr.fl input{width:100%;min-width:70px;padding:3px 7px;font-size:12px;border-radius:5px}
td.ra{white-space:nowrap;width:1%;padding:3px 6px}.ra button,.acts button,.cacts button{background:transparent;color:var(--muted);padding:1px 6px;border-radius:5px;font-size:13px;line-height:1.3}
.ra button:hover,.acts button:hover,.cacts button:hover{background:#2A3342;color:var(--text);filter:none}tbody tr .ra{opacity:.35}tbody tr:hover .ra{opacity:1}
tr.crit td{color:var(--crit)}tr.warn td{color:var(--warn)}tr.muted td{color:#7B8496}
.pill{display:inline-block;padding:2px 11px;border-radius:10px;font-weight:600;font-size:12.5px;white-space:nowrap;background:#1E252F;color:#AEB6C4}.pill.ok{color:var(--ok);background:#15291F}.pill.warn{color:var(--warn);background:#2E2616}.pill.crit{color:var(--crit);background:#2E1A1E}.pill.info{color:var(--info);background:#1A2640}
.chips{margin:10px 0 0}.chip{display:inline-block;font-size:11.5px;padding:1px 9px;border-radius:9px;margin:0 6px 4px 0;background:#1E252F;color:#C9D0DC}.chip.warn{background:#2E2616;color:var(--warn)}.chip.crit{background:#2E1A1E;color:var(--crit)}.chip.info{background:#1A2640;color:var(--info)}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px 20px;margin:0 0 16px;scroll-margin-top:80px}
.head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.head h2{margin:0;font-size:18px}.sub{color:var(--muted);margin-top:2px}.top{font-size:12px;color:var(--faint)}.cacts{margin-top:4px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:12px;margin-top:14px}.sec{background:var(--card2);border:1px solid var(--line2);border-radius:10px;padding:10px 14px}
.sec h3{margin:0 0 6px;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--faint)}dl{display:grid;grid-template-columns:minmax(130px,42%) 1fr;gap:3px 12px;margin:0}dt{color:var(--muted)}dd{margin:0;word-break:break-word}dd.e{color:#3F4757}
details{margin-top:12px;border:1px solid var(--line2);border-radius:10px;background:var(--card2);overflow:auto}summary{cursor:pointer;padding:9px 14px;font-weight:600;list-style:none}summary::-webkit-details-marker{display:none}summary::before{content:"▸";display:inline-block;width:16px;color:var(--muted)}details[open]>summary::before{content:"▾";color:var(--info)}
.n{display:inline-block;margin-left:6px;padding:0 8px;border-radius:8px;background:#1A2640;color:var(--info);font-size:11.5px}.empty{padding:2px 14px 12px;color:var(--faint)}.note{padding:6px 14px 10px;color:var(--warn);font-size:12px}
.lf{padding:2px 14px 8px}.lf input{width:260px;padding:4px 8px;font-size:12px}
.tree details{margin:0 0 0 22px;border:0;background:transparent;overflow:visible}.tree details.root{margin:6px 0;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:6px 10px}
.tree summary{padding:3px 4px;border-radius:6px;font-weight:400}.tree summary:hover{background:#1D2430}.leaf{margin-left:38px;padding:2px 4px;color:#AEB6C4;border-radius:6px}.leaf:hover{background:#1D2430}
.acts{display:inline-block;margin-left:8px;opacity:0}summary:hover>.acts,.leaf:hover>.acts{opacity:1}
.k{display:inline-block;font-size:11px;padding:0 7px;border-radius:8px;background:#1A2640;color:#8CC0FF;margin-left:8px}.d{color:#7B8496;font-style:italic;margin-left:8px}.w{color:#FF7A86;margin-left:8px}.m{color:#5E6779}
.hit{background:#2E2616 !important;outline:1px solid #FFC46B}.hide{display:none !important}
.errs{border-color:#4A2A32}.errs h2{color:var(--crit);font-size:15px;margin:0;padding:12px 14px}
#dop-toast{position:fixed;right:20px;bottom:20px;background:#1E2530;border:1px solid #2F3846;color:var(--text);padding:9px 16px;border-radius:9px;opacity:0;transition:opacity .2s;pointer-events:none;z-index:50}#dop-toast.on{opacity:1}
@media print{body{background:#fff;color:#111;padding:0;font-size:11.5px}.bar,.top,.cacts,.acts,.ra,tr.fl,.lf,#dop-toast{display:none !important}.tile,.card,.sec,details,.box{background:#fff !important;border-color:#bbb;max-height:none}.card{break-inside:avoid-page}
th{background:#eee;color:#333;position:static}td{border-color:#ddd}tr:nth-child(even) td{background:#fff}dt,.sub,.meta,.tile span,.sec h3{color:#555}.pill,.chip,.n,.k{border:1px solid #999;background:#fff !important;color:#111 !important}a{color:#111}.tile b{color:#111 !important}.hide{display:none !important}}
'@

$script:ReportJs = @'
(function(){
"use strict";
function T(el){return (el.innerText||el.textContent||"").replace(/ /g," ").trim();}
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
var tt=null;function toast(m){var t=document.getElementById("dop-toast");if(!t)return;t.textContent=m;t.classList.add("on");clearTimeout(tt);tt=setTimeout(function(){t.classList.remove("on")},1800);}
function fallbackCopy(s){var a=document.createElement("textarea");a.value=s;a.style.position="fixed";a.style.top="-1000px";document.body.appendChild(a);a.select();var ok=false;try{ok=document.execCommand("copy")}catch(e){}document.body.removeChild(a);toast(ok?"Skopiowano do schowka":"Nie udało się skopiować");}
function copy(s){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(s).then(function(){toast("Skopiowano do schowka")},function(){fallbackCopy(s)})}else{fallbackCopy(s)}}
function openWin(title,html){var w=window.open("","_blank","width=980,height=720,resizable=yes,scrollbars=yes");if(!w){toast("Przeglądarka zablokowała nowe okno – zezwól na wyskakujące okna dla tego pliku");return;}
var css=document.getElementById("dop-css");w.document.open();w.document.write("<!DOCTYPE html><html lang=\"pl\"><head><meta charset=\"utf-8\"><title>"+esc(title)+"</title><style>"+(css?css.textContent:"")+"</style></head><body class=\"popup\">"+html+"</body></html>");w.document.close();}
function clean(el){var c=el.cloneNode(true);c.querySelectorAll(".acts,.cacts,.ra,.lf,tr.fl,.top").forEach(function(x){x.remove()});c.querySelectorAll("details").forEach(function(d){d.open=true});c.querySelectorAll(".hide").forEach(function(x){x.classList.remove("hide")});return c;}
function heads(tbl){var r=tbl.tHead?tbl.tHead.rows[0]:null;if(!r)return[];return Array.prototype.filter.call(r.cells,function(c){return !c.classList.contains("ra")}).map(T);}
function cellsOf(tr){return Array.prototype.filter.call(tr.cells,function(c){return !c.classList.contains("ra")});}
function rowLines(tr){var tbl=tr.closest("table"),h=heads(tbl),c=cellsOf(tr),out=[];for(var i=0;i<c.length;i++){var v=T(c[i]);if(v!=="")out.push((h[i]||("Kolumna "+(i+1)))+": "+v);}return out.join("\n");}
function rowHtml(tr){var tbl=tr.closest("table"),h=heads(tbl),c=cellsOf(tr),s="<h1>"+esc(T(c[0]||tr))+"</h1><div class=\"meta\">"+esc(document.title)+"</div><div class=\"box\"><table>";for(var i=0;i<c.length;i++){s+="<tr><th style=\"position:static\">"+esc(h[i]||"")+"</th><td>"+c[i].innerHTML+"</td></tr>";}return s+"</table></div>";}
function visibleTsv(tbl){var h=heads(tbl),lines=[h.join("\t")];Array.prototype.forEach.call(tbl.tBodies[0].rows,function(tr){if(tr.classList.contains("hide")||tr.style.display==="none")return;lines.push(cellsOf(tr).map(function(c){return T(c).replace(/[\t\r\n]+/g," ")}).join("\t"));});return {text:lines.join("\n"),n:lines.length-1};}
function nodeText(el,depth){var pad=new Array(depth+1).join("  ");if(el.classList&&el.classList.contains("leaf"))return pad+T(el)+"\n";var s=el.querySelector(":scope>summary");var out=pad+(s?T(s):"")+"\n";Array.prototype.forEach.call(el.children,function(ch){if(ch.tagName==="DETAILS"||(ch.classList&&ch.classList.contains("leaf")))out+=nodeText(ch,depth+1);});return out;}
function num(s){var t=String(s).replace(/\s/g,"").replace(",",".");return (t!==""&&!isNaN(t))?parseFloat(t):null;}
function cmp(a,b){var x=num(a),y=num(b);if(x!==null&&y!==null)return x-y;return a.localeCompare(b,"pl",{sensitivity:"base",numeric:true});}
function match(v,f){if(!f)return true;var neg=false;if(f.charAt(0)==="!"){neg=true;f=f.slice(1);if(!f)return true;}var lv=v.toLowerCase(),r;
if(f.charAt(0)==="="){r=lv===f.slice(1).toLowerCase();}else if(f.charAt(0)===">"||f.charAt(0)==="<"){var a=f.slice(1).trim(),x=num(v),y=num(a);var c=(x!==null&&y!==null)?x-y:v.localeCompare(a,"pl",{numeric:true});r=f.charAt(0)===">"?c>0:c<0;if(v==="")r=false;}else{r=lv.indexOf(f.toLowerCase())>=0;}return neg?!r:r;}
function applyTable(tbl){var fr=tbl.tHead.querySelector("tr.fl");var fs=fr?Array.prototype.map.call(fr.querySelectorAll("input"),function(i){return i.value.trim()}):[];var q=tbl.getAttribute("data-q")||"";var n=0,tot=0;
Array.prototype.forEach.call(tbl.tBodies[0].rows,function(tr){tot++;var c=cellsOf(tr),ok=true;for(var i=0;i<fs.length&&ok;i++){if(fs[i]&&!match(T(c[i]||tr),fs[i]))ok=false;}if(ok&&q){ok=T(tr).toLowerCase().indexOf(q)>=0;}tr.classList.toggle("hide",!ok);if(ok)n++;});
var cnt=document.querySelector("[data-count-for=\""+tbl.id+"\"]");if(cnt)cnt.textContent=(n===tot?String(tot):n+" z "+tot);return n;}
function initTable(tbl,i){if(!tbl.id)tbl.id="dt"+i;var h=tbl.tHead?tbl.tHead.rows[0]:null;if(!h||!tbl.tBodies[0])return;var cols=h.cells.length;
Array.prototype.forEach.call(h.cells,function(th,ci){th.classList.add("s");th.title="Kliknij, aby posortować";th.addEventListener("click",function(){var asc=!th.classList.contains("asc");Array.prototype.forEach.call(h.cells,function(x){x.classList.remove("asc","desc")});th.classList.add(asc?"asc":"desc");var rows=Array.prototype.slice.call(tbl.tBodies[0].rows);rows.sort(function(a,b){var r=cmp(T(cellsOf(a)[ci]||a),T(cellsOf(b)[ci]||b));return asc?r:-r;});rows.forEach(function(r){tbl.tBodies[0].appendChild(r)});});});
if(tbl.getAttribute("data-filters")!=="no"){var fr=document.createElement("tr");fr.className="fl";for(var c=0;c<cols;c++){var th=document.createElement("th"),inp=document.createElement("input");inp.placeholder="filtr…";inp.title="Zawiera tekst; !tekst – nie zawiera; =tekst – dokładnie; >10, <2026-01-01 – większe/mniejsze";inp.addEventListener("input",function(){applyTable(tbl)});th.appendChild(inp);fr.appendChild(th);}var e=document.createElement("th");e.className="ra";fr.appendChild(e);tbl.tHead.appendChild(fr);}
var eh=document.createElement("th");eh.className="ra";h.appendChild(eh);
Array.prototype.forEach.call(tbl.tBodies[0].rows,function(tr){var td=document.createElement("td");td.className="ra";td.innerHTML="<button data-act=\"copy-row\" title=\"Kopiuj wiersz\">⧉</button><button data-act=\"open-row\" title=\"Otwórz w osobnym oknie\">↗</button>";tr.appendChild(td);});}
function search(){var q=document.getElementById("q");if(!q)return;var v=q.value.trim().toLowerCase(),mode=q.getAttribute("data-mode")||"cards",n=0;
if(mode==="rows"){document.querySelectorAll("table.dt").forEach(function(t){t.setAttribute("data-q",v);n+=applyTable(t)});}
else if(mode==="tree"){document.querySelectorAll(".hit").forEach(function(e){e.classList.remove("hit")});document.querySelectorAll(".tree details.root").forEach(function(r){var h=!v||T(r).toLowerCase().indexOf(v)>=0;r.classList.toggle("hide",!h);if(h)n++;});if(v){document.querySelectorAll(".tree summary,.tree .leaf").forEach(function(e){var own=e.cloneNode(true);own.querySelectorAll(".acts").forEach(function(x){x.remove()});if(T(own).toLowerCase().indexOf(v)>=0){e.classList.add("hit");var p=e.parentElement;while(p&&p.tagName==="DETAILS"){p.open=true;p=p.parentElement;}}});}}
else{document.querySelectorAll(".card").forEach(function(c){var h=!v||T(c).toLowerCase().indexOf(v)>=0;c.classList.toggle("hide",!h);if(h)n++;var t=document.getElementById("t-"+c.id);if(t)t.classList.toggle("hide",!h);});}
var cnt=document.getElementById("cnt");if(cnt)cnt.textContent=n;}
document.addEventListener("click",function(ev){var b=ev.target.closest("[data-act]");if(!b)return;var a=b.getAttribute("data-act");if(b.closest("summary"))ev.preventDefault();
if(a==="expand"||a==="collapse"){var sel=b.getAttribute("data-sel")||"details";document.querySelectorAll(sel).forEach(function(d){d.open=(a==="expand")});}
else if(a==="print"){window.print();}
else if(a==="copy-row"){copy(rowLines(b.closest("tr")));}
else if(a==="open-row"){var tr=b.closest("tr");openWin(T(cellsOf(tr)[0]||tr),rowHtml(tr));}
else if(a==="copy-card"){copy(T(clean(b.closest(".card"))));}
else if(a==="open-card"){var c=b.closest(".card");var h2=c.querySelector("h2");openWin(h2?T(h2):document.title,clean(c).outerHTML);}
else if(a==="copy-node"){var n=b.closest(".leaf")||b.closest("details");copy(nodeText(n,0).replace(/\s+$/,""));}
else if(a==="open-node"){var d=b.closest("details");var s=d.querySelector(":scope>summary");var c=clean(d);c.open=true;c.classList.add("root");openWin(s?T(clean(s)):document.title,"<div class=\"tree\">"+c.outerHTML+"</div>");}
else if(a==="copy-visible"){var t=document.getElementById(b.getAttribute("data-table"))||document.querySelector("table.dt");if(t){var r=visibleTsv(t);copy(r.text);}}
else if(a==="clear-filters"){document.querySelectorAll("table.dt tr.fl input").forEach(function(i){i.value=""});var q=document.getElementById("q");if(q)q.value="";document.querySelectorAll("table.dt").forEach(function(t){t.setAttribute("data-q","");applyTable(t)});search();}
else if(a==="toggle"){var tg=b.getAttribute("data-class");document.body.classList.toggle(tg,b.checked);}});
document.addEventListener("change",function(ev){var b=ev.target;if(b.getAttribute&&b.getAttribute("data-act")==="toggle"){document.body.classList.toggle(b.getAttribute("data-class"),b.checked);}});
document.querySelectorAll("table.dt").forEach(initTable);
document.querySelectorAll(".lf input").forEach(function(inp){inp.addEventListener("input",function(){var t=document.getElementById(inp.getAttribute("data-table"));if(t){t.setAttribute("data-q",inp.value.trim().toLowerCase());applyTable(t);}})});
var q=document.getElementById("q");if(q)q.addEventListener("input",search);
window.addEventListener("beforeprint",function(){document.querySelectorAll("details").forEach(function(d){d.open=true})});
window.dopReport={copy:copy,openWin:openWin,applyTable:applyTable,search:search};
})();
'@

function Get-ReportHead {
    # Początek dokumentu: tytuł, wspólne style (+ dodatkowe) i nagłówek z metadanymi
    param([string]$Title, [string]$Meta = '', [string]$ExtraCss = '')
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append('<!DOCTYPE html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>').Append((ConvertTo-HtmlText $Title)).Append('</title><style id="dop-css">')
    [void]$sb.Append($script:ReportCss).Append($ExtraCss).Append('</style></head><body><h1>').Append((ConvertTo-HtmlText $Title)).Append('</h1>')
    if ($Meta) { [void]$sb.Append('<div class="meta">').Append((ConvertTo-HtmlText $Meta)).Append('</div>') }
    return $sb.ToString()
}

function Get-ReportBar {
    # Pasek narzędzi: wyszukiwarka (tryb cards / rows / tree) i przyciski
    param([string]$Mode = 'cards', [string]$Placeholder = 'Szukaj…', [string[]]$Buttons = @('expand', 'collapse', 'print'), [int]$Count = -1, [string]$Extra = '')
    $labels = @{
        expand  = '<button data-act="expand">Rozwiń listy</button>'
        collapse = '<button class="g" data-act="collapse">Zwiń listy</button>'
        print   = '<button class="g" data-act="print">Drukuj</button>'
        copy    = '<button class="g" data-act="copy-visible" title="Widoczne wiersze w formacie Excela (z nagłówkami)">Kopiuj widoczne</button>'
        clear   = '<button class="g" data-act="clear-filters">Wyczyść filtry</button>'
    }
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append('<div class="bar"><input id="q" data-mode="').Append($Mode).Append('" placeholder="').Append((ConvertTo-HtmlText $Placeholder)).Append('">')
    foreach ($b in $Buttons) { if ($labels.ContainsKey($b)) { [void]$sb.Append($labels[$b]) } }
    [void]$sb.Append($Extra)
    if ($Count -ge 0) { [void]$sb.Append('<span class="cnt">widoczne: <b id="cnt">').Append($Count).Append('</b></span>') }
    [void]$sb.Append('</div>')
    return $sb.ToString()
}

function Get-ReportTail {
    return '<div id="dop-toast"></div><script>' + $script:ReportJs + '</script></body></html>'
}
#endregion

#region Silnik operacji w tle
# Każdy obiekt docelowy to osobne zadanie w puli wątków. Tryb 'Remote' wykonuje blok skryptu na komputerze
# przez Invoke-Command (blok dostaje jeden parametr: hashtablę $P). Tryb 'Local' wykonuje blok lokalnie
# z parametrami ($Target, $P, $Ctx) - np. polecenia AD, kopiowanie plików albo połączenie obu podejść.
# Wyniki odbiera timer w wątku okna, więc wszystkie aktualizacje interfejsu są bezpieczne.
$script:WorkerScript = @'
param($Target, $Mode, $ScriptText, $P, $Ctx)
$ProgressPreference = 'SilentlyContinue'
$result = @{ Target = $Target; Ok = $true; Data = @(); Errors = @() }
try {
    $sb = [scriptblock]::Create($ScriptText)
    if ($Mode -eq 'Remote') {
        $icErrors = $null
        $ic = @{
            ComputerName  = $Target
            ScriptBlock   = $sb
            ArgumentList  = @(, $P)
            ErrorAction   = 'SilentlyContinue'
            ErrorVariable = 'icErrors'
        }
        if ($Ctx.Credential) { $ic.Credential = $Ctx.Credential }
        if ($Ctx.SessionOption) { $ic.SessionOption = $Ctx.SessionOption }
        $result.Data = @(Invoke-Command @ic)
        if ($icErrors) { $result.Errors = @($icErrors | ForEach-Object { $_.Exception.Message }) }
    }
    else {
        $raw = @(& $sb $Target $P $Ctx 2>&1)
        $result.Data = @($raw | Where-Object { $_ -isnot [System.Management.Automation.ErrorRecord] })
        $result.Errors = @($raw | Where-Object { $_ -is [System.Management.Automation.ErrorRecord] } | ForEach-Object { $_.Exception.Message })
    }
}
catch {
    $result.Errors = @($result.Errors) + @($_.Exception.Message)
}
if ($result.Errors.Count -gt 0 -and $result.Data.Count -eq 0) { $result.Ok = $false }
[pscustomobject]$result
'@

function New-EnginePool([int]$Max) {
    $iss = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
    # Zasady wykonywania dotyczą tylko Windows (na innych platformach Open() rzuciłby wyjątek)
    if ([System.Environment]::OSVersion.Platform -eq [System.PlatformID]::Win32NT) {
        try { $iss.ExecutionPolicy = [Microsoft.PowerShell.ExecutionPolicy]::Bypass } catch { }
    }
    $pool = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspacePool(1, $Max, $iss, $Host)
    $pool.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
    $pool.Open()
    return $pool
}

function Initialize-Engine {
    # Dwie pule wątków: ogólna (zdalne operacje na komputerach, pliki) i mniejsza dla zapytań do AD.
    # Usługa ADWS na kontrolerze domeny ogranicza równoległe żądania - przy kilkunastu naraz odrzuca je
    # błędami «A connection to the directory ... was unavailable» / «invalid enumeration context».
    param([switch]$Ad)
    if (-not $script:Engine.Pool) { $script:Engine.Pool = New-EnginePool ([int]$script:Settings.ThrottleLimit) }
    if ($Ad -and -not $script:Engine.AdPool) { $script:Engine.AdPool = New-EnginePool ([int]$script:Settings.AdThrottleLimit) }
}

function Initialize-EngineTimer {
    if ($script:Engine.Timer) { return }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(150)
    $timer.add_Tick({ param($s, $e) Update-Operations })
    $script:Engine.Timer = $timer
}

function Set-EngineThrottle([int]$Limit, [int]$AdLimit = 0) {
    $script:Settings.ThrottleLimit = [Math]::Min(64, [Math]::Max(1, $Limit))
    if ($script:Engine.Pool) {
        try { [void]$script:Engine.Pool.SetMaxRunspaces($script:Settings.ThrottleLimit) } catch { }
    }
    if ($AdLimit -gt 0) {
        $script:Settings.AdThrottleLimit = [Math]::Min(16, [Math]::Max(1, $AdLimit))
        if ($script:Engine.AdPool) {
            try { [void]$script:Engine.AdPool.SetMaxRunspaces($script:Settings.AdThrottleLimit) } catch { }
        }
    }
}

function Set-ModuleBusy {
    param([hashtable]$Module, [bool]$Busy, [string]$Text = '')
    $Module.Busy = $Busy
    foreach ($b in $Module.Buttons) { $b.IsEnabled = -not $Busy }
    $chip = $Module.View_['busyChip']
    if ($chip) {
        $chip.Visibility = if ($Busy) { 'Visible' } else { 'Collapsed' }
        if ($Text) { $Module.View_['busyText'].Text = $Text }
    }
    Update-ResultCount -Module $Module
    Update-NavBusy -Module $Module
}

function New-SessionOption {
    # Odpowiednik New-PSSessionOption -OpenTimeout (obiekt tworzony bezpośrednio)
    $option = New-Object System.Management.Automation.Remoting.PSSessionOption
    $option.OpenTimeout = [TimeSpan]::FromSeconds([int]$script:Settings.TimeoutSec)
    return $option
}

function Start-HostOperation {
    <#
        Uruchamia blok skryptu dla każdego obiektu z -Targets (komputery albo dowolne identyfikatory w trybie -Local).
        -Output Grid : wyniki trafiają do tabeli modułu (kolumna -TargetColumn + właściwości obiektów)
        -Output Log  : wyniki wypisywane są w dzienniku
        -Output None : tylko -OnResult/-OnComplete
        -PerTarget   : osobna hashtabla $P dla wybranych obiektów (np. różne usługi na różnych komputerach)
        -OnResult { param($m, $r) }   - po zakończeniu każdego obiektu ($r: Target, Ok, Data, Errors)
        -OnComplete { param($m, $op) } - po zakończeniu wszystkich (nie wywoływane po anulowaniu)
    #>
    param(
        [Parameter(Mandatory)][hashtable]$Module,
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Targets,
        [Parameter(Mandatory)][scriptblock]$ScriptBlock,
        [switch]$Local,
        [hashtable]$Parameters = @{},
        [hashtable]$PerTarget = @{},
        [ValidateSet('Grid', 'Log', 'None')][string]$Output = 'Grid',
        [string]$TargetColumn = 'Komputer',
        [switch]$Append,
        [scriptblock]$OnResult,
        [scriptblock]$OnComplete,
        [ValidateSet('Default', 'AD')][string]$Pool = 'Default'
    )
    if ($Module.Busy) {
        Show-Warning "Poprzednia operacja w module «$($Module.Title)» jeszcze trwa. Poczekaj na jej zakończenie lub przerwij ją na pasku stanu."
        return
    }
    $items = @($Targets | Where-Object { $_ } | ForEach-Object { $_.Trim() } | Select-Object -Unique)
    if ($items.Count -eq 0) { return }

    Initialize-Engine -Ad:($Pool -eq 'AD')
    Initialize-EngineTimer
    $runspacePool = if ($Pool -eq 'AD') { $script:Engine.AdPool } else { $script:Engine.Pool }
    if ($Output -eq 'Grid' -and -not $Append -and $Module.Grid) { Reset-ResultTable -Module $Module }

    $ctx = @{
        Credential    = Get-EffectiveCredential
        Server        = [string]$script:Settings.DomainController
        SessionOption = New-SessionOption
    }
    $mode = if ($Local) { 'Local' } else { 'Remote' }
    $scriptText = $ScriptBlock.ToString()

    $op = @{
        Id           = $script:Engine.NextId
        Name         = $Name
        Module       = $Module
        Output       = $Output
        TargetColumn = $TargetColumn
        OnResult     = $OnResult
        OnComplete   = $OnComplete
        Items        = New-Object System.Collections.ArrayList
        Total        = $items.Count
        Done         = 0
        Failed       = 0
        Cancelled    = $false
        CancelAt     = $null
        Started      = Get-Date
    }
    $script:Engine.NextId++

    foreach ($t in $items) {
        $p = $Parameters
        if ($PerTarget.ContainsKey($t)) { $p = $PerTarget[$t] }
        $ps = [System.Management.Automation.PowerShell]::Create()
        $ps.RunspacePool = $runspacePool
        [void]$ps.AddScript($script:WorkerScript)
        [void]$ps.AddArgument($t).AddArgument($mode).AddArgument($scriptText).AddArgument($p).AddArgument($ctx)
        $handle = $ps.BeginInvoke()
        [void]$op.Items.Add(@{ Target = $t; PS = $ps; Handle = $handle; Finished = $false })
    }

    [void]$script:Engine.Operations.Add($op)
    Set-ModuleBusy -Module $Module -Busy $true -Text ("{0}: 0/{1}" -f $Name, $items.Count)
    $list = (@($items | Select-Object -First 8) -join ', ')
    if ($items.Count -gt 8) { $list += ", … (+$($items.Count - 8))" }
    Write-Log ("{0} – start ({1}): {2}" -f $Name, $items.Count, $list) -Module $Module.Title
    $script:Engine.Timer.Start()
    Update-StatusBar
}

function Update-Operations {
    # Wywoływane przez timer w wątku okna
    if ($script:Engine.InTick) { return }
    $script:Engine.InTick = $true
    try {
        Clear-AbandonedTasks
        foreach ($op in @($script:Engine.Operations)) {
            $changed = $false
            $abandon = ($op.Cancelled -and $op.CancelAt -and ((Get-Date) - $op.CancelAt).TotalSeconds -ge $script:Engine.AbandonAfterSec)
            foreach ($item in $op.Items) {
                if (-not $item.Finished -and $abandon -and -not $item.Handle.IsCompleted) {
                    $item.Finished = $true
                    $changed = $true
                    [void]$script:Engine.Abandoned.Add(@{ PS = $item.PS; Handle = $item.Handle })
                    $msg = 'Przerwano – zadanie nie odpowiedziało i zostało porzucone (może jeszcze działać w tle albo na komputerze docelowym).'
                    Complete-OperationItem -Operation $op -Result ([pscustomobject]@{ Target = $item.Target; Ok = $false; Data = @(); Errors = @($msg) })
                    continue
                }
                if ($item.Finished -or -not $item.Handle.IsCompleted) { continue }
                $item.Finished = $true
                $changed = $true
                $r = $null
                try {
                    $output = $item.PS.EndInvoke($item.Handle)
                    if ($output -and $output.Count -gt 0) { $r = $output[0] }
                    if (-not $r) {
                        $msg = 'Zadanie nie zwróciło wyniku.'
                        if ($item.PS.Streams.Error.Count -gt 0) { $msg = $item.PS.Streams.Error[0].Exception.Message }
                        $r = [pscustomobject]@{ Target = $item.Target; Ok = $false; Data = @(); Errors = @($msg) }
                    }
                }
                catch {
                    $msg = if ($op.Cancelled) { 'Anulowano.' } else { $_.Exception.Message }
                    $r = [pscustomobject]@{ Target = $item.Target; Ok = $false; Data = @(); Errors = @($msg) }
                }
                finally {
                    try { $item.PS.Dispose() } catch { }
                }
                Complete-OperationItem -Operation $op -Result $r
            }
            if ($changed -and -not $op.Cancelled -and $op.Module.View_['busyText']) {
                $text = '{0}: {1}/{2}' -f $op.Name, $op.Done, $op.Total
                if ($op.Failed -gt 0) { $text += " • błędy: $($op.Failed)" }
                $op.Module.View_['busyText'].Text = $text
            }
            if ($op.Done -ge $op.Total) { Complete-Operation -Operation $op }
        }
    }
    catch {
        Write-Log "Błąd silnika operacji: $($_.Exception.Message)" 'ERROR' -Module ''
    }
    finally {
        $script:Engine.InTick = $false
        if ($script:Engine.Operations.Count -eq 0 -and $script:Engine.Timer) { $script:Engine.Timer.Stop() }
        Update-StatusBar
    }
    # Akcje odroczone (np. okna z wynikami) - wykonywane po zwolnieniu blokady, aby modalne okno
    # nie wstrzymywało odbierania wyników pozostałych operacji
    while ($script:Engine.Deferred.Count -gt 0) {
        $next = $script:Engine.Deferred[0]
        $script:Engine.Deferred.RemoveAt(0)
        Invoke-UiAction -Module $next.Module -Action $next.Action
    }
}

function Invoke-Deferred {
    param([hashtable]$Module, [scriptblock]$Action)
    [void]$script:Engine.Deferred.Add(@{ Module = $Module; Action = $Action })
}

function Complete-OperationItem {
    param([hashtable]$Operation, $Result)
    $Operation.Done++
    $m = $Operation.Module
    $previous = $script:LogContext
    $script:LogContext = $m.Title
    try {
        $errorText = (@($Result.Errors | Where-Object { $_ } | Select-Object -Unique)) -join ' | '
        if (-not $Result.Ok) {
            $Operation.Failed++
            Write-Log ("[{0}] {1}" -f $Result.Target, $errorText) 'ERROR'
            if ($Operation.Output -eq 'Grid') {
                # Bez kolumny obiektu docelowego wiersz błędu sam mówi, czego dotyczy
                $errRow = [ordered]@{ 'Status' = 'Błąd' }
                if (-not $Operation.TargetColumn) { $errRow['Obiekt'] = $Result.Target }
                $errRow['Szczegóły'] = $errorText
                Add-ResultRows -Module $m -Computer $Result.Target -TargetColumn $Operation.TargetColumn -Objects @([pscustomobject]$errRow)
            }
        }
        else {
            if ($errorText) { Write-Log ("[{0}] ostrzeżenia: {1}" -f $Result.Target, $errorText) 'WARN' }
            $data = @($Result.Data | Where-Object { $null -ne $_ })
            switch ($Operation.Output) {
                'Grid' {
                    if ($data.Count -gt 0) { Add-ResultRows -Module $m -Computer $Result.Target -TargetColumn $Operation.TargetColumn -Objects $data }
                    else { Write-Log ("[{0}] brak wyników" -f $Result.Target) }
                }
                'Log' {
                    foreach ($d in $data) {
                        $text = Format-LogObject $d
                        $level = if ($text -match 'Błąd') { 'WARN' } else { 'OK' }
                        Write-Log ("[{0}] {1}" -f $Result.Target, $text) $level
                    }
                }
            }
        }
        if ($Operation.OnResult) {
            try { $null = & $Operation.OnResult $m $Result }
            catch { Write-Log "Błąd obsługi wyniku ($($Result.Target)): $($_.Exception.Message)" 'ERROR' }
        }
    }
    finally {
        $script:LogContext = $previous
    }
}

function Complete-Operation {
    param([hashtable]$Operation)
    [void]$script:Engine.Operations.Remove($Operation)
    $m = $Operation.Module
    Set-ModuleBusy -Module $m -Busy $false
    $seconds = [Math]::Round(((Get-Date) - $Operation.Started).TotalSeconds, 1)
    $okCount = $Operation.Done - $Operation.Failed
    if ($Operation.Cancelled) {
        Write-Log ("{0} – przerwano (zakończone: {1}, czas {2} s)" -f $Operation.Name, $okCount, $seconds) 'WARN' -Module $m.Title
        Show-Toast ("{0}: przerwano" -f $Operation.Name) 'warn'
    }
    else {
        $level = if ($Operation.Failed -gt 0) { 'WARN' } else { 'OK' }
        Write-Log ("{0} – zakończono: {1} OK, {2} z błędem, czas {3} s" -f $Operation.Name, $okCount, $Operation.Failed, $seconds) $level -Module $m.Title
        if ($Operation.Total -gt 1 -or $Operation.Failed -gt 0 -or $seconds -ge 3) {
            $tone = if ($Operation.Failed -eq 0) { 'ok' } elseif ($okCount -gt 0) { 'warn' } else { 'crit' }
            $text = if ($Operation.Failed -eq 0) { '{0}: gotowe ({1}, {2} s)' -f $Operation.Name, $okCount, $seconds }
            else { '{0}: {1} OK, {2} z błędem' -f $Operation.Name, $okCount, $Operation.Failed }
            Show-Toast $text $tone
        }
    }
    if ($Operation.OnComplete -and -not $Operation.Cancelled) {
        $previous = $script:LogContext
        $script:LogContext = $m.Title
        try { $null = & $Operation.OnComplete $m $Operation }
        catch { Write-Log "Błąd po zakończeniu operacji: $($_.Exception.Message)" 'ERROR' }
        finally { $script:LogContext = $previous }
    }
}

function Stop-Operation {
    # Przerwanie jednej operacji. Zadania, które nie zareagują (np. zablokowane wywołanie .NET lub WMI),
    # po $script:Engine.AbandonAfterSec sekundach są porzucane - patrz Update-Operations.
    param([Parameter(Mandatory)][hashtable]$Operation)
    if ($Operation.Cancelled) { return }
    $Operation.Cancelled = $true
    $Operation.CancelAt = Get-Date
    foreach ($item in $Operation.Items) {
        if (-not $item.Finished) { try { [void]$item.PS.BeginStop($null, $null) } catch { } }
    }
    $text = $Operation.Module.View_['busyText']
    if ($text) { $text.Text = '{0}: przerywanie…' -f $Operation.Name }
}

function Stop-ModuleOperations {
    param([Parameter(Mandatory)][hashtable]$Module)
    $ops = @($script:Engine.Operations | Where-Object { $_.Module -eq $Module -and -not $_.Cancelled })
    if ($ops.Count -eq 0) { return }
    foreach ($op in $ops) { Stop-Operation -Operation $op }
    Write-Log ('Przerywanie: {0}…' -f ((@($ops | ForEach-Object { $_.Name })) -join ', ')) 'WARN' -Module $Module.Title
    Update-StatusBar
}

function Stop-AllOperations {
    $ops = @($script:Engine.Operations | Where-Object { -not $_.Cancelled })
    if ($ops.Count -eq 0) { return }
    foreach ($op in $ops) { Stop-Operation -Operation $op }
    Write-Log 'Przerywanie trwających operacji…' 'WARN' -Module ''
    Update-StatusBar
}

function Clear-AbandonedTasks {
    # Porzucone zadania zwalniamy dopiero, gdy same się zakończą (Dispose trwającego zadania blokowałby okno)
    foreach ($a in @($script:Engine.Abandoned)) {
        if ($a.Handle.IsCompleted) {
            try { $a.PS.Dispose() } catch { }
            [void]$script:Engine.Abandoned.Remove($a)
        }
    }
}

function Close-Engine {
    try { if ($script:Engine.Timer) { $script:Engine.Timer.Stop() } } catch { }
    $handles = @()
    foreach ($op in @($script:Engine.Operations)) {
        foreach ($item in $op.Items) {
            if (-not $item.Finished) { try { $handles += $item.PS.BeginStop($null, $null) } catch { } }
        }
    }
    foreach ($h in $handles) { try { [void]$h.AsyncWaitHandle.WaitOne(3000) } catch { } }
    Clear-AbandonedTasks
    # Zamknięcie puli czeka na zakończenie wszystkich zadań - z wiszącym zadaniem zamknięcie programu by zawisło.
    # Wątki puli są wątkami tła, więc i tak skończą się razem z procesem.
    $stuck = @($handles | Where-Object { -not $_.IsCompleted }).Count + $script:Engine.Abandoned.Count
    foreach ($key in 'Pool', 'AdPool') {
        if ($script:Engine[$key]) {
            if ($stuck -eq 0) { try { $script:Engine[$key].Close(); $script:Engine[$key].Dispose() } catch { } }
            $script:Engine[$key] = $null
        }
    }
}

function Update-StatusBar {
    $c = $script:UI.Controls
    $label = $c['txtStatus']
    if (-not $label) { return }
    $ops = @($script:Engine.Operations)
    if ($ops.Count -eq 0) {
        $label.Text = 'Gotowe'
        $c.statusDot.Fill = Get-Brush '#5EE3AE'
        $c.prgStatus.Visibility = 'Collapsed'
        $c.btnCancelOps.Visibility = 'Collapsed'
        return
    }
    $total = 0
    $done = 0
    $parts = foreach ($op in $ops) {
        $total += $op.Total
        $done += $op.Done
        $text = '{0}: {1}/{2}' -f $op.Name, $op.Done, $op.Total
        if ($op.Failed -gt 0) { $text += " (błędy: $($op.Failed))" }
        $text
    }
    $label.Text = 'Trwa: ' + (@($parts) -join '   •   ')
    $c.statusDot.Fill = Get-Brush '#4C7DF0'
    $bar = $c.prgStatus
    $bar.Maximum = [Math]::Max(1, $total)
    $bar.Value = [Math]::Min($done, $bar.Maximum)
    $bar.Visibility = 'Visible'
    $c.btnCancelOps.Visibility = 'Visible'
}
#endregion

#region Przestrzenie robocze i moduły (rejestracja i budowa)
function Register-Workspace {
    <#
        Przestrzeń robocza = przycisk na górnym pasku + własna nawigacja modułów.
        -Target: 'Computer' (lista komputerów po lewej), 'User' (lista kont), 'Group' (lista grup) albo 'None' (bez listy).
        -Categories: kolejność kategorii w nawigacji (pozostałe kategorie - w kolejności rejestracji modułów).
    #>
    param(
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)][string]$Title,
        [string]$Icon = 'E80F',
        [ValidateSet('Computer', 'User', 'Group', 'None')][string]$Target = 'None',
        [string]$Description = '',
        [string[]]$Categories = @()
    )
    $script:UI.Workspaces[$Key] = @{
        Key         = $Key
        Title       = $Title
        Icon        = $Icon
        Target      = $Target
        Description = $Description
        Categories  = @($Categories)
        NavHost     = $null
        Tab         = $null
        NavItems    = @{}
    }
}

function Register-Module {
    <#
        Moduł = pozycja w nawigacji przestrzeni roboczej, w kategorii -Category.
        -Build { param($m) } buduje panel parametrów i akcje (wywoływany przy pierwszym otwarciu).
        Ponowna rejestracja tego samego klucza zastępuje moduł (np. własną wersją z folderu modułów).
    #>
    param(
        [Parameter(Mandatory)][string]$Workspace,
        [Parameter(Mandatory)][string]$Category,
        [Parameter(Mandatory)][string]$Key,
        [Parameter(Mandatory)][string]$Title,
        [string]$Icon = 'E74C',
        [string]$Description = '',
        [string]$Badge = '',
        [Parameter(Mandatory)][scriptblock]$Build
    )
    $definition = @{ Workspace = $Workspace; Category = $Category; Key = $Key; Title = $Title; Icon = $Icon; Description = $Description; Badge = $Badge; Build = $Build }
    for ($i = 0; $i -lt $script:UI.ModuleDefs.Count; $i++) {
        if ($script:UI.ModuleDefs[$i].Key -eq $Key) { $script:UI.ModuleDefs[$i] = $definition; return }
    }
    [void]$script:UI.ModuleDefs.Add($definition)
}

function New-ModuleContext {
    param([hashtable]$Definition)
    $ws = $null
    if ($Definition['Workspace'] -and $script:UI.Workspaces.Contains($Definition['Workspace'])) { $ws = $script:UI.Workspaces[$Definition['Workspace']] }
    return @{
        Key            = $Definition['Key']
        Title          = $Definition['Title']
        Description    = $Definition['Description']
        Category       = $Definition['Category']
        Icon           = $Definition['Icon']
        Workspace      = $Definition['Workspace']
        WorkspaceTitle = $(if ($ws) { $ws.Title } else { '' })
        Target         = $(if ($ws) { $ws.Target } else { 'None' })
        Busy           = $false
        Buttons        = New-Object System.Collections.ArrayList
        PrimaryButton  = $null
        RowActions     = New-Object System.Collections.ArrayList
        Actions        = @{}
        RowDoubleClick = $null
        SecretColumns  = @()
        PillColumns    = @()
        GoodWhenNo     = @()
        HiddenColumns  = @()
        EditableColumns = @()
        OnCellEdit     = $null
        Loading        = $false
        InCellEdit     = $false
        ColorBools     = $false
        RevealSecrets  = $false
        Stats          = @{}
        EmptyText      = ''
        EmptyHint      = ''
        EmptyIcon      = ''
        ResultHint     = ''
        ExtraFilter    = ''
        ColumnFilters  = [ordered]@{}
        FilterButtons  = @{}
        MenuCell       = $null
        ParamsCollapsed = $false
        Data           = @{}
        View_          = @{}
        ColumnIndex    = @{}
        Root           = $null
        ParamsCard     = $null
        ParamsStack    = $null
        StatsGrid      = $null
        Grid           = $null
        Table          = $null
        View           = $null
        FilterBox      = $null
    }
}

function Get-ModuleDefinition([string]$Key) {
    foreach ($d in $script:UI.ModuleDefs) { if ($d.Key -eq $Key) { return $d } }
    return $null
}

function Initialize-Module {
    param([hashtable]$Definition)
    $m = New-ModuleContext -Definition $Definition
    $script:UI.Modules[$Definition.Key] = $m
    New-ModuleView -Module $m
    $previous = $script:LogContext
    $script:LogContext = $m.Title
    try { $null = & $Definition.Build $m }
    catch {
        Write-Log "Nie udało się zbudować modułu: $($_.Exception.Message)" 'ERROR'
        Add-Label -Parent (Add-ToolbarRow -Module $m) -Text "Błąd modułu: $($_.Exception.Message)" | Out-Null
    }
    finally { $script:LogContext = $previous }
    Complete-ModuleView -Module $m
    $m.Root.Visibility = 'Collapsed'
    [void]$script:UI.Controls['contentHost'].Children.Add($m.Root)
    return $m
}

function Show-Module {
    param([string]$Key)
    $definition = Get-ModuleDefinition $Key
    if (-not $definition) { return }
    if ($script:UI.ActiveWorkspace -ne $definition.Workspace) { Show-Workspace -Key $definition.Workspace -ModuleKey $Key; return }
    $m = $script:UI.Modules[$Key]
    if (-not $m) { $m = Invoke-WithWaitCursor { Initialize-Module -Definition $definition } }
    $active = $script:UI.ActiveModule
    if ($active -and -not [object]::ReferenceEquals($active, $m)) { $active.Root.Visibility = 'Collapsed' }
    $m.Root.Visibility = 'Visible'
    $script:UI.ActiveModule = $m
    $script:Settings.LastModules[$definition.Workspace] = $Key
    $ws = $script:UI.Workspaces[$definition.Workspace]
    $nav = $ws.NavItems[$Key]
    if ($nav -and $nav.IsChecked -ne $true) { $nav.IsChecked = $true }
}

function Show-Workspace {
    param([string]$Key, [string]$ModuleKey = '')
    if (-not $script:UI.Workspaces.Contains($Key)) { $Key = @($script:UI.Workspaces.Keys)[0] }
    $ws = $script:UI.Workspaces[$Key]
    $script:UI.ActiveWorkspace = $Key
    $script:Settings.LastWorkspace = $Key
    foreach ($other in $script:UI.Workspaces.Values) {
        if ($other.NavHost) { $other.NavHost.Visibility = if ($other.Key -eq $Key) { 'Visible' } else { 'Collapsed' } }
        if ($other.Tab -and $other.Key -eq $Key -and $other.Tab.IsChecked -ne $true) { $other.Tab.IsChecked = $true }
    }
    $c = $script:UI.Controls
    $c.panelComputers.Visibility = if ($ws.Target -eq 'Computer') { 'Visible' } else { 'Collapsed' }
    $c.panelUsers.Visibility = if ($ws.Target -eq 'User') { 'Visible' } else { 'Collapsed' }
    $c.panelGroups.Visibility = if ($ws.Target -eq 'Group') { 'Visible' } else { 'Collapsed' }
    $c.targetColumn.Width = if ($ws.Target -eq 'None') { New-Object System.Windows.GridLength 0 } else { New-Object System.Windows.GridLength 300 }
    $c.txtSubtitle.Text = $ws.Description
    if (-not $ModuleKey) { $ModuleKey = [string]$script:Settings.LastModules[$Key] }
    $def = Get-ModuleDefinition $ModuleKey
    if (-not $def -or $def.Workspace -ne $Key) {
        $def = $null
        foreach ($d in $script:UI.ModuleDefs) { if ($d.Workspace -eq $Key) { $def = $d; break } }
    }
    if ($def) { Show-Module -Key $def.Key }
    elseif ($script:UI.ActiveModule) { $script:UI.ActiveModule.Root.Visibility = 'Collapsed'; $script:UI.ActiveModule = $null }
}

function Update-NavBusy {
    # Kropka przy pozycji nawigacji pokazuje moduły z trwającą operacją
    param([hashtable]$Module)
    if (-not $Module.Workspace -or -not $script:UI.Workspaces.Contains($Module.Workspace)) { return }
    $nav = $script:UI.Workspaces[$Module.Workspace].NavItems[$Module.Key]
    if (-not $nav) { return }
    $dot = $script:NavDots[$nav]
    if ($dot) { $dot.Visibility = if ($Module.Busy) { 'Visible' } else { 'Collapsed' } }
}
$script:NavDots = @{}

function Get-TargetComputers {
    # Komputery zaznaczone na liście po lewej
    param([switch]$Quiet)
    $rows = @($script:UI.HostTable.Select('Sel = true', 'Name ASC'))
    $names = @($rows | ForEach-Object { [string]$_['Name'] } | Where-Object { $_ } | Select-Object -Unique)
    if ($names.Count -eq 0 -and -not $Quiet) { Show-Warning 'Zaznacz komputery na liście po lewej stronie.' }
    return $names
}

function Get-TargetGroups {
    # Grupy zaznaczone na liście grup (sAMAccountName)
    param([switch]$Quiet)
    $rows = @($script:UI.GroupTable.Select('Sel = true', 'Sam ASC'))
    $names = @($rows | ForEach-Object { [string]$_['Sam'] } | Where-Object { $_ } | Select-Object -Unique)
    if ($names.Count -eq 0 -and -not $Quiet) { Show-Warning 'Zaznacz grupy na liście po lewej stronie.' }
    return $names
}

function Get-TargetUsers {
    # Konta zaznaczone na liście użytkowników (sAMAccountName)
    param([switch]$Quiet)
    $rows = @($script:UI.UserTable.Select('Sel = true', 'Login ASC'))
    $names = @($rows | ForEach-Object { [string]$_['Login'] } | Where-Object { $_ } | Select-Object -Unique)
    if ($names.Count -eq 0 -and -not $Quiet) { Show-Warning 'Zaznacz konta na liście użytkowników po lewej stronie.' }
    return $names
}
#endregion

#region Listy obiektów docelowych (lewy panel): komputery i użytkownicy
# Oba panele działają tak samo: DataTable + DataView (szybki filtr), ListBox z szablonem wiersza,
# pole wyboru w wierszu zapisuje stan bezpośrednio w DataRow (kolumna Sel), dzięki czemu zaznaczenia
# przetrwają filtrowanie. Kolumna Dot to kolor kropki stanu, Sub - druga linia opisu.
$script:TargetPanelXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Background="#12171D" BorderBrush="#1E242E" BorderThickness="0,0,1,0">
  <Grid Margin="14,14,12,10">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/>
      <RowDefinition Height="*"/>
      <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <Grid Margin="2,0,0,10">
      <TextBlock x:Name="pTitle" Foreground="#8791A5" FontSize="11" FontWeight="SemiBold" VerticalAlignment="Center"/>
      <Border Style="{StaticResource Chip}" HorizontalAlignment="Right" Margin="0">
        <TextBlock x:Name="pCount" Text="0" Foreground="#AEB6C4" FontSize="11"/>
      </Border>
    </Grid>
    <Border Grid.Row="1" Style="{StaticResource Card}" Padding="12,12,12,6" Margin="0,0,0,10">
      <StackPanel x:Name="pSource"/>
    </Border>
    <TextBox x:Name="pSearch" Grid.Row="2" Margin="0,0,0,8"/>
    <Grid Grid.Row="3">
      <ListBox x:Name="pList" SelectionMode="Extended">
        <ListBox.ItemTemplate>
          <DataTemplate>
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
              </Grid.ColumnDefinitions>
              <CheckBox IsChecked="{Binding [Sel], Mode=OneWay}" Margin="0,0,10,0" VerticalAlignment="Center" Focusable="False"/>
              <Ellipse Grid.Column="1" Width="8" Height="8" Fill="{Binding [Dot]}" Margin="0,0,10,0" VerticalAlignment="Center"/>
              <StackPanel Grid.Column="2">
                <TextBlock Text="{Binding [Title]}" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/>
                <TextBlock Text="{Binding [Sub]}" Foreground="#7B8496" FontSize="11.5" TextTrimming="CharacterEllipsis"/>
              </StackPanel>
            </Grid>
          </DataTemplate>
        </ListBox.ItemTemplate>
      </ListBox>
      <StackPanel x:Name="pEmpty" HorizontalAlignment="Center" VerticalAlignment="Center" IsHitTestVisible="False" Margin="10">
        <TextBlock x:Name="pEmptyIcon" Style="{StaticResource Glyph}" FontSize="28" Foreground="#3A4352" HorizontalAlignment="Center"/>
        <TextBlock x:Name="pEmptyText" Foreground="#5E6779" TextAlignment="Center" TextWrapping="Wrap" Margin="0,10,0,0"/>
      </StackPanel>
    </Grid>
    <Grid Grid.Row="4" Margin="0,8,0,0">
      <StackPanel Orientation="Horizontal">
        <Button x:Name="pAll" Style="{StaticResource GhostButton}" ToolTip="Zaznacz widoczne"/>
        <Button x:Name="pNone" Style="{StaticResource GhostButton}" ToolTip="Odznacz wszystkie"/>
        <Button x:Name="pInvert" Style="{StaticResource GhostButton}" ToolTip="Odwróć zaznaczenie widocznych"/>
      </StackPanel>
      <TextBlock x:Name="pSel" HorizontalAlignment="Right" VerticalAlignment="Center" Foreground="#8791A5" FontSize="12"/>
    </Grid>
  </Grid>
</Border>
'@

$script:DotColors = @{ unknown = '#3A4352'; ok = '#5EE3AE'; warn = '#FFC46B'; crit = '#FF7A86'; off = '#5E6779' }

function New-TargetPanel {
    # Wspólny szkielet panelu; zwraca hashtablę z kontrolkami i tabelą
    param([string]$Kind, [string]$Title, [string]$Placeholder, [string]$EmptyIcon, [string]$EmptyText, [string[]]$Columns, [string]$KeyColumn)
    $root = New-UiElement $script:TargetPanelXaml
    $p = @{ Kind = $Kind; Root = $root; KeyColumn = $KeyColumn; EmptyText = $EmptyText }
    foreach ($n in 'pTitle', 'pCount', 'pSource', 'pSearch', 'pList', 'pEmpty', 'pEmptyIcon', 'pEmptyText', 'pAll', 'pNone', 'pInvert', 'pSel') { $p[$n] = $root.FindName($n) }
    $p.pTitle.Text = $Title
    $p.pSearch.Tag = $Placeholder
    $p.pEmptyIcon.Text = Get-Glyph $EmptyIcon
    $p.pEmptyText.Text = $EmptyText
    $p.pAll.Content = New-IconContent -Text '' -Icon 'E8B3' -IconSize 13
    $p.pNone.Content = New-IconContent -Text '' -Icon 'E894' -IconSize 13
    $p.pInvert.Content = New-IconContent -Text '' -Icon 'E8AB' -IconSize 13

    $t = New-Object System.Data.DataTable $Kind
    [void]$t.Columns.Add('Sel', [bool])
    foreach ($c in $Columns) {
        if ($c -eq 'LastLogon' -or $c -eq 'PwdLastSet') { [void]$t.Columns.Add($c, [datetime]) }
        else { [void]$t.Columns.Add($c, [string]) }
    }
    foreach ($c in 'Source', 'Dot', 'Title', 'Sub', 'Status') { if (-not $t.Columns.Contains($c)) { [void]$t.Columns.Add($c, [string]) } }
    $t.Columns['Sel'].DefaultValue = $false
    $t.Columns['Dot'].DefaultValue = $script:DotColors.unknown
    $t.PrimaryKey = [System.Data.DataColumn[]]@($t.Columns[$KeyColumn])
    $t.CaseSensitive = $false
    $view = [System.Data.DataView]::new($t)
    $view.Sort = "$KeyColumn ASC"
    $p.Table = $t
    $p.View = $view
    $p.pList.ItemsSource = $view

    $script:TargetPanels[$p.pList] = $p
    $script:TargetPanels[$p.pSearch] = $p
    $p.pList.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]$script:TargetEvents.ItemClick)
    $p.pList.add_PreviewKeyDown($script:TargetEvents.KeyDown)
    $p.pSearch.add_TextChanged($script:TargetEvents.SearchChanged)
    foreach ($pair in @(@('pAll', 'CheckVisible'), @('pNone', 'UncheckAll'), @('pInvert', 'InvertVisible'))) {
        $script:TargetPanels[$p[$pair[0]]] = $p
        $script:TargetButtonModes[$p[$pair[0]]] = $pair[1]
        $p[$pair[0]].add_Click($script:TargetEvents.ButtonClick)
    }
    Update-TargetCount $p
    return $p
}

$script:TargetPanels = New-Object 'System.Collections.Generic.Dictionary[object,hashtable]'
$script:TargetButtonModes = New-Object 'System.Collections.Generic.Dictionary[object,string]'
$script:TargetEvents = @{
    ItemClick     = {
        param($s, $e)
        try {
            $cb = $e.OriginalSource
            if (-not ($cb -is [System.Windows.Controls.CheckBox])) { return }
            $drv = $cb.DataContext
            if (-not ($drv -is [System.Data.DataRowView])) { return }
            $p = $script:TargetPanels[$s]
            $value = ($cb.IsChecked -eq $true)
            # Kliknięcie pola w jednym z kilku zaznaczonych wierszy zmienia je wszystkie
            $rows = @($s.SelectedItems | Where-Object { $_ -is [System.Data.DataRowView] })
            if ($rows.Count -gt 1 -and $rows -contains $drv) { foreach ($r in $rows) { $r.Row['Sel'] = $value } }
            else { $drv.Row['Sel'] = $value }
            Update-TargetCount $p
        }
        catch { Write-Log "Błąd zaznaczania: $($_.Exception.Message)" 'ERROR' }
    }
    KeyDown       = {
        param($s, $e)
        try {
            if ($e.Key -ne [System.Windows.Input.Key]::Space) { return }
            $p = $script:TargetPanels[$s]
            $rows = @($s.SelectedItems | Where-Object { $_ -is [System.Data.DataRowView] })
            if ($rows.Count -eq 0) { return }
            $value = -not [bool]$rows[0].Row['Sel']
            foreach ($r in $rows) { $r.Row['Sel'] = $value }
            Update-TargetCount $p
            $e.Handled = $true
        }
        catch { }
    }
    SearchChanged = {
        param($s, $e)
        try { Update-TargetFilter $script:TargetPanels[$s] } catch { }
    }
    ButtonClick   = {
        param($s, $e)
        try { Set-TargetCheck -Panel $script:TargetPanels[$s] -Mode $script:TargetButtonModes[$s] } catch { }
    }
}

function Update-TargetCount {
    param([hashtable]$Panel)
    $t = $Panel.Table
    $selected = @($t.Select('Sel = true')).Count
    $Panel.pCount.Text = [string]$t.Rows.Count
    $Panel.pSel.Text = if ($Panel.View.Count -ne $t.Rows.Count) { "zaznaczone: $selected • widoczne: $($Panel.View.Count)" } else { "zaznaczone: $selected z $($t.Rows.Count)" }
    $Panel.pSel.Foreground = Get-Brush $(if ($selected -gt 0) { '#8CB0FF' } else { '#7B8496' })
    if ($Panel.View.Count -gt 0) { $Panel.pEmpty.Visibility = 'Collapsed' }
    else {
        $Panel.pEmpty.Visibility = 'Visible'
        $Panel.pEmptyText.Text = if ($t.Rows.Count -gt 0) { 'Nic nie pasuje do wyszukiwania' } else { $Panel.EmptyText }
    }
}

function Update-TargetFilter {
    param([hashtable]$Panel)
    $text = $Panel.pSearch.Text.Trim()
    if ($text) {
        $lit = ConvertTo-LikeLiteral $text
        $parts = foreach ($c in $Panel.SearchColumns) { "[$c] LIKE '*$lit*'" }
        $Panel.View.RowFilter = (@($parts) -join ' OR ')
    }
    else { $Panel.View.RowFilter = '' }
    Update-TargetCount $Panel
}

function Set-TargetCheck {
    param([hashtable]$Panel, [ValidateSet('CheckVisible', 'UncheckAll', 'InvertVisible', 'CheckSelected', 'UncheckSelected')][string]$Mode)
    $t = $Panel.Table
    switch ($Mode) {
        'CheckVisible' { foreach ($drv in @($Panel.View | ForEach-Object { $_ })) { $drv.Row['Sel'] = $true } }
        'UncheckAll' { foreach ($r in $t.Rows) { if ([bool]$r['Sel']) { $r['Sel'] = $false } } }
        'InvertVisible' { foreach ($drv in @($Panel.View | ForEach-Object { $_ })) { $drv.Row['Sel'] = -not [bool]$drv.Row['Sel'] } }
        'CheckSelected' { foreach ($drv in @($Panel.pList.SelectedItems)) { $drv.Row['Sel'] = $true } }
        'UncheckSelected' { foreach ($drv in @($Panel.pList.SelectedItems)) { $drv.Row['Sel'] = $false } }
    }
    Update-TargetCount $Panel
}

function ConvertTo-DbValue($Value) {
    if ($null -eq $Value -or [string]$Value -eq '') { return [System.DBNull]::Value }
    return $Value
}

function Import-TargetRows {
    # Dodaje/aktualizuje pozycje panelu; zachowuje zaznaczenia istniejących pozycji
    param([hashtable]$Panel, [object[]]$Items, [string]$Source, [switch]$Check, [switch]$ReplaceSource)
    $t = $Panel.Table
    $key = $Panel.KeyColumn
    $added = 0
    # Odpięcie widoku od listy na czas importu - tysiące wierszy dodają się wtedy szybko
    $Panel.pList.ItemsSource = $null
    $t.BeginLoadData()
    try {
        if ($ReplaceSource) {
            foreach ($r in @($t.Select(("Source = '{0}' AND Sel = false" -f $Source.Replace("'", "''"))))) { $t.Rows.Remove($r) }
        }
        foreach ($it in $Items) {
            $name = ([string](Get-ObjectValue $it $key)).Trim()
            if (-not $name) { continue }
            $row = $t.Rows.Find($name)
            $isNew = ($null -eq $row)
            if ($isNew) {
                $row = $t.NewRow()
                $row[$key] = $name
                $row['Sel'] = $false
                $row['Source'] = $Source
            }
            elseif ($Source -eq 'AD') { $row['Source'] = 'AD' }
            foreach ($col in $t.Columns) {
                $n = $col.ColumnName
                if ($n -eq $key -or $n -eq 'Sel' -or $n -eq 'Source' -or $n -eq 'Dot' -or $n -eq 'Title' -or $n -eq 'Sub') { continue }
                $v = Get-ObjectValue $it $n
                if ($null -eq $v) { continue }
                if ($col.DataType -eq [datetime]) { if ($v -is [datetime]) { $row[$n] = $v } }
                elseif ($v -is [bool]) { $row[$n] = $(if ($v) { 'Tak' } else { 'Nie' }) }
                else { $row[$n] = ConvertTo-DbValue ([string]$v) }
            }
            if ($Check) { $row['Sel'] = $true }
            & $Panel.Describe $row
            if ($isNew) {
                $t.Rows.Add($row)
                $added++
            }
        }
    }
    finally {
        $t.EndLoadData()
        $t.AcceptChanges()
        $Panel.pList.ItemsSource = $Panel.View
    }
    Update-TargetCount $Panel
    return $added
}

function Remove-TargetRows {
    param([hashtable]$Panel)
    $rows = @($Panel.pList.SelectedItems | ForEach-Object { $_.Row })
    if ($rows.Count -eq 0) { return }
    foreach ($r in $rows) { $Panel.Table.Rows.Remove($r) }
    $Panel.Table.AcceptChanges()
    Update-TargetCount $Panel
}

function Get-TargetSelection {
    # Nazwy z wierszy podświetlonych na liście (menu kontekstowe)
    param([hashtable]$Panel)
    return @($Panel.pList.SelectedItems | ForEach-Object { [string]$_.Row[$Panel.KeyColumn] })
}

function New-SourceRow {
    # Wiersz w karcie źródła danych: kontrolka rozciągana + przyciski za nią
    param($Stretch, [object[]]$After = @(), [string]$Caption = '')
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Margin = '0,0,0,8'
    if ($Caption) {
        $c = New-Object System.Windows.Controls.TextBlock
        $c.Text = $Caption
        $c.Foreground = Get-Brush '#8791A5'
        $c.FontSize = 11.5
        $c.Margin = '1,0,0,4'
        [void]$sp.Children.Add($c)
    }
    $dock = New-Object System.Windows.Controls.DockPanel
    $dock.LastChildFill = $true
    foreach ($a in $After) {
        [System.Windows.Controls.DockPanel]::SetDock($a, 'Right')
        $a.Margin = '6,0,0,0'
        [void]$dock.Children.Add($a)
    }
    [void]$dock.Children.Add($Stretch)
    [void]$sp.Children.Add($dock)
    return $sp
}

function Add-PanelMenu {
    # Menu kontekstowe listy: pozycje @{ Text; Icon; Action = { param($panel, $names) } } albo '-' (separator)
    param([hashtable]$Panel, [object[]]$Items)
    $menu = New-Object System.Windows.Controls.ContextMenu
    foreach ($it in $Items) {
        if ($it -is [string]) { [void]$menu.Items.Add((New-MenuSeparator)); continue }
        $mi = New-MenuItem -Text $it.Text -Icon $it.Icon -Danger:([bool]$it['Danger'])
        $script:PanelMenuActions[$mi] = @{ Panel = $Panel; Action = $it.Action }
        $mi.add_Click($script:PanelMenuClick)
        [void]$menu.Items.Add($mi)
    }
    $Panel.pList.ContextMenu = $menu
}
$script:PanelMenuActions = New-Object 'System.Collections.Generic.Dictionary[object,hashtable]'
$script:PanelMenuClick = {
    param($s, $e)
    try {
        $entry = $script:PanelMenuActions[$s]
        $names = @(Get-TargetSelection -Panel $entry.Panel)
        if ($names.Count -eq 0) { return }
        $null = & $entry.Action $entry.Panel $names
    }
    catch {
        Write-Log "Błąd: $($_.Exception.Message)" 'ERROR' -Module ''
        Show-Error 'Operacja nie powiodła się.' $_
    }
}

function Start-Tool {
    # Uruchamia narzędzie systemowe (konsola MMC, RDP, Eksplorator) - tylko dla poprawnych nazw hostów
    param([string]$FilePath, [string[]]$Arguments, [string]$Name)
    if ($Name -and $Name -notmatch '^[A-Za-z0-9._-]+$') { Show-Warning "Niepoprawna nazwa komputera: $Name"; return }
    try { Start-Process -FilePath $FilePath -ArgumentList $Arguments | Out-Null }
    catch { Show-Error "Nie można uruchomić $FilePath." $_ }
}
#endregion

#region Panel komputerów
function New-ComputerLdapFilter {
    param([string]$NamePattern, [bool]$OnlyEnabled)
    $parts = @('(objectCategory=computer)')
    $pattern = ([string]$NamePattern).Trim()
    if ($pattern) {
        if ($pattern -notmatch '\*') { $pattern = "*$pattern*" }
        # Znaki specjalne LDAP (poza gwiazdką, która jest symbolem wieloznacznym)
        $escaped = $pattern -replace '\\', '\5c' -replace '\(', '\28' -replace '\)', '\29'
        $parts += "(name=$escaped)"
    }
    if ($OnlyEnabled) { $parts += '(!(userAccountControl:1.2.840.113556.1.4.803:=2))' }
    return '(&' + ($parts -join '') + ')'
}

function Initialize-ComputerPanel {
    $p = New-TargetPanel -Kind 'Computers' -Title 'KOMPUTERY' -Placeholder 'Szukaj na liście…' -EmptyIcon 'E7F4' `
        -EmptyText "Lista jest pusta.`nWczytaj komputery z Active Directory albo dodaj nazwy ręcznie." `
        -Columns @('Name', 'OS', 'LastLogon', 'Enabled', 'DNSHostName', 'DN') -KeyColumn 'Name'
    $p.SearchColumns = @('Name', 'OS', 'Source', 'DN', 'Status')
    $p.Describe = {
        param($row)
        $row['Title'] = $row['Name']
        $os = [string]$row['OS']
        $os = $os -replace '^Microsoft ', '' -replace ' (Edition|Evaluation)$', ''
        $parts = @()
        if ($os) { $parts += $os } else { $parts += 'system nieznany' }
        if ([string]$row['Enabled'] -eq 'Nie') { $parts += 'konto wyłączone' }
        if ([string]$row['Status']) { $parts += [string]$row['Status'] }
        $parts += [string]$row['Source']
        $row['Sub'] = $parts -join ' • '
        if ([string]$row['Enabled'] -eq 'Nie' -and [string]$row['Dot'] -eq $script:DotColors.unknown) { $row['Dot'] = $script:DotColors.off }
    }
    $script:UI.ComputerPanel = $p
    $script:UI.HostTable = $p.Table

    $ou = New-Object System.Windows.Controls.TextBox
    $ou.Tag = 'Cała domena'
    $ou.Text = [string]$script:Settings.SearchBase
    $ou.ToolTip = 'Jednostka organizacyjna (DN), z której wczytać komputery'
    $btnOu = New-PlainButton -Icon 'E8B7' -ToolTip 'Wybierz jednostkę organizacyjną'
    $btnOu.Padding = '9,6'
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $ou -After @($btnOu) -Caption 'Jednostka organizacyjna'))
    $name = New-Object System.Windows.Controls.TextBox
    $name.Tag = 'np. PC-* albo fragment nazwy'
    $name.Text = [string]$script:Settings.NameFilter
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $name -Caption 'Filtr nazwy'))
    $chk = New-Object System.Windows.Controls.CheckBox
    $chk.Content = 'Tylko włączone konta'
    $chk.IsChecked = [bool]$script:Settings.OnlyEnabled
    $chk.Margin = '1,0,0,10'
    [void]$p.pSource.Children.Add($chk)
    $load = New-PlainButton -Text 'Wczytaj z AD' -Icon 'E896' -Primary
    $add = New-PlainButton -Icon 'E710' -ToolTip 'Dodaj nazwy ręcznie'
    $file = New-PlainButton -Icon 'E8E5' -ToolTip 'Wczytaj nazwy z pliku TXT/CSV'
    foreach ($b in $add, $file) { $b.Padding = '9,6' }
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $load -After @($file, $add)))
    $p.Ou = $ou
    $p.NameFilter = $name
    $p.OnlyEnabled = $chk

    $tm = New-ModuleContext -Definition @{ Key = '__computers'; Title = 'Lista komputerów'; Category = ''; Icon = 'E7F4'; Workspace = '' }
    $script:UI.Modules['__computers'] = $tm
    [void]$tm.Buttons.Add($load)
    Register-ControlHandler -Control $btnOu -EventName 'Click' -Module $tm -Action {
        $dn = Select-OrganizationalUnit -Title 'Komputery z jednostki organizacyjnej' -Selected $script:UI.ComputerPanel.Ou.Text.Trim() -AllowDomainRoot
        if ($null -ne $dn) { $script:UI.ComputerPanel.Ou.Text = $dn }
    }
    Register-ControlHandler -Control $load -EventName 'Click' -Module $tm -Action { param($m) Start-AdComputerLoad -Module $m }
    Register-ControlHandler -Control $add -EventName 'Click' -Module $tm -Action { Add-ManualComputers }
    Register-ControlHandler -Control $file -EventName 'Click' -Module $tm -Action { Import-ComputerFile }
    $name.add_KeyDown({ param($s, $e) if ($e.Key -eq [System.Windows.Input.Key]::Return) { Invoke-UiAction -Module $script:UI.Modules['__computers'] -Action { param($m) Start-AdComputerLoad -Module $m } } })

    Add-PanelMenu -Panel $p -Items @(
        @{ Text = 'Zaznacz wybrane'; Icon = 'E73A'; Action = { param($panel) Set-TargetCheck -Panel $panel -Mode CheckSelected } }
        @{ Text = 'Odznacz wybrane'; Icon = 'E739'; Action = { param($panel) Set-TargetCheck -Panel $panel -Mode UncheckSelected } }
        '-'
        @{ Text = 'Pulpit zdalny'; Icon = 'E8AF'; Action = { param($panel, $names) Start-Tool -FilePath 'mstsc.exe' -Arguments @("/v:$($names[0])") -Name $names[0] } }
        @{ Text = 'Zarządzanie komputerem'; Icon = 'E912'; Action = { param($panel, $names) Start-Tool -FilePath 'compmgmt.msc' -Arguments @("/computer:\\$($names[0])") -Name $names[0] } }
        @{ Text = 'Usługi'; Icon = 'E9F5'; Action = { param($panel, $names) Start-Tool -FilePath 'services.msc' -Arguments @("/computer:\\$($names[0])") -Name $names[0] } }
        @{ Text = 'Podgląd zdarzeń'; Icon = 'E81C'; Action = { param($panel, $names) Start-Tool -FilePath 'eventvwr.exe' -Arguments @("\\$($names[0])") -Name $names[0] } }
        @{ Text = 'Udział C$'; Icon = 'E838'; Action = { param($panel, $names) Start-Tool -FilePath 'explorer.exe' -Arguments @("\\$($names[0])\C$") -Name $names[0] } }
        @{ Text = 'Ping ciągły (konsola)'; Icon = 'E968'; Action = { param($panel, $names) Start-Tool -FilePath 'cmd.exe' -Arguments @('/k', "ping -t $($names[0])") -Name $names[0] } }
        '-'
        @{ Text = 'Kopiuj nazwy'; Icon = 'E8C8'; Action = { param($panel, $names) Set-ClipboardText ($names -join [Environment]::NewLine); Show-Toast "Skopiowano nazw: $($names.Count)" 'ok' } }
        @{ Text = 'Usuń z listy'; Icon = 'E74D'; Danger = $true; Action = { param($panel) Remove-TargetRows -Panel $panel } }
    )
    return $p
}

function Start-AdComputerLoad {
    param([hashtable]$Module)
    $p = $script:UI.ComputerPanel
    $script:Settings.SearchBase = $p.Ou.Text.Trim()
    $script:Settings.NameFilter = $p.NameFilter.Text.Trim()
    $script:Settings.OnlyEnabled = ($p.OnlyEnabled.IsChecked -eq $true)
    $params = @{
        LdapFilter = New-ComputerLdapFilter -NamePattern $script:Settings.NameFilter -OnlyEnabled $script:Settings.OnlyEnabled
        SearchBase = $script:Settings.SearchBase
    }
    Start-AdOperation -Module $Module -Name 'Wczytywanie komputerów z AD' -Targets @('Active Directory') -Output None -Parameters $params -ScriptBlock {
        param($Target, $P, $Ctx)
        Import-Module ActiveDirectory -ErrorAction Stop -Verbose:$false
        $q = @{
            LDAPFilter  = $P.LdapFilter
            Properties  = @('OperatingSystem', 'LastLogonDate', 'Enabled', 'DNSHostName')
            ErrorAction = 'Stop'
        }
        if ($P.SearchBase) { $q.SearchBase = $P.SearchBase }
        if ($Ctx.Server) { $q.Server = $Ctx.Server }
        if ($Ctx.Credential) { $q.Credential = $Ctx.Credential }
        Get-ADComputer @q | ForEach-Object {
            [pscustomobject]@{
                Name        = $_.Name
                OS          = $_.OperatingSystem
                LastLogon   = $_.LastLogonDate
                Enabled     = $_.Enabled
                DNSHostName = $_.DNSHostName
                DN          = $_.DistinguishedName
            }
        }
    } -OnResult {
        param($m, $r)
        if (-not $r.Ok) {
            $m.Data.LastError = (@($r.Errors)) -join "`r`n"
            Invoke-Deferred -Module $m -Action { param($m) Show-Error 'Nie udało się wczytać komputerów z Active Directory.' $m.Data.LastError }
            return
        }
        $items = @($r.Data)
        $added = Import-TargetRows -Panel $script:UI.ComputerPanel -Items $items -Source 'AD' -ReplaceSource
        Write-Log ("Wczytano z AD {0} komputerów (nowych na liście: {1})." -f $items.Count, $added) 'OK'
    }
}

function Read-NameList {
    # Nazwy z tekstu (wiersze, przecinki, spacje)
    param([string]$Text)
    return @($Text -split '[\s,;]+' | ForEach-Object { $_.Trim().Trim('"') } | Where-Object { $_ } | Select-Object -Unique)
}

function Add-ManualComputers {
    $text = Show-InputDialog -Title 'Dodaj komputery' -Prompt 'Wpisz lub wklej nazwy komputerów – po jednej w wierszu albo rozdzielone przecinkiem lub spacją. Dodane pozycje zostaną zaznaczone.' -Multiline -Icon 'E710'
    if ($null -eq $text) { return }
    $names = @(Read-NameList $text)
    if ($names.Count -eq 0) { return }
    $added = Import-TargetRows -Panel $script:UI.ComputerPanel -Items @($names | ForEach-Object { [pscustomobject]@{ Name = $_ } }) -Source 'ręcznie' -Check
    Write-Log ("Dodano ręcznie {0} komputerów (nowych: {1})." -f $names.Count, $added) 'OK' -Module 'Komputery'
}

function Read-NameFile {
    # Pierwsza kolumna pliku TXT/CSV (bez wiersza nagłówka)
    param([string]$HeaderPattern)
    $dlg = New-Object Microsoft.Win32.OpenFileDialog
    $dlg.Filter = 'Pliki tekstowe i CSV (*.txt;*.csv)|*.txt;*.csv|Wszystkie pliki (*.*)|*.*'
    $answer = if ($script:UI.Window) { $dlg.ShowDialog($script:UI.Window) } else { $dlg.ShowDialog() }
    if ($answer -ne $true) { return $null }
    $names = foreach ($line in (Get-Content -LiteralPath $dlg.FileName -Encoding UTF8)) {
        $first = (($line -split '[,;\t]')[0]).Trim().Trim('"')
        if ($first -and $first -notmatch $HeaderPattern) { $first }
    }
    # Przecinek: pusta lista ma pozostać tablicą (nie $null, który oznacza anulowanie)
    return , @($names | Select-Object -Unique)
}

function Import-ComputerFile {
    $names = Read-NameFile -HeaderPattern '^(name|computer|computername|hostname|nazwa|komputer)$'
    if ($null -eq $names) { return }
    if ($names.Count -eq 0) { Show-Warning 'Plik nie zawiera nazw komputerów.'; return }
    $added = Import-TargetRows -Panel $script:UI.ComputerPanel -Items @($names | ForEach-Object { [pscustomobject]@{ Name = $_ } }) -Source 'plik' -Check
    Write-Log ("Wczytano z pliku {0} komputerów (nowych: {1})." -f $names.Count, $added) 'OK' -Module 'Komputery'
}

function Set-ComputerState {
    # Kolor kropki i opis stanu komputera na liście (np. po teście łączności)
    param([string]$Name, [ValidateSet('unknown', 'ok', 'warn', 'crit', 'off')][string]$State, [string]$Status = '')
    $p = $script:UI.ComputerPanel
    if (-not $p) { return }
    $row = $p.Table.Rows.Find($Name)
    if (-not $row) { return }
    $row['Dot'] = $script:DotColors[$State]
    $row['Status'] = ConvertTo-DbValue $Status
    & $p.Describe $row
}

function Rename-ComputerRow {
    # Po zmianie nazwy komputera aktualizuje pozycję na liście
    param([string]$OldName, [string]$NewName)
    $t = $script:UI.HostTable
    $row = $t.Rows.Find($OldName)
    if (-not $row -or $t.Rows.Find($NewName)) { return }
    $row['Name'] = $NewName
    & $script:UI.ComputerPanel.Describe $row
    $t.AcceptChanges()
}
#endregion

#region Panel użytkowników
function New-UserLdapFilter {
    param([string]$Query, [int]$State)
    $parts = @('(objectCategory=person)', '(objectClass=user)')
    $q = ([string]$Query).Trim()
    if ($q) {
        if ($q -match '\*') {
            $v = $q -replace '\\', '\5c' -replace '\(', '\28' -replace '\)', '\29'
            $parts += "(|(sAMAccountName=$v)(displayName=$v)(userPrincipalName=$v)(mail=$v))"
        }
        else {
            $v = ConvertTo-LdapFilterValue $q
            $parts += "(|(anr=$v)(sAMAccountName=$v*)(userPrincipalName=$v*)(employeeID=$v))"
        }
    }
    switch ($State) {
        1 { $parts += '(!(userAccountControl:1.2.840.113556.1.4.803:=2))' }
        2 { $parts += '(userAccountControl:1.2.840.113556.1.4.803:=2)' }
        3 { $parts += '(lockoutTime>=1)' }
    }
    return '(&' + ($parts -join '') + ')'
}

function Initialize-UserPanel {
    $p = New-TargetPanel -Kind 'Users' -Title 'UŻYTKOWNICY' -Placeholder 'Szukaj na liście…' -EmptyIcon 'E716' `
        -EmptyText "Lista jest pusta.`nWyszukaj konta w Active Directory albo dodaj loginy ręcznie." `
        -Columns @('Login', 'Name', 'Upn', 'Mail', 'Enabled', 'Locked', 'Department', 'Title_', 'LastLogon', 'DN') -KeyColumn 'Login'
    $p.SearchColumns = @('Login', 'Name', 'Upn', 'Mail', 'Department', 'Title_', 'Source', 'DN')
    $p.Describe = {
        param($row)
        $display = [string]$row['Name']
        $row['Title'] = if ($display) { $display } else { $row['Login'] }
        $parts = @([string]$row['Login'])
        if ([string]$row['Title_']) { $parts += [string]$row['Title_'] }
        elseif ([string]$row['Department']) { $parts += [string]$row['Department'] }
        if ([string]$row['Locked'] -eq 'Tak') { $parts += 'zablokowane' }
        elseif ([string]$row['Enabled'] -eq 'Nie') { $parts += 'wyłączone' }
        if ([string]$row['Source'] -ne 'AD') { $parts += [string]$row['Source'] }
        $row['Sub'] = $parts -join ' • '
        $row['Dot'] = if ([string]$row['Locked'] -eq 'Tak') { $script:DotColors.crit }
        elseif ([string]$row['Enabled'] -eq 'Nie') { $script:DotColors.off }
        elseif ([string]$row['Enabled'] -eq 'Tak') { $script:DotColors.ok }
        else { $script:DotColors.unknown }
    }
    $script:UI.UserPanel = $p
    $script:UI.UserTable = $p.Table

    $query = New-Object System.Windows.Controls.TextBox
    $query.Tag = 'Login, nazwisko lub e-mail'
    $query.ToolTip = 'Puste pole = wszystkie konta z wybranej jednostki. Można używać gwiazdki, np. jan*'
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $query -Caption 'Wyszukaj konta'))
    $ou = New-Object System.Windows.Controls.TextBox
    $ou.Tag = 'Cała domena'
    $ou.Text = [string]$script:Settings.UserSearchBase
    $btnOu = New-PlainButton -Icon 'E8B7' -ToolTip 'Wybierz jednostkę organizacyjną'
    $btnOu.Padding = '9,6'
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $ou -After @($btnOu) -Caption 'Jednostka organizacyjna'))
    $state = New-Object System.Windows.Controls.ComboBox
    foreach ($i in 'Wszystkie konta', 'Tylko aktywne', 'Tylko wyłączone', 'Tylko zablokowane') { [void]$state.Items.Add($i) }
    $state.SelectedIndex = [int]$script:Settings.UserFilter
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $state -Caption 'Stan konta'))
    $find = New-PlainButton -Text 'Szukaj w AD' -Icon 'E721' -Primary
    $add = New-PlainButton -Icon 'E710' -ToolTip 'Dodaj loginy ręcznie'
    $file = New-PlainButton -Icon 'E8E5' -ToolTip 'Wczytaj loginy z pliku TXT/CSV'
    foreach ($b in $add, $file) { $b.Padding = '9,6' }
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $find -After @($file, $add)))
    $p.Query = $query
    $p.Ou = $ou
    $p.State = $state

    $tm = New-ModuleContext -Definition @{ Key = '__users'; Title = 'Lista użytkowników'; Category = ''; Icon = 'E716'; Workspace = '' }
    $script:UI.Modules['__users'] = $tm
    [void]$tm.Buttons.Add($find)
    Register-ControlHandler -Control $btnOu -EventName 'Click' -Module $tm -Action {
        $dn = Select-OrganizationalUnit -Title 'Konta z jednostki organizacyjnej' -Selected $script:UI.UserPanel.Ou.Text.Trim() -AllowDomainRoot
        if ($null -ne $dn) { $script:UI.UserPanel.Ou.Text = $dn }
    }
    Register-ControlHandler -Control $find -EventName 'Click' -Module $tm -Action { param($m) Start-AdUserLoad -Module $m }
    Register-ControlHandler -Control $add -EventName 'Click' -Module $tm -Action { param($m) Add-ManualUsers -Module $m }
    Register-ControlHandler -Control $file -EventName 'Click' -Module $tm -Action { param($m) Import-UserFile -Module $m }
    $query.add_KeyDown({ param($s, $e) if ($e.Key -eq [System.Windows.Input.Key]::Return) { Invoke-UiAction -Module $script:UI.Modules['__users'] -Action { param($m) Start-AdUserLoad -Module $m } } })

    Add-PanelMenu -Panel $p -Items @(
        @{ Text = 'Zaznacz wybrane'; Icon = 'E73A'; Action = { param($panel) Set-TargetCheck -Panel $panel -Mode CheckSelected } }
        @{ Text = 'Odznacz wybrane'; Icon = 'E739'; Action = { param($panel) Set-TargetCheck -Panel $panel -Mode UncheckSelected } }
        '-'
        @{ Text = 'Kopiuj loginy'; Icon = 'E8C8'; Action = { param($panel, $names) Set-ClipboardText ($names -join [Environment]::NewLine); Show-Toast "Skopiowano loginów: $($names.Count)" 'ok' } }
        @{ Text = 'Kopiuj adresy e-mail'; Icon = 'E715'; Action = {
                param($panel, $names)
                $mails = @(foreach ($n in $names) { $r = $panel.Table.Rows.Find($n); if ($r -and [string]$r['Mail']) { [string]$r['Mail'] } })
                if ($mails.Count -eq 0) { Show-Warning 'Wybrane konta nie mają adresów e-mail.'; return }
                Set-ClipboardText ($mails -join '; ')
                Show-Toast "Skopiowano adresów: $($mails.Count)" 'ok'
            }
        }
        @{ Text = 'Usuń z listy'; Icon = 'E74D'; Danger = $true; Action = { param($panel) Remove-TargetRows -Panel $panel } }
    )
    return $p
}

$script:UserLoadScript = {
    # Wspólny blok: wyszukiwanie (LdapFilter) albo uzupełnianie danych podanych loginów (Logins)
    param($Target, $P, $Ctx)
    Import-Module ActiveDirectory -ErrorAction Stop -Verbose:$false
    $ad = @{ ErrorAction = 'Stop' }
    if ($Ctx.Server) { $ad.Server = $Ctx.Server }
    if ($Ctx.Credential) { $ad.Credential = $Ctx.Credential }
    $props = @('DisplayName', 'UserPrincipalName', 'mail', 'Enabled', 'LockedOut', 'Department', 'Title', 'LastLogonDate')
    $users = @()
    if ($P.Logins) {
        $users = foreach ($login in $P.Logins) {
            try { Get-ADUser -Identity $login -Properties $props @ad }
            catch { Write-Error "Nie znaleziono konta $login`: $($_.Exception.Message)" }
        }
    }
    else {
        $q = @{ LDAPFilter = $P.LdapFilter; Properties = $props; ResultSetSize = 20000 }
        if ($P.SearchBase) { $q.SearchBase = $P.SearchBase }
        $users = @(Get-ADUser @q @ad)
        if ($P.OnlyLocked) { $users = @($users | Where-Object { $_.LockedOut }) }
    }
    foreach ($u in $users) {
        if (-not $u) { continue }
        [pscustomobject]@{
            Login      = $u.SamAccountName
            Name       = $u.DisplayName
            Upn        = $u.UserPrincipalName
            Mail       = $u.mail
            Enabled    = [bool]$u.Enabled
            Locked     = [bool]$u.LockedOut
            Department = $u.Department
            Title_     = $u.Title
            LastLogon  = $u.LastLogonDate
            DN         = $u.DistinguishedName
        }
    }
}

function Start-AdUserLoad {
    param([hashtable]$Module, [string[]]$Logins = @(), [string]$Source = 'AD', [switch]$Check)
    $p = $script:UI.UserPanel
    $params = @{ Logins = @($Logins) }
    if ($Logins.Count -eq 0) {
        $state = [int]$p.State.SelectedIndex
        $script:Settings.UserFilter = $state
        $script:Settings.UserSearchBase = $p.Ou.Text.Trim()
        $params.LdapFilter = New-UserLdapFilter -Query $p.Query.Text -State $state
        $params.SearchBase = $script:Settings.UserSearchBase
        $params.OnlyLocked = ($state -eq 3)
    }
    $Module.Data.Source = $Source
    $Module.Data.Check = [bool]$Check
    $Module.Data.Replace = ($Logins.Count -eq 0)
    $title = if ($Logins.Count -gt 0) { 'Uzupełnianie danych kont z AD' } else { 'Wyszukiwanie kont w AD' }
    Start-AdOperation -Module $Module -Name $title -Targets @('Active Directory') -Output None -Parameters $params -ScriptBlock $script:UserLoadScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) {
            $m.Data.LastError = (@($r.Errors)) -join "`r`n"
            Invoke-Deferred -Module $m -Action { param($m) Show-Error 'Nie udało się pobrać kont z Active Directory.' $m.Data.LastError }
            return
        }
        $items = @($r.Data)
        $panel = $script:UI.UserPanel
        if ($m.Data.Replace) {
            # Nowe wyszukiwanie zastępuje poprzednie wyniki (zaznaczone pozycje zostają)
            $added = Import-TargetRows -Panel $panel -Items $items -Source 'AD' -ReplaceSource
        }
        else {
            $added = Import-TargetRows -Panel $panel -Items $items -Source 'AD' -Check:$m.Data.Check
        }
        if ($items.Count -ge 20000) { Write-Log 'Wyświetlono pierwsze 20000 kont - zawęź wyszukiwanie.' 'WARN' }
        Write-Log ("Znaleziono w AD {0} kont (nowych na liście: {1})." -f $items.Count, $added) 'OK'
    }
}

function Add-UserLogins {
    param([hashtable]$Module, [string[]]$Names, [string]$Source)
    if ($Names.Count -eq 0) { return }
    $logins = @($Names | ForEach-Object { ($_ -replace '^.*\\', '') -replace '@.*$', '' } | Where-Object { $_ } | Select-Object -Unique)
    [void](Import-TargetRows -Panel $script:UI.UserPanel -Items @($logins | ForEach-Object { [pscustomobject]@{ Login = $_ } }) -Source $Source -Check)
    Write-Log ("Dodano {0} kont ({1}); pobieranie danych z AD…" -f $logins.Count, $Source) 'INFO' -Module 'Użytkownicy'
    if (Get-Module -ListAvailable -Name ActiveDirectory) { Start-AdUserLoad -Module $Module -Logins $logins -Source $Source -Check }
}

function Add-ManualUsers {
    param([hashtable]$Module)
    $text = Show-InputDialog -Title 'Dodaj konta' -Prompt 'Wpisz lub wklej loginy (sAMAccountName, DOMENA\login albo UPN) – po jednym w wierszu albo rozdzielone przecinkiem lub spacją.' -Multiline -Icon 'E8FA'
    if ($null -eq $text) { return }
    Add-UserLogins -Module $Module -Names (Read-NameList $text) -Source 'ręcznie'
}

function Import-UserFile {
    param([hashtable]$Module)
    $names = Read-NameFile -HeaderPattern '^(login|samaccountname|user|username|użytkownik|uzytkownik|konto)$'
    if ($null -eq $names) { return }
    if ($names.Count -eq 0) { Show-Warning 'Plik nie zawiera loginów.'; return }
    Add-UserLogins -Module $Module -Names $names -Source 'plik'
}

function Update-UserRow {
    # Aktualizacja pozycji listy po zmianie w AD (np. odblokowanie, wyłączenie konta)
    param([string]$Login, [hashtable]$Values)
    $p = $script:UI.UserPanel
    if (-not $p) { return }
    $row = $p.Table.Rows.Find($Login)
    if (-not $row) { return }
    foreach ($k in $Values.Keys) {
        if (-not $p.Table.Columns.Contains($k)) { continue }
        $v = $Values[$k]
        $row[$k] = if ($v -is [bool]) { $(if ($v) { 'Tak' } else { 'Nie' }) } else { ConvertTo-DbValue $v }
    }
    & $p.Describe $row
}
#endregion

#region Panel grup
function New-GroupLdapFilter {
    param([string]$Query, [int]$Kind)
    $parts = @('(objectCategory=group)')
    $q = ([string]$Query).Trim()
    if ($q) {
        if ($q -match '\*') {
            $v = $q -replace '\\', '\5c' -replace '\(', '\28' -replace '\)', '\29'
            $parts += "(|(name=$v)(sAMAccountName=$v)(description=$v))"
        }
        else {
            $v = ConvertTo-LdapFilterValue $q
            $parts += "(|(name=*$v*)(sAMAccountName=*$v*)(description=*$v*)(mail=$v*))"
        }
    }
    switch ($Kind) {
        1 { $parts += '(groupType:1.2.840.113556.1.4.803:=2147483648)' }
        2 { $parts += '(!(groupType:1.2.840.113556.1.4.803:=2147483648))' }
        3 { $parts += '(!(member=*))' }
        4 { $parts += '(adminCount=1)' }
    }
    return '(&' + ($parts -join '') + ')'
}

function Initialize-GroupPanel {
    $p = New-TargetPanel -Kind 'Groups' -Title 'GRUPY' -Placeholder 'Szukaj na liście…' -EmptyIcon 'E902' `
        -EmptyText "Lista jest pusta.`nWyszukaj grupy w Active Directory albo dodaj nazwy ręcznie." `
        -Columns @('Sam', 'Name', 'Scope', 'Category', 'Description', 'Mail', 'DN') -KeyColumn 'Sam'
    $p.SearchColumns = @('Sam', 'Name', 'Scope', 'Category', 'Description', 'Mail', 'Source', 'DN')
    $p.Describe = {
        param($row)
        $name = [string]$row['Name']
        $row['Title'] = if ($name) { $name } else { $row['Sam'] }
        $parts = @()
        if ($name -and $name -ne [string]$row['Sam']) { $parts += [string]$row['Sam'] }
        if ([string]$row['Scope']) { $parts += [string]$row['Scope'] }
        if ([string]$row['Category'] -eq 'Dystrybucyjna') { $parts += 'dystrybucyjna' }
        if ([string]$row['Description']) { $parts += [string]$row['Description'] }
        if ([string]$row['Source'] -ne 'AD') { $parts += [string]$row['Source'] }
        $row['Sub'] = $parts -join ' • '
        $row['Dot'] = switch ([string]$row['Category']) { 'Zabezpieczeń' { '#8CB0FF' } 'Dystrybucyjna' { '#C792EA' } default { $script:DotColors.unknown } }
    }
    $script:UI.GroupPanel = $p
    $script:UI.GroupTable = $p.Table

    $query = New-Object System.Windows.Controls.TextBox
    $query.Tag = 'Nazwa, fragment nazwy lub opisu'
    $query.ToolTip = 'Puste pole = wszystkie grupy z wybranej jednostki. Można używać gwiazdki, np. GG_*'
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $query -Caption 'Wyszukaj grupy'))
    $ou = New-Object System.Windows.Controls.TextBox
    $ou.Tag = 'Cała domena'
    $ou.Text = [string]$script:Settings.GroupSearchBase
    $btnOu = New-PlainButton -Icon 'E8B7' -ToolTip 'Wybierz jednostkę organizacyjną'
    $btnOu.Padding = '9,6'
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $ou -After @($btnOu) -Caption 'Jednostka organizacyjna'))
    $kind = New-Object System.Windows.Controls.ComboBox
    foreach ($i in 'Wszystkie grupy', 'Grupy zabezpieczeń', 'Grupy dystrybucyjne', 'Grupy bez członków', 'Grupy uprzywilejowane (adminCount)') { [void]$kind.Items.Add($i) }
    $kind.SelectedIndex = [int]$script:Settings.GroupFilter
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $kind -Caption 'Rodzaj'))
    $find = New-PlainButton -Text 'Szukaj w AD' -Icon 'E721' -Primary
    $add = New-PlainButton -Icon 'E710' -ToolTip 'Dodaj grupy ręcznie (nazwy lub sAMAccountName)'
    $file = New-PlainButton -Icon 'E8E5' -ToolTip 'Wczytaj nazwy grup z pliku TXT/CSV'
    foreach ($b in $add, $file) { $b.Padding = '9,6' }
    [void]$p.pSource.Children.Add((New-SourceRow -Stretch $find -After @($file, $add)))
    $p.Query = $query
    $p.Ou = $ou
    $p.KindBox = $kind

    $tm = New-ModuleContext -Definition @{ Key = '__groups'; Title = 'Lista grup'; Category = ''; Icon = 'E902'; Workspace = '' }
    $script:UI.Modules['__groups'] = $tm
    [void]$tm.Buttons.Add($find)
    Register-ControlHandler -Control $btnOu -EventName 'Click' -Module $tm -Action {
        $dn = Select-OrganizationalUnit -Title 'Grupy z jednostki organizacyjnej' -Selected $script:UI.GroupPanel.Ou.Text.Trim() -AllowDomainRoot
        if ($null -ne $dn) { $script:UI.GroupPanel.Ou.Text = $dn }
    }
    Register-ControlHandler -Control $find -EventName 'Click' -Module $tm -Action { param($m) Start-AdGroupLoad -Module $m }
    Register-ControlHandler -Control $add -EventName 'Click' -Module $tm -Action {
        param($m)
        $text = Show-InputDialog -Title 'Dodaj grupy' -Prompt 'Wpisz lub wklej nazwy grup albo sAMAccountName – po jednej w wierszu (nazwy ze spacjami muszą być w osobnych wierszach).' -Multiline -Icon 'E902'
        if ($null -eq $text) { return }
        Add-GroupNames -Module $m -Names @(Get-TextLines $text | ForEach-Object { $_.Trim('"') }) -Source 'ręcznie'
    }
    Register-ControlHandler -Control $file -EventName 'Click' -Module $tm -Action {
        param($m)
        $names = Read-NameFile -HeaderPattern '^(name|nazwa|grupa|group|samaccountname)$'
        if ($null -eq $names) { return }
