#region Zarządzanie zdalne: Diagnostyka
Register-Module -Workspace 'Remote' -Category 'Diagnostyka' -Key 'Connectivity' -Title 'Łączność' -Icon 'E968' `
    -Description 'DNS, ping, porty TCP i sesja PowerShell Remoting. Test działa lokalnie – także dla komputerów bez WinRM – i koloruje kropki na liście komputerów.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $row = Add-ToolbarRow -Module $m -Title 'Parametry'
    Add-Label -Parent $row -Text 'Porty TCP' | Out-Null
    $m.Ports = Add-TextBox -Parent $row -Width 220 -Text '5985, 5986, 445, 3389, 135'
    Add-Label -Parent $row -Text 'Limit (ms)' | Out-Null
    $m.TcpTimeout = Add-Numeric -Parent $row -Value 1500 -Minimum 200 -Maximum 10000 -Width 70
    $m.TestSession = Add-CheckBox -Parent $row -Text 'Test sesji PowerShell' -Checked $true -ToolTip 'Invoke-Command na komputerze docelowym (wymaga WinRM i uprawnień)'
    $row2 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row2 -Text 'Testuj zaznaczone' -Icon 'E72C' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $ports = @(Split-ListText ($m.Ports.Text -replace '\s+', ',') | Where-Object { $_ -match '^\d+$' -and [int]$_ -ge 1 -and [int]$_ -le 65535 } | ForEach-Object { [int]$_ } | Select-Object -Unique)
        $params = @{ Ports = $ports; TimeoutMs = (Get-Num $m.TcpTimeout); TestSession = (Test-Checked $m.TestSession) }
        $m.Data.Counts = @{ ok = 0; warn = 0; crit = 0 }
        Reset-StatTiles $m
        Start-HostOperation -Module $m -Name 'Test łączności' -Targets $targets -Local -Parameters $params -ScriptBlock {
            param($Target, $P, $Ctx)
            $row = [ordered]@{ 'Stan' = '' }
            $ip = ''
            try {
                $addresses = [System.Net.Dns]::GetHostAddresses($Target) | Where-Object { $_.AddressFamily -eq 'InterNetwork' }
                $ip = (@($addresses | ForEach-Object { $_.IPAddressToString }) -join ', ')
            }
            catch { $ip = '(brak w DNS)' }
            $row['Adres IP'] = $ip
            $pingOk = $false
            $rtt = $null
            try {
                $reply = (New-Object System.Net.NetworkInformation.Ping).Send($Target, 1000)
                if ($reply.Status -eq 'Success') { $pingOk = $true; $rtt = [int]$reply.RoundtripTime }
            }
            catch { }
            $row['Ping'] = $pingOk
            $row['Czas (ms)'] = $rtt
            $anyPort = $false
            foreach ($port in $P.Ports) {
                $open = $false
                $client = New-Object System.Net.Sockets.TcpClient
                try {
                    $async = $client.BeginConnect($Target, [int]$port, $null, $null)
                    if ($async.AsyncWaitHandle.WaitOne([int]$P.TimeoutMs) -and $client.Connected) { $open = $true }
                }
                catch { }
                finally { $client.Close() }
                if ($open) { $anyPort = $true }
                $row["TCP $port"] = $open
            }
            $psOk = $null
            if ($P.TestSession) {
                try {
                    $ic = @{ ComputerName = $Target; ErrorAction = 'Stop'; ScriptBlock = { $PSVersionTable.PSVersion.ToString() } }
                    if ($Ctx.Credential) { $ic.Credential = $Ctx.Credential }
                    if ($Ctx.SessionOption) { $ic.SessionOption = $Ctx.SessionOption }
                    $row['PowerShell zdalnie'] = 'Tak (PS ' + (Invoke-Command @ic) + ')'
                    $psOk = $true
                }
                catch {
                    $row['PowerShell zdalnie'] = 'Nie'
                    $row['Szczegóły'] = ($_.Exception.Message -split "`n")[0].Trim()
                    $psOk = $false
                }
            }
            if ($psOk -eq $true -or ($null -eq $psOk -and ($pingOk -or $anyPort))) { $row['Stan'] = 'Dostępny'; $row['__tone'] = 'ok' }
            elseif ($pingOk -or $anyPort) { $row['Stan'] = 'Częściowo'; $row['__tone'] = 'warn' }
            else { $row['Stan'] = 'Niedostępny'; $row['__tone'] = 'crit' }
            [pscustomobject]$row
        } -OnResult {
            param($m, $r)
            $d = @($r.Data | Where-Object { $_ })
            $tone = if ($d.Count -gt 0) { [string](Get-ObjectValue $d[0] '__tone') } else { 'crit' }
            if (-not $tone) { $tone = 'crit' }
            $status = switch ($tone) { 'ok' { 'online' } 'warn' { 'częściowo dostępny' } default { 'offline' } }
            $psText = if ($d.Count -gt 0) { [string](Get-ObjectValue $d[0] 'PowerShell zdalnie') } else { '' }
            if ($psText -like 'Tak*') { $status += ' • ' + ($psText -replace '^Tak \((.*)\)$', '$1') }
            Set-ComputerState -Name $r.Target -State $tone -Status $status
            $m.Data.Counts[$tone]++
        } -OnComplete {
            param($m)
            Set-StatTile -Module $m -Key 'ok' -Value ([string]$m.Data.Counts.ok) -Tone 'ok'
            Set-StatTile -Module $m -Key 'warn' -Value ([string]$m.Data.Counts.warn) -Tone $(if ($m.Data.Counts.warn) { 'warn' } else { '' })
            Set-StatTile -Module $m -Key 'crit' -Value ([string]$m.Data.Counts.crit) -Tone $(if ($m.Data.Counts.crit) { 'crit' } else { '' })
        }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Zaznacz tylko dostępne' -Icon 'E73E' -Module $m -AlwaysEnabled -ToolTip 'Na liście komputerów zostaną zaznaczone tylko komputery dostępne w ostatnim teście' -OnClick {
        param($m)
        $online = @($m.Table.Rows | Where-Object { [string]$_['__tone'] -eq 'ok' } | ForEach-Object { [string]$_['Komputer'] })
        if ($online.Count -eq 0) { Show-Warning 'Brak komputerów dostępnych w ostatnim teście.'; return }
        foreach ($r in $script:UI.HostTable.Rows) { $r['Sel'] = ($online -contains [string]$r['Name']) }
        Update-TargetCount $script:UI.ComputerPanel
        Show-Toast "Zaznaczono dostępne komputery: $($online.Count)" 'ok'
    } | Out-Null
    Add-StatTile -Module $m -Key 'ok' -Label 'Dostępne' -Icon 'E73E' | Out-Null
    Add-StatTile -Module $m -Key 'warn' -Label 'Częściowo (bez WinRM)' -Icon 'E7BA' | Out-Null
    Add-StatTile -Module $m -Key 'crit' -Label 'Niedostępne' -Icon 'E711' | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'Diagnostyka' -Key 'Inventory' -Title 'Inwentaryzacja' -Icon 'E7F8' `
    -Description 'Sprzęt, system, numer seryjny, pamięć, dysk systemowy, adresy IP i zalogowany użytkownik zaznaczonych komputerów.' -Build {
    param($m)
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pobierz informacje' -Icon 'E896' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Inwentaryzacja' -Targets $targets -ScriptBlock {
            param($P)
            $cs = Get-CimInstance -ClassName Win32_ComputerSystem
            $os = Get-CimInstance -ClassName Win32_OperatingSystem
            $bios = Get-CimInstance -ClassName Win32_BIOS
            $cpu = @(Get-CimInstance -ClassName Win32_Processor)[0]
            $nics = @(Get-CimInstance -ClassName Win32_NetworkAdapterConfiguration -Filter 'IPEnabled = True')
            $ips = @($nics | ForEach-Object { $_.IPAddress } | Where-Object { $_ -match '^\d{1,3}(\.\d{1,3}){3}$' }) -join ', '
            $macs = @($nics | ForEach-Object { $_.MACAddress } | Where-Object { $_ }) -join ', '
            $sysDisk = Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $env:SystemDrive)
            $cv = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
            $release = ''
            $build = $os.BuildNumber
            if ($cv) {
                if ($cv.DisplayVersion) { $release = $cv.DisplayVersion } elseif ($cv.ReleaseId) { $release = $cv.ReleaseId }
                if ($null -ne $cv.UBR) { $build = '{0}.{1}' -f $os.BuildNumber, $cv.UBR }
            }
            $tpm = $null
            try { $tpm = Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftTpm' -ClassName Win32_Tpm -ErrorAction Stop } catch { }
            $secureBoot = $null
            try { $secureBoot = Confirm-SecureBootUEFI -ErrorAction Stop } catch { }
            [pscustomobject]@{
                'Producent'                = $cs.Manufacturer
                'Model'                    = $cs.Model
                'Numer seryjny'            = $bios.SerialNumber
                'BIOS'                     = $bios.SMBIOSBIOSVersion
                'System'                   = $os.Caption
                'Wydanie'                  = $release
                'Kompilacja'               = $build
                'Architektura'             = $os.OSArchitecture
                'Procesor'                 = ([string]$cpu.Name).Trim()
                'Rdzenie'                  = $cpu.NumberOfCores
                'RAM (GB)'                 = [Math]::Round($cs.TotalPhysicalMemory / 1GB, 1)
                'Dysk systemowy (GB)'      = $(if ($sysDisk) { [Math]::Round($sysDisk.Size / 1GB, 1) } else { $null })
                'Wolne na systemowym (GB)' = $(if ($sysDisk) { [Math]::Round($sysDisk.FreeSpace / 1GB, 1) } else { $null })
                'TPM'                      = $(if ($tpm) { 'wersja ' + (([string]$tpm.SpecVersion -split ',')[0]).Trim() } else { 'brak / niedostępny' })
                'Secure Boot'              = $secureBoot
                'Zalogowany użytkownik'    = $cs.UserName
                'Domena'                   = $cs.Domain
                'Adresy IP'                = $ips
                'MAC'                      = $macs
                'Instalacja systemu'       = $os.InstallDate
                'Ostatni start'            = $os.LastBootUpTime
            }
        }
    } | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'Diagnostyka' -Key 'Performance' -Title 'Wydajność' -Icon 'E9D2' -Badge 'nowe' `
    -Description 'Co obciąża komputer lub serwer: procesor (kolejka, jądro, przerwania), pamięć (dostępna, commit, stronicowanie), dyski (opóźnienia, kolejki, IOPS), sieć (wykorzystanie, kolejki, błędy, retransmisje TCP), procesy z czołówki CPU/pamięci/I/O (z usługami i użytkownikiem) oraz zdarzenia o awariach. Ocena wskazuje wąskie gardło.' -Build {
    param($m)
    Initialize-PerfModule -Module $m
}

Register-Module -Workspace 'Remote' -Category 'Diagnostyka' -Key 'Power' -Title 'Zasilanie i uptime' -Icon 'E7E8' `
    -Description 'Czas pracy, oczekujący restart (CBS, Windows Update, zmiana nazwy, SCCM) oraz zaplanowany restart lub wyłączenie z komunikatem dla użytkownika.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.GoodWhenNo = @('Oczekuje restartu')
    $row = Add-ToolbarRow -Module $m -Title 'Sprawdzenie'
    Add-Button -Parent $row -Text 'Pokaż uptime' -Icon 'E916' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Uptime' -Targets $targets -ScriptBlock {
            param($P)
            $os = Get-CimInstance -ClassName Win32_OperatingSystem
            $boot = $os.LastBootUpTime
            $up = (Get-Date) - $boot
            $reasons = @()
            if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { $reasons += 'Obsługa składników (CBS)' }
            if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { $reasons += 'Windows Update' }
            $pending = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name PendingFileRenameOperations -ErrorAction SilentlyContinue
            if ($pending) { $reasons += 'Operacje na plikach' }
            $active = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ActiveComputerName' -ErrorAction SilentlyContinue).ComputerName
            $next = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\ComputerName\ComputerName' -ErrorAction SilentlyContinue).ComputerName
            if ($active -and $next -and $active -ne $next) { $reasons += "Zmiana nazwy na $next" }
            try {
                $ccm = Invoke-CimMethod -Namespace 'root\ccm\ClientSDK' -ClassName CCM_ClientUtilities -MethodName DetermineIfRebootPending -ErrorAction Stop
                if ($ccm.RebootPending -or $ccm.IsHardRebootPending) { $reasons += 'SCCM' }
            }
            catch { }
            [pscustomobject]@{
                'Ostatni start'     = $boot
                'Czas pracy'        = '{0} d {1:00} h {2:00} min' -f $up.Days, $up.Hours, $up.Minutes
                'Dni pracy'         = [Math]::Round($up.TotalDays, 1)
                'Oczekuje restartu' = ($reasons.Count -gt 0)
                'Powód'             = ($reasons -join ', ')
                'Zalogowany'        = (Get-CimInstance -ClassName Win32_ComputerSystem).UserName
                '__flag'            = $(if ($reasons.Count -gt 0) { 'warn' } else { '' })
            }
        }
    } | Out-Null

    $row2 = Add-ToolbarRow -Module $m -Title 'Restart i wyłączenie'
    Add-Label -Parent $row2 -Text 'Opóźnienie (s)' | Out-Null
    $m.Delay = Add-Numeric -Parent $row2 -Value 60 -Minimum 0 -Maximum 86400 -Width 80
    Add-Label -Parent $row2 -Text 'Komunikat' | Out-Null
    $m.Message = Add-TextBox -Parent $row2 -Width 380 -Text 'Komputer zostanie uruchomiony ponownie przez administratora. Zapisz swoją pracę.'
    $m.Force = Add-CheckBox -Parent $row2 -Text 'Wymuś zamknięcie aplikacji' -Checked $true
    $row3 = Add-ToolbarRow -Module $m -Title ' '
    $powerAction = {
        param($m, $s)
        $mode = [string]$s.Tag
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $question = @{ '/r' = 'Uruchomić ponownie wybrane komputery?'; '/s' = 'Wyłączyć wybrane komputery?'; '/a' = 'Anulować zaplanowany restart lub wyłączenie na wybranych komputerach?' }[$mode]
        $targets = @(Confirm-Action -Text $question -Items $targets -ConfirmText $(if ($mode -eq '/a') { 'Anuluj zaplanowane' } else { 'Wykonaj' }) -Danger:($mode -ne '/a') -Select); if ($targets.Count -eq 0) { return }
        $params = @{ Mode = $mode; Delay = (Get-Num $m.Delay); Message = $m.Message.Text.Trim(); Force = (Test-Checked $m.Force) }
        Start-HostOperation -Module $m -Name "Zasilanie ($mode)" -Targets $targets -Output Log -Parameters $params -ScriptBlock {
            param($P)
            $shutdown = Join-Path $env:SystemRoot 'System32\shutdown.exe'
            if ($P.Mode -eq '/a') {
                $out = & $shutdown /a 2>&1
                if ($LASTEXITCODE -eq 0) { return 'Anulowano zaplanowane zamknięcie systemu.' }
                if ($LASTEXITCODE -eq 1116) { return 'Brak zaplanowanego zamknięcia systemu.' }
                throw ("shutdown.exe /a: kod {0} {1}" -f $LASTEXITCODE, ($out | Out-String).Trim())
            }
            $cmdArgs = @($P.Mode, '/t', [string]$P.Delay, '/d', 'p:0:0')
            if ($P.Force) { $cmdArgs += '/f' }
            if ($P.Message) { $cmdArgs += '/c'; $cmdArgs += $P.Message.Substring(0, [Math]::Min(500, $P.Message.Length)) }
            $out = & $shutdown @cmdArgs 2>&1
            if ($LASTEXITCODE -ne 0) { throw ("shutdown.exe: kod {0} {1}" -f $LASTEXITCODE, ($out | Out-String).Trim()) }
            $what = if ($P.Mode -eq '/r') { 'Restart' } else { 'Wyłączenie' }
            "$what zaplanowane za $($P.Delay) s."
        }
    }
    $b = Add-Button -Parent $row3 -Text 'Restart' -Icon 'E777' -Module $m -Danger -OnClick $powerAction
    $b.Tag = '/r'
    $b = Add-Button -Parent $row3 -Text 'Wyłącz' -Icon 'E7E8' -Module $m -Danger -OnClick $powerAction
    $b.Tag = '/s'
    $b = Add-Button -Parent $row3 -Text 'Anuluj zaplanowane' -Icon 'E711' -Module $m -OnClick $powerAction
    $b.Tag = '/a'
}
#endregion

#region Zarządzanie zdalne: Użytkownicy i dostęp
# Profile użytkowników: lista profili z komputerów + weryfikacja kont w AD (ADSI - nie wymaga RSAT).
# Kandydaci do usunięcia: konta usunięte, wyłączone lub wygasłe w AD, usunięte konta lokalne, profile tymczasowe
# i uszkodzone, opcjonalnie profile nieużywane dłużej niż N dni. Profile załadowane (zalogowany użytkownik)
# i systemowe nigdy nie są kandydatami i nie są usuwane.
$script:ProfileScanScript = {
    param($Target, $P, $Ctx)
    $ic = @{ ComputerName = $Target; ErrorAction = 'Stop'; ArgumentList = @(, @{ Size = $P.Size }) }
    if ($Ctx.Credential) { $ic.Credential = $Ctx.Credential }
    if ($Ctx.SessionOption) { $ic.SessionOption = $Ctx.SessionOption }
    $profiles = @(Invoke-Command @ic -ScriptBlock {
            param($Q)
            # Konta lokalne (SID -> włączone) i SID komputera - do rozpoznania profili kont lokalnych
            $machineSid = ''
            $localUsers = @{}
            try {
                foreach ($u in @(Get-LocalUser -ErrorAction Stop)) {
                    $localUsers[[string]$u.SID] = [bool]$u.Enabled
                    if (-not $machineSid) { $machineSid = [string]$u.SID.AccountDomainSid }
                }
            }
            catch {
                try {
                    $computer = [ADSI]"WinNT://$env:COMPUTERNAME,computer"
                    foreach ($child in $computer.Children) {
                        if ($child.SchemaClassName -ne 'User') { continue }
                        $sidObj = New-Object System.Security.Principal.SecurityIdentifier($child.objectSid.Value, 0)
                        $localUsers[$sidObj.Value] = -not ([int]$child.UserFlags.Value -band 2)
                        if (-not $machineSid) { $machineSid = $sidObj.AccountDomainSid.Value }
                    }
                }
                catch { }
            }
            $system = @('S-1-5-18', 'S-1-5-19', 'S-1-5-20')
            foreach ($pr in @(Get-CimInstance -ClassName Win32_UserProfile | Where-Object { -not $_.Special -and $system -notcontains $_.SID })) {
                $sid = [string]$pr.SID
                # Ostatnie użycie: czasy załadowania/wyładowania profilu z ProfileList (Windows 10 1903+),
                # potem NTUSER.DAT; LastUseTime z WMI bywa zmieniany przez skanery i kopie zapasowe
                $reg = Get-ItemProperty -LiteralPath "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList\$sid" -ErrorAction SilentlyContinue
                $times = @()
                foreach ($pair in @(@('LocalProfileLoadTimeHigh', 'LocalProfileLoadTimeLow'), @('LocalProfileUnloadTimeHigh', 'LocalProfileUnloadTimeLow'))) {
                    if ($reg -and $null -ne $reg.($pair[0]) -and $null -ne $reg.($pair[1])) {
                        try {
                            $ft = ([int64][uint32]$reg.($pair[0]) -shl 32) -bor [int64][uint32]$reg.($pair[1])
                            if ($ft -gt 0) { $times += [datetime]::FromFileTime($ft) }
                        }
                        catch { }
                    }
                }
                $last = $null
                $source = 'rejestr (ProfileList)'
                if ($times.Count -gt 0) { $last = @($times | Sort-Object -Descending)[0] }
                else {
                    $nt = if ($pr.LocalPath) { Get-Item -LiteralPath (Join-Path $pr.LocalPath 'NTUSER.DAT') -Force -ErrorAction SilentlyContinue } else { $null }
                    if ($nt) { $last = $nt.LastWriteTime; $source = 'NTUSER.DAT' }
                    elseif ($pr.LastUseTime) { $last = $pr.LastUseTime; $source = 'WMI LastUseTime' }
                }
                $size = $null
                if ($Q.Size -and $pr.LocalPath -and (Test-Path -LiteralPath $pr.LocalPath)) {
                    # Własne przejście katalogów: pomija dowiązania (reparse points), nie przerywa na braku dostępu
                    $total = [int64]0
                    $stack = New-Object System.Collections.Stack
                    $stack.Push((New-Object System.IO.DirectoryInfo($pr.LocalPath)))
                    while ($stack.Count -gt 0) {
                        $dir = $stack.Pop()
                        try {
                            foreach ($e in $dir.EnumerateFileSystemInfos()) {
                                if ($e.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { continue }
                                if ($e -is [System.IO.DirectoryInfo]) { $stack.Push($e) } else { $total += $e.Length }
                            }
                        }
                        catch { }
                    }
                    $size = $total
                }
                $localState = ''
                if ($machineSid -and $sid.StartsWith($machineSid + '-')) {
                    $localState = if (-not $localUsers.ContainsKey($sid)) { 'missing' } elseif ($localUsers[$sid]) { 'enabled' } else { 'disabled' }
                }
                $account = ''
                try { $account = (New-Object System.Security.Principal.SecurityIdentifier($sid)).Translate([System.Security.Principal.NTAccount]).Value } catch { }
                [pscustomobject]@{
                    Sid        = $sid
                    Path       = [string]$pr.LocalPath
                    Loaded     = [bool]$pr.Loaded
                    Status     = [int]$pr.Status
                    Roaming    = [bool]$pr.RoamingConfigured
                    LastUse    = $last
                    LastSource = $source
                    Size       = $size
                    LocalState = $localState
                    Account    = $account
                }
            }
        })

    # Weryfikacja kont w AD przez ADSI (wspólna pamięć podręczna wszystkich komputerów w $P.Cache)
    $cache = $P.Cache
    $server = if ($Ctx.Server) { $Ctx.Server + '/' } else { '' }
    $user = $null
    $pass = $null
    if ($Ctx.Credential) { $user = $Ctx.Credential.UserName; $pass = $Ctx.Credential.GetNetworkCredential().Password }
    $newEntry = {
        param([string]$Path)
        if ($user) { New-Object System.DirectoryServices.DirectoryEntry($Path, $user, $pass) } else { New-Object System.DirectoryServices.DirectoryEntry($Path) }
    }
    if (-not $cache.ContainsKey('__domainSid')) {
        try {
            $rootDse = & $newEntry ('LDAP://{0}RootDSE' -f $server)
            $dnc = [string]$rootDse.Properties['defaultNamingContext'].Value
            $domain = & $newEntry ('LDAP://{0}{1}' -f $server, $dnc)
            $cache['__domainSid'] = (New-Object System.Security.Principal.SecurityIdentifier([byte[]]$domain.Properties['objectSid'].Value, 0)).Value
        }
        catch {
            $cache['__domainSid'] = ''
            $cache['__domainError'] = $_.Exception.Message
        }
    }
    $domainSid = [string]$cache['__domainSid']
    $classify = [scriptblock]::Create($P.ClassifyScript)
    $now = Get-Date
    foreach ($pr in $profiles) {
        $sid = [string]$pr.Sid
        $ad = @{ Kind = 'other'; Found = $false; Error = ''; Sam = ''; Name = ''; Uac = 0; Expires = [int64]0; Logon = [int64]0 }
        if ($sid.StartsWith('S-1-12-1-')) { $ad.Kind = 'entra' }
        elseif ($pr.LocalState) { $ad.Kind = 'local' }
        elseif ($domainSid -and $sid.StartsWith($domainSid + '-')) {
            $ad.Kind = 'domain'
            $info = $cache[$sid]
            if (-not $info) {
                $info = @{ Found = $false; Error = ''; Sam = ''; Name = ''; Uac = 0; Expires = [int64]0; Logon = [int64]0 }
                try {
                    $entry = & $newEntry ('LDAP://{0}<SID={1}>' -f $server, $sid)
                    $ds = New-Object System.DirectoryServices.DirectorySearcher($entry)
                    $ds.SearchScope = 'Base'
                    $ds.Filter = '(objectClass=*)'
                    foreach ($a in 'sAMAccountName', 'displayName', 'userAccountControl', 'accountExpires', 'lastLogonTimestamp') { [void]$ds.PropertiesToLoad.Add($a) }
                    $res = $ds.FindOne()
                    if ($res) {
                        $info.Found = $true
                        if ($res.Properties['samaccountname'].Count) { $info.Sam = [string]$res.Properties['samaccountname'][0] }
                        if ($res.Properties['displayname'].Count) { $info.Name = [string]$res.Properties['displayname'][0] }
                        if ($res.Properties['useraccountcontrol'].Count) { $info.Uac = [int]$res.Properties['useraccountcontrol'][0] }
                        if ($res.Properties['accountexpires'].Count) { $info.Expires = [int64]$res.Properties['accountexpires'][0] }
                        if ($res.Properties['lastlogontimestamp'].Count) { $info.Logon = [int64]$res.Properties['lastlogontimestamp'][0] }
                    }
                }
                catch {
                    $ex = $_.Exception
                    while ($ex.InnerException -and -not ($ex -is [System.Runtime.InteropServices.COMException])) { $ex = $ex.InnerException }
                    # 0x80072030: obiekt nie istnieje - konto usunięte
                    if (-not ($ex -is [System.Runtime.InteropServices.COMException] -and $ex.ErrorCode -eq -2147016656)) { $info.Error = $ex.Message }
                }
                $cache[$sid] = $info
            }
            foreach ($k in @($info.Keys)) { $ad[$k] = $info[$k] }
        }
        elseif (-not $domainSid -and $cache['__domainError']) { $ad.Kind = 'error'; $ad.Error = [string]$cache['__domainError'] }
        & $classify $pr $ad $P $now
    }
}

# Ocena profilu (wydzielona, żeby dało się ją testować bez AD i WinRM):
# $pr - profil z komputera, $Ad - wynik sprawdzenia konta (Kind: domain/local/entra/other/error), $P - parametry, $Now - data
$script:ProfileClassifyScript = {
    param($pr, $Ad, $P, [datetime]$Now)
    $kind = 'inny'
    $state = ''
    $stateTone = ''
    $candidate = $false
    $display = ''
    $adLogon = $null
    $account = [string]$pr.Account
    switch ($Ad.Kind) {
        'entra' { $kind = 'Entra ID'; $state = 'Konto Entra ID (nie sprawdzano)' }
        'local' {
            $kind = 'lokalny'
            switch ($pr.LocalState) {
                'missing' { $state = 'Konto lokalne usunięte'; $stateTone = 'crit'; $candidate = $true }
                'disabled' { $state = 'Konto lokalne wyłączone'; $stateTone = 'warn' }
                default { $state = 'Konto lokalne aktywne' }
            }
        }
        'domain' {
            $kind = 'domenowy'
            if ($Ad.Error) { $state = 'Nie sprawdzono: ' + $Ad.Error }
            elseif (-not $Ad.Found) { $state = 'Konto usunięte z AD'; $stateTone = 'crit'; $candidate = $true }
            else {
                if ($Ad.Sam -and -not $account) { $account = $Ad.Sam }
                $display = $Ad.Name
                if ([int64]$Ad.Logon -gt 0) { $adLogon = [datetime]::FromFileTime([int64]$Ad.Logon) }
                $expired = ([int64]$Ad.Expires -gt 0 -and [int64]$Ad.Expires -lt [int64]::MaxValue -and [datetime]::FromFileTimeUtc([int64]$Ad.Expires) -lt $Now.ToUniversalTime())
                if ([int]$Ad.Uac -band 2) { $state = 'Konto wyłączone w AD'; $stateTone = 'crit'; $candidate = $true }
                elseif ($expired) { $state = 'Konto wygasło'; $stateTone = 'crit'; $candidate = $true }
                else { $state = 'Konto aktywne w AD' }
            }
        }
        'error' { $state = 'Nie sprawdzono: ' + $Ad.Error }
        default { $state = 'Konto z innej domeny (nie sprawdzano)' }
    }
    $temp = (([int]$pr.Status -band 1) -ne 0) -or ([string]$pr.Path -match '\.TEMP(\.\d+)?$')
    $corrupt = (([int]$pr.Status -band 8) -ne 0)
    $days = if ($pr.LastUse) { [int][Math]::Floor(($Now - [datetime]$pr.LastUse).TotalDays) } else { $null }
    $inactive = ($null -ne $days -and $days -ge [int]$P.Days)
    $verdict = ''
    $tone = 'ok'
    if ($pr.Loaded) { $verdict = 'W użyciu (zalogowany)'; $tone = 'info'; $candidate = $false }
    elseif ($stateTone -eq 'crit') { $verdict = $state; $tone = 'crit' }
    elseif ($temp -or $corrupt) { $verdict = $(if ($corrupt) { 'Profil uszkodzony' } else { 'Profil tymczasowy' }); $tone = 'warn'; $candidate = $true }
    elseif ($inactive) {
        $verdict = "Nieużywany od $days dni"
        $tone = 'warn'
        if ($P.InactiveCandidates) { $candidate = $true }
    }
    elseif ($state -like 'Nie sprawdzono*') { $verdict = 'Nie sprawdzono'; $tone = '' }
    elseif ($stateTone -eq 'warn') { $verdict = $state; $tone = 'warn' }
    else { $verdict = 'Aktywny' }
    $type = $kind
    if ($pr.Roaming) { $type += ', mobilny' }
    if ($temp) { $type += ', tymczasowy' }
    [pscustomobject][ordered]@{
        'Ocena'                   = $verdict
        'Kandydat'                = $candidate
        'Konto'                   = $(if ($account) { $account } else { '(nieznane)' })
        'Nazwa'                   = $display
        'Stan konta'              = $state
        'Ostatnie użycie'         = $pr.LastUse
        'Dni'                     = $days
        'Rozmiar (GB)'            = $(if ($null -ne $pr.Size) { [Math]::Round([double]$pr.Size / 1GB, 2) } else { $null })
        'Ścieżka'                 = $pr.Path
        'Załadowany'              = [bool]$pr.Loaded
        'Ostatnie logowanie w AD' = $adLogon
        'Typ'                     = $type
        'Źródło daty'             = $pr.LastSource
        'SID'                     = [string]$pr.Sid
        '__tone'                  = $tone
        '__flag'                  = $(if ($pr.Loaded) { 'muted' } else { '' })
    }
}

function Update-ProfileStats {
    param([hashtable]$Module)
    $rows = @($Module.Table.Rows | Where-Object { [string]$_['SID'] })
    $candidates = @($rows | Where-Object { [string]$_['Kandydat'] -eq 'Tak' })
    $measured = @($candidates | Where-Object { $_['Rozmiar (GB)'] -isnot [System.DBNull] })
    $hosts = @($Module.Table.Rows | ForEach-Object { [string]$_['Komputer'] } | Select-Object -Unique)
    Set-StatTile -Module $Module -Key 'profiles' -Value ([string]$rows.Count)
    Set-StatTile -Module $Module -Key 'candidates' -Value ([string]$candidates.Count) -Tone $(if ($candidates.Count) { 'warn' } else { 'ok' })
    if ($measured.Count -gt 0) {
        $sum = 0.0
        foreach ($r in $measured) { $sum += [double]$r['Rozmiar (GB)'] }
        Set-StatTile -Module $Module -Key 'reclaim' -Value ('{0:N1} GB' -f $sum) -Tone 'info' -Label 'Do odzyskania (kandydaci)'
    }
    else { Set-StatTile -Module $Module -Key 'reclaim' -Value '–' -Label 'Do odzyskania (włącz pomiar rozmiaru)' }
    Set-StatTile -Module $Module -Key 'hosts' -Value ([string]$hosts.Count)
}

Register-Module -Workspace 'Remote' -Category 'Użytkownicy i dostęp' -Key 'Profiles' -Title 'Profile użytkowników' -Icon 'E77B' -Badge 'Nowość w wersji 4.0' `
    -Description 'Profile na komputerach porównane z Active Directory: konta usunięte, wyłączone i wygasłe, profile tymczasowe oraz nieużywane – kandydaci do usunięcia. Weryfikacja przez ADSI (bez RSAT), bezpieczne usuwanie przez Win32_UserProfile.' -Build {
    param($m)
    $m.PillColumns = @('Ocena')
    $m.GoodWhenNo = @('Kandydat', 'Załadowany')
    $m.HiddenColumns = @()
    $m.EmptyIcon = 'E77B'
    $row = Add-ToolbarRow -Module $m -Title 'Ocena'
    Add-Label -Parent $row -Text 'Nieużywany dłużej niż (dni)' | Out-Null
    $m.Days = Add-Numeric -Parent $row -Value ([int]$script:Settings.InactiveDays) -Minimum 1 -Maximum 3650 -Width 70
    $m.InactiveCand = Add-CheckBox -Parent $row -Text 'Nieużywane też są kandydatami' -Checked $true -ToolTip 'Profile aktywnych kont, nieużywane dłużej niż podana liczba dni, zostaną oznaczone jako kandydaci do usunięcia'
    $m.MeasureSize = Add-CheckBox -Parent $row -Text 'Mierz rozmiar profili (wolniej)' -ToolTip 'Sumuje rozmiar plików w folderach profili (z pominięciem dowiązań)'
    $row2 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row2 -Text 'Sprawdź profile' -Icon 'E721' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $params = @{
            Days               = (Get-Num $m.Days)
            InactiveCandidates = (Test-Checked $m.InactiveCand)
            Size               = (Test-Checked $m.MeasureSize)
            Cache              = [hashtable]::Synchronized(@{})
            ClassifyScript     = $script:ProfileClassifyScript.ToString()
        }
        Reset-StatTiles $m
        Start-HostOperation -Module $m -Name 'Profile użytkowników' -Targets $targets -Local -Parameters $params -ScriptBlock $script:ProfileScanScript -OnComplete { param($m) Update-ProfileStats -Module $m }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Zaznacz kandydatów' -Icon 'E8B3' -Module $m -OnClick {
        param($m)
        $grid = $m.Grid
        $grid.SelectedItems.Clear()
        $count = 0
        foreach ($drv in @($m.View | ForEach-Object { $_ })) {
            if ([string]$drv['Kandydat'] -eq 'Tak') { [void]$grid.SelectedItems.Add($drv); $count++ }
        }
        if ($count -eq 0) { Show-Toast 'Brak kandydatów do usunięcia w widocznych wierszach.' 'info' }
        else { Show-Toast "Zaznaczono kandydatów: $count" 'ok' }
    } | Out-Null
    $m.OnlyCand = Add-CheckBox -Parent $row2 -Text 'Pokaż tylko kandydatów'
    Register-ControlHandler -Control $m.OnlyCand -EventName 'Checked' -Module $m -Action { param($m) $m.ExtraFilter = "[Kandydat] = 'Tak'"; Update-ResultFilter -Module $m }
    Register-ControlHandler -Control $m.OnlyCand -EventName 'Unchecked' -Module $m -Action { param($m) $m.ExtraFilter = ''; Update-ResultFilter -Module $m }
    Add-Button -Parent $row2 -Text 'Usuń zaznaczone profile' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Remove $m $null } | Out-Null

    $m.Actions.Remove = {
        param($m, $Rows)
        $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $m })
        $selected = @($source | Where-Object { [string](Get-ObjectValue $_ 'SID') -match '^S-1-[\d-]+$' })
        if ($selected.Count -eq 0) { Show-Warning 'Zaznacz w tabeli profile do usunięcia (np. przyciskiem «Zaznacz kandydatów»).'; return }
        $loaded = @($selected | Where-Object { [string](Get-ObjectValue $_ 'Załadowany') -eq 'Tak' })
        $selected = @($selected | Where-Object { [string](Get-ObjectValue $_ 'Załadowany') -ne 'Tak' })
        if ($selected.Count -eq 0) { Show-Warning 'Zaznaczone profile są w użyciu (użytkownicy są zalogowani) – nie można ich usunąć.'; return }
        $nonCandidates = @($selected | Where-Object { [string](Get-ObjectValue $_ 'Kandydat') -ne 'Tak' })
        $items = foreach ($r in $selected) {
            $size = Get-ObjectValue $r 'Rozmiar (GB)'
            '{0}: {1}{2} – {3}' -f (Get-ObjectValue $r 'Komputer'), (Get-ObjectValue $r 'Ścieżka'), $(if ($null -ne $size) { " ($size GB)" } else { '' }), (Get-ObjectValue $r 'Ocena')
        }
        $text = "Usunąć $($selected.Count) profil(i) użytkowników? Folder profilu i jego wpis w rejestrze zostaną trwale usunięte – tej operacji nie można cofnąć."
        if ($loaded.Count -gt 0) { $text += "`r`n`r`nPominięto profile w użyciu: $($loaded.Count)." }
        if ($nonCandidates.Count -gt 0) { $text += "`r`n`r`nUWAGA: $($nonCandidates.Count) z zaznaczonych profili NIE jest kandydatem do usunięcia (konto jest aktywne i profil był niedawno używany)." }
        if (-not (Confirm-Action -Text $text -Items $items -Title 'Usuwanie profili' -ConfirmText 'Usuń profile' -Danger)) { return }
        $per = @{}
        foreach ($r in $selected) {
            $h = [string](Get-ObjectValue $r 'Komputer')
            if (-not $per.ContainsKey($h)) { $per[$h] = @{ Sids = New-Object System.Collections.ArrayList } }
            [void]$per[$h].Sids.Add([string](Get-ObjectValue $r 'SID'))
        }
        foreach ($h in @($per.Keys)) { $per[$h].Sids = @($per[$h].Sids) }
        Start-HostOperation -Module $m -Name 'Usuwanie profili' -Targets @($per.Keys) -PerTarget $per -Output Log -ScriptBlock {
            param($P)
            foreach ($sid in $P.Sids) {
                if ($sid -notmatch '^S-1-[\d-]+$') { continue }
                try {
                    $pr = Get-CimInstance -ClassName Win32_UserProfile -Filter ("SID='{0}'" -f $sid)
                    if (-not $pr) { [pscustomobject]@{ 'SID' = $sid; 'Wynik' = 'Nie znaleziono profilu' }; continue }
                    if ($pr.Special) { [pscustomobject]@{ 'SID' = $sid; 'Wynik' = 'Pominięto – profil systemowy' }; continue }
                    if ($pr.Loaded) { [pscustomobject]@{ 'SID' = $sid; 'Ścieżka' = $pr.LocalPath; 'Wynik' = 'Pominięto – profil w użyciu' }; continue }
                    $path = $pr.LocalPath
                    Remove-CimInstance -InputObject $pr -ErrorAction Stop
                    $left = $path -and (Test-Path -LiteralPath $path)
                    [pscustomobject]@{ 'SID' = $sid; 'Ścieżka' = $path; 'Wynik' = $(if ($left) { 'Usunięto (część plików pozostała w folderze)' } else { 'Usunięto' }) }
                }
                catch { [pscustomobject]@{ 'SID' = $sid; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        } -OnResult {
            param($m, $r)
            $removed = @($r.Data | Where-Object { [string](Get-ObjectValue $_ 'Wynik') -like 'Usunięto*' } | ForEach-Object { [string](Get-ObjectValue $_ 'SID') })
            if ($removed.Count -eq 0) { return }
            $rows = @($m.Table.Rows | Where-Object { [string]$_['Komputer'] -eq $r.Target -and $removed -contains [string]$_['SID'] })
            Remove-ResultRows -Module $m -Rows $rows
        } -OnComplete { param($m) Update-ProfileStats -Module $m }
    }
    Add-RowAction -Module $m -Text 'Usuń profil' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Remove $m $rows }
    Add-RowAction -Module $m -Text 'Otwórz folder profilu (C$)' -Icon 'E838' -Action {
        param($m, $rows)
        $r = $rows[0]
        $computer = [string](Get-ObjectValue $r 'Komputer')
        $path = [string](Get-ObjectValue $r 'Ścieżka')
        if ($path -notmatch '^[A-Za-z]:\\') { return }
        Start-Tool -FilePath 'explorer.exe' -Arguments @(('\\{0}\{1}${2}' -f $computer, $path.Substring(0, 1), $path.Substring(2))) -Name $computer
    }
    Add-StatTile -Module $m -Key 'profiles' -Label 'Profile' -Icon 'E77B' | Out-Null
    Add-StatTile -Module $m -Key 'candidates' -Label 'Kandydaci do usunięcia' -Icon 'E7BA' | Out-Null
    Add-StatTile -Module $m -Key 'reclaim' -Label 'Do odzyskania' -Icon 'EDA2' | Out-Null
    Add-StatTile -Module $m -Key 'hosts' -Label 'Komputery' -Icon 'E7F4' | Out-Null
    $m.ResultHint = 'Kandydaci: konta usunięte/wyłączone/wygasłe, profile tymczasowe i nieużywane'
}

Register-Module -Workspace 'Remote' -Category 'Użytkownicy i dostęp' -Key 'Sessions' -Title 'Sesje użytkowników' -Icon 'E7EE' -Badge 'Nowość w wersji 4.0' `
    -Description 'Zalogowani użytkownicy (konsola i pulpit zdalny): stan sesji, bezczynność, czas logowania. Wylogowanie, rozłączenie, wiadomość dla użytkownika i podgląd sesji (shadow).' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Sesje' -Targets $targets -ScriptBlock {
            param($P)
            $oem = [System.Text.Encoding]::GetEncoding([System.Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
            $psi = New-Object System.Diagnostics.ProcessStartInfo
            $psi.FileName = Join-Path $env:SystemRoot 'System32\quser.exe'
            $psi.UseShellExecute = $false
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $psi.CreateNoWindow = $true
            $psi.StandardOutputEncoding = $oem
            $psi.StandardErrorEncoding = $oem
            $proc = [System.Diagnostics.Process]::Start($psi)
            $errTask = $proc.StandardError.ReadToEndAsync()
            $out = $proc.StandardOutput.ReadToEnd()
            $proc.WaitForExit()
            $lines = @($out -split "`r?`n" | Where-Object { $_.Trim() })
            if ($lines.Count -le 1) { return [pscustomobject]@{ 'Użytkownik' = '(brak zalogowanych użytkowników)'; '__flag' = 'muted' } }
            foreach ($line in ($lines | Select-Object -Skip 1)) {
                $mt = [regex]::Match($line, '^(?<cur>>)?\s*(?<user>\S+)\s+(?:(?<session>\S+)\s+)?(?<id>\d+)\s+(?<state>\S+)\s+(?<idle>\S+)\s+(?<logon>.+?)\s*$')
                if (-not $mt.Success) { continue }
                $state = $mt.Groups['state'].Value
                $active = ($state -match '^(Active|Aktywn)')
                [pscustomobject]@{
                    'Użytkownik'   = $mt.Groups['user'].Value
                    'Stan'         = $(if ($active) { 'Aktywna' } else { 'Rozłączona' })
                    'Sesja'        = $mt.Groups['session'].Value
                    'ID'           = [int]$mt.Groups['id'].Value
                    'Bezczynność'  = $mt.Groups['idle'].Value
                    'Zalogowano'   = $mt.Groups['logon'].Value
                    '__tone'       = $(if ($active) { 'ok' } else { 'warn' })
                }
            }
        }
    }
    $m.Actions.Session = {
        param($m, [string]$Op, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('ID', 'Użytkownik') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli sesje użytkowników.'; return }
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) '{0} (sesja {1})' -f $i['Użytkownik'], $i['ID'] }
        $message = ''
        switch ($Op) {
            'Logoff' { if (-not (Confirm-Action -Text 'Wylogować wybrane sesje? Niezapisane dane użytkowników zostaną utracone.' -Items $items -ConfirmText 'Wyloguj' -Danger)) { return } }
            'Disconnect' { if (-not (Confirm-Action -Text 'Rozłączyć wybrane sesje? Programy użytkowników pozostaną uruchomione.' -Items $items -ConfirmText 'Rozłącz')) { return } }
            'Message' {
                $message = Show-InputDialog -Title 'Wiadomość dla użytkowników' -Prompt 'Treść komunikatu wyświetlanego w wybranych sesjach (maks. 255 znaków).' -Default 'Za 10 minut nastąpi restart komputera. Zapisz swoją pracę.' -Icon 'E715' -Validate { param($t) if (-not $t.Trim()) { 'Wpisz treść wiadomości.' } elseif ($t.Length -gt 255) { 'Maksymalnie 255 znaków.' } else { '' } }
                if (-not $message) { return }
            }
        }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Op = $Op; Message = $message; Ids = @($byHost[$h] | ForEach-Object { [int]$_['ID'] }) } }
        $onComplete = if ($Op -eq 'Message') { $null } else { { param($m) & $m.Actions.List $m } }
        Start-HostOperation -Module $m -Name "Sesje – $Op" -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete $onComplete -ScriptBlock {
            param($P)
            foreach ($id in $P.Ids) {
                $exe = switch ($P.Op) { 'Logoff' { 'logoff.exe' } 'Disconnect' { 'tsdiscon.exe' } 'Message' { 'msg.exe' } }
                $cmdArgs = @([string]$id)
                if ($P.Op -eq 'Message') { $cmdArgs += '/TIME:300'; $cmdArgs += $P.Message }
                $out = & (Join-Path $env:SystemRoot "System32\$exe") @cmdArgs 2>&1
                if ($LASTEXITCODE -eq 0) { [pscustomobject]@{ 'Sesja' = $id; 'Operacja' = $P.Op; 'Wynik' = 'OK' } }
                else { [pscustomobject]@{ 'Sesja' = $id; 'Operacja' = $P.Op; 'Wynik' = ('Błąd – kod {0} {1}' -f $LASTEXITCODE, ($out | Out-String).Trim()) } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pokaż sesje' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Wiadomość…' -Icon 'E715' -Module $m -OnClick { param($m) & $m.Actions.Session $m 'Message' $null } | Out-Null
    Add-Button -Parent $row -Text 'Rozłącz' -Icon 'E8CD' -Module $m -OnClick { param($m) & $m.Actions.Session $m 'Disconnect' $null } | Out-Null
    Add-Button -Parent $row -Text 'Wyloguj' -Icon 'E7E8' -Module $m -Danger -OnClick { param($m) & $m.Actions.Session $m 'Logoff' $null } | Out-Null
    Add-RowAction -Module $m -Text 'Wyślij wiadomość…' -Icon 'E715' -Action { param($m, $rows) & $m.Actions.Session $m 'Message' $rows }
    Add-RowAction -Module $m -Text 'Podgląd sesji (shadow)' -Icon 'E7B3' -Action {
        param($m, $rows)
        $r = $rows[0]
        $computer = [string](Get-ObjectValue $r 'Komputer')
        $id = [string](Get-ObjectValue $r 'ID')
        if ($id -notmatch '^\d+$') { return }
        Start-Tool -FilePath 'mstsc.exe' -Arguments @("/v:$computer", "/shadow:$id", '/control') -Name $computer
    }
    Add-RowAction -Module $m -Text 'Rozłącz' -Icon 'E8CD' -Action { param($m, $rows) & $m.Actions.Session $m 'Disconnect' $rows }
    Add-RowAction -Module $m -Text 'Wyloguj' -Icon 'E7E8' -Danger -Separator -Action { param($m, $rows) & $m.Actions.Session $m 'Logoff' $rows }
}

$script:LocalGroupDefs = @(
    @{ Name = 'Administratorzy'; Sid = 'S-1-5-32-544' }
    @{ Name = 'Użytkownicy pulpitu zdalnego'; Sid = 'S-1-5-32-555' }
    @{ Name = 'Użytkownicy zarządzania zdalnego (WinRM)'; Sid = 'S-1-5-32-580' }
    @{ Name = 'Czytelnicy dziennika zdarzeń'; Sid = 'S-1-5-32-573' }
    @{ Name = 'Operatorzy kopii zapasowych'; Sid = 'S-1-5-32-551' }
    @{ Name = 'Użytkownicy'; Sid = 'S-1-5-32-545' }
)

Register-Module -Workspace 'Remote' -Category 'Użytkownicy i dostęp' -Key 'LocalGroups' -Title 'Grupy lokalne' -Icon 'E902' `
    -Description 'Członkowie wbudowanych grup lokalnych (Administratorzy, Pulpit zdalny, WinRM…) wyznaczanych po SID – działa w każdym języku systemu. Podgląd, dodawanie i usuwanie członków.' -Build {
    param($m)
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $sid = $script:LocalGroupDefs[$m.Group.SelectedIndex].Sid
        Start-HostOperation -Module $m -Name 'Grupy lokalne' -Targets $targets -Parameters @{ Sid = $sid } -ScriptBlock {
            param($P)
            $groupName = (New-Object System.Security.Principal.SecurityIdentifier($P.Sid)).Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
            $rows = @()
            try {
                $rows = @(Get-LocalGroupMember -SID $P.Sid -ErrorAction Stop | ForEach-Object {
                        [pscustomobject]@{ 'Członek' = $_.Name; 'Typ' = [string]$_.ObjectClass; 'Źródło' = [string]$_.PrincipalSource; 'SID' = [string]$_.SID }
                    })
            }
            catch {
                # Get-LocalGroupMember zawodzi np. przy osieroconych SID-ach - odczyt przez ADSI
                $group = [ADSI]("WinNT://{0}/{1},group" -f $env:COMPUTERNAME, $groupName)
                foreach ($member in @($group.Invoke('Members'))) {
                    $type = $member.GetType()
                    $path = [string]$type.InvokeMember('ADsPath', 'GetProperty', $null, $member, $null)
                    $class = [string]$type.InvokeMember('Class', 'GetProperty', $null, $member, $null)
                    $sid = ''
                    try { $sid = (New-Object System.Security.Principal.SecurityIdentifier($type.InvokeMember('objectSid', 'GetProperty', $null, $member, $null), 0)).Value } catch { }
                    $parts = @($path -replace '^WinNT://', '' -split '/')
                    $name = if ($parts.Count -ge 2) { $parts[-2] + '\' + $parts[-1] } else { $parts[-1] }
                    $rows += [pscustomobject]@{ 'Członek' = $name; 'Typ' = $class; 'Źródło' = '(ADSI)'; 'SID' = $sid }
                }
            }
            if ($rows.Count -eq 0) { return [pscustomobject]@{ 'Grupa' = $groupName; 'Członek' = '(grupa jest pusta)'; '__flag' = 'muted' } }
            $rows | ForEach-Object {
                $flag = if ($_.'Członek' -match '^S-1-') { 'warn' } else { '' }
                $_ | Add-Member -NotePropertyName 'Grupa' -NotePropertyValue $groupName -PassThru | Add-Member -NotePropertyName '__flag' -NotePropertyValue $flag -PassThru
            }
        }
    }
    $m.Actions.Remove = {
        param($m, $Rows)
        $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $m })
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Członek') -Rows $source
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli członków grupy do usunięcia.'; return }
        $sid = $script:LocalGroupDefs[$m.Group.SelectedIndex].Sid
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Członek'] }
        if (-not (Confirm-Action -Text "Usunąć wybrane konta z grupy «$($m.Group.SelectedItem)»?" -Items $items -ConfirmText 'Usuń z grupy' -Danger)) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ GroupSid = $sid; Members = @($byHost[$h] | ForEach-Object { @{ Name = [string]$_['Członek']; Sid = [string](Get-RowValue $_['__row'] 'SID') } }) } }
        Start-HostOperation -Module $m -Name 'Usuwanie z grupy' -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            $groupName = (New-Object System.Security.Principal.SecurityIdentifier($P.GroupSid)).Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
            foreach ($member in $P.Members) {
                try {
                    # Zabezpieczenie przed odcięciem dostępu: wbudowane konto Administrator i Domain Admins w grupie Administratorzy
                    if ($P.GroupSid -eq 'S-1-5-32-544' -and ($member.Sid -match '-500$' -or $member.Sid -match '^S-1-5-21-.+-512$')) { throw 'Pominięto: wbudowane konto Administrator / grupa Domain Admins.' }
                    $identity = if ($member.Sid) { $member.Sid } else { $member.Name }
                    if (Get-Command Remove-LocalGroupMember -ErrorAction SilentlyContinue) {
                        Remove-LocalGroupMember -SID $P.GroupSid -Member $identity -ErrorAction Stop
                    }
                    else {
                        $group = [ADSI]("WinNT://{0}/{1},group" -f $env:COMPUTERNAME, $groupName)
                        $group.Remove('WinNT://' + ($member.Name -replace '\\', '/'))
                    }
                    [pscustomobject]@{ 'Członek' = $member.Name; 'Wynik' = 'Usunięto' }
                }
                catch { [pscustomobject]@{ 'Członek' = $member.Name; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Grupa'
    $m.Group = Add-ComboBox -Parent $row -Items @($script:LocalGroupDefs | ForEach-Object { $_.Name }) -Width 320
    Add-Button -Parent $row -Text 'Pokaż członków' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Usuń zaznaczonych' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Remove $m $null } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Dodaj członków'
    $m.NewMember = Add-TextBox -Parent $row2 -Width 340 -Placeholder 'DOMENA\konto lub grupa (kilka – po przecinku)'
    Add-Button -Parent $row2 -Text 'Wybierz grupy z AD…' -Icon 'E902' -Module $m -OnClick {
        param($m)
        $groups = Select-AdGroups -Title 'Grupy do dodania' -Subtitle 'Wybrane grupy domenowe zostaną dopisane do pola poniżej.'
        if (-not $groups) { return }
        $domain = if ($env:USERDOMAIN) { $env:USERDOMAIN } else { '' }
        $names = @(Split-ListText $m.NewMember.Text) + @($groups | ForEach-Object { if ($domain) { "$domain\$($_.Sam)" } else { $_.Sam } })
        $m.NewMember.Text = (@($names | Select-Object -Unique) -join ', ')
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Dodaj na zaznaczonych komputerach' -Icon 'E710' -Module $m -OnClick {
        param($m)
        $members = @(Split-ListText $m.NewMember.Text)
        if ($members.Count -eq 0) { Show-Warning 'Podaj konto lub grupę, np. FIRMA\Helpdesk.'; return }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $sid = $script:LocalGroupDefs[$m.Group.SelectedIndex].Sid
        $targets = @(Confirm-Action -Text ("Dodać {0} do grupy «{1}» na wybranych komputerach?" -f ($members -join ', '), $m.Group.SelectedItem) -Items $targets -ConfirmText 'Dodaj' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name 'Dodawanie do grupy' -Targets $targets -Output Log -Parameters @{ Members = $members; GroupSid = $sid } -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            $groupName = (New-Object System.Security.Principal.SecurityIdentifier($P.GroupSid)).Translate([System.Security.Principal.NTAccount]).Value.Split('\')[-1]
            foreach ($member in $P.Members) {
                try {
                    if (Get-Command Add-LocalGroupMember -ErrorAction SilentlyContinue) {
                        Add-LocalGroupMember -SID $P.GroupSid -Member $member -ErrorAction Stop
                    }
                    else {
                        $group = [ADSI]("WinNT://{0}/{1},group" -f $env:COMPUTERNAME, $groupName)
                        $group.Add('WinNT://' + ($member -replace '\\', '/'))
                    }
                    [pscustomobject]@{ 'Członek' = $member; 'Grupa' = $groupName; 'Wynik' = 'Dodano' }
                }
                catch {
                    $msg = $_.Exception.Message
                    if ($_.FullyQualifiedErrorId -like 'MemberExists*') { $msg = 'już jest członkiem grupy' }
                    [pscustomobject]@{ 'Członek' = $member; 'Grupa' = $groupName; 'Wynik' = "Błąd – $msg" }
                }
            }
        }
    } | Out-Null
    Add-RowAction -Module $m -Text 'Usuń z grupy' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Remove $m $rows }
}

Register-Module -Workspace 'Remote' -Category 'Użytkownicy i dostęp' -Key 'LocalUsers' -Title 'Konta lokalne' -Icon 'E77B' `
    -Description 'Lokalne konta użytkowników: stan, ostatnie logowanie, wiek hasła; włączanie, wyłączanie i ustawianie hasła zaznaczonych kont.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Konta lokalne' -Targets $targets -ScriptBlock {
            param($P)
            if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
                Get-LocalUser | ForEach-Object {
                    $age = if ($_.PasswordLastSet) { [int]((Get-Date) - $_.PasswordLastSet).TotalDays } else { $null }
                    [pscustomobject]@{
                        'Konto'              = $_.Name
                        'Pełna nazwa'        = $_.FullName
                        'Włączone'           = $_.Enabled
                        'Ostatnie logowanie' = $_.LastLogon
                        'Hasło ustawione'    = $_.PasswordLastSet
                        'Wiek hasła (dni)'   = $age
                        'Hasło wygasa'       = $_.PasswordExpires
                        'Opis'               = $_.Description
                        'SID'                = [string]$_.SID
                        '__flag'             = $(if (-not $_.Enabled) { 'muted' } else { '' })
                    }
                }
            }
            else {
                Get-CimInstance -ClassName Win32_UserAccount -Filter 'LocalAccount = True' | ForEach-Object {
                    [pscustomobject]@{ 'Konto' = $_.Name; 'Pełna nazwa' = $_.FullName; 'Włączone' = (-not $_.Disabled); 'Opis' = $_.Description; 'SID' = $_.SID }
                }
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Konto') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli konta lokalne.'; return }
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Konto'] }
        $password = $null
        if ($Op -eq 'Password') {
            $password = Read-NewPassword -Subtitle 'Nowe hasło zostanie ustawione dla wszystkich zaznaczonych kont lokalnych.'
            if (-not $password) { return }
        }
        $question = @{ Enable = 'Włączyć wybrane konta lokalne?'; Disable = 'Wyłączyć wybrane konta lokalne?'; Password = 'Ustawić nowe hasło dla wybranych kont lokalnych?' }[$Op]
        if (-not (Confirm-Action -Text $question -Items $items -ConfirmText 'Wykonaj' -Danger:($Op -ne 'Enable'))) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Op = $Op; Password = $password; Names = @($byHost[$h] | ForEach-Object { [string]$_['Konto'] }) } }
        Start-HostOperation -Module $m -Name "Konta lokalne – $Op" -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($name in $P.Names) {
                try {
                    switch ($P.Op) {
                        'Enable' { Enable-LocalUser -Name $name -ErrorAction Stop }
                        'Disable' { Disable-LocalUser -Name $name -ErrorAction Stop }
                        'Password' { Set-LocalUser -Name $name -Password $P.Password -ErrorAction Stop }
                    }
                    [pscustomobject]@{ 'Konto' = $name; 'Operacja' = $P.Op; 'Wynik' = 'OK' }
                }
                catch { [pscustomobject]@{ 'Konto' = $name; 'Operacja' = $P.Op; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pokaż konta' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Włącz' -Icon 'E73E' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Enable' $null } | Out-Null
    Add-Button -Parent $row -Text 'Wyłącz' -Icon 'E8D8' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Disable' $null } | Out-Null
    Add-Button -Parent $row -Text 'Ustaw hasło…' -Icon 'E8D7' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Password' $null } | Out-Null
    Add-RowAction -Module $m -Text 'Włącz konto' -Icon 'E73E' -Action { param($m, $rows) & $m.Actions.Change $m 'Enable' $rows }
    Add-RowAction -Module $m -Text 'Wyłącz konto' -Icon 'E8D8' -Action { param($m, $rows) & $m.Actions.Change $m 'Disable' $rows }
    Add-RowAction -Module $m -Text 'Ustaw hasło…' -Icon 'E8D7' -Danger -Action { param($m, $rows) & $m.Actions.Change $m 'Password' $rows }
}

Register-Module -Workspace 'Remote' -Category 'Użytkownicy i dostęp' -Key 'Rdp' -Title 'Pulpit zdalny' -Icon 'E8AF' -Badge 'Nowość w wersji 4.0' `
    -Description 'Stan Pulpitu zdalnego (RDP): włączenie, uwierzytelnianie na poziomie sieci (NLA), port, reguły zapory i członkowie grupy Użytkownicy pulpitu zdalnego. Włączanie i wyłączanie RDP razem z zaporą.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('RDP')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Pulpit zdalny' -Targets $targets -ScriptBlock {
            param($P)
            $ts = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction SilentlyContinue
            $tcp = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction SilentlyContinue
            $policy = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services' -ErrorAction SilentlyContinue
            $enabled = ($ts -and [int]$ts.fDenyTSConnections -eq 0)
            $byPolicy = ($policy -and $null -ne $policy.PSObject.Properties['fDenyTSConnections'])
            $fw = $null
            try {
                $rules = @(Get-NetFirewallRule -Group '@FirewallAPI.dll,-28752' -ErrorAction Stop)
                $fw = (@($rules | Where-Object { $_.Enabled -eq 'True' -and $_.Direction -eq 'Inbound' }).Count -gt 0)
            }
            catch { }
            $members = @()
            try { $members = @(Get-LocalGroupMember -SID 'S-1-5-32-555' -ErrorAction Stop | ForEach-Object { $_.Name }) } catch { }
            $svc = Get-Service -Name TermService -ErrorAction SilentlyContinue
            [pscustomobject]@{
                'RDP'                     = $(if ($enabled) { 'Włączony' } else { 'Wyłączony' })
                'NLA'                     = $(if ($tcp) { [int]$tcp.UserAuthentication -eq 1 } else { $null })
                'Port'                    = $(if ($tcp) { [int]$tcp.PortNumber } else { $null })
                'Zapora (reguły RDP)'     = $fw
                'Usługa'                  = $(if ($svc) { [string]$svc.Status } else { '' })
                'Wymuszone zasadami'      = $byPolicy
                'Użytkownicy pulpitu zdalnego' = ($members -join ', ')
                '__tone'                  = $(if ($enabled) { 'ok' } else { '' })
            }
        }
    }
    $m.Actions.Set = {
        param($m, [string]$Op)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $text = @{
            Enable     = 'Włączyć Pulpit zdalny (z NLA) i odblokować reguły zapory?'
            Disable    = 'Wyłączyć Pulpit zdalny? Aktywne sesje RDP pozostaną do wylogowania, nowe połączenia będą odrzucane.'
            NlaOn      = 'Włączyć wymaganie uwierzytelniania na poziomie sieci (NLA)?'
            NlaOff     = 'Wyłączyć wymaganie NLA? Obniża to bezpieczeństwo – używaj tylko do diagnostyki.'
        }[$Op]
        $targets = @(Confirm-Action -Text $text -Items $targets -ConfirmText 'Wykonaj' -Danger:($Op -eq 'Disable' -or $Op -eq 'NlaOff') -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name "Pulpit zdalny – $Op" -Targets $targets -Output Log -Parameters @{ Op = $Op } -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            $ts = 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server'
            $tcp = "$ts\WinStations\RDP-Tcp"
            switch ($P.Op) {
                'Enable' {
                    Set-ItemProperty -Path $ts -Name fDenyTSConnections -Value 0 -Type DWord
                    Set-ItemProperty -Path $tcp -Name UserAuthentication -Value 1 -Type DWord
                    try { Enable-NetFirewallRule -Group '@FirewallAPI.dll,-28752' -ErrorAction Stop } catch { 'Uwaga: nie udało się włączyć reguł zapory – ' + $_.Exception.Message }
                    'Pulpit zdalny włączony (NLA wymagane).'
                }
                'Disable' {
                    Set-ItemProperty -Path $ts -Name fDenyTSConnections -Value 1 -Type DWord
                    try { Disable-NetFirewallRule -Group '@FirewallAPI.dll,-28752' -ErrorAction Stop } catch { }
                    'Pulpit zdalny wyłączony.'
                }
                'NlaOn' { Set-ItemProperty -Path $tcp -Name UserAuthentication -Value 1 -Type DWord; 'NLA włączone.' }
                'NlaOff' { Set-ItemProperty -Path $tcp -Name UserAuthentication -Value 0 -Type DWord; 'NLA wyłączone.' }
            }
            if (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\Terminal Services' -Name fDenyTSConnections -ErrorAction SilentlyContinue) {
                'Uwaga: ustawienie RDP jest wymuszone zasadami grupy – zmiana może zostać nadpisana.'
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Sprawdź stan' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Włącz RDP' -Icon 'E73E' -Module $m -OnClick { param($m) & $m.Actions.Set $m 'Enable' } | Out-Null
    Add-Button -Parent $row -Text 'Wyłącz RDP' -Icon 'E711' -Module $m -Danger -OnClick { param($m) & $m.Actions.Set $m 'Disable' } | Out-Null
    Add-Button -Parent $row -Text 'Wymagaj NLA' -Icon 'E72E' -Module $m -OnClick { param($m) & $m.Actions.Set $m 'NlaOn' } | Out-Null
    Add-Button -Parent $row -Text 'Wyłącz NLA' -Icon 'E785' -Module $m -Danger -OnClick { param($m) & $m.Actions.Set $m 'NlaOff' } | Out-Null
    Add-RowAction -Module $m -Text 'Połącz (mstsc)' -Icon 'E8AF' -Action {
        param($m, $rows)
        $computer = [string](Get-ObjectValue $rows[0] 'Komputer')
        Start-Tool -FilePath 'mstsc.exe' -Arguments @("/v:$computer") -Name $computer
    }
}
#endregion

#region Zarządzanie zdalne: Zdalne wykonanie
# Blok uruchamiany na komputerze docelowym (Invoke-Command). Polecenie działa w osobnym procesie bez okna:
#  - wejście procesu jest od razu zamykane, więc programy czekające na klawiaturę (cmd, pause, choice, set /p,
#    Read-Host w trybie -NonInteractive) kończą się zamiast wisieć,
#  - wyjście jest czytane w pętli, która co chwilę oddaje sterowanie PowerShell - przerwanie operacji
#    (zatrzymanie potoku) albo przekroczenie limitu czasu kończy pętlę, a blok finally zabija całe drzewo procesów,
#  - zebrany wynik ma limit rozmiaru, a proces potomny trzymający wyjście (np. start notepad) nie blokuje zakończenia.
# $P: Mode (PS | CMD | EXE), Command (PS/CMD) albo FilePath + Arguments (EXE), Input (tekst na wejście, opcjonalnie),
#     TimeoutSec (0 = bez limitu).
$script:RemoteExecScript = {
    param($P)
    $ErrorActionPreference = 'Stop'
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $tempFile = $null
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $timeout = 0
    if ($P.ContainsKey('TimeoutSec') -and $P.TimeoutSec) { $timeout = [int]$P.TimeoutSec }
    $mode = [string]$P.Mode
    if ($mode -eq 'PS') {
        $exe = @('powershell.exe', 'pwsh.exe') | ForEach-Object { Join-Path $PSHOME $_ } | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
        if (-not $exe) { throw "Nie znaleziono powershell.exe w katalogu $PSHOME." }
        $encoding = New-Object System.Text.UTF8Encoding $false
        $userScript = [string]$P.Command
        $wrapperFor = {
            param($load)
            # Kod startowy procesu potomnego: wynik w UTF-8, błędy liczone i dołączane do wyniku
            "`$ProgressPreference = 'SilentlyContinue'`n" +
            "[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding `$false`n" +
            "`$__errors = 0`n" +
            "try { `$__sb = [scriptblock]::Create($load); & `$__sb 2>&1 | ForEach-Object { if (`$_ -is [System.Management.Automation.ErrorRecord]) { `$__errors++ }; `$_ } | Out-String -Width 250 -Stream }`n" +
            "catch { `$__errors++; 'BŁĄD: ' + `$_.Exception.Message }`n" +
            "'##DOMAINOPS_ERRORS=' + `$__errors`n" +
            "if (`$LASTEXITCODE) { exit `$LASTEXITCODE }"
        }
        $payload = [Convert]::ToBase64String($encoding.GetBytes($userScript))
        $wrapper = & $wrapperFor ("[System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('{0}'))" -f $payload)
        $encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($wrapper))
        if ($encoded.Length -gt 30000) {
            # Wiersz polecenia ma limit 32767 znaków - długi skrypt przekazujemy w pliku tymczasowym
            $tempFile = Join-Path ([System.IO.Path]::GetTempPath()) ('DomainOps_' + [guid]::NewGuid().ToString('N') + '.txt')
            [System.IO.File]::WriteAllText($tempFile, $userScript, $encoding)
            $wrapper = & $wrapperFor ("[System.IO.File]::ReadAllText('{0}')" -f $tempFile.Replace("'", "''"))
            $encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($wrapper))
        }
        $psi.FileName = $exe
        $psi.Arguments = '-NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' + $encoded
    }
    elseif ($mode -eq 'CMD') {
        $encoding = [System.Text.Encoding]::GetEncoding([System.Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
        $text = ([string]$P.Command).Trim()
        $psi.FileName = Join-Path $env:SystemRoot 'System32\cmd.exe'
        if ($text -match "[\r\n]") {
            # Kilka linii - uruchamiamy jak plik wsadowy (w pętlach for zmienne zapisuje się wtedy jako %%i)
            $tempFile = Join-Path ([System.IO.Path]::GetTempPath()) ('DomainOps_' + [guid]::NewGuid().ToString('N') + '.cmd')
            [System.IO.File]::WriteAllText($tempFile, "@echo off`r`n" + ($text -replace "`r?`n", "`r`n") + "`r`n", $encoding)
            $psi.Arguments = '/d /s /c ""' + $tempFile + '""'
        }
        else {
            $psi.Arguments = '/d /s /c "' + $text + '"'
        }
    }
    else {
        $encoding = [System.Text.Encoding]::GetEncoding([System.Globalization.CultureInfo]::CurrentCulture.TextInfo.OEMCodePage)
        $psi.FileName = [string]$P.FilePath
        $psi.Arguments = [string]$P.Arguments
    }
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardInput = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.StandardOutputEncoding = $encoding
    $psi.StandardErrorEncoding = $encoding
    # Przygotowane wcześniej: w bloku finally po przerwaniu potoku używamy tylko wywołań .NET
    $kill = New-Object System.Diagnostics.ProcessStartInfo
    $kill.FileName = Join-Path $env:SystemRoot 'System32\taskkill.exe'
    $kill.UseShellExecute = $false
    $kill.CreateNoWindow = $true
    $limit = 1000000
    $truncated = $false
    $state = 'exited'
    $proc = $null
    $outBuf = New-Object System.Text.StringBuilder
    $errBuf = New-Object System.Text.StringBuilder
    try {
        $proc = [System.Diagnostics.Process]::Start($psi)
        if ($P.ContainsKey('Input') -and $P.Input) { try { $proc.StandardInput.Write([string]$P.Input) } catch { } }
        $proc.StandardInput.Close()
        $readers = @(
            @{ R = $proc.StandardOutput; B = $outBuf; C = (New-Object char[] 8192); T = $null; Eof = $false }
            @{ R = $proc.StandardError; B = $errBuf; C = (New-Object char[] 8192); T = $null; Eof = $false }
        )
        foreach ($r in $readers) { $r.T = $r.R.ReadAsync($r.C, 0, $r.C.Length) }
        $exitedAt = -1
        while ($true) {
            $progress = $false
            foreach ($r in $readers) {
                while (-not $r.Eof -and $r.T.IsCompleted) {
                    $n = 0
                    if (-not $r.T.IsFaulted -and -not $r.T.IsCanceled) { $n = $r.T.Result }
                    if ($n -le 0) { $r.Eof = $true; break }
                    if ($r.B.Length -lt $limit) { [void]$r.B.Append($r.C, 0, $n) } else { $truncated = $true }
                    $r.T = $r.R.ReadAsync($r.C, 0, $r.C.Length)
                    $progress = $true
                }
            }
            $exited = $proc.HasExited
            if ($exited -and $readers[0].Eof -and $readers[1].Eof) { break }
            if ($exited) {
                # Proces potomny (np. uruchomiony przez start) może trzymać otwarte wyjście - nie czekamy na niego
                if ($exitedAt -lt 0) { $exitedAt = $sw.Elapsed.TotalSeconds }
                elseif (($sw.Elapsed.TotalSeconds - $exitedAt) -gt 3) { $state = 'detached'; break }
            }
            if ($timeout -gt 0 -and $sw.Elapsed.TotalSeconds -ge $timeout) { $state = 'timeout'; break }
            if (-not $progress) { Start-Sleep -Milliseconds 150 }
        }
    }
    finally {
        # Wykonywane także po przerwaniu operacji - wtedy proces i jego potomkowie muszą zniknąć
        if ($proc -and -not $proc.HasExited) {
            try {
                $kill.Arguments = '/T /F /PID ' + $proc.Id
                $k = [System.Diagnostics.Process]::Start($kill)
                [void]$k.WaitForExit(10000)
            }
            catch { }
            try { if (-not $proc.HasExited) { $proc.Kill() } } catch { }
        }
        if ($tempFile) { try { [System.IO.File]::Delete($tempFile) } catch { } }
    }
    $code = $null
    if ($state -ne 'timeout') { try { $code = $proc.ExitCode } catch { } }
    $out = $outBuf.ToString()
    $err = $errBuf.ToString()
    $psErrors = 0
    if ($mode -eq 'PS') {
        $mk = [regex]::Match($out, '(?m)^##DOMAINOPS_ERRORS=(\d+)\s*$')
        if ($mk.Success) { $psErrors = [int]$mk.Groups[1].Value; $out = $out.Remove($mk.Index, $mk.Length) }
        if ($err.StartsWith('#< CLIXML')) {
            # Strumienie serializowane przez powershell.exe - zostawiamy sam tekst błędów
            $err = ((@([regex]::Matches($err, '<S S="Error">(.*?)</S>') | ForEach-Object { $_.Groups[1].Value })) -join '')
            $err = [System.Net.WebUtility]::HtmlDecode(($err -replace '_x000D_', "`r" -replace '_x000A_', "`n"))
        }
    }
    $text = $out.TrimStart([char]0xFEFF).TrimEnd()
    if ($err.Trim()) { $text = ($text + "`r`n" + $err.Trim()).Trim() }
    if ($truncated) { $text += "`r`n… (wynik obcięty do $limit znaków)" }
    $seconds = [Math]::Round($sw.Elapsed.TotalSeconds, 1)
    $status = 'OK'
    $tone = 'ok'
    if ($state -eq 'timeout') { $status = "Przekroczono limit czasu ($timeout s) – proces zatrzymany"; $tone = 'crit' }
    elseif ($code -ne 0 -and $null -ne $code) { $status = "Kod wyjścia $code"; $tone = 'warn' }
    elseif ($psErrors -gt 0) { $status = "Błędy PowerShell: $psErrors"; $tone = 'warn' }
    if ($state -eq 'detached') {
        $status += ' (proces potomny działa dalej)'
        if ($tone -eq 'ok') { $tone = 'info' }
    }
    [pscustomobject]@{
        'Stan'        = $status
        'Kod wyjścia' = $code
        'Czas (s)'    = $seconds
        'Wynik'       = $text
        '__tone'      = $tone
    }
}

$script:ExecTimeouts = [ordered]@{ '1 min' = 60; '5 min' = 300; '15 min' = 900; '30 min' = 1800; '1 godz.' = 3600; '2 godz.' = 7200; 'bez limitu' = 0 }

Register-Module -Workspace 'Remote' -Category 'Zdalne wykonanie' -Key 'Commands' -Title 'Polecenia' -Icon 'E756' `
    -Description 'Uruchamia polecenia PowerShell lub cmd.exe na zaznaczonych komputerach (sesja WinRM, bez pulpitu użytkownika). Pełny wynik w panelu szczegółów lub po dwukliku.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Templates = @(
        @{ Name = '(wybierz szablon polecenia)'; Mode = ''; Text = '' }
        @{ Name = 'Wersja systemu i czas pracy'; Mode = 'PS'; Text = 'Get-CimInstance Win32_OperatingSystem | Select-Object Caption, Version, LastBootUpTime' }
        @{ Name = 'Ostatnie poprawki (10)'; Mode = 'PS'; Text = 'Get-HotFix | Sort-Object InstalledOn -Descending | Select-Object -First 10 HotFixID, Description, InstalledOn' }
        @{ Name = 'Konfiguracja IP'; Mode = 'CMD'; Text = 'ipconfig /all' }
        @{ Name = 'Odśwież DNS (flushdns + registerdns)'; Mode = 'CMD'; Text = 'ipconfig /flushdns && ipconfig /registerdns' }
        @{ Name = 'Wyczyść bilety Kerberos komputera'; Mode = 'CMD'; Text = 'klist -li 0x3e7 purge' }
        @{ Name = 'Wynikowe zasady komputera (gpresult)'; Mode = 'CMD'; Text = 'gpresult /r /scope computer' }
        @{ Name = 'Procesy – top 10 pamięci'; Mode = 'PS'; Text = "Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 10 Name, Id, @{n='MB';e={[math]::Round(`$_.WorkingSet64/1MB)}}" }
        @{ Name = 'Test połączenia z kontrolerem domeny'; Mode = 'PS'; Text = 'Test-NetConnection -ComputerName $env:USERDNSDOMAIN -Port 389 | Select-Object ComputerName, RemoteAddress, TcpTestSucceeded' }
        @{ Name = 'Kanał zaufania z domeną'; Mode = 'PS'; Text = 'Test-ComputerSecureChannel -Verbose 4>&1' }
        @{ Name = 'Synchronizacja czasu (w32tm)'; Mode = 'CMD'; Text = 'w32tm /query /status && w32tm /resync' }
        @{ Name = 'Naprawa obrazu systemu (DISM + SFC)'; Mode = 'CMD'; Text = 'DISM /Online /Cleanup-Image /RestoreHealth && sfc /scannow'; Timeout = '2 godz.' }
    )
    $row = Add-ToolbarRow -Module $m -Title 'Interpreter'
    $m.Mode = Add-Segmented -Parent $row -Items @('PowerShell', 'cmd.exe')
    Add-Label -Parent $row -Text '   Szablon' | Out-Null
    $m.Template = Add-ComboBox -Parent $row -Items @($m.Templates | ForEach-Object { $_.Name }) -Width 340
    Register-ControlHandler -Control $m.Template -EventName 'SelectionChanged' -Module $m -Action {
        param($m, $s)
        $t = $m.Templates[$s.SelectedIndex]
        if (-not $t.Mode) { return }
        Set-SegmentIndex $m.Mode $(if ($t.Mode -eq 'PS') { 0 } else { 1 })
        $m.CommandBox.Text = $t.Text
        $limit = if ($t.ContainsKey('Timeout')) { $t.Timeout } else { '15 min' }
        $m.Timeout.SelectedIndex = @($script:ExecTimeouts.Keys).IndexOf($limit)
    }
    $m.CommandBox = Add-StretchTextBox -Module $m -Title 'Polecenie' -Multiline -Height 130 -Placeholder 'Wpisz polecenie lub skrypt…'
    $row3 = Add-ToolbarRow -Module $m -Title 'Limit czasu'
    $m.Timeout = Add-ComboBox -Parent $row3 -Items @($script:ExecTimeouts.Keys) -Width 120
    $m.Timeout.SelectedIndex = 2
    Add-Button -Parent $row3 -Text 'Uruchom na zaznaczonych' -Icon 'E768' -Module $m -Primary -OnClick {
        param($m)
        $command = $m.CommandBox.Text.Trim()
        if (-not $command) { Show-Warning 'Wpisz polecenie do wykonania.'; return }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $isPs = ((Get-SegmentIndex $m.Mode) -eq 0)
        $mode = if ($isPs) { 'PowerShell' } else { 'cmd.exe' }
        $limitName = [string]$m.Timeout.SelectedItem
        $timeout = [int]$script:ExecTimeouts[$limitName]
        $preview = if ($command.Length -gt 400) { $command.Substring(0, 400) + '…' } else { $command }
        $targets = @(Confirm-Action -Text "Uruchomić polecenie ($mode, limit czasu: $limitName) na zaznaczonych komputerach?`r`n`r`n$preview" -Items $targets -ConfirmText 'Uruchom' -Select)
        if ($targets.Count -eq 0) { return }
        Write-Log "Polecenie ($mode, limit $limitName): $command"
        $params = @{ Mode = $(if ($isPs) { 'PS' } else { 'CMD' }); Command = $command; TimeoutSec = $timeout }
        Start-HostOperation -Module $m -Name "Polecenie $mode" -Targets $targets -Parameters $params -ScriptBlock $script:RemoteExecScript
    } | Out-Null
    Add-Label -Parent $row3 -Text 'Polecenie działa w osobnym procesie, bez okna i bez klawiatury: programy czekające na odpowiedź (cmd, pause, choice, set /p, Read-Host) kończą się od razu. Po upływie limitu albo po kliknięciu «Przerwij» proces wraz z potomnymi jest zamykany. Kilka linii w trybie cmd.exe działa jak plik .cmd (@echo off). Zasoby sieciowe mogą być niedostępne (podwójny przeskok).' -Hint -MaxWidth 760 | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'Zdalne wykonanie' -Key 'Install' -Title 'Instalacja oprogramowania' -Icon 'E896' `
    -Description 'Kopiuje instalator (MSI, MSP, MSU, EXE) na zaznaczone komputery i uruchamia go w trybie cichym. Wynik zawiera kod wyjścia i jego znaczenie.' -Build {
    param($m)
    $m.PillColumns = @('Wynik')
    $row = Add-ToolbarRow -Module $m -Title 'Instalator'
    $m.Path = Add-TextBox -Parent $row -Width 560 -Placeholder 'Ścieżka do pliku .msi, .msp, .msu lub .exe'
    Add-Button -Parent $row -Text 'Przeglądaj…' -Icon 'E8E5' -Module $m -AlwaysEnabled -OnClick {
        param($m)
        $dlg = New-Object Microsoft.Win32.OpenFileDialog
        $dlg.Filter = 'Instalatory (*.msi;*.msp;*.msu;*.exe)|*.msi;*.msp;*.msu;*.exe|Wszystkie pliki (*.*)|*.*'
        if ($dlg.ShowDialog($script:UI.Window) -eq $true) { $m.Path.Text = $dlg.FileName }
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Opcje'
    $m.Args = Add-TextBox -Parent $row2 -Width 300 -Placeholder 'Dodatkowe argumenty (EXE: np. /S, /quiet)'
    $m.Cleanup = Add-CheckBox -Parent $row2 -Text 'Usuń instalator po zakończeniu' -Checked $true
    Add-Label -Parent $row2 -Text '   Limit czasu' | Out-Null
    $m.Timeout = Add-ComboBox -Parent $row2 -Items @($script:ExecTimeouts.Keys) -Width 120
    $m.Timeout.SelectedIndex = 4
    Add-Button -Parent $row2 -Text 'Zainstaluj na zaznaczonych' -Icon 'E896' -Module $m -Primary -OnClick {
        param($m)
        $path = $m.Path.Text.Trim().Trim('"')
        if (-not $path -or -not (Test-Path -LiteralPath $path -PathType Leaf)) { Show-Warning 'Wskaż istniejący plik instalatora.'; return }
        $ext = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
        if (@('.msi', '.msp', '.msu', '.exe') -notcontains $ext) { Show-Warning 'Obsługiwane są pliki .msi, .msp, .msu i .exe.'; return }
        $extra = $m.Args.Text.Trim()
        if ($ext -eq '.exe' -and -not $extra) {
            if (-not (Confirm-Action -Text 'Nie podano argumentów cichej instalacji dla pliku EXE. Instalator może czekać na odpowiedź użytkownika, którego nie ma – zostanie zatrzymany po upływie limitu czasu albo po kliknięciu «Przerwij». Kontynuować?' -ConfirmText 'Kontynuuj')) { return }
        }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $targets = @(Confirm-Action -Text "Zainstalować $([System.IO.Path]::GetFileName($path)) na zaznaczonych komputerach?" -Items $targets -ConfirmText 'Zainstaluj' -Select)
        if ($targets.Count -eq 0) { return }
        $params = @{ LocalPath = $path; FileName = [System.IO.Path]::GetFileName($path); Args = $extra; Cleanup = (Test-Checked $m.Cleanup); TimeoutSec = [int]$script:ExecTimeouts[[string]$m.Timeout.SelectedItem] }
        Start-HostOperation -Module $m -Name 'Instalacja' -Targets $targets -Local -Parameters $params -ScriptBlock {
            param($Target, $P, $Ctx)
            $ErrorActionPreference = 'Stop'
            $sp = @{ ComputerName = $Target }
            if ($Ctx.Credential) { $sp.Credential = $Ctx.Credential }
            if ($Ctx.SessionOption) { $sp.SessionOption = $Ctx.SessionOption }
            $session = New-PSSession @sp
            try {
                $remoteFile = Invoke-Command -Session $session -ArgumentList $P.FileName -ScriptBlock {
                    param($name)
                    $dir = Join-Path $env:SystemRoot 'Temp\DomainOps'
                    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
                    Join-Path $dir $name
                }
                # Najpierw szybka kopia przez udział ADMIN$ (tylko dla bieżących poświadczeń), potem przez WinRM
                $method = ''
                if (-not $Ctx.Credential) {
                    try {
                        Copy-Item -LiteralPath $P.LocalPath -Destination ('\\{0}\ADMIN$\Temp\DomainOps\{1}' -f $Target, $P.FileName) -Force
                        $method = 'SMB'
                    }
                    catch { }
                }
                if (-not $method) {
                    Copy-Item -LiteralPath $P.LocalPath -Destination $remoteFile -ToSession $session -Force
                    $method = 'WinRM'
                }
                $res = Invoke-Command -Session $session -ArgumentList $remoteFile, $P.Args, $P.Cleanup, $P.TimeoutSec -ScriptBlock {
                    param($File, $ExtraArgs, $Cleanup, $TimeoutSec)
                    $ext = [System.IO.Path]::GetExtension($File).ToLowerInvariant()
                    $log = [System.IO.Path]::ChangeExtension($File, '.log')
                    $exe = $File
                    $arguments = [string]$ExtraArgs
                    switch ($ext) {
                        '.msi' { $exe = Join-Path $env:SystemRoot 'System32\msiexec.exe'; $arguments = ('/i "{0}" /qn /norestart /l*v "{1}" {2}' -f $File, $log, $ExtraArgs) }
                        '.msp' { $exe = Join-Path $env:SystemRoot 'System32\msiexec.exe'; $arguments = ('/p "{0}" /qn /norestart /l*v "{1}" {2}' -f $File, $log, $ExtraArgs) }
                        '.msu' { $exe = Join-Path $env:SystemRoot 'System32\wusa.exe'; $arguments = ('"{0}" /quiet /norestart {1}' -f $File, $ExtraArgs); $log = '' }
                        default { $log = '' }
                    }
                    $sw = [System.Diagnostics.Stopwatch]::StartNew()
                    $spArgs = @{ FilePath = $exe; PassThru = $true; WindowStyle = 'Hidden' }
                    if ($arguments.Trim()) { $spArgs.ArgumentList = $arguments.Trim() }
                    $kill = New-Object System.Diagnostics.ProcessStartInfo
                    $kill.FileName = Join-Path $env:SystemRoot 'System32\taskkill.exe'
                    $kill.UseShellExecute = $false
                    $kill.CreateNoWindow = $true
                    $proc = Start-Process @spArgs
                    $null = $proc.Handle
                    $timedOut = $false
                    try {
                        # Czekanie w pętli (zamiast WaitForExit) pozwala przerwać operację; finally zamyka instalator
                        while (-not $proc.HasExited) {
                            if ($TimeoutSec -gt 0 -and $sw.Elapsed.TotalSeconds -ge $TimeoutSec) { $timedOut = $true; break }
                            Start-Sleep -Milliseconds 500
                        }
                    }
                    finally {
                        if (-not $proc.HasExited) {
                            try { $kill.Arguments = '/T /F /PID ' + $proc.Id; [void][System.Diagnostics.Process]::Start($kill).WaitForExit(10000) } catch { }
                            try { if (-not $proc.HasExited) { $proc.Kill() } } catch { }
                        }
                    }
                    if ($timedOut) {
                        if ($Cleanup) { Start-Sleep -Seconds 1; Remove-Item -LiteralPath $File -Force -ErrorAction SilentlyContinue }
                        return [pscustomobject]@{ Plik = [System.IO.Path]::GetFileName($File); Kod = $null; Wynik = "Błąd – przekroczono limit czasu ($TimeoutSec s), instalator zatrzymany (czekał na odpowiedź? sprawdź przełączniki cichej instalacji)"; Czas = [Math]::Round($sw.Elapsed.TotalSeconds); Log = $log }
                    }
                    $code = $proc.ExitCode
                    $known = @{
                        0           = 'Sukces'
                        3010        = 'Sukces – wymagany restart'
                        1641        = 'Sukces – instalator uruchomił restart'
                        1602        = 'Błąd – instalacja anulowana'
                        1603        = 'Błąd – krytyczny błąd instalacji (1603)'
                        1618        = 'Błąd – trwa inna instalacja (1618)'
                        1619        = 'Błąd – nie można otworzyć pakietu (1619)'
                        1625        = 'Błąd – instalacja zablokowana przez zasady (1625)'
                        1633        = 'Błąd – nieobsługiwana platforma (1633)'
                        1638        = 'Błąd – zainstalowana jest inna wersja produktu (1638)'
                        2359302     = 'Aktualizacja jest już zainstalowana'
                        -2145124329 = 'Aktualizacja nie dotyczy tego systemu'
                    }
                    $meaning = if ($known.ContainsKey($code)) { $known[$code] } else { "Błąd – kod wyjścia $code" }
                    if ($Cleanup) {
                        Start-Sleep -Seconds 1
                        Remove-Item -LiteralPath $File -Force -ErrorAction SilentlyContinue
                    }
                    [pscustomobject]@{ Plik = [System.IO.Path]::GetFileName($File); Kod = $code; Wynik = $meaning; Czas = [Math]::Round($sw.Elapsed.TotalSeconds); Log = $log }
                }
                [pscustomobject]@{
                    'Plik'            = $res.Plik
                    'Wynik'           = $res.Wynik
                    'Kod wyjścia'     = $res.Kod
                    'Czas (s)'        = $res.Czas
                    'Kopiowanie'      = $method
                    'Log instalatora' = $res.Log
                    '__tone'          = $(if ($res.Wynik -like 'Sukces*' -or $res.Wynik -like 'Aktualizacja jest już*') { 'ok' } elseif ($res.Wynik -like 'Aktualizacja nie dotyczy*') { 'info' } else { 'crit' })
                }
            }
            finally {
                Remove-PSSession -Session $session -ErrorAction SilentlyContinue
            }
        }
    } | Out-Null
    Add-Label -Parent (Add-ToolbarRow -Module $m -Title ' ') -Text 'MSI/MSP: automatycznie /qn /norestart i log w %SystemRoot%\Temp\DomainOps;  MSU: /quiet /norestart;  EXE: podaj przełączniki cichej instalacji.' -Hint | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'Zdalne wykonanie' -Key 'GPUpdate' -Title 'Aktualizacja zasad grupy' -Icon 'E895' `
    -Description 'Wymusza odświeżenie zasad grupy (gpupdate) na zaznaczonych komputerach.' -Build {
    param($m)
    $m.PillColumns = @('Wynik')
    $row = Add-ToolbarRow -Module $m -Title 'Parametry'
    Add-Label -Parent $row -Text 'Zakres' | Out-Null
    $m.Scope = Add-ComboBox -Parent $row -Items @('Komputer', 'Komputer i użytkownik', 'Użytkownik') -Width 200
    $m.Force = Add-CheckBox -Parent $row -Text 'Wymuś ponowne zastosowanie (/force)' -Checked $true
    Add-Button -Parent $row -Text 'Uruchom gpupdate' -Icon 'E895' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $scope = @('Computer', '', 'User')[$m.Scope.SelectedIndex]
        $arguments = @()
        if ($scope) { $arguments += "/target:$scope" }
        if (Test-Checked $m.Force) { $arguments += '/force' }
        $arguments += '/wait:600'
        # gpupdate może zapytać o wylogowanie lub restart - odpowiedź «N» trafia na wejście procesu
        $params = @{ Mode = 'EXE'; FilePath = '%SystemRoot%\System32\gpupdate.exe'; Arguments = ($arguments -join ' '); Input = "N`r`nN`r`n"; TimeoutSec = 900 }
        $sb = [scriptblock]::Create(@"
param(`$P)
`$P.FilePath = [Environment]::ExpandEnvironmentVariables(`$P.FilePath)
`$r = & { $($script:RemoteExecScript.ToString()) } `$P
`$lines = @(`$r.'Wynik' -split "``r?``n" | ForEach-Object { `$_.Trim() } | Where-Object { `$_ })
`$ok = (`$r.'Kod wyjścia' -eq 0)
[pscustomobject]@{
    'Wynik'       = `$(if (`$ok) { 'OK' } elseif (`$null -eq `$r.'Kod wyjścia') { `$r.'Stan' } else { 'Błąd – kod ' + `$r.'Kod wyjścia' })
    'Kod wyjścia' = `$r.'Kod wyjścia'
    'Czas (s)'    = `$r.'Czas (s)'
    'Komunikaty'  = (`$lines -join ' | ')
    '__tone'      = `$(if (`$ok) { 'ok' } else { 'crit' })
}
"@)
        Start-HostOperation -Module $m -Name 'GPUpdate' -Targets $targets -Parameters $params -ScriptBlock $sb
    } | Out-Null
}
#endregion

#region Zarządzanie zdalne: System
function Get-HostItemList {
    # Lista "komputer: element" do okna potwierdzenia
    param([System.Collections.IDictionary]$ByHost, [scriptblock]$Format)
    return @(foreach ($h in $ByHost.Keys) { foreach ($i in $ByHost[$h]) { '{0}: {1}' -f $h, (& $Format $i) } })
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Services' -Title 'Usługi' -Icon 'E9F5' `
    -Description 'Usługi na zaznaczonych komputerach. Akcje (przyciski lub menu pod prawym przyciskiem) dotyczą usług zaznaczonych w tabeli – na właściwych komputerach.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $state = @('All', 'Running', 'Stopped', 'AutoStopped')[$m.StateFilter.SelectedIndex]
        Start-HostOperation -Module $m -Name 'Usługi' -Targets $targets -Parameters @{ Filter = $m.Filter.Text.Trim(); State = $state } -ScriptBlock {
            param($P)
            $services = @(Get-CimInstance -ClassName Win32_Service)
            if ($P.Filter) {
                $f = "*$($P.Filter)*"
                $services = @($services | Where-Object { $_.Name -like $f -or $_.DisplayName -like $f })
            }
            switch ($P.State) {
                'Running' { $services = @($services | Where-Object { $_.State -eq 'Running' }) }
                'Stopped' { $services = @($services | Where-Object { $_.State -ne 'Running' }) }
                'AutoStopped' { $services = @($services | Where-Object { $_.StartMode -eq 'Auto' -and $_.State -ne 'Running' }) }
            }
            $services | Sort-Object DisplayName | ForEach-Object {
                $tone = if ($_.State -eq 'Running') { 'ok' } elseif ($_.StartMode -eq 'Auto') { 'crit' } elseif ($_.StartMode -eq 'Disabled') { '' } else { 'info' }
                [pscustomobject]@{
                    'Nazwa'             = $_.Name
                    'Nazwa wyświetlana' = $_.DisplayName
                    'Stan'              = $_.State
                    'Uruchamianie'      = $_.StartMode
                    'Konto'             = $_.StartName
                    'PID'               = $_.ProcessId
                    'Ścieżka'           = $_.PathName
                    '__tone'            = $tone
                }
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Nazwa') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli usługi, których dotyczy operacja.'; return }
        $startup = @('Automatic', 'Manual', 'Disabled')[$m.StartupType.SelectedIndex]
        $question = @{
            Start       = 'Uruchomić wybrane usługi?'
            Stop        = 'Zatrzymać wybrane usługi? Zatrzymane zostaną też usługi od nich zależne.'
            Restart     = 'Uruchomić ponownie wybrane usługi?'
            StartupType = "Ustawić typ uruchamiania «$($m.StartupType.SelectedItem)» dla wybranych usług?"
        }[$Op]
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Nazwa'] }
        if (-not (Confirm-Action -Text $question -Items $items -ConfirmText 'Wykonaj' -Danger:($Op -eq 'Stop'))) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Op = $Op; StartupType = $startup; Names = @($byHost[$h] | ForEach-Object { [string]$_['Nazwa'] }) } }
        Start-HostOperation -Module $m -Name "Usługi – $Op" -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($name in $P.Names) {
                try {
                    switch ($P.Op) {
                        'Start' { Start-Service -Name $name -ErrorAction Stop }
                        'Stop' { Stop-Service -Name $name -Force -ErrorAction Stop }
                        'Restart' { Restart-Service -Name $name -Force -ErrorAction Stop }
                        'StartupType' { Set-Service -Name $name -StartupType $P.StartupType -ErrorAction Stop }
                    }
                    $svc = Get-Service -Name $name
                    [pscustomobject]@{ 'Usługa' = $name; 'Operacja' = $P.Op; 'Wynik' = 'OK'; 'Stan' = [string]$svc.Status }
                }
                catch {
                    [pscustomobject]@{ 'Usługa' = $name; 'Operacja' = $P.Op; 'Wynik' = "Błąd – $($_.Exception.Message)" }
                }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    Add-Label -Parent $row -Text 'Nazwa' | Out-Null
    $m.Filter = Add-TextBox -Parent $row -Width 170 -Placeholder 'fragment nazwy'
    Add-Label -Parent $row -Text 'Stan' | Out-Null
    $m.StateFilter = Add-ComboBox -Parent $row -Items @('Wszystkie', 'Uruchomione', 'Zatrzymane', 'Automatyczne, ale zatrzymane') -Width 230
    Add-Button -Parent $row -Text 'Pokaż usługi' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Zaznaczone usługi'
    foreach ($a in @(@('Start', 'Start', 'E768'), @('Stop', 'Stop', 'E71A'), @('Restart', 'Restart', 'E72C'))) {
        $b = Add-Button -Parent $row2 -Text $a[0] -Icon $a[2] -Module $m -OnClick { param($m, $s) & $m.Actions.Change $m ([string]$s.Tag) $null }
        $b.Tag = $a[1]
    }
    Add-Label -Parent $row2 -Text '   Typ uruchamiania' | Out-Null
    $m.StartupType = Add-ComboBox -Parent $row2 -Items @('Automatyczny', 'Ręczny', 'Wyłączony') -Width 140
    $b = Add-Button -Parent $row2 -Text 'Ustaw' -Module $m -OnClick { param($m, $s) & $m.Actions.Change $m 'StartupType' $null }
    Add-RowAction -Module $m -Text 'Uruchom' -Icon 'E768' -Action { param($m, $rows) & $m.Actions.Change $m 'Start' $rows }
    Add-RowAction -Module $m -Text 'Zatrzymaj' -Icon 'E71A' -Action { param($m, $rows) & $m.Actions.Change $m 'Stop' $rows }
    Add-RowAction -Module $m -Text 'Uruchom ponownie' -Icon 'E72C' -Action { param($m, $rows) & $m.Actions.Change $m 'Restart' $rows }
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Processes' -Title 'Procesy' -Icon 'E7EF' `
    -Description 'Procesy uruchomione na zaznaczonych komputerach (pamięć, właściciel, wiersz poleceń) i kończenie wybranych procesów.' -Build {
    param($m)
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Procesy' -Targets $targets -Parameters @{ Filter = $m.Filter.Text.Trim(); WithOwner = (Test-Checked $m.WithOwner) } -ScriptBlock {
            param($P)
            $procs = @(Get-CimInstance -ClassName Win32_Process)
            if ($P.Filter) { $procs = @($procs | Where-Object { $_.Name -like "*$($P.Filter)*" }) }
            $procs | Sort-Object WorkingSetSize -Descending | ForEach-Object {
                $owner = ''
                if ($P.WithOwner) {
                    try {
                        $o = Invoke-CimMethod -InputObject $_ -MethodName GetOwner -ErrorAction Stop
                        if ($o.User) { $owner = '{0}\{1}' -f $o.Domain, $o.User }
                    }
                    catch { }
                }
                [pscustomobject]@{
                    'Proces'         = $_.Name
                    'PID'            = [int]$_.ProcessId
                    'Pamięć (MB)'    = [Math]::Round($_.WorkingSetSize / 1MB, 1)
                    'Właściciel'     = $owner
                    'Sesja'          = $_.SessionId
                    'Uruchomiony'    = $_.CreationDate
                    'Wiersz poleceń' = $_.CommandLine
                }
            }
        }
    }
    $m.Actions.Kill = {
        param($m, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('PID', 'Proces') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli procesy do zakończenia.'; return }
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) '{0} (PID {1})' -f $i['Proces'], $i['PID'] }
        if (-not (Confirm-Action -Text 'Zakończyć wybrane procesy? Niezapisane dane w tych programach zostaną utracone.' -Items $items -ConfirmText 'Zakończ procesy' -Danger)) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Ids = @($byHost[$h] | ForEach-Object { [int]$_['PID'] }) } }
        Start-HostOperation -Module $m -Name 'Kończenie procesów' -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($id in $P.Ids) {
                try {
                    $proc = Get-Process -Id $id -ErrorAction Stop
                    Stop-Process -Id $id -Force -ErrorAction Stop
                    [pscustomobject]@{ 'Proces' = $proc.ProcessName; 'PID' = $id; 'Wynik' = 'Zakończono' }
                }
                catch { [pscustomobject]@{ 'PID' = $id; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    Add-Label -Parent $row -Text 'Nazwa' | Out-Null
    $m.Filter = Add-TextBox -Parent $row -Width 170 -Placeholder 'np. chrome'
    $m.WithOwner = Add-CheckBox -Parent $row -Text 'Pokaż właściciela (wolniej)'
    Add-Button -Parent $row -Text 'Pokaż procesy' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Zakończ zaznaczone' -Icon 'E711' -Module $m -Danger -OnClick { param($m) & $m.Actions.Kill $m $null } | Out-Null
    Add-RowAction -Module $m -Text 'Zakończ proces' -Icon 'E711' -Danger -Action { param($m, $rows) & $m.Actions.Kill $m $rows }
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Disks' -Title 'Dyski' -Icon 'EDA2' `
    -Description 'Zajętość dysków lokalnych oraz czyszczenie plików tymczasowych i Kosza (z raportem odzyskanego miejsca).' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $row = Add-ToolbarRow -Module $m -Title 'Zajętość'
    Add-Button -Parent $row -Text 'Pokaż dyski' -Icon 'EDA2' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Dyski' -Targets $targets -ScriptBlock {
            param($P)
            Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType = 3' | ForEach-Object {
                $size = [double]$_.Size
                $free = [double]$_.FreeSpace
                $freePct = if ($size -gt 0) { [Math]::Round($free / $size * 100, 1) } else { $null }
                $tone = if ($null -eq $freePct) { '' } elseif ($freePct -le 5) { 'crit' } elseif ($freePct -le 15) { 'warn' } else { 'ok' }
                [pscustomobject]@{
                    'Dysk'          = $_.DeviceID
                    'Stan'          = $(switch ($tone) { 'crit' { 'krytycznie mało' } 'warn' { 'mało miejsca' } 'ok' { 'OK' } default { '' } })
                    'Etykieta'      = $_.VolumeName
                    'System plików' = $_.FileSystem
                    'Rozmiar (GB)'  = [Math]::Round($size / 1GB, 1)
                    'Wolne (GB)'    = [Math]::Round($free / 1GB, 1)
                    'Wolne (%)'     = $freePct
                    '__tone'        = $tone
                }
            }
        }
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Czyszczenie'
    $m.WinTemp = Add-CheckBox -Parent $row2 -Text 'Windows\Temp' -Checked $true
    $m.UserTemp = Add-CheckBox -Parent $row2 -Text 'TEMP profili użytkowników' -Checked $true
    $m.Recycle = Add-CheckBox -Parent $row2 -Text 'Kosz (wszystkie dyski)' -Checked $true
    $m.WuCache = Add-CheckBox -Parent $row2 -Text 'Pobrane aktualizacje (SoftwareDistribution\Download)' -ToolTip 'Usługa Windows Update zostanie na chwilę zatrzymana'
    Add-Label -Parent $row2 -Text 'Starsze niż (dni)' | Out-Null
    $m.Days = Add-Numeric -Parent $row2 -Value 2 -Minimum 0 -Maximum 365 -Width 60
    Add-Button -Parent $row2 -Text 'Wyczyść na zaznaczonych' -Icon 'E74D' -Module $m -Danger -OnClick {
        param($m)
        if (-not ((Test-Checked $m.WinTemp) -or (Test-Checked $m.UserTemp) -or (Test-Checked $m.Recycle) -or (Test-Checked $m.WuCache))) { Show-Warning 'Wybierz, co ma zostać wyczyszczone.'; return }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $targets = @(Confirm-Action -Text "Usunąć pliki tymczasowe na wybranych komputerach?" -Items $targets -ConfirmText 'Wyczyść' -Danger -Select); if ($targets.Count -eq 0) { return }
        $params = @{ WindowsTemp = (Test-Checked $m.WinTemp); UserTemp = (Test-Checked $m.UserTemp); RecycleBin = (Test-Checked $m.Recycle); WuCache = (Test-Checked $m.WuCache); OlderThanDays = (Get-Num $m.Days) }
        Start-HostOperation -Module $m -Name 'Czyszczenie dysków' -Targets $targets -Parameters $params -ScriptBlock {
            param($P)
            $drive = Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $env:SystemDrive)
            $before = [double]$drive.FreeSpace
            $limit = (Get-Date).AddDays( - [int]$P.OlderThanDays)
            $roots = @()
            if ($P.WindowsTemp) { $roots += (Join-Path $env:SystemRoot 'Temp') }
            if ($P.UserTemp) {
                $profiles = Get-CimInstance -ClassName Win32_UserProfile -Filter 'Special = False' -ErrorAction SilentlyContinue
                foreach ($pr in $profiles) {
                    $t = Join-Path $pr.LocalPath 'AppData\Local\Temp'
                    if (Test-Path -LiteralPath $t) { $roots += $t }
                }
            }
            $removed = 0
            $failed = 0
            foreach ($root in $roots) {
                Get-ChildItem -LiteralPath $root -Recurse -Force -File -ErrorAction SilentlyContinue |
                    Where-Object { $_.LastWriteTime -lt $limit -and $_.FullName -notlike '*\Temp\DomainOps\*' } |
                    ForEach-Object {
                        try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop; $removed++ } catch { $failed++ }
                    }
                Get-ChildItem -LiteralPath $root -Recurse -Force -Directory -ErrorAction SilentlyContinue |
                    Where-Object { $_.FullName -notlike '*\Temp\DomainOps*' } |
                    Sort-Object { $_.FullName.Length } -Descending |
                    ForEach-Object {
                        if (-not (Get-ChildItem -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue)) {
                            Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
                        }
                    }
            }
            if ($P.RecycleBin) {
                foreach ($d in Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType = 3') {
                    $bin = $d.DeviceID + '\$Recycle.Bin'
                    if (-not (Test-Path -LiteralPath $bin)) { continue }
                    foreach ($sidDir in Get-ChildItem -LiteralPath $bin -Force -Directory -ErrorAction SilentlyContinue) {
                        Get-ChildItem -LiteralPath $sidDir.FullName -Force -ErrorAction SilentlyContinue |
                            Where-Object { $_.Name -ne 'desktop.ini' } |
                            ForEach-Object {
                                try { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Stop; $removed++ } catch { $failed++ }
                            }
                    }
                }
            }
            if ($P.WuCache) {
                $download = Join-Path $env:SystemRoot 'SoftwareDistribution\Download'
                try {
                    Stop-Service -Name wuauserv -Force -ErrorAction Stop
                    Get-ChildItem -LiteralPath $download -Force -ErrorAction SilentlyContinue | ForEach-Object {
                        try { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction Stop; $removed++ } catch { $failed++ }
                    }
                }
                finally { Start-Service -Name wuauserv -ErrorAction SilentlyContinue }
            }
            $after = [double](Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $env:SystemDrive)).FreeSpace
            [pscustomobject]@{
                'Usunięte elementy'            = $removed
                'Nie udało się usunąć'         = $failed
                'Odzyskano na systemowym (GB)' = [Math]::Round(($after - $before) / 1GB, 2)
                'Wolne na systemowym (GB)'     = [Math]::Round($after / 1GB, 1)
            }
        }
    } | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Events' -Title 'Dziennik zdarzeń' -Icon 'E81C' `
    -Description 'Zdarzenia z wybranych dzienników z ostatnich godzin. Gotowe zestawy pomagają szybko znaleźć typowe problemy (nieoczekiwane wyłączenia, błędy dysku, nieudane logowania).' -Build {
    param($m)
    $m.PillColumns = @('Poziom')
    $m.Presets = @(
        @{ Name = '(własne ustawienia)' }
        @{ Name = 'Nieoczekiwane wyłączenia i restarty'; Logs = @('System'); Ids = '41, 6008, 1074, 1076'; Levels = @(1, 2, 3, 4) }
        @{ Name = 'Błędy dysków i systemu plików'; Logs = @('System'); Ids = '7, 11, 15, 51, 55, 98, 129, 153'; Levels = @(1, 2, 3) }
        @{ Name = 'Awarie aplikacji'; Logs = @('Application'); Ids = '1000, 1001, 1002, 1026'; Levels = @(1, 2, 4) }
        @{ Name = 'Nieudane logowania (Security 4625)'; Logs = @('Security'); Ids = '4625'; Levels = @() }
        @{ Name = 'Blokady kont (Security 4740)'; Logs = @('Security'); Ids = '4740'; Levels = @() }
        @{ Name = 'Zasady grupy – błędy'; Logs = @('System'); Ids = '1085, 1096, 1125, 1129'; Levels = @(1, 2, 3) }
        @{ Name = 'Windows Update – instalacje'; Logs = @('System'); Ids = '19, 20, 43'; Levels = @(1, 2, 3, 4) }
    )
    $row = Add-ToolbarRow -Module $m -Title 'Zestaw'
    $m.Preset = Add-ComboBox -Parent $row -Items @($m.Presets | ForEach-Object { $_.Name }) -Width 320
    Register-ControlHandler -Control $m.Preset -EventName 'SelectionChanged' -Module $m -Action {
        param($m, $s)
        $p = $m.Presets[$s.SelectedIndex]
        if (-not $p.ContainsKey('Logs')) { return }
        $m.LogSystem.IsChecked = ($p.Logs -contains 'System')
        $m.LogApp.IsChecked = ($p.Logs -contains 'Application')
        $m.LogSec.IsChecked = ($p.Logs -contains 'Security')
        $m.LvlCrit.IsChecked = ($p.Levels -contains 1)
        $m.LvlErr.IsChecked = ($p.Levels -contains 2)
        $m.LvlWarn.IsChecked = ($p.Levels -contains 3)
        $m.LvlInfo.IsChecked = ($p.Levels -contains 4)
        $m.Ids.Text = $p.Ids
    }
    $row1 = Add-ToolbarRow -Module $m -Title 'Dzienniki'
    $m.LogSystem = Add-CheckBox -Parent $row1 -Text 'System' -Checked $true
    $m.LogApp = Add-CheckBox -Parent $row1 -Text 'Application' -Checked $true
    $m.LogSec = Add-CheckBox -Parent $row1 -Text 'Security'
    Add-Label -Parent $row1 -Text '   Poziom' -Hint | Out-Null
    $m.LvlCrit = Add-CheckBox -Parent $row1 -Text 'Krytyczny' -Checked $true
    $m.LvlErr = Add-CheckBox -Parent $row1 -Text 'Błąd' -Checked $true
    $m.LvlWarn = Add-CheckBox -Parent $row1 -Text 'Ostrzeżenie' -Checked $true
    $m.LvlInfo = Add-CheckBox -Parent $row1 -Text 'Informacja'
    $row2 = Add-ToolbarRow -Module $m -Title 'Zakres'
    Add-Label -Parent $row2 -Text 'Ostatnie godziny' | Out-Null
    $m.Hours = Add-Numeric -Parent $row2 -Value 24 -Minimum 1 -Maximum 2160 -Width 70
    Add-Label -Parent $row2 -Text 'ID zdarzeń' | Out-Null
    $m.Ids = Add-TextBox -Parent $row2 -Width 200 -Placeholder 'opcjonalnie, np. 41, 6008'
    Add-Label -Parent $row2 -Text 'Maks. na komputer' | Out-Null
    $m.Max = Add-Numeric -Parent $row2 -Value 300 -Minimum 10 -Maximum 10000 -Width 70
    Add-Button -Parent $row2 -Text 'Pobierz zdarzenia' -Icon 'E896' -Module $m -Primary -OnClick {
        param($m)
        $logs = @()
        if (Test-Checked $m.LogSystem) { $logs += 'System' }
        if (Test-Checked $m.LogApp) { $logs += 'Application' }
        if (Test-Checked $m.LogSec) { $logs += 'Security' }
        if ($logs.Count -eq 0) { Show-Warning 'Wybierz co najmniej jeden dziennik.'; return }
        $levels = @()
        if (Test-Checked $m.LvlCrit) { $levels += 1 }
        if (Test-Checked $m.LvlErr) { $levels += 2 }
        if (Test-Checked $m.LvlWarn) { $levels += 3 }
        if (Test-Checked $m.LvlInfo) { $levels += 4; $levels += 0 }
        if ($levels.Count -eq 0 -and -not ($logs.Count -eq 1 -and $logs[0] -eq 'Security')) { Show-Warning 'Wybierz co najmniej jeden poziom zdarzeń.'; return }
        $ids = @(Split-ListText ($m.Ids.Text -replace '\s+', ',') | Where-Object { $_ -match '^\d+$' } | ForEach-Object { [int]$_ })
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $params = @{ Logs = $logs; Levels = $levels; Ids = $ids; Hours = (Get-Num $m.Hours); Max = (Get-Num $m.Max) }
        Start-HostOperation -Module $m -Name 'Dziennik zdarzeń' -Targets $targets -Parameters $params -ScriptBlock {
            param($P)
            $filter = @{ LogName = [string[]]@($P.Logs); StartTime = (Get-Date).AddHours( - [int]$P.Hours) }
            $ids = @($P.Ids | Where-Object { $null -ne $_ })
            if ($ids.Count -gt 0) { $filter.Id = [int[]]$ids }
            # Security nie używa poziomów (audyt) - bez filtra poziomu, gdy wybrano tylko Security
            $levels = [int[]]@($P.Levels)
            if ($levels.Count -gt 0 -and (@($P.Logs) -notcontains 'Security' -or @($P.Logs).Count -gt 1)) { $filter.Level = $levels }
            try {
                $events = @(Get-WinEvent -FilterHashtable $filter -MaxEvents ([int]$P.Max) -ErrorAction Stop)
            }
            catch {
                if ($_.FullyQualifiedErrorId -like 'NoMatchingEventsFound*') { $events = @() } else { throw }
            }
            $events | Sort-Object TimeCreated -Descending | ForEach-Object {
                $msg = $_.Message
                if (-not $msg) { $msg = '(brak opisu – brak biblioteki komunikatów dostawcy)' }
                $tone = switch ([int]$_.Level) { 1 { 'crit' } 2 { 'crit' } 3 { 'warn' } default { 'info' } }
                [pscustomobject]@{
                    'Czas'      = $_.TimeCreated
                    'Poziom'    = $(if ($_.LevelDisplayName) { $_.LevelDisplayName } else { 'Inspekcja' })
                    'ID'        = $_.Id
                    'Źródło'    = $_.ProviderName
                    'Dziennik'  = $_.LogName
                    'Komunikat' = ($msg -replace '\s+', ' ').Trim()
                    '__tone'    = $tone
                }
            }
        }
    } | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Tasks' -Title 'Harmonogram zadań' -Icon 'E787' `
    -Description 'Zadania Harmonogramu: podgląd, uruchamianie, włączanie, wyłączanie, usuwanie i tworzenie prostych zadań (konto SYSTEM).' -Build {
    param($m)
    $m.PillColumns = @('Ostatni wynik')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Harmonogram' -Targets $targets -Parameters @{ Filter = $m.Filter.Text.Trim(); HideMicrosoft = (Test-Checked $m.HideMs) } -ScriptBlock {
            param($P)
            $tasks = @(Get-ScheduledTask -ErrorAction Stop)
            if ($P.HideMicrosoft) { $tasks = @($tasks | Where-Object { $_.TaskPath -notlike '\Microsoft\*' }) }
            if ($P.Filter) {
                $f = "*$($P.Filter)*"
                $tasks = @($tasks | Where-Object { $_.TaskName -like $f -or $_.TaskPath -like $f })
            }
            foreach ($t in $tasks) {
                $info = $null
                try { $info = Get-ScheduledTaskInfo -InputObject $t -ErrorAction Stop } catch { }
                $actions = @($t.Actions | ForEach-Object { if ($_.PSObject.Properties['Execute'] -and $_.Execute) { ('{0} {1}' -f $_.Execute, $_.Arguments).Trim() } }) -join ' ; '
                $lastResult = ''
                $tone = ''
                $lastRun = $null
                $nextRun = $null
                if ($info) {
                    $lastRun = $info.LastRunTime
                    $nextRun = $info.NextRunTime
                    $code = [int64]$info.LastTaskResult
                    $lastResult = switch ($code) {
                        0 { 'Sukces' }
                        267009 { 'W trakcie' }
                        267011 { 'Jeszcze nie uruchomiono' }
                        267014 { 'Zatrzymane przez użytkownika' }
                        default { '0x{0:X8}' -f $code }
                    }
                    $tone = switch ($code) { 0 { 'ok' } 267009 { 'info' } 267011 { '' } default { 'crit' } }
                }
                [pscustomobject]@{
                    'Ścieżka'               = $t.TaskPath
                    'Nazwa'                 = $t.TaskName
                    'Stan'                  = [string]$t.State
                    'Ostatnie uruchomienie' = $lastRun
                    'Ostatni wynik'         = $lastResult
                    'Następne uruchomienie' = $nextRun
                    'Konto'                 = $t.Principal.UserId
                    'Akcja'                 = $actions
                    'Autor'                 = $t.Author
                    '__tone'                = $tone
                    '__flag'                = $(if ([string]$t.State -eq 'Disabled') { 'muted' } else { '' })
                }
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Ścieżka', 'Nazwa') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli zadania, których dotyczy operacja.'; return }
        $label = @{ Run = 'Uruchomić'; Stop = 'Zatrzymać'; Enable = 'Włączyć'; Disable = 'Wyłączyć'; Delete = 'Usunąć' }[$Op]
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Ścieżka'] + $i['Nazwa'] }
        if (-not (Confirm-Action -Text "$label wybrane zadania?" -Items $items -ConfirmText $(if ($Op -eq 'Delete') { 'Usuń zadania' } else { 'Wykonaj' }) -Danger:($Op -eq 'Delete'))) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) {
            $per[$h] = @{ Op = $Op; Tasks = @($byHost[$h] | ForEach-Object { @{ Path = [string]$_['Ścieżka']; Name = [string]$_['Nazwa'] } }) }
        }
        Start-HostOperation -Module $m -Name "Harmonogram – $Op" -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($t in $P.Tasks) {
                try {
                    $tp = @{ TaskPath = $t.Path; TaskName = $t.Name; ErrorAction = 'Stop' }
                    switch ($P.Op) {
                        'Run' { Start-ScheduledTask @tp }
                        'Stop' { Stop-ScheduledTask @tp }
                        'Enable' { Enable-ScheduledTask @tp | Out-Null }
                        'Disable' { Disable-ScheduledTask @tp | Out-Null }
                        'Delete' { Unregister-ScheduledTask @tp -Confirm:$false }
                    }
                    [pscustomobject]@{ 'Zadanie' = $t.Path + $t.Name; 'Operacja' = $P.Op; 'Wynik' = 'OK' }
                }
                catch { [pscustomobject]@{ 'Zadanie' = $t.Path + $t.Name; 'Operacja' = $P.Op; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    Add-Label -Parent $row -Text 'Filtr' | Out-Null
    $m.Filter = Add-TextBox -Parent $row -Width 170 -Placeholder 'nazwa lub ścieżka'
    $m.HideMs = Add-CheckBox -Parent $row -Text 'Ukryj zadania systemowe (\Microsoft\)' -Checked $true
    Add-Button -Parent $row -Text 'Pokaż zadania' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Zaznaczone zadania'
    foreach ($a in @(@('Uruchom', 'Run', 'E768'), @('Zatrzymaj', 'Stop', 'E71A'), @('Włącz', 'Enable', 'E73E'), @('Wyłącz', 'Disable', 'E8D8'))) {
        $b = Add-Button -Parent $row2 -Text $a[0] -Icon $a[2] -Module $m -OnClick { param($m, $s) & $m.Actions.Change $m ([string]$s.Tag) $null }
        $b.Tag = $a[1]
    }
    $b = Add-Button -Parent $row2 -Text 'Usuń' -Icon 'E74D' -Module $m -Danger -OnClick { param($m, $s) & $m.Actions.Change $m 'Delete' $null }
    Add-RowAction -Module $m -Text 'Uruchom teraz' -Icon 'E768' -Action { param($m, $rows) & $m.Actions.Change $m 'Run' $rows }
    Add-RowAction -Module $m -Text 'Włącz' -Icon 'E73E' -Action { param($m, $rows) & $m.Actions.Change $m 'Enable' $rows }
    Add-RowAction -Module $m -Text 'Wyłącz' -Icon 'E8D8' -Action { param($m, $rows) & $m.Actions.Change $m 'Disable' $rows }
    Add-RowAction -Module $m -Text 'Usuń zadanie' -Icon 'E74D' -Danger -Separator -Action { param($m, $rows) & $m.Actions.Change $m 'Delete' $rows }

    $row3 = Add-ToolbarRow -Module $m -Title 'Nowe zadanie'
    $m.NewName = Add-TextBox -Parent $row3 -Width 150 -Placeholder 'Nazwa zadania'
    $m.NewExe = Add-TextBox -Parent $row3 -Width 220 -Placeholder 'Program, np. powershell.exe'
    $m.NewArgs = Add-TextBox -Parent $row3 -Width 220 -Placeholder 'Argumenty'
    $m.NewTrigger = Add-ComboBox -Parent $row3 -Items @('Przy logowaniu', 'Przy uruchomieniu', 'Codziennie o', 'Jednorazowo o', 'Tylko na żądanie') -Width 160
    $m.NewTime = Add-TextBox -Parent $row3 -Width 64 -Text '07:00'
    Add-Button -Parent $row3 -Text 'Utwórz' -Icon 'E710' -Module $m -OnClick {
        param($m)
        $name = $m.NewName.Text.Trim()
        $exe = $m.NewExe.Text.Trim()
        if (-not $name -or -not $exe) { Show-Warning 'Podaj nazwę zadania i program do uruchomienia.'; return }
        if ($name -match '[\\/:*?"<>|]') { Show-Warning 'Nazwa zadania zawiera niedozwolone znaki.'; return }
        $trigger = @('Logon', 'Startup', 'Daily', 'Once', 'None')[$m.NewTrigger.SelectedIndex]
        $time = $m.NewTime.Text.Trim()
        if (($trigger -eq 'Daily' -or $trigger -eq 'Once') -and $time -notmatch '^([01]?\d|2[0-3]):[0-5]\d$') { Show-Warning 'Podaj godzinę w formacie GG:MM (np. 07:30).'; return }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $targets = @(Confirm-Action -Text "Utworzyć zadanie «$name» (konto SYSTEM, najwyższe uprawnienia)?`r`nProgram: $exe $($m.NewArgs.Text.Trim())" -Items $targets -ConfirmText 'Utwórz' -Select); if ($targets.Count -eq 0) { return }
        $params = @{ Name = $name; Execute = $exe; Arguments = $m.NewArgs.Text.Trim(); Trigger = $trigger; Time = $time }
        Start-HostOperation -Module $m -Name 'Tworzenie zadania' -Targets $targets -Output Log -Parameters $params -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            if ($P.Arguments) { $action = New-ScheduledTaskAction -Execute $P.Execute -Argument $P.Arguments }
            else { $action = New-ScheduledTaskAction -Execute $P.Execute }
            $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
            $register = @{ TaskName = $P.Name; Action = $action; Principal = $principal; Settings = $settings; Force = $true; ErrorAction = 'Stop' }
            $at = $null
            if ($P.Time) {
                $at = [datetime]::Today.Add([timespan]::Parse($P.Time))
                if ($P.Trigger -eq 'Once' -and $at -lt (Get-Date)) { $at = $at.AddDays(1) }
            }
            switch ($P.Trigger) {
                'Logon' { $register.Trigger = New-ScheduledTaskTrigger -AtLogOn }
                'Startup' { $register.Trigger = New-ScheduledTaskTrigger -AtStartup }
                'Daily' { $register.Trigger = New-ScheduledTaskTrigger -Daily -At $at }
                'Once' { $register.Trigger = New-ScheduledTaskTrigger -Once -At $at }
            }
            Register-ScheduledTask @register | Out-Null
            [pscustomobject]@{ 'Zadanie' = '\' + $P.Name; 'Wynik' = 'Utworzono' }
        }
    } | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Autostart' -Title 'Autostart' -Icon 'E768' -Badge 'Nowość w wersji 4.0' `
    -Description 'Programy uruchamiane automatycznie: klucze Run/RunOnce (komputer i załadowane profile użytkowników) oraz foldery Autostart. Wybrane wpisy można usunąć.' -Build {
    param($m)
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Autostart' -Targets $targets -ScriptBlock {
            param($P)
            $keys = @(
                @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'; Scope = 'Komputer' }
                @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'; Scope = 'Komputer (jednorazowo)' }
                @{ Path = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; Scope = 'Komputer (32-bit)' }
                @{ Path = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\RunOnce'; Scope = 'Komputer (32-bit, jednorazowo)' }
            )
            # Załadowane gałęzie użytkowników (zalogowani) - nazwy kont z SID
            foreach ($hive in @(Get-ChildItem -Path 'Registry::HKEY_USERS' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^S-1-5-21-[\d-]+$' })) {
                $sid = $hive.PSChildName
                $user = $sid
                try { $user = (New-Object System.Security.Principal.SecurityIdentifier($sid)).Translate([System.Security.Principal.NTAccount]).Value } catch { }
                $keys += @{ Path = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\Run"; Scope = "Użytkownik $user" }
                $keys += @{ Path = "Registry::HKEY_USERS\$sid\Software\Microsoft\Windows\CurrentVersion\RunOnce"; Scope = "Użytkownik $user (jednorazowo)" }
            }
            foreach ($k in $keys) {
                $item = Get-Item -LiteralPath $k.Path -ErrorAction SilentlyContinue
                if (-not $item) { continue }
                foreach ($name in $item.GetValueNames()) {
                    if (-not $name) { continue }
                    [pscustomobject]@{
                        'Nazwa'    = $name
                        'Polecenie' = [string]$item.GetValue($name)
                        'Zakres'   = $k.Scope
                        'Typ'      = 'Rejestr'
                        'Lokalizacja' = $k.Path -replace '^Registry::', ''
                    }
                }
            }
            $folders = @(@{ Path = Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs\Startup'; Scope = 'Wszyscy użytkownicy' })
            foreach ($pr in @(Get-CimInstance -ClassName Win32_UserProfile -Filter 'Special = False' -ErrorAction SilentlyContinue)) {
                $folders += @{ Path = Join-Path $pr.LocalPath 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup'; Scope = 'Profil ' + (Split-Path $pr.LocalPath -Leaf) }
            }
            foreach ($f in $folders) {
                if (-not (Test-Path -LiteralPath $f.Path)) { continue }
                foreach ($file in @(Get-ChildItem -LiteralPath $f.Path -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' })) {
                    $target = ''
                    if ($file.Extension -eq '.lnk') {
                        try { $target = (New-Object -ComObject WScript.Shell).CreateShortcut($file.FullName).TargetPath } catch { }
                    }
                    [pscustomobject]@{
                        'Nazwa'       = $file.Name
                        'Polecenie'   = $(if ($target) { $target } else { $file.FullName })
                        'Zakres'      = $f.Scope
                        'Typ'         = 'Folder Autostart'
                        'Lokalizacja' = $file.FullName
                    }
                }
            }
        }
    }
    $m.Actions.Remove = {
        param($m, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Nazwa', 'Typ', 'Lokalizacja') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli wpisy autostartu do usunięcia.'; return }
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) '{0} ({1})' -f $i['Nazwa'], $i['Lokalizacja'] }
        if (-not (Confirm-Action -Text 'Usunąć wybrane wpisy autostartu? Programy nie będą uruchamiane automatycznie (same programy nie zostaną odinstalowane).' -Items $items -ConfirmText 'Usuń wpisy' -Danger)) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Items = @($byHost[$h] | ForEach-Object { @{ Name = [string]$_['Nazwa']; Type = [string]$_['Typ']; Location = [string]$_['Lokalizacja'] } }) } }
        Start-HostOperation -Module $m -Name 'Usuwanie z autostartu' -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($i in $P.Items) {
                try {
                    if ($i.Type -eq 'Rejestr') {
                        $path = if ($i.Location -like 'HKEY_USERS\*') { 'Registry::' + $i.Location } else { $i.Location }
                        Remove-ItemProperty -LiteralPath $path -Name $i.Name -ErrorAction Stop
                    }
                    else { Remove-Item -LiteralPath $i.Location -Force -ErrorAction Stop }
                    [pscustomobject]@{ 'Wpis' = $i.Name; 'Wynik' = 'Usunięto' }
                }
                catch { [pscustomobject]@{ 'Wpis' = $i.Name; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pokaż autostart' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Usuń zaznaczone wpisy' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Remove $m $null } | Out-Null
    Add-Label -Parent $row -Text 'Wpisy użytkowników są widoczne tylko dla zalogowanych (załadowane profile).' -Hint | Out-Null
    Add-RowAction -Module $m -Text 'Usuń z autostartu' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Remove $m $rows }
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Printers' -Title 'Drukarki' -Icon 'E749' -Badge 'Nowość w wersji 4.0' `
    -Description 'Drukarki zainstalowane na komputerze (sterownik, port, udostępnianie, zadania w kolejce), czyszczenie kolejek, usuwanie drukarek i restart bufora wydruku.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Drukarki' -Targets $targets -ScriptBlock {
            param($P)
            $spooler = Get-Service -Name Spooler -ErrorAction SilentlyContinue
            $printers = @(Get-CimInstance -ClassName Win32_Printer)
            $jobs = @(Get-CimInstance -ClassName Win32_PrintJob -ErrorAction SilentlyContinue)
            foreach ($prn in $printers) {
                $count = @($jobs | Where-Object { ($_.Name -split ',')[0] -eq $prn.Name }).Count
                $status = switch ([int]$prn.PrinterStatus) { 1 { 'Inny' } 2 { 'Nieznany' } 3 { 'Bezczynna' } 4 { 'Drukuje' } 5 { 'Rozgrzewanie' } 6 { 'Zatrzymana' } 7 { 'Offline' } default { [string]$prn.PrinterStatus } }
                if ($prn.WorkOffline) { $status = 'Offline' }
                $tone = switch ($status) { 'Bezczynna' { 'ok' } 'Drukuje' { 'info' } 'Offline' { 'crit' } 'Zatrzymana' { 'crit' } default { 'warn' } }
                [pscustomobject]@{
                    'Drukarka'     = $prn.Name
                    'Stan'         = $status
                    'Zadania'      = $count
                    'Domyślna'     = [bool]$prn.Default
                    'Sterownik'    = $prn.DriverName
                    'Port'         = $prn.PortName
                    'Udostępniona' = [bool]$prn.Shared
                    'Nazwa udziału' = $prn.ShareName
                    'Lokalizacja'  = $prn.Location
                    'Bufor wydruku' = $(if ($spooler) { [string]$spooler.Status } else { '?' })
                    '__tone'       = $tone
                }
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Drukarka') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli drukarki.'; return }
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Drukarka'] }
        $text = if ($Op -eq 'Remove') { 'Usunąć wybrane drukarki z komputerów?' } else { 'Usunąć wszystkie zadania z kolejek wybranych drukarek?' }
        if (-not (Confirm-Action -Text $text -Items $items -ConfirmText $(if ($Op -eq 'Remove') { 'Usuń drukarki' } else { 'Wyczyść kolejki' }) -Danger)) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Op = $Op; Names = @($byHost[$h] | ForEach-Object { [string]$_['Drukarka'] }) } }
        Start-HostOperation -Module $m -Name "Drukarki – $Op" -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($name in $P.Names) {
                try {
                    $printer = Get-CimInstance -ClassName Win32_Printer | Where-Object { $_.Name -eq $name }
                    if (-not $printer) { throw 'Nie znaleziono drukarki.' }
                    if ($P.Op -eq 'Remove') {
                        Remove-CimInstance -InputObject $printer -ErrorAction Stop
                        [pscustomobject]@{ 'Drukarka' = $name; 'Wynik' = 'Usunięto' }
                    }
                    else {
                        $r = Invoke-CimMethod -InputObject $printer -MethodName CancelAllJobs
                        [pscustomobject]@{ 'Drukarka' = $name; 'Wynik' = $(if ($r.ReturnValue -eq 0) { 'Wyczyszczono kolejkę' } else { "Błąd – kod $($r.ReturnValue)" }) }
                    }
                }
                catch { [pscustomobject]@{ 'Drukarka' = $name; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pokaż drukarki' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Wyczyść kolejki zaznaczonych' -Icon 'E894' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Clear' $null } | Out-Null
    Add-Button -Parent $row -Text 'Usuń zaznaczone' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Remove' $null } | Out-Null
    Add-Button -Parent $row -Text 'Restart bufora wydruku' -Icon 'E777' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $targets = @(Confirm-Action -Text 'Uruchomić ponownie usługę bufora wydruku (Spooler)? Zadania w trakcie drukowania mogą zostać przerwane.' -Items $targets -ConfirmText 'Uruchom ponownie' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name 'Restart bufora wydruku' -Targets $targets -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            Restart-Service -Name Spooler -Force -ErrorAction Stop
            'Bufor wydruku: ' + [string](Get-Service -Name Spooler).Status
        }
    } | Out-Null
    Add-RowAction -Module $m -Text 'Wyczyść kolejkę' -Icon 'E894' -Action { param($m, $rows) & $m.Actions.Change $m 'Clear' $rows }
    Add-RowAction -Module $m -Text 'Usuń drukarkę' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Change $m 'Remove' $rows }
}

Register-Module -Workspace 'Remote' -Category 'System' -Key 'Drivers' -Title 'Sterowniki i urządzenia' -Icon 'E772' `
    -Description 'Zainstalowane sterowniki (Win32_PnPSignedDriver) oraz urządzenia zgłaszające problem w Menedżerze urządzeń.' -Build {
    param($m)
    $m.ColorBools = $true
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Label -Parent $row -Text 'Filtr' | Out-Null
    $m.Filter = Add-TextBox -Parent $row -Width 220 -Placeholder 'urządzenie, producent lub klasa'
    Add-Button -Parent $row -Text 'Pokaż sterowniki' -Icon 'E72C' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Sterowniki' -Targets $targets -Parameters @{ Filter = $m.Filter.Text.Trim() } -ScriptBlock {
            param($P)
            $drivers = @(Get-CimInstance -ClassName Win32_PnPSignedDriver | Where-Object { $_.DeviceName })
            if ($P.Filter) {
                $f = "*$($P.Filter)*"
                $drivers = @($drivers | Where-Object { $_.DeviceName -like $f -or $_.Manufacturer -like $f -or $_.DriverProviderName -like $f -or $_.DeviceClass -like $f })
            }
            $drivers | Sort-Object DeviceClass, DeviceName | ForEach-Object {
                [pscustomobject]@{
                    'Urządzenie' = $_.DeviceName
                    'Klasa'      = $_.DeviceClass
                    'Wersja'     = $_.DriverVersion
                    'Data'       = $_.DriverDate
                    'Producent'  = $_.Manufacturer
                    'Dostawca'   = $_.DriverProviderName
                    'Plik INF'   = $_.InfName
                    'Podpisany'  = $_.IsSigned
                }
            }
        }
    } | Out-Null
    Add-Button -Parent $row -Text 'Urządzenia z problemami' -Icon 'E7BA' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Urządzenia z problemami' -Targets $targets -ScriptBlock {
            param($P)
            $devices = @(Get-CimInstance -ClassName Win32_PnPEntity | Where-Object { $_.ConfigManagerErrorCode -ne 0 })
            if ($devices.Count -eq 0) { return [pscustomobject]@{ 'Urządzenie' = '(brak urządzeń z problemami)' } }
            foreach ($d in $devices) {
                [pscustomobject]@{
                    'Urządzenie'    = $d.Name
                    'Kod błędu'     = $d.ConfigManagerErrorCode
                    'Stan'          = $d.Status
                    'Klasa'         = $d.PNPClass
                    'Producent'     = $d.Manufacturer
                    'ID urządzenia' = $d.DeviceID
                    '__flag'        = 'warn'
                }
            }
        }
    } | Out-Null
}
#endregion

#region Zarządzanie zdalne: Oprogramowanie
# Skrypt instalacji aktualizacji uruchamiany na komputerze jako zadanie SYSTEM - API Windows Update
# (pobieranie/instalacja) nie działa bezpośrednio w sesji WinRM.
$script:WuJobScript = @'
param([switch]$AutoReboot, [switch]$IncludeDrivers)
$log = Join-Path $PSScriptRoot 'WU.log'
function Write-WuLog([string]$Text) {
    Add-Content -LiteralPath $log -Value ('[{0:yyyy-MM-dd HH:mm:ss}] {1}' -f (Get-Date), $Text) -Encoding UTF8
}
Write-WuLog '==== START ===='
try {
    $session = New-Object -ComObject Microsoft.Update.Session
    $session.ClientApplicationID = 'DomainOps'
    $criteria = "IsInstalled=0 and IsHidden=0"
    if (-not $IncludeDrivers) { $criteria += " and Type='Software'" }
    Write-WuLog "Wyszukiwanie aktualizacji ($criteria)…"
    $search = $session.CreateUpdateSearcher().Search($criteria)
    if ($search.Updates.Count -eq 0) {
        Write-WuLog 'Brak aktualizacji do zainstalowania.'
    }
    else {
        $toInstall = New-Object -ComObject Microsoft.Update.UpdateColl
        foreach ($u in $search.Updates) {
            if (-not $u.EulaAccepted) { $u.AcceptEula() }
            [void]$toInstall.Add($u)
            Write-WuLog "Do instalacji: $($u.Title)"
        }
        Write-WuLog "Pobieranie ($($toInstall.Count))…"
        $downloader = $session.CreateUpdateDownloader()
        $downloader.Updates = $toInstall
        $download = $downloader.Download()
        Write-WuLog "Pobieranie zakończone (ResultCode=$($download.ResultCode))."
        $ready = New-Object -ComObject Microsoft.Update.UpdateColl
        foreach ($u in $toInstall) { if ($u.IsDownloaded) { [void]$ready.Add($u) } }
        if ($ready.Count -eq 0) {
            Write-WuLog 'Żadna aktualizacja nie została pobrana.'
        }
        else {
            Write-WuLog "Instalacja ($($ready.Count))…"
            $installer = $session.CreateUpdateInstaller()
            $installer.Updates = $ready
            $result = $installer.Install()
            for ($i = 0; $i -lt $ready.Count; $i++) {
                Write-WuLog ('{0} -> ResultCode={1}' -f $ready.Item($i).Title, $result.GetUpdateResult($i).ResultCode)
            }
            Write-WuLog "Instalacja zakończona (ResultCode=$($result.ResultCode), RebootRequired=$($result.RebootRequired))."
            if ($result.RebootRequired -and $AutoReboot) {
                Write-WuLog 'Restart za 5 minut.'
                & (Join-Path $env:SystemRoot 'System32\shutdown.exe') /r /t 300 /d p:2:17 /c 'Restart po instalacji aktualizacji (Domain Ops).'
            }
        }
    }
}
catch {
    Write-WuLog "BŁĄD: $($_.Exception.Message)"
}
Write-WuLog '==== KONIEC ===='
'@

# Wspólna funkcja (wklejana do bloków zdalnych): jak odinstalować program z danego wpisu rejestru.
# Kind: msi | quiet | inno (da się po cichu), interactive (tylko z przełącznikami), none, blocked.
$script:UninstallPlanText = @'
function Get-UninstallPlan($Key) {
    $id = [string]$Key.PSChildName
    $us = [string]$Key.UninstallString
    $qs = [string]$Key.QuietUninstallString
    if ($Key.NoRemove -eq 1) { return @{ Kind = 'blocked'; Label = 'Zablokowane (NoRemove)'; Command = ''; Reason = 'Producent zablokował odinstalowanie (NoRemove=1 w rejestrze).' } }
    $guid = ''
    if ($id -match '^\{[0-9A-Fa-f-]{36}\}$' -and ($Key.WindowsInstaller -eq 1 -or $us -match '(?i)msiexec')) { $guid = $id }
    else {
        $mx = [regex]::Match($us, '(?i)msiexec(?:\.exe)?["\s].*?/[IX]\s*(\{[0-9A-Fa-f-]{36}\})')
        if ($mx.Success) { $guid = $mx.Groups[1].Value }
    }
    if ($guid) { return @{ Kind = 'msi'; Label = 'MSI – cicho'; Command = "msiexec.exe /x $guid /qn /norestart"; Reason = ''; Guid = $guid } }
    if ($qs) { return @{ Kind = 'quiet'; Label = 'Tryb cichy producenta'; Command = $qs; Reason = '' } }
    if ($us -match '(?i)unins\d{3}\.exe') { return @{ Kind = 'inno'; Label = 'Inno Setup – cicho'; Command = ($us + ' /VERYSILENT /SUPPRESSMSGBOXES /NORESTART'); Reason = '' } }
    if ($us) { return @{ Kind = 'interactive'; Label = 'Tylko z przełącznikami'; Command = $us; Reason = 'deinstalator nie ma w rejestrze trybu cichego – bez przełączników producenta (np. /S, /silent, /quiet) czekałby na kliknięcie, którego nikt nie wykona' } }
    return @{ Kind = 'none'; Label = 'Brak deinstalatora'; Command = ''; Reason = 'wpis w rejestrze nie zawiera polecenia odinstalowania' }
}
'@

$script:ProgramListBody = @'
$roots = @(
    @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'; Scope = 'Komputer' },
    @{ Path = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'; Scope = 'Komputer (32-bit)' },
    @{ Path = 'Registry::HKEY_USERS\*\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'; Scope = 'Użytkownik' }
)
$accounts = @{}
foreach ($root in $roots) {
    Get-ItemProperty -Path $root.Path -ErrorAction SilentlyContinue | ForEach-Object {
        if (-not $_.DisplayName) { return }
        if (-not $P.ShowSystem -and ($_.SystemComponent -eq 1 -or $_.ParentKeyName -or @('Update', 'Hotfix', 'Security Update') -contains $_.ReleaseType)) { return }
        if ($P.Filter -and $_.DisplayName -notlike "*$($P.Filter)*" -and $_.Publisher -notlike "*$($P.Filter)*") { return }
        $date = $null
        if ($_.InstallDate -match '^\d{8}$') { try { $date = [datetime]::ParseExact($_.InstallDate, 'yyyyMMdd', $null) } catch { } }
        $plan = Get-UninstallPlan $_
        $hive = ''
        $user = ''
        if ($root.Scope -eq 'Użytkownik') {
            $hive = [regex]::Match([string]$_.PSPath, 'HKEY_USERS\\([^\\]+)\\').Groups[1].Value
            if (-not $accounts.ContainsKey($hive)) {
                $name = $hive
                try { $name = (New-Object System.Security.Principal.SecurityIdentifier($hive)).Translate([System.Security.Principal.NTAccount]).Value } catch { }
                $accounts[$hive] = $name
            }
            $user = $accounts[$hive]
        }
        $quiet = @('msi', 'quiet', 'inno') -contains $plan.Kind
        $label = $plan.Label
        $tone = if ($quiet) { 'ok' } elseif ($plan.Kind -eq 'interactive') { 'warn' } else { 'crit' }
        if ($root.Scope -eq 'Użytkownik') {
            if ($quiet) { $label = 'W sesji użytkownika (' + $plan.Label + ')'; $tone = 'warn' }
            else { $label = 'Profil użytkownika – ' + $plan.Label.ToLower(); $tone = 'crit' }
        }
        [pscustomobject]@{
            'Nazwa'                   = $_.DisplayName
            'Odinstalowanie zdalne'   = $label
            'Stan'                    = ''
            'Wersja'                  = $_.DisplayVersion
            'Wydawca'                 = $_.Publisher
            'Data instalacji'         = $date
            'Rozmiar (MB)'            = $(if ($_.EstimatedSize) { [Math]::Round($_.EstimatedSize / 1024, 1) } else { $null })
            'Zakres'                  = $root.Scope
            'Użytkownik'              = $user
            'Identyfikator'           = $_.PSChildName
            'Polecenie odinstalowania' = $plan.Command
            '__plan'                  = $plan.Kind
            '__reason'                = $plan.Reason
            '__hive'                  = $hive
            '__tone'                  = $tone
        }
    }
}
'@

$script:ProgramUninstallBody = @'
$ErrorActionPreference = 'Stop'
$logDir = Join-Path $env:SystemRoot 'Temp\DomainOps'
if (-not (Test-Path -LiteralPath $logDir)) { New-Item -ItemType Directory -Path $logDir -Force | Out-Null }
$kill = New-Object System.Diagnostics.ProcessStartInfo
$kill.FileName = Join-Path $env:SystemRoot 'System32\taskkill.exe'
$kill.UseShellExecute = $false
$kill.CreateNoWindow = $true
$meaning = @{
    0 = @('Odinstalowano', 'ok'); 3010 = @('Odinstalowano – wymagany restart', 'warn'); 1641 = @('Odinstalowano – deinstalator uruchomił restart', 'warn')
    1605 = @('Program nie jest zainstalowany (MSI 1605)', 'info'); 1614 = @('Program był już odinstalowany (MSI 1614)', 'info')
    1602 = @('Anulowano (MSI 1602)', 'crit'); 1603 = @('Błąd krytyczny MSI (1603) – szczegóły w logu', 'crit'); 1618 = @('Trwa inna instalacja – spróbuj ponownie później (MSI 1618)', 'crit')
    1625 = @('Zablokowane przez zasady (MSI 1625)', 'crit'); 1612 = @('Brak źródła instalacji potrzebnego do odinstalowania (MSI 1612)', 'crit')
}
foreach ($item in $P.Items) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $res = [ordered]@{ Id = $item.Id; Name = $item.Name; Status = ''; Tone = 'crit'; Code = $null; Detail = ''; Seconds = 0 }
    try {
        $roots = if ($item.Scope -eq 'Użytkownik') { @("Registry::HKEY_USERS\$($item.Hive)\Software\Microsoft\Windows\CurrentVersion\Uninstall") }
        else { @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall') }
        $keyPath = $null
        foreach ($r in $roots) { $c = Join-Path $r $item.Id; if (Test-Path -LiteralPath $c) { $keyPath = $c; break } }
        if (-not $keyPath) { $res.Status = 'Programu już nie ma w rejestrze (odinstalowany wcześniej?)'; $res.Tone = 'info'; [pscustomobject]$res; continue }
        $key = Get-ItemProperty -LiteralPath $keyPath
        $plan = Get-UninstallPlan $key
        $command = $plan.Command
        if ($plan.Kind -eq 'interactive' -and $item.Args) { $command = $plan.Command + ' ' + $item.Args }
        elseif (@('msi', 'quiet', 'inno') -notcontains $plan.Kind) { throw ('Nie da się odinstalować zdalnie: ' + $plan.Reason) }
        $msiLog = ''
        if ($plan.Kind -eq 'msi') {
            $msiLog = Join-Path $logDir ('Uninstall_{0}.log' -f ($plan.Guid -replace '[{}]', ''))
            $command = 'msiexec.exe /x {0} /qn /norestart /l*v "{1}"' -f $plan.Guid, $msiLog
            if ($item.Args) { $command += ' ' + $item.Args }
        }
        $timedOut = $false
        if ($item.Scope -eq 'Użytkownik') {
            # Program w profilu: deinstalator musi działać jako ten użytkownik - zadanie w jego zalogowanej sesji
            $account = (New-Object System.Security.Principal.SecurityIdentifier($item.Hive)).Translate([System.Security.Principal.NTAccount]).Value
            $taskName = 'DomainOps_Uninstall_' + [guid]::NewGuid().ToString('N')
            $action = New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32\cmd.exe') -Argument ('/d /s /c "' + $command + '"')
            $principal = New-ScheduledTaskPrincipal -UserId $account -LogonType Interactive -RunLevel Limited
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit ([TimeSpan]::FromSeconds([Math]::Max(60, [int]$P.TimeoutSec)))
            Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Settings $settings -Force | Out-Null
            try {
                Start-ScheduledTask -TaskName $taskName
                Start-Sleep -Seconds 2
                while ((Get-ScheduledTask -TaskName $taskName).State -eq 'Running') {
                    if ([int]$P.TimeoutSec -gt 0 -and $sw.Elapsed.TotalSeconds -ge [int]$P.TimeoutSec) { $timedOut = $true; Stop-ScheduledTask -TaskName $taskName; break }
                    Start-Sleep -Seconds 1
                }
                $info = Get-ScheduledTaskInfo -TaskName $taskName
                $res.Code = [int64]$info.LastTaskResult
                if ($res.Code -eq 0x41303 -or $res.Code -eq 0x41306) { throw "Zadanie nie wystartowało – użytkownik $account nie jest zalogowany interaktywnie (zaloguj go albo odinstaluj program w jego sesji)." }
            }
            finally { Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue }
        }
        else {
            $psi = New-Object System.Diagnostics.ProcessStartInfo
            if ($plan.Kind -eq 'msi') { $psi.FileName = Join-Path $env:SystemRoot 'System32\msiexec.exe'; $psi.Arguments = $command.Substring('msiexec.exe '.Length) }
            else { $psi.FileName = Join-Path $env:SystemRoot 'System32\cmd.exe'; $psi.Arguments = '/d /s /c "' + $command + '"' }
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $proc = [System.Diagnostics.Process]::Start($psi)
            try {
                while (-not $proc.HasExited) {
                    if ([int]$P.TimeoutSec -gt 0 -and $sw.Elapsed.TotalSeconds -ge [int]$P.TimeoutSec) { $timedOut = $true; break }
                    Start-Sleep -Milliseconds 500
                }
            }
            finally {
                if (-not $proc.HasExited) {
                    try { $kill.Arguments = '/T /F /PID ' + $proc.Id; [void][System.Diagnostics.Process]::Start($kill).WaitForExit(10000) } catch { }
                    try { if (-not $proc.HasExited) { $proc.Kill() } } catch { }
                }
            }
            if (-not $timedOut) { $res.Code = $proc.ExitCode }
        }
        if ($timedOut) {
            $res.Status = "Przekroczono limit czasu ($($P.TimeoutSec) s) – deinstalator zatrzymany; prawdopodobnie czekał na odpowiedź użytkownika"
        }
        else {
            $known = $meaning[[int]$res.Code]
            if ($known) { $res.Status = $known[0]; $res.Tone = $known[1] } else { $res.Status = "Błąd – kod wyjścia $($res.Code)" }
            # Weryfikacja: wpis w rejestrze powinien zniknąć
            Start-Sleep -Seconds 2
            if (@('ok', 'warn') -contains $res.Tone -and (Test-Path -LiteralPath $keyPath)) {
                if ($res.Tone -eq 'ok') { $res.Status = 'Deinstalator zakończył się bez błędu, ale program nadal jest zainstalowany – mógł czekać na potwierdzenie, uruchomić osobny proces albo wymaga restartu'; $res.Tone = 'warn' }
            }
        }
        if ($msiLog) { $res.Detail = "Log MSI: $msiLog" }
    }
    catch {
        $res.Status = $_.Exception.Message
        $res.Tone = 'crit'
    }
    $res.Seconds = [Math]::Round($sw.Elapsed.TotalSeconds)
    [pscustomobject]$res
}
'@

function New-ProgramScript([string]$Body) {
    # Blok zdalny: param($P) musi być pierwszy, potem wspólna funkcja Get-UninstallPlan i właściwa treść
    return [scriptblock]::Create("param(`$P)`n" + $script:UninstallPlanText + "`n" + $Body)
}

function Start-ProgramUninstall {
    # -Args: dodatkowe przełączniki (dla deinstalatorów bez trybu cichego w rejestrze albo dodatkowe opcje MSI)
    param([hashtable]$Module, $Rows, [string]$Switches = '')
    $m = $Module
    $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Identyfikator', 'Nazwa', 'Zakres') -Rows $Rows
    if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli programy do odinstalowania.'; return }
    $possible = New-Object System.Collections.ArrayList
    $blocked = New-Object System.Collections.ArrayList
    foreach ($h in $byHost.Keys) {
        foreach ($i in $byHost[$h]) {
            $row = $i['__row']
            $plan = [string](Get-RowValue $row '__plan')
            $entry = @{ Host = $h; Row = $row; Id = [string]$i['Identyfikator']; Name = [string]$i['Nazwa']; Scope = [string]$i['Zakres']; Hive = [string](Get-RowValue $row '__hive'); Plan = $plan; Reason = [string](Get-RowValue $row '__reason') }
            if (@('msi', 'quiet', 'inno') -contains $plan -or ($plan -eq 'interactive' -and $Switches)) { [void]$possible.Add($entry) } else { [void]$blocked.Add($entry) }
        }
    }
    foreach ($b in $blocked) {
        $why = if ($b.Plan -eq 'interactive') { 'Nie zdalnie: brak trybu cichego (użyj «Odinstaluj z przełącznikami…»)' } else { 'Nie zdalnie: ' + $b.Reason }
        Set-RowState -Module $m -Row $b.Row -State $why -Tone 'crit'
    }
    $blockedText = (@($blocked | Select-Object -First 8 | ForEach-Object { '• {0}: {1} – {2}' -f $_.Host, $_.Name, $(if ($_.Reason) { $_.Reason } else { 'brak metody' }) }) -join "`r`n")
    if ($blocked.Count -gt 8) { $blockedText += "`r`n• … i $($blocked.Count - 8) więcej" }
    if ($possible.Count -eq 0) {
        Show-Message -Title 'Nie można odinstalować zdalnie' -Tone 'warn' -Text ("Żadnego z wybranych programów nie da się odinstalować bez udziału użytkownika:`r`n`r`n$blockedText`r`n`r`n" +
            "Co można zrobić:`r`n• «Odinstaluj z przełącznikami…» – podaj przełączniki cichego trybu z dokumentacji producenta (często /S, /silent, /quiet, /uninstall)`r`n" +
            "• program w profilu użytkownika bez trybu cichego – odinstaluj go w sesji tego użytkownika (np. pulpit zdalny / pomoc zdalna)`r`n• NoRemove – użyj narzędzia do usuwania od producenta")
        return
    }
    $items = @($possible | ForEach-Object { '{0}: {1}{2}' -f $_.Host, $_.Name, $(if ($_.Scope -eq 'Użytkownik') { '  (w sesji użytkownika)' } else { '' }) })
    $text = 'Odinstalować wybrane programy? Deinstalator działa bez okien i bez restartu; po zakończeniu sprawdzane jest, czy program zniknął z rejestru.'
    if ($Switches) { $text += "`r`nDodatkowe przełączniki: $Switches" }
    if (@($possible | Where-Object { $_.Scope -eq 'Użytkownik' }).Count) { $text += "`r`nProgramy z profilu użytkownika zostaną odinstalowane zadaniem w jego sesji – użytkownik musi być zalogowany." }
    if ($blocked.Count) { $text += "`r`n`r`nPominięte – nie da się ich odinstalować zdalnie ($($blocked.Count)):`r`n$blockedText" }
    $chosen = @(Confirm-Action -Text $text -Items $items -ConfirmText 'Odinstaluj' -Danger -Select -ReturnIndex)
    if ($chosen.Count -eq 0) { return }
    $timeout = [int]$script:ExecTimeouts[[string]$m.Timeout.SelectedItem]
    $per = @{}
    $m.Data.UninstallRows = @{}
    foreach ($i in $chosen) {
        $e = $possible[$i]
        if (-not $per.ContainsKey($e.Host)) { $per[$e.Host] = @{ Items = @(); TimeoutSec = $timeout } }
        $per[$e.Host].Items += @{ Id = $e.Id; Name = $e.Name; Scope = $e.Scope; Hive = $e.Hive; Args = $Switches }
        $m.Data.UninstallRows[('{0}|{1}' -f $e.Host, $e.Id)] = $e.Row
        Set-RowState -Module $m -Row $e.Row -State 'Odinstalowywanie…' -Tone 'info'
    }
    $m.Data.UninstallResults = New-Object System.Collections.ArrayList
    $sb = New-ProgramScript $script:ProgramUninstallBody
    Start-HostOperation -Module $m -Name 'Odinstalowanie' -Targets @($per.Keys) -PerTarget $per -Output None -ScriptBlock $sb -OnResult {
        param($m, $r)
        if (-not $r.Ok) {
            foreach ($k in @($m.Data.UninstallRows.Keys | Where-Object { $_ -like "$($r.Target)|*" })) { Set-RowState -Module $m -Row $m.Data.UninstallRows[$k] -State ('Błąd połączenia: ' + ((@($r.Errors)) -join ' | ')) -Tone 'crit' }
            return
        }
        foreach ($d in @($r.Data)) {
            $row = $m.Data.UninstallRows[('{0}|{1}' -f $r.Target, $d.Id)]
            if ($row) { Set-RowState -Module $m -Row $row -State ([string]$d.Status) -Tone ([string]$d.Tone) }
            $level = @{ ok = 'OK'; info = 'INFO'; warn = 'WARN'; crit = 'ERROR' }[[string]$d.Tone]
            Write-Log ('[{0}] {1}: {2}{3}' -f $r.Target, $d.Name, $d.Status, $(if ($d.Detail) { " ($($d.Detail))" } else { '' })) $level
            [void]$m.Data.UninstallResults.Add([pscustomobject][ordered]@{ 'Komputer' = $r.Target; 'Program' = $d.Name; 'Wynik' = $d.Status; 'Kod wyjścia' = $d.Code; 'Czas (s)' = $d.Seconds; 'Szczegóły' = $d.Detail; '__tone' = $d.Tone })
        }
    } -OnComplete {
        param($m)
        $res = @($m.Data.UninstallResults)
        $bad = @($res | Where-Object { @('warn', 'crit') -contains $_.__tone }).Count
        if ($bad -gt 0) { Show-GridDialog -Title 'Wynik odinstalowania' -Subtitle "Nie wszystko się udało ($bad z $($res.Count)) – przyczyny w kolumnie «Wynik»." -Rows $res -PillColumns @('Wynik') }
        else { Show-Toast "Odinstalowano: $($res.Count)" 'ok' }
    }
}

Register-Module -Workspace 'Remote' -Category 'Oprogramowanie' -Key 'Programs' -Title 'Zainstalowane programy' -Icon 'E71D' `
    -Description 'Programy z rejestru (64/32-bit i profile zalogowanych użytkowników). Kolumna «Odinstalowanie zdalne» mówi, czy i jak program da się usunąć bez użytkownika (MSI, tryb cichy, Inno Setup, zadanie w sesji użytkownika); wynik i przyczyna niepowodzenia trafiają do kolumny «Stan».' -Build {
    param($m)
    $m.PillColumns = @('Odinstalowanie zdalne', 'Stan')
    $m.Data.UninstallRows = @{}
    $m.Data.UninstallResults = @()
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $sb = New-ProgramScript $script:ProgramListBody
        Start-HostOperation -Module $m -Name 'Programy' -Targets $targets -Parameters @{ Filter = $m.Filter.Text.Trim(); ShowSystem = (Test-Checked $m.ShowSystem) } -ScriptBlock $sb
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    Add-Label -Parent $row -Text 'Nazwa lub wydawca' | Out-Null
    $m.Filter = Add-TextBox -Parent $row -Width 200 -Placeholder 'np. Office'
    $m.ShowSystem = Add-CheckBox -Parent $row -Text 'Pokaż aktualizacje i składniki systemowe'
    Add-Button -Parent $row -Text 'Pokaż programy' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Odinstalowanie'
    Add-Button -Parent $row2 -Text 'Odinstaluj zaznaczone' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) Start-ProgramUninstall -Module $m -Rows $null } | Out-Null
    Add-Label -Parent $row2 -Text 'Limit czasu' | Out-Null
    $m.Timeout = Add-ComboBox -Parent $row2 -Items @($script:ExecTimeouts.Keys) -Width 120
    $m.Timeout.SelectedIndex = 2
    Add-Label -Parent $row2 -Text 'Zielone – usunie się po cichu; żółte – z zastrzeżeniem (przełączniki albo sesja użytkownika); czerwone – nie zdalnie (powód w «Stan» po próbie).' -Hint -MaxWidth 640 | Out-Null
    Add-RowAction -Module $m -Text 'Odinstaluj' -Icon 'E74D' -Danger -Action { param($m, $rows) Start-ProgramUninstall -Module $m -Rows $rows }
    Add-RowAction -Module $m -Text 'Odinstaluj z przełącznikami…' -Icon 'E74D' -Danger -Action {
        param($m, $rows)
        $switches = Show-InputDialog -Title 'Przełączniki deinstalatora' -Prompt 'Przełączniki cichego trybu z dokumentacji producenta, dopisywane do polecenia odinstalowania (np. /S – NSIS, /silent, /quiet /norestart, --uninstall --force-uninstall). Bez właściwych przełączników deinstalator zostanie zatrzymany po upływie limitu czasu.' -Default '/S' -Icon 'E74D' -Validate { param($t) if (-not $t.Trim()) { 'Podaj przełączniki.' } else { '' } }
        if (-not $switches) { return }
        Start-ProgramUninstall -Module $m -Rows $rows -Switches $switches.Trim()
    }
    Add-RowAction -Module $m -Text 'Pokaż ten program na wszystkich komputerach' -Icon 'E721' -Separator -Action {
        param($m, $rows)
        $name = [string](Get-ObjectValue $rows[0] 'Nazwa')
        if ($name) { $m.FilterBox.Text = $name }
    }
}

Register-Module -Workspace 'Remote' -Category 'Oprogramowanie' -Key 'WindowsUpdate' -Title 'Windows Update' -Icon 'E777' `
    -Description 'Dostępne aktualizacje, historia, sprawdzanie konkretnych poprawek KB oraz instalacja (zadanie SYSTEM na komputerze, log w %SystemRoot%\Temp\DomainOps\WU.log). Nie wymaga modułu PSWindowsUpdate.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Status', 'Stan')
    $row = Add-ToolbarRow -Module $m -Title 'Sprawdzenie'
    $m.Drivers = Add-CheckBox -Parent $row -Text 'Uwzględnij sterowniki'
    Add-Button -Parent $row -Text 'Wyszukaj dostępne' -Icon 'E721' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Wyszukiwanie aktualizacji' -Targets $targets -Parameters @{ IncludeDrivers = (Test-Checked $m.Drivers) } -ScriptBlock {
            param($P)
            $session = New-Object -ComObject Microsoft.Update.Session
            $criteria = "IsInstalled=0 and IsHidden=0"
            if (-not $P.IncludeDrivers) { $criteria += " and Type='Software'" }
            $result = $session.CreateUpdateSearcher().Search($criteria)
            if ($result.Updates.Count -eq 0) { return [pscustomobject]@{ 'Aktualizacja' = '(brak dostępnych aktualizacji)'; 'Stan' = 'Aktualny'; '__tone' = 'ok' } }
            foreach ($u in $result.Updates) {
                [pscustomobject]@{
                    'Aktualizacja'    = $u.Title
                    'Stan'            = 'Do instalacji'
                    'KB'              = (@($u.KBArticleIDs | ForEach-Object { "KB$_" }) -join ', ')
                    'Kategoria'       = (@($u.Categories | ForEach-Object { $_.Name }) -join ', ')
                    'Ważność'         = $u.MsrcSeverity
                    'Rozmiar (MB)'    = [Math]::Round([double]$u.MaxDownloadSize / 1MB, 1)
                    'Pobrana'         = [bool]$u.IsDownloaded
                    'Wymaga restartu' = ($u.InstallationBehavior.RebootBehavior -ne 0)
                    '__tone'          = $(if ($u.MsrcSeverity -eq 'Critical') { 'crit' } else { 'warn' })
                }
            }
        }
    } | Out-Null
    Add-Button -Parent $row -Text 'Historia (ostatnie 50)' -Icon 'E81C' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Historia aktualizacji' -Targets $targets -ScriptBlock {
            param($P)
            $searcher = (New-Object -ComObject Microsoft.Update.Session).CreateUpdateSearcher()
            $count = $searcher.GetTotalHistoryCount()
            if ($count -eq 0) { return [pscustomobject]@{ 'Aktualizacja' = '(historia jest pusta)' } }
            foreach ($h in $searcher.QueryHistory(0, [Math]::Min($count, 50))) {
                if (-not $h.Title) { continue }
                $status = switch ([int]$h.ResultCode) { 1 { 'W toku' } 2 { 'Sukces' } 3 { 'Sukces z błędami' } 4 { 'Błąd' } 5 { 'Przerwano' } default { 'Nieznany' } }
                $operation = switch ([int]$h.Operation) { 1 { 'Instalacja' } 2 { 'Odinstalowanie' } default { '' } }
                [pscustomobject]@{
                    'Data'         = $h.Date.ToLocalTime()
                    'Aktualizacja' = $h.Title
                    'Operacja'     = $operation
                    'Status'       = $status
                    'Kod HRESULT'  = $(if ($h.HResult) { '0x{0:X8}' -f $h.HResult } else { '' })
                    '__tone'       = $(switch ([int]$h.ResultCode) { 2 { 'ok' } 3 { 'warn' } 4 { 'crit' } 5 { 'warn' } default { 'info' } })
                }
            }
        }
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Poprawki KB'
    $m.Kb = Add-TextBox -Parent $row2 -Width 300 -Placeholder 'np. KB5034441, KB5005565'
    Add-Button -Parent $row2 -Text 'Sprawdź obecność' -Icon 'E73E' -Module $m -OnClick {
        param($m)
        $kbs = @(Split-ListText ($m.Kb.Text -replace '\s+', ',') | ForEach-Object { $_.ToUpperInvariant() -replace '^(KB)?(\d+)$', 'KB$2' } | Where-Object { $_ -match '^KB\d+$' } | Select-Object -Unique)
        if ($kbs.Count -eq 0) { Show-Warning 'Podaj numery poprawek, np. KB5034441.'; return }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Sprawdzanie KB' -Targets $targets -Parameters @{ Kbs = $kbs } -ScriptBlock {
            param($P)
            $hotfixes = @{}
            foreach ($h in @(Get-CimInstance -ClassName Win32_QuickFixEngineering -ErrorAction SilentlyContinue)) { $hotfixes[[string]$h.HotFixID] = $h }
            $history = @()
            try {
                $searcher = (New-Object -ComObject Microsoft.Update.Session).CreateUpdateSearcher()
                $count = $searcher.GetTotalHistoryCount()
                if ($count -gt 0) { $history = @($searcher.QueryHistory(0, [Math]::Min($count, 500)) | Where-Object { $_.Title -and $_.ResultCode -eq 2 -and $_.Operation -eq 1 }) }
            }
            catch { }
            $os = Get-CimInstance -ClassName Win32_OperatingSystem
            foreach ($kb in $P.Kbs) {
                $found = $hotfixes[$kb]
                $wu = @($history | Where-Object { $_.Title -like "*$kb*" } | Select-Object -First 1)
                $installed = ($null -ne $found -or $wu.Count -gt 0)
                $date = $null
                if ($found -and $found.InstalledOn) { $date = $found.InstalledOn } elseif ($wu.Count -gt 0) { $date = $wu[0].Date.ToLocalTime() }
                [pscustomobject]@{
                    'KB'              = $kb
                    'Stan'            = $(if ($installed) { 'Zainstalowana' } else { 'Brak' })
                    'Data instalacji' = $date
                    'Źródło'          = $(if ($found) { 'Win32_QuickFixEngineering' } elseif ($wu.Count -gt 0) { 'Historia Windows Update' } else { '' })
                    'Opis'            = $(if ($found) { $found.Description } elseif ($wu.Count -gt 0) { $wu[0].Title } else { '' })
                    'System'          = '{0} ({1})' -f $os.Caption, $os.BuildNumber
                    '__tone'          = $(if ($installed) { 'ok' } else { 'crit' })
                }
            }
        }
    } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Instalacja'
    $m.AutoReboot = Add-CheckBox -Parent $row3 -Text 'Automatyczny restart po instalacji (za 5 min), jeśli wymagany'
    Add-Button -Parent $row3 -Text 'Zainstaluj aktualizacje' -Icon 'E896' -Module $m -Danger -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $reboot = if (Test-Checked $m.AutoReboot) { 'z automatycznym restartem' } else { 'bez restartu' }
        $targets = @(Confirm-Action -Text "Zainstalować wszystkie dostępne aktualizacje ($reboot) na wybranych komputerach?" -Items $targets -ConfirmText 'Zainstaluj' -Select); if ($targets.Count -eq 0) { return }
        $params = @{ Script = $script:WuJobScript; AutoReboot = (Test-Checked $m.AutoReboot); IncludeDrivers = (Test-Checked $m.Drivers) }
        Start-HostOperation -Module $m -Name 'Instalacja aktualizacji' -Targets $targets -Output Log -Parameters $params -ScriptBlock {
            param($P)
            $dir = Join-Path $env:SystemRoot 'Temp\DomainOps'
            if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
            $file = Join-Path $dir 'Invoke-DomainOpsWU.ps1'
            Set-Content -LiteralPath $file -Value $P.Script -Encoding UTF8
            $taskName = 'DomainOps-WindowsUpdate'
            $existing = Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
            if ($existing -and [string]$existing.State -eq 'Running') { return 'Instalacja już trwa (zadanie DomainOps-WindowsUpdate).' }
            $argLine = '-NoProfile -ExecutionPolicy Bypass -File "{0}"' -f $file
            if ($P.AutoReboot) { $argLine += ' -AutoReboot' }
            if ($P.IncludeDrivers) { $argLine += ' -IncludeDrivers' }
            $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $argLine
            $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Hours 4)
            Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Settings $settings -Force | Out-Null
            Start-ScheduledTask -TaskName $taskName
            'Zlecono instalację (zadanie SYSTEM). Postęp: przycisk «Stan instalacji».'
        }
    } | Out-Null
    Add-Button -Parent $row3 -Text 'Stan instalacji' -Icon 'E9D9' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Stan instalacji aktualizacji' -Targets $targets -ScriptBlock {
            param($P)
            $log = Join-Path $env:SystemRoot 'Temp\DomainOps\WU.log'
            $task = Get-ScheduledTask -TaskName 'DomainOps-WindowsUpdate' -ErrorAction SilentlyContinue
            $lines = @()
            if (Test-Path -LiteralPath $log) {
                $all = @(Get-Content -LiteralPath $log -Encoding UTF8)
                $start = 0
                for ($i = $all.Count - 1; $i -ge 0; $i--) { if ($all[$i] -like '*==== START ====*') { $start = $i; break } }
                $lines = @($all[$start..($all.Count - 1)])
            }
            $rebootRequired = $false
            try { $rebootRequired = [bool](New-Object -ComObject Microsoft.Update.SystemInfo).RebootRequired } catch { }
            $state = if ($task) { [string]$task.State } else { '(brak – instalacji nie zlecano)' }
            [pscustomobject]@{
                'Stan'            = $(if ($state -eq 'Running') { 'Trwa instalacja' } elseif ($lines.Count -and $lines[-1] -like '*KONIEC*') { 'Zakończono' } else { $state })
                'Ostatni wpis'    = $(if ($lines.Count) { $lines[-1] } else { '' })
                'Wymaga restartu' = $rebootRequired
                'Log'             = ($lines -join "`r`n")
                '__tone'          = $(if ($state -eq 'Running') { 'info' } elseif ($rebootRequired) { 'warn' } else { 'ok' })
            }
        }
    } | Out-Null
    $m.GoodWhenNo = @('Wymaga restartu')
}
#endregion

#region Zarządzanie zdalne: Bezpieczeństwo
Register-Module -Workspace 'Remote' -Category 'Bezpieczeństwo' -Key 'SecurityAudit' -Title 'Szybki audyt bezpieczeństwa' -Icon 'EA18' -Badge 'Nowość w wersji 4.0' `
    -Description 'Kilkanaście kontroli w jednym przebiegu: zapora, antywirus i sygnatury, BitLocker, SMBv1, NLA, UAC, LAPS, aktualizacje, Secure Boot, TPM, WDigest, ochrona LSA, LLMNR i konto Gość. Wynik procentowy dla każdego komputera.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Wynik')
    $row = Add-ToolbarRow -Module $m -Title 'Parametry'
    Add-Label -Parent $row -Text 'Aktualizacje nie starsze niż (dni)' | Out-Null
    $m.UpdateDays = Add-Numeric -Parent $row -Value 45 -Minimum 7 -Maximum 365 -Width 60
    Add-Label -Parent $row -Text 'Sygnatury AV (dni)' | Out-Null
    $m.SigDays = Add-Numeric -Parent $row -Value 3 -Minimum 1 -Maximum 60 -Width 60
    Add-Button -Parent $row -Text 'Uruchom audyt' -Icon 'EA18' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Reset-StatTiles $m
        Start-HostOperation -Module $m -Name 'Audyt bezpieczeństwa' -Targets $targets -Parameters @{ UpdateDays = (Get-Num $m.UpdateDays); SigDays = (Get-Num $m.SigDays) } -ScriptBlock {
            param($P)
            $r = [ordered]@{}
            $problems = New-Object System.Collections.ArrayList
            $check = {
                param([string]$Name, $Value, [string]$Problem)
                $r[$Name] = $Value
                if ($Value -eq $false -and $Problem) { [void]$problems.Add($Problem) }
            }
            $isServer = ((Get-CimInstance -ClassName Win32_OperatingSystem).ProductType -ne 1)
            # Zapora
            $fw = $null
            try { $fw = (@(Get-NetFirewallProfile -ErrorAction Stop | Where-Object { [string]$_.Enabled -ne 'True' }).Count -eq 0) } catch { }
            & $check 'Zapora włączona' $fw 'zapora wyłączona w co najmniej jednym profilu'
            # Antywirus
            $av = $null
            $sigOk = $null
            try {
                $mp = Get-MpComputerStatus -ErrorAction Stop
                $av = [bool]($mp.AntivirusEnabled -and $mp.RealTimeProtectionEnabled)
                $sigOk = ([int]$mp.AntivirusSignatureAge -le [int]$P.SigDays)
            }
            catch {
                if (-not $isServer) {
                    try {
                        $products = @(Get-CimInstance -Namespace 'root\SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)
                        # productState: bajt 2 = 0x10 -> ochrona włączona, bajt 3 = 0x00 -> sygnatury aktualne
                        $active = @($products | Where-Object { (([int]$_.productState -shr 8) -band 0xFF) -band 0x10 })
                        $av = ($active.Count -gt 0)
                        if ($av) { $sigOk = (@($active | Where-Object { ([int]$_.productState -band 0xFF) -eq 0 }).Count -gt 0) }
                    }
                    catch { }
                }
            }
            & $check 'Antywirus aktywny' $av 'antywirus wyłączony lub nieobecny'
            & $check 'Sygnatury aktualne' $sigOk 'nieaktualne sygnatury antywirusa'
            # BitLocker na dysku systemowym
            $bl = $null
            try {
                $vol = Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftVolumeEncryption' -ClassName Win32_EncryptableVolume -Filter ("DriveLetter='{0}'" -f $env:SystemDrive) -ErrorAction Stop
                if ($vol) { $bl = ([int]$vol.ProtectionStatus -eq 1) }
            }
            catch { }
            & $check 'BitLocker na systemowym' $bl 'dysk systemowy bez ochrony BitLocker'
            # SMBv1
            $smb1 = $null
            try { $smb1 = -not [bool](Get-SmbServerConfiguration -ErrorAction Stop).EnableSMB1Protocol } catch { }
            & $check 'SMBv1 wyłączony' $smb1 'włączony protokół SMBv1'
            # RDP + NLA
            $ts = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction SilentlyContinue
            $rdpOn = ($ts -and [int]$ts.fDenyTSConnections -eq 0)
            $nla = $null
            if ($rdpOn) { $nla = ([int](Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction SilentlyContinue).UserAuthentication -eq 1) }
            $r['RDP włączony'] = $rdpOn
            & $check 'NLA dla RDP' $nla 'pulpit zdalny bez NLA'
            # UAC
            $lua = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction SilentlyContinue).EnableLUA
            & $check 'UAC włączony' ($null -eq $lua -or [int]$lua -eq 1) 'kontrola konta użytkownika (UAC) wyłączona'
            # LAPS (Windows LAPS albo LAPS legacy)
            $laps = $false
            if (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\LAPS' -ErrorAction SilentlyContinue) { $laps = $true }
            if (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Policies\LAPS' -ErrorAction SilentlyContinue) { $laps = $true }
            $legacy = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft Services\AdmPwd' -ErrorAction SilentlyContinue
            if ($legacy -and [int]$legacy.AdmPwdEnabled -eq 1) { $laps = $true }
            if ((Get-CimInstance -ClassName Win32_ComputerSystem).DomainRole -ge 4) { $laps = $null }
            & $check 'LAPS skonfigurowany' $laps 'brak konfiguracji LAPS'
            # Aktualizacje
            $last = $null
            try { $last = @(Get-HotFix -ErrorAction Stop | Where-Object { $_.InstalledOn } | Sort-Object InstalledOn -Descending)[0].InstalledOn } catch { }
            $r['Ostatnia poprawka'] = $last
            & $check 'Aktualizacje świeże' $(if ($last) { ((Get-Date) - $last).TotalDays -le [int]$P.UpdateDays } else { $null }) "brak poprawek z ostatnich $($P.UpdateDays) dni"
            # Oczekujący restart
            $pending = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
            & $check 'Bez oczekującego restartu' (-not $pending) 'oczekuje na restart'
            # Secure Boot i TPM
            $sb = $null
            try { $sb = [bool](Confirm-SecureBootUEFI -ErrorAction Stop) } catch { }
            & $check 'Secure Boot' $sb 'Secure Boot wyłączony'
            $tpm = $null
            try {
                $t = Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftTpm' -ClassName Win32_Tpm -ErrorAction Stop
                $tpm = [bool]($t -and $t.IsEnabled_InitialValue -and $t.IsActivated_InitialValue)
            }
            catch { }
            & $check 'TPM aktywny' $tpm 'brak aktywnego modułu TPM'
            # WDigest, LSA, LLMNR
            $wd = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest' -ErrorAction SilentlyContinue).UseLogonCredential
            & $check 'WDigest wyłączony' ($null -eq $wd -or [int]$wd -eq 0) 'WDigest przechowuje hasła w pamięci'
            $ppl = (Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -ErrorAction SilentlyContinue).RunAsPPL
            & $check 'Ochrona LSA' ($null -ne $ppl -and [int]$ppl -ge 1) 'brak ochrony procesu LSA (RunAsPPL)'
            $llmnr = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -ErrorAction SilentlyContinue).EnableMulticast
            & $check 'LLMNR wyłączony' ($null -ne $llmnr -and [int]$llmnr -eq 0) 'włączony LLMNR'
            # Konta lokalne
            $guest = $null
            $admins = $null
            try {
                $g = @(Get-LocalUser -ErrorAction Stop | Where-Object { [string]$_.SID -match '-501$' })
                if ($g.Count) { $guest = -not $g[0].Enabled }
                $admins = @(Get-LocalGroupMember -SID 'S-1-5-32-544' -ErrorAction Stop).Count
            }
            catch { }
            & $check 'Konto Gość wyłączone' $guest 'włączone konto Gość'
            $r['Administratorzy lokalni'] = $admins
            # Ocena: odsetek spełnionych kontroli (pomijamy niedostępne)
            $evaluated = @($r.Keys | Where-Object { $r[$_] -is [bool] -and $_ -ne 'RDP włączony' })
            $passed = @($evaluated | Where-Object { $r[$_] -eq $true }).Count
            $score = if ($evaluated.Count) { [int][Math]::Round($passed / $evaluated.Count * 100) } else { 0 }
            $result = [ordered]@{
                'Wynik'    = '{0}% ({1}/{2})' -f $score, $passed, $evaluated.Count
                'Problemy' = (@($problems) -join '; ')
            }
            foreach ($k in $r.Keys) { $result[$k] = $r[$k] }
            $result['__tone'] = if ($score -ge 85) { 'ok' } elseif ($score -ge 60) { 'warn' } else { 'crit' }
            $result['__score'] = $score
            [pscustomobject]$result
        } -OnComplete {
            param($m)
            $rows = @($m.Table.Rows | Where-Object { $m.Table.Columns.Contains('__score') -and $_['__score'] -isnot [System.DBNull] })
            if ($rows.Count -eq 0) { return }
            $sum = 0
            foreach ($r in $rows) { $sum += [int]$r['__score'] }
            $avg = [int][Math]::Round($sum / $rows.Count)
            Set-StatTile -Module $m -Key 'avg' -Value "$avg%" -Tone $(if ($avg -ge 85) { 'ok' } elseif ($avg -ge 60) { 'warn' } else { 'crit' })
            Set-StatTile -Module $m -Key 'good' -Value ([string]@($rows | Where-Object { [int]$_['__score'] -ge 85 }).Count) -Tone 'ok'
            $bad = @($rows | Where-Object { [int]$_['__score'] -lt 60 }).Count
            Set-StatTile -Module $m -Key 'bad' -Value ([string]$bad) -Tone $(if ($bad) { 'crit' } else { '' })
        }
    } | Out-Null
    Add-StatTile -Module $m -Key 'avg' -Label 'Średni wynik' -Icon 'EA18' | Out-Null
    Add-StatTile -Module $m -Key 'good' -Label 'Komputery ≥ 85%' -Icon 'E73E' | Out-Null
    Add-StatTile -Module $m -Key 'bad' -Label 'Komputery < 60%' -Icon 'E7BA' | Out-Null
    $m.ResultHint = 'Puste pole = kontrola niedostępna na tym komputerze'
}

Register-Module -Workspace 'Remote' -Category 'Bezpieczeństwo' -Key 'Defender' -Title 'Microsoft Defender' -Icon 'E83D' `
    -Description 'Stan ochrony i sygnatur, wykryte zagrożenia, aktualizacja sygnatur oraz skanowanie (skan trwa w tle – można pracować dalej).' -Build {
    param($m)
    $m.ColorBools = $true
    $row = Add-ToolbarRow -Module $m -Title 'Stan'
    Add-Button -Parent $row -Text 'Stan ochrony' -Icon 'E83D' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Defender – stan' -Targets $targets -ScriptBlock {
            param($P)
            if (-not (Get-Command Get-MpComputerStatus -ErrorAction SilentlyContinue)) { throw 'Brak modułu Defender (Get-MpComputerStatus) na komputerze.' }
            $s = Get-MpComputerStatus -ErrorAction Stop
            [pscustomobject]@{
                'Antywirus'                 = $s.AntivirusEnabled
                'Ochrona w czasie rzecz.'   = $s.RealTimeProtectionEnabled
                'Ochrona przed naruszeniem' = $s.IsTamperProtected
                'Tryb'                      = $s.AMRunningMode
                'Wersja sygnatur'           = $s.AntivirusSignatureVersion
                'Sygnatury z dnia'          = $s.AntivirusSignatureLastUpdated
                'Wiek sygnatur (dni)'       = $s.AntivirusSignatureAge
                'Ostatni szybki skan'       = $s.QuickScanEndTime
                'Ostatni pełny skan'        = $s.FullScanEndTime
                'Wersja silnika'            = $s.AMEngineVersion
                '__flag'                    = $(if (-not $s.RealTimeProtectionEnabled -or $s.AntivirusSignatureAge -gt 3) { 'warn' } else { '' })
            }
        }
    } | Out-Null
    Add-Button -Parent $row -Text 'Wykryte zagrożenia' -Icon 'E7BA' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Defender – zagrożenia' -Targets $targets -ScriptBlock {
            param($P)
            if (-not (Get-Command Get-MpThreatDetection -ErrorAction SilentlyContinue)) { throw 'Brak modułu Defender na komputerze.' }
            $names = @{}
            foreach ($t in @(Get-MpThreat -ErrorAction SilentlyContinue)) { $names[[string]$t.ThreatID] = $t.ThreatName }
            $detections = @(Get-MpThreatDetection -ErrorAction SilentlyContinue)
            if ($detections.Count -eq 0) { return [pscustomobject]@{ 'Zagrożenie' = '(brak wykrytych zagrożeń)'; '__flag' = 'muted' } }
            foreach ($d in $detections) {
                [pscustomobject]@{
                    'Wykryto'     = $d.InitialDetectionTime
                    'Zagrożenie'  = $names[[string]$d.ThreatID]
                    'Zasoby'      = (@($d.Resources) -join '; ')
                    'Akcja udana' = $d.ActionSuccess
                    'Proces'      = $d.ProcessName
                    'Użytkownik'  = $d.DomainUser
                    '__flag'      = 'crit'
                }
            }
        }
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Akcje'
    $defAction = {
        param($m, $s)
        $op = [string]$s.Tag
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $label = @{ Update = 'Zaktualizować sygnatury'; QuickScan = 'Uruchomić szybkie skanowanie'; FullScan = 'Uruchomić PEŁNE skanowanie (może trwać godzinami i obciąża dysk)' }[$op]
        $targets = @(Confirm-Action -Text "$label na wybranych komputerach?" -Items $targets -ConfirmText 'Wykonaj' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name "Defender – $op" -Targets $targets -Output Log -Parameters @{ Op = $op } -ScriptBlock {
            param($P)
            if (-not (Get-Command Start-MpScan -ErrorAction SilentlyContinue)) { throw 'Brak modułu Defender na komputerze.' }
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            switch ($P.Op) {
                'Update' { Update-MpSignature -ErrorAction Stop; $v = (Get-MpComputerStatus).AntivirusSignatureVersion; "Sygnatury zaktualizowane (wersja $v)." }
                'QuickScan' { Start-MpScan -ScanType QuickScan -ErrorAction Stop; "Szybkie skanowanie zakończone ($([Math]::Round($sw.Elapsed.TotalMinutes, 1)) min)." }
                'FullScan' { Start-MpScan -ScanType FullScan -ErrorAction Stop; "Pełne skanowanie zakończone ($([Math]::Round($sw.Elapsed.TotalMinutes, 1)) min)." }
            }
        }
    }
    foreach ($a in @(@('Aktualizuj sygnatury', 'Update', 'E895'), @('Szybki skan', 'QuickScan', 'E721'), @('Pełny skan', 'FullScan', 'E9D9'))) {
        $b = Add-Button -Parent $row2 -Text $a[0] -Icon $a[2] -Module $m -OnClick $defAction
        $b.Tag = $a[1]
    }
}

Register-Module -Workspace 'Remote' -Category 'Bezpieczeństwo' -Key 'BitLocker' -Title 'BitLocker' -Icon 'E72E' `
    -Description 'Stan szyfrowania woluminów i kopia zapasowa kluczy odzyskiwania do AD. Klucze zapisane w AD: przestrzeń «Komputery AD».' -Build {
    param($m)
    $m.PillColumns = @('Ochrona')
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Stan woluminów' -Icon 'E72E' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'BitLocker – stan' -Targets $targets -ScriptBlock {
            param($P)
            if (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue) {
                foreach ($v in @(Get-BitLockerVolume -ErrorAction Stop)) {
                    $prot = [string]$v.ProtectionStatus
                    [pscustomobject]@{
                        'Wolumin'          = $v.MountPoint
                        'Ochrona'          = $(if ($prot -eq 'On') { 'Włączona' } elseif ($prot -eq 'Off') { 'Wyłączona' } else { $prot })
                        'Typ'              = [string]$v.VolumeType
                        'Stan'             = [string]$v.VolumeStatus
                        'Zaszyfrowano (%)' = $v.EncryptionPercentage
                        'Metoda'           = [string]$v.EncryptionMethod
                        'Blokada'          = [string]$v.LockStatus
                        'Zabezpieczenia'   = (@($v.KeyProtector | ForEach-Object { [string]$_.KeyProtectorType }) -join ', ')
                        '__tone'           = $(if ($prot -eq 'On') { 'ok' } elseif ([string]$v.VolumeType -eq 'OperatingSystem') { 'crit' } else { 'warn' })
                    }
                }
                return
            }
            # Starsze systemy / brak modułu: klasa WMI (niezależna od języka systemu)
            $conversion = @{ 0 = 'Odszyfrowany'; 1 = 'Zaszyfrowany'; 2 = 'Szyfrowanie w toku'; 3 = 'Odszyfrowywanie w toku'; 4 = 'Szyfrowanie wstrzymane'; 5 = 'Odszyfrowywanie wstrzymane' }
            $volumes = @(Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftVolumeEncryption' -ClassName Win32_EncryptableVolume -ErrorAction Stop)
            foreach ($v in $volumes) {
                $status = Invoke-CimMethod -InputObject $v -MethodName GetConversionStatus -ErrorAction SilentlyContinue
                $on = ([int]$v.ProtectionStatus -eq 1)
                [pscustomobject]@{
                    'Wolumin'          = $v.DriveLetter
                    'Ochrona'          = $(if ($on) { 'Włączona' } else { 'Wyłączona' })
                    'Stan'             = $(if ($status) { $conversion[[int]$status.ConversionStatus] } else { '' })
                    'Zaszyfrowano (%)' = $(if ($status) { $status.EncryptionPercentage } else { $null })
                    '__tone'           = $(if ($on) { 'ok' } else { 'warn' })
                }
            }
        }
    } | Out-Null
    Add-Button -Parent $row -Text 'Kopia kluczy do AD' -Icon 'E74E' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $targets = @(Confirm-Action -Text "Zapisać w AD klucze odzyskiwania BitLocker (wszystkie woluminy) z wybranych komputerów?" -Items $targets -ConfirmText 'Zapisz w AD' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name 'BitLocker – kopia do AD' -Targets $targets -Output Log -ScriptBlock {
            param($P)
            if (Get-Command Backup-BitLockerKeyProtector -ErrorAction SilentlyContinue) {
                $found = $false
                foreach ($v in @(Get-BitLockerVolume -ErrorAction Stop)) {
                    foreach ($kp in @($v.KeyProtector | Where-Object { [string]$_.KeyProtectorType -eq 'RecoveryPassword' })) {
                        $found = $true
                        try {
                            Backup-BitLockerKeyProtector -MountPoint $v.MountPoint -KeyProtectorId $kp.KeyProtectorId -ErrorAction Stop | Out-Null
                            [pscustomobject]@{ 'Wolumin' = $v.MountPoint; 'Klucz' = $kp.KeyProtectorId; 'Wynik' = 'Zapisano w AD' }
                        }
                        catch { [pscustomobject]@{ 'Wolumin' = $v.MountPoint; 'Klucz' = $kp.KeyProtectorId; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
                    }
                }
                if (-not $found) { 'Brak zabezpieczeń typu hasło odzyskiwania (RecoveryPassword) – nie ma czego zapisać.' }
                return
            }
            $bde = Join-Path $env:SystemRoot 'System32\manage-bde.exe'
            if (-not (Test-Path -LiteralPath $bde)) { throw 'Brak Get-BitLockerVolume i manage-bde.exe na komputerze.' }
            $volumes = @(Get-CimInstance -Namespace 'root\cimv2\Security\MicrosoftVolumeEncryption' -ClassName Win32_EncryptableVolume -ErrorAction Stop | Where-Object { $_.DriveLetter })
            foreach ($v in $volumes) {
                $text = (& $bde -protectors -get $v.DriveLetter -Type RecoveryPassword 2>&1) -join "`n"
                $ids = @([regex]::Matches($text, '\{[0-9A-Fa-f-]{36}\}') | ForEach-Object { $_.Value } | Select-Object -Unique)
                foreach ($id in $ids) {
                    $out = & $bde -protectors -adbackup $v.DriveLetter -id $id 2>&1
                    $res = if ($LASTEXITCODE -eq 0) { 'Zapisano w AD' } else { "Błąd – $(($out | Out-String).Trim())" }
                    [pscustomobject]@{ 'Wolumin' = $v.DriveLetter; 'Klucz' = $id; 'Wynik' = $res }
                }
            }
        }
    } | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'Bezpieczeństwo' -Key 'Firewall' -Title 'Zapora Windows' -Icon 'E785' `
    -Description 'Stan profili zapory, reguły (z portami i programami), włączanie, wyłączanie i usuwanie zaznaczonych reguł oraz tworzenie nowych.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $params = @{ Direction = @('Inbound', 'Outbound')[$m.Direction.SelectedIndex]; EnabledOnly = (Test-Checked $m.EnabledOnly); Filter = $m.Filter.Text.Trim() }
        Start-HostOperation -Module $m -Name 'Reguły zapory' -Targets $targets -Parameters $params -ScriptBlock {
            param($P)
            $rules = @(Get-NetFirewallRule -Direction $P.Direction -ErrorAction Stop)
            if ($P.EnabledOnly) { $rules = @($rules | Where-Object { [string]$_.Enabled -eq 'True' }) }
            if ($P.Filter) {
                $f = "*$($P.Filter)*"
                $rules = @($rules | Where-Object { $_.DisplayName -like $f -or $_.Name -like $f -or $_.DisplayGroup -like $f })
            }
            if ($rules.Count -eq 0) { return }
            # Filtry pobierane hurtowo i łączone po InstanceID - zapytanie per reguła trwałoby minutami
            $ports = @{}
            foreach ($pf in @(Get-NetFirewallPortFilter -ErrorAction SilentlyContinue)) { $ports[$pf.InstanceID] = $pf }
            $apps = @{}
            foreach ($af in @(Get-NetFirewallApplicationFilter -ErrorAction SilentlyContinue)) { $apps[$af.InstanceID] = $af }
            $addresses = @{}
            foreach ($ad in @(Get-NetFirewallAddressFilter -ErrorAction SilentlyContinue)) { $addresses[$ad.InstanceID] = $ad }
            foreach ($r in $rules) {
                $pf = $ports[$r.InstanceID]
                $af = $apps[$r.InstanceID]
                $adf = $addresses[$r.InstanceID]
                [pscustomobject]@{
                    'Nazwa wyświetlana' = $r.DisplayName
                    'Włączona'          = ([string]$r.Enabled -eq 'True')
                    'Akcja'             = [string]$r.Action
                    'Profil'            = [string]$r.Profile
                    'Protokół'          = $(if ($pf) { [string]$pf.Protocol } else { '' })
                    'Port lokalny'      = $(if ($pf) { @($pf.LocalPort) -join ',' } else { '' })
                    'Port zdalny'       = $(if ($pf) { @($pf.RemotePort) -join ',' } else { '' })
                    'Adres zdalny'      = $(if ($adf) { @($adf.RemoteAddress) -join ',' } else { '' })
                    'Program'           = $(if ($af) { $af.Program } else { '' })
                    'Grupa'             = $r.DisplayGroup
                    'ID reguły'         = $r.Name
                    '__flag'            = $(if ([string]$r.Enabled -ne 'True') { 'muted' } elseif ([string]$r.Action -eq 'Block') { 'warn' } else { '' })
                }
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('ID reguły', 'Nazwa wyświetlana') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli reguły zapory (widok «Pokaż reguły»).'; return }
        $label = @{ Enable = 'Włączyć'; Disable = 'Wyłączyć'; Delete = 'Usunąć' }[$Op]
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Nazwa wyświetlana'] }
        if (-not (Confirm-Action -Text "$label wybrane reguły zapory?" -Items $items -ConfirmText $(if ($Op -eq 'Delete') { 'Usuń reguły' } else { 'Wykonaj' }) -Danger:($Op -ne 'Enable'))) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Op = $Op; Names = @($byHost[$h] | ForEach-Object { [string]$_['ID reguły'] }) } }
        Start-HostOperation -Module $m -Name "Zapora – $Op" -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($name in $P.Names) {
                try {
                    switch ($P.Op) {
                        'Enable' { Enable-NetFirewallRule -Name $name -ErrorAction Stop }
                        'Disable' { Disable-NetFirewallRule -Name $name -ErrorAction Stop }
                        'Delete' { Remove-NetFirewallRule -Name $name -ErrorAction Stop }
                    }
                    [pscustomobject]@{ 'Reguła' = $name; 'Operacja' = $P.Op; 'Wynik' = 'OK' }
                }
                catch { [pscustomobject]@{ 'Reguła' = $name; 'Operacja' = $P.Op; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Profile'
    Add-Button -Parent $row -Text 'Stan profili zapory' -Icon 'E785' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Profile zapory' -Targets $targets -ScriptBlock {
            param($P)
            Get-NetFirewallProfile -ErrorAction Stop | ForEach-Object {
                [pscustomobject]@{
                    'Profil'               = $_.Name
                    'Włączony'             = ([string]$_.Enabled -eq 'True')
                    'Ruch przychodzący'    = [string]$_.DefaultInboundAction
                    'Ruch wychodzący'      = [string]$_.DefaultOutboundAction
                    'Rejestrowanie blokad' = [string]$_.LogBlocked
                }
            }
        }
    } | Out-Null
    $row1 = Add-ToolbarRow -Module $m -Title 'Reguły'
    $m.Direction = Add-ComboBox -Parent $row1 -Items @('Przychodzące', 'Wychodzące') -Width 150
    $m.EnabledOnly = Add-CheckBox -Parent $row1 -Text 'Tylko włączone' -Checked $true
    $m.Filter = Add-TextBox -Parent $row1 -Width 180 -Placeholder 'nazwa, grupa lub ID'
    Add-Button -Parent $row1 -Text 'Pokaż reguły' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Zaznaczone reguły'
    foreach ($a in @(@('Włącz', 'Enable', 'E73E'), @('Wyłącz', 'Disable', 'E8D8'))) {
        $b = Add-Button -Parent $row2 -Text $a[0] -Icon $a[2] -Module $m -OnClick { param($m, $s) & $m.Actions.Change $m ([string]$s.Tag) $null }
        $b.Tag = $a[1]
    }
    Add-Button -Parent $row2 -Text 'Usuń' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Delete' $null } | Out-Null
    Add-RowAction -Module $m -Text 'Włącz regułę' -Icon 'E73E' -Action { param($m, $rows) & $m.Actions.Change $m 'Enable' $rows }
    Add-RowAction -Module $m -Text 'Wyłącz regułę' -Icon 'E8D8' -Action { param($m, $rows) & $m.Actions.Change $m 'Disable' $rows }
    Add-RowAction -Module $m -Text 'Usuń regułę' -Icon 'E74D' -Danger -Separator -Action { param($m, $rows) & $m.Actions.Change $m 'Delete' $rows }

    $row3 = Add-ToolbarRow -Module $m -Title 'Nowa reguła'
    $m.NewName = Add-TextBox -Parent $row3 -Width 200 -Text 'Domain Ops – nowa reguła'
    $m.NewDirection = Add-ComboBox -Parent $row3 -Items @('Przychodząca', 'Wychodząca') -Width 140
    $m.NewAction = Add-ComboBox -Parent $row3 -Items @('Zezwalaj', 'Blokuj') -Width 110
    $m.NewProtocol = Add-ComboBox -Parent $row3 -Items @('TCP', 'UDP') -Width 80
    $m.NewPorts = Add-TextBox -Parent $row3 -Width 120 -Text '5985' -Placeholder 'porty'
    $m.NewProfile = Add-ComboBox -Parent $row3 -Items @('Wszystkie profile', 'Domena', 'Prywatny', 'Publiczny') -Width 160
    $m.NewRemote = Add-TextBox -Parent $row3 -Width 140 -Text 'Any' -Placeholder 'adres zdalny'
    Add-Button -Parent $row3 -Text 'Utwórz' -Icon 'E710' -Module $m -OnClick {
        param($m)
        $name = $m.NewName.Text.Trim()
        $ports = @(Split-ListText $m.NewPorts.Text)
        if (-not $name) { Show-Warning 'Podaj nazwę reguły.'; return }
        if ($ports.Count -eq 0 -or @($ports | Where-Object { $_ -notmatch '^\d{1,5}(-\d{1,5})?$' }).Count -gt 0) { Show-Warning 'Podaj porty jako liczby lub zakresy, np. 80, 443, 8000-8010.'; return }
        $remote = @(Split-ListText $m.NewRemote.Text)
        if ($remote.Count -eq 0) { $remote = @('Any') }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $params = @{
            DisplayName   = $name
            Direction     = @('Inbound', 'Outbound')[$m.NewDirection.SelectedIndex]
            Action        = @('Allow', 'Block')[$m.NewAction.SelectedIndex]
            Protocol      = [string]$m.NewProtocol.SelectedItem
            Ports         = $ports
            Profile       = @('Any', 'Domain', 'Private', 'Public')[$m.NewProfile.SelectedIndex]
            RemoteAddress = $remote
        }
        $targets = @(Confirm-Action -Text ("Utworzyć regułę «{0}» ({1}, {2}, {3}/{4})?" -f $name, $m.NewDirection.SelectedItem, $m.NewAction.SelectedItem, $params.Protocol, ($ports -join ',')) -Items $targets -ConfirmText 'Utwórz' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name 'Nowa reguła zapory' -Targets $targets -Output Log -Parameters $params -ScriptBlock {
            param($P)
            $rp = @{
                DisplayName   = $P.DisplayName
                Group         = 'Domain Ops'
                Direction     = $P.Direction
                Action        = $P.Action
                Protocol      = $P.Protocol
                LocalPort     = [string[]]@($P.Ports)
                RemoteAddress = [string[]]@($P.RemoteAddress)
                Profile       = $P.Profile
                Enabled       = 'True'
                ErrorAction   = 'Stop'
            }
            $rule = New-NetFirewallRule @rp
            [pscustomobject]@{ 'Reguła' = $P.DisplayName; 'ID reguły' = $rule.Name; 'Wynik' = 'Utworzono (grupa «Domain Ops»)' }
        }
    } | Out-Null
}

Register-Module -Workspace 'Remote' -Category 'Bezpieczeństwo' -Key 'Certificates' -Title 'Certyfikaty komputera' -Icon 'EB95' `
    -Description 'Certyfikaty z magazynów LocalMachine, wyszukiwanie wygasających oraz eksport zaznaczonych do plików .cer.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Ważność')
    $row = Add-ToolbarRow -Module $m -Title 'Magazyn'
    $m.Store = Add-ComboBox -Parent $row -Items @('My', 'Root', 'CA', 'TrustedPublisher', 'TrustedPeople', 'WebHosting', 'Remote Desktop') -Width 170
    $m.Filter = Add-TextBox -Parent $row -Width 180 -Placeholder 'podmiot, wystawca, odcisk'
    $m.OnlyExpiring = Add-CheckBox -Parent $row -Text 'Tylko wygasające w ciągu (dni)'
    $m.Days = Add-Numeric -Parent $row -Value 30 -Minimum 1 -Maximum 3650 -Width 60
    $row2 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row2 -Text 'Pokaż certyfikaty' -Icon 'EB95' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $params = @{ Store = [string]$m.Store.SelectedItem; Filter = $m.Filter.Text.Trim(); ExpiringDays = $(if (Test-Checked $m.OnlyExpiring) { Get-Num $m.Days } else { 0 }) }
        Start-HostOperation -Module $m -Name 'Certyfikaty' -Targets $targets -Parameters $params -ScriptBlock {
            param($P)
            $now = Get-Date
            foreach ($c in @(Get-ChildItem -Path ('Cert:\LocalMachine\' + $P.Store) -ErrorAction Stop)) {
                if ($P.Filter) {
                    $f = "*$($P.Filter)*"
                    if ($c.Subject -notlike $f -and $c.Thumbprint -notlike $f -and $c.FriendlyName -notlike $f -and $c.Issuer -notlike $f) { continue }
                }
                $days = [int][Math]::Floor(($c.NotAfter - $now).TotalDays)
                if ($P.ExpiringDays -gt 0 -and $days -gt $P.ExpiringDays) { continue }
                [pscustomobject]@{
                    'Podmiot'            = $c.Subject
                    'Ważność'            = $(if ($days -lt 0) { 'Wygasł' } elseif ($days -le 30) { "Wygasa za $days dni" } else { 'Ważny' })
                    'Wystawca'           = $c.Issuer
                    'Ważny od'           = $c.NotBefore
                    'Ważny do'           = $c.NotAfter
                    'Dni do wygaśnięcia' = $days
                    'Klucz prywatny'     = $c.HasPrivateKey
                    'Przeznaczenie'      = (@($c.EnhancedKeyUsageList | ForEach-Object { $_.FriendlyName } | Where-Object { $_ }) -join ', ')
                    'Nazwa przyjazna'    = $c.FriendlyName
                    'Odcisk palca'       = $c.Thumbprint
                    'Magazyn'            = $P.Store
                    '__tone'             = $(if ($days -lt 0) { 'crit' } elseif ($days -le 30) { 'warn' } else { 'ok' })
                }
            }
        }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Eksportuj zaznaczone (.cer)…' -Icon 'EDE1' -Module $m -OnClick {
        param($m)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Odcisk palca', 'Magazyn')
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli certyfikaty do eksportu.'; return }
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = 'Folder docelowy dla plików .cer'
        if ($dlg.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $m.Data.ExportFolder = $dlg.SelectedPath
        $per = @{}
        foreach ($h in $byHost.Keys) {
            $per[$h] = @{ Items = @($byHost[$h] | ForEach-Object { @{ Thumbprint = [string]$_['Odcisk palca']; Store = [string]$_['Magazyn'] } }) }
        }
        Start-HostOperation -Module $m -Name 'Eksport certyfikatów' -Targets @($byHost.Keys) -PerTarget $per -Output None -ScriptBlock {
            param($P)
            foreach ($i in $P.Items) {
                $cert = Get-Item -Path ('Cert:\LocalMachine\{0}\{1}' -f $i.Store, $i.Thumbprint) -ErrorAction Stop
                [pscustomobject]@{ Thumbprint = $cert.Thumbprint; Base64 = [Convert]::ToBase64String($cert.RawData) }
            }
        } -OnResult {
            param($m, $r)
            foreach ($d in @($r.Data)) {
                $thumb = [string](Get-ObjectValue $d 'Thumbprint')
                $b64 = [string](Get-ObjectValue $d 'Base64')
                if (-not $thumb -or -not $b64) { continue }
                $file = Join-Path $m.Data.ExportFolder ('{0}_{1}.cer' -f $r.Target, $thumb)
                [System.IO.File]::WriteAllBytes($file, [Convert]::FromBase64String($b64))
                Write-Log ("[{0}] zapisano {1}" -f $r.Target, $file) 'OK'
            }
        }
    } | Out-Null
}
#endregion

#region Zarządzanie zdalne: Udostępnianie
Register-Module -Workspace 'Remote' -Category 'Udostępnianie' -Key 'Shares' -Title 'Udziały sieciowe' -Icon 'E72D' `
    -Description 'Udziały SMB na zaznaczonych komputerach: podgląd, uprawnienia, tworzenie (z uprawnieniami udziału i opcjonalnie NTFS) oraz usuwanie.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.GoodWhenNo = @('Administracyjny')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Udziały' -Targets $targets -Parameters @{ ShowSpecial = (Test-Checked $m.ShowSpecial) } -ScriptBlock {
            param($P)
            if (Get-Command Get-SmbShare -ErrorAction SilentlyContinue) {
                $shares = @(Get-SmbShare -ErrorAction Stop)
                if (-not $P.ShowSpecial) { $shares = @($shares | Where-Object { -not $_.Special }) }
                foreach ($s in $shares) {
                    [pscustomobject]@{ 'Udział' = $s.Name; 'Ścieżka' = $s.Path; 'Opis' = $s.Description; 'Administracyjny' = [bool]$s.Special; 'Połączenia' = $s.CurrentUsers }
                }
            }
            else {
                foreach ($s in @(Get-CimInstance -ClassName Win32_Share)) {
                    $special = ([int64]$s.Type -ge 2147483648)
                    if ($special -and -not $P.ShowSpecial) { continue }
                    [pscustomobject]@{ 'Udział' = $s.Name; 'Ścieżka' = $s.Path; 'Opis' = $s.Description; 'Administracyjny' = $special }
                }
            }
        }
    }
    $m.Actions.Permissions = {
        param($m, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Udział') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli udziały.'; return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Names = @($byHost[$h] | ForEach-Object { [string]$_['Udział'] }) } }
        $m.Data.PermissionRows = New-Object System.Collections.ArrayList
        Start-HostOperation -Module $m -Name 'Uprawnienia udziałów' -Targets @($byHost.Keys) -PerTarget $per -Output None -ScriptBlock {
            param($P)
            foreach ($name in $P.Names) {
                Get-SmbShareAccess -Name $name -ErrorAction Stop | ForEach-Object {
                    [pscustomobject]@{ 'Udział' = $name; 'Konto' = $_.AccountName; 'Typ' = [string]$_.AccessControlType; 'Uprawnienie' = [string]$_.AccessRight }
                }
            }
        } -OnResult {
            param($m, $r)
            foreach ($d in @($r.Data)) {
                [void]$m.Data.PermissionRows.Add([pscustomobject]@{
                        'Komputer'    = $r.Target
                        'Udział'      = Get-ObjectValue $d 'Udział'
                        'Konto'       = Get-ObjectValue $d 'Konto'
                        'Typ'         = Get-ObjectValue $d 'Typ'
                        'Uprawnienie' = Get-ObjectValue $d 'Uprawnienie'
                    })
            }
        } -OnComplete {
            param($m)
            if ($m.Data.PermissionRows.Count -eq 0) { return }
            # Okno pokazujemy poza obsługą timera, żeby nie wstrzymywać innych trwających operacji
            Invoke-Deferred -Module $m -Action { param($m) Show-GridDialog -Title 'Uprawnienia udziałów' -Subtitle 'Uprawnienia na poziomie udziału (SMB)' -Rows @($m.Data.PermissionRows) }
        }
    }
    $m.Actions.Remove = {
        param($m, $Rows)
        $byHost = Get-SelectedRowsByHost -Module $m -Columns @('Udział') -Rows $Rows
        if ($byHost.Count -eq 0) { Show-Warning 'Zaznacz w tabeli udziały do usunięcia.'; return }
        $items = Get-HostItemList -ByHost $byHost -Format { param($i) $i['Udział'] }
        if (-not (Confirm-Action -Text 'Usunąć wybrane udziały? Dane w folderach pozostaną nienaruszone.' -Items $items -ConfirmText 'Usuń udziały' -Danger)) { return }
        $per = @{}
        foreach ($h in $byHost.Keys) { $per[$h] = @{ Names = @($byHost[$h] | ForEach-Object { [string]$_['Udział'] }) } }
        Start-HostOperation -Module $m -Name 'Usuwanie udziałów' -Targets @($byHost.Keys) -PerTarget $per -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            foreach ($name in $P.Names) {
                try {
                    if (@('ADMIN$', 'IPC$', 'PRINT$') -contains $name.ToUpperInvariant() -or $name -match '^[A-Za-z]\$$') { throw 'Pominięto udział administracyjny.' }
                    if (Get-Command Remove-SmbShare -ErrorAction SilentlyContinue) { Remove-SmbShare -Name $name -Force -ErrorAction Stop }
                    else {
                        $share = Get-CimInstance -ClassName Win32_Share -Filter ("Name = '{0}'" -f $name.Replace("'", "''"))
                        if (-not $share) { throw 'Nie znaleziono udziału.' }
                        $r = Invoke-CimMethod -InputObject $share -MethodName Delete
                        if ($r.ReturnValue -ne 0) { throw "Win32_Share.Delete zwrócił $($r.ReturnValue)." }
                    }
                    [pscustomobject]@{ 'Udział' = $name; 'Wynik' = 'Usunięto' }
                }
                catch { [pscustomobject]@{ 'Udział' = $name; 'Wynik' = "Błąd – $($_.Exception.Message)" } }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    $m.ShowSpecial = Add-CheckBox -Parent $row -Text 'Pokaż udziały administracyjne (C$, ADMIN$…)'
    Add-Button -Parent $row -Text 'Pokaż udziały' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Uprawnienia zaznaczonych' -Icon 'E8D7' -Module $m -OnClick { param($m) & $m.Actions.Permissions $m $null } | Out-Null
    Add-Button -Parent $row -Text 'Usuń zaznaczone' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Remove $m $null } | Out-Null
    Add-RowAction -Module $m -Text 'Uprawnienia udziału' -Icon 'E8D7' -Action { param($m, $rows) & $m.Actions.Permissions $m $rows }
    Add-RowAction -Module $m -Text 'Otwórz w Eksploratorze' -Icon 'E838' -Action {
        param($m, $rows)
        $computer = [string](Get-ObjectValue $rows[0] 'Komputer')
        $share = [string](Get-ObjectValue $rows[0] 'Udział')
        Start-Tool -FilePath 'explorer.exe' -Arguments @("\\$computer\$share") -Name $computer
    }
    Add-RowAction -Module $m -Text 'Usuń udział' -Icon 'E74D' -Danger -Separator -Action { param($m, $rows) & $m.Actions.Remove $m $rows }

    $row2 = Add-ToolbarRow -Module $m -Title 'Nowy udział'
    $m.NewName = Add-TextBox -Parent $row2 -Width 150 -Placeholder 'Nazwa udziału'
    $m.NewPath = Add-TextBox -Parent $row2 -Width 220 -Text 'D:\Udzial' -Placeholder 'Ścieżka na komputerze'
    $m.NewDesc = Add-TextBox -Parent $row2 -Width 200 -Placeholder 'Opis'
    $row3 = Add-ToolbarRow -Module $m -Title 'Uprawnienia'
    $m.NewFull = Add-TextBox -Parent $row3 -Width 170 -Placeholder 'Pełna kontrola'
    $m.NewChange = Add-TextBox -Parent $row3 -Width 170 -Placeholder 'Zmiana'
    $m.NewRead = Add-TextBox -Parent $row3 -Width 170 -Placeholder 'Odczyt'
    $m.NewNtfs = Add-CheckBox -Parent $row3 -Text 'Nadaj też NTFS'
    $m.NewCreate = Add-CheckBox -Parent $row3 -Text 'Utwórz folder' -Checked $true
    Add-Button -Parent $row3 -Text 'Utwórz' -Icon 'E710' -Module $m -OnClick {
        param($m)
        $name = $m.NewName.Text.Trim()
        $path = $m.NewPath.Text.Trim()
        if (-not $name -or -not $path) { Show-Warning 'Podaj nazwę udziału i ścieżkę folderu na komputerze.'; return }
        if ($path -notmatch '^[A-Za-z]:\\') { Show-Warning 'Ścieżka musi być lokalną ścieżką na komputerze, np. D:\Dane\Projekty.'; return }
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $params = @{
            Name = $name; Path = $path; Description = $m.NewDesc.Text.Trim()
            Full = @(Split-ListText $m.NewFull.Text); Change = @(Split-ListText $m.NewChange.Text); Read = @(Split-ListText $m.NewRead.Text)
            Ntfs = (Test-Checked $m.NewNtfs); CreateFolder = (Test-Checked $m.NewCreate)
        }
        $targets = @(Confirm-Action -Text ("Utworzyć udział {0} -> {1}?" -f $name, $path) -Items $targets -ConfirmText 'Utwórz' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name 'Tworzenie udziału' -Targets $targets -Output Log -Parameters $params -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            param($P)
            if (-not (Test-Path -LiteralPath $P.Path)) {
                if ($P.CreateFolder) { New-Item -ItemType Directory -Path $P.Path -Force | Out-Null }
                else { throw "Folder $($P.Path) nie istnieje." }
            }
            $full = @($P.Full | Where-Object { $_ })
            $change = @($P.Change | Where-Object { $_ })
            $read = @($P.Read | Where-Object { $_ })
            if (Get-Command New-SmbShare -ErrorAction SilentlyContinue) {
                $sp = @{ Name = $P.Name; Path = $P.Path; ErrorAction = 'Stop' }
                if ($P.Description) { $sp.Description = $P.Description }
                if ($full.Count) { $sp.FullAccess = [string[]]$full }
                if ($change.Count) { $sp.ChangeAccess = [string[]]$change }
                if ($read.Count) { $sp.ReadAccess = [string[]]$read }
                New-SmbShare @sp | Out-Null
            }
            else {
                $r = Invoke-CimMethod -ClassName Win32_Share -MethodName Create -Arguments @{ Path = $P.Path; Name = $P.Name; Type = [uint32]0; Description = [string]$P.Description }
                if ($r.ReturnValue -ne 0) { throw "Win32_Share.Create zwrócił $($r.ReturnValue)." }
            }
            $ntfs = ''
            if ($P.Ntfs) {
                $grants = @()
                foreach ($a in $full) { $grants += "${a}:(OI)(CI)F" }
                foreach ($a in $change) { $grants += "${a}:(OI)(CI)M" }
                foreach ($a in $read) { $grants += "${a}:(OI)(CI)RX" }
                foreach ($g in $grants) {
                    $out = & icacls.exe $P.Path /grant $g 2>&1
                    if ($LASTEXITCODE -ne 0) { throw "icacls $g : $(($out | Out-String).Trim())" }
                }
                if ($grants.Count) { $ntfs = ' + NTFS' }
            }
            [pscustomobject]@{ 'Udział' = $P.Name; 'Ścieżka' = $P.Path; 'Wynik' = "Utworzono$ntfs" }
        }
    } | Out-Null
}
#endregion

#region Zarządzanie zdalne: analiza wydajności (co obciąża komputer lub serwer)
# Pomiar na komputerze docelowym: kilka próbek surowych liczników wydajności (klasy Win32_PerfRawData_* - nazwy
# niezależne od języka systemu) w zadanym oknie czasu. Z różnic między próbkami liczone są prawdziwe średnie
# i wartości szczytowe (pojedynczy odczyt liczników sformatowanych bywa mylący, a opóźnienia dysku w klasach
# sformatowanych są zaokrąglane do pełnych sekund). Wynik to płaskie obiekty z polem __kind:
#   summary (jeden na komputer), proc (procesy z czołówki), disk (woluminy), nic (karty sieciowe), event (zdarzenia).
$script:PerfAnalysisScript = {
    param($P)
    $ErrorActionPreference = 'Stop'
    $state = @{ Missing = New-Object System.Collections.ArrayList }
    function Get-Raw([string]$Class, [string]$Filter = '') {
        try {
            if ($Filter) { return @(Get-CimInstance -ClassName $Class -Filter $Filter -ErrorAction Stop) }
            return @(Get-CimInstance -ClassName $Class -ErrorAction Stop)
        }
        catch {
            if (-not $state.Missing.Contains($Class)) { [void]$state.Missing.Add($Class) }
            return @()
        }
    }
    function Get-Delta($a, $b, [string]$Prop) {
        if ($null -eq $a -or $null -eq $b) { return 0.0 }
        $d = [double]$b.$Prop - [double]$a.$Prop
        # Liczniki 32-bitowe się przekręcają
        if ($d -lt 0 -and [double]$a.$Prop -lt 4294967296) { $d += 4294967296 }
        return $d
    }
    function Get-Rate($a, $b, [string]$Prop) {
        # PERF_COUNTER_COUNTER / BULK_COUNT: zdarzenia na sekundę
        if ($null -eq $a -or $null -eq $b) { return 0.0 }
        $dt = (Get-Delta $a $b 'Timestamp_PerfTime') / [double]$b.Frequency_PerfTime
        if ($dt -le 0) { return 0.0 }
        return (Get-Delta $a $b $Prop) / $dt
    }
    function Get-Pct100ns($a, $b, [string]$Prop) {
        # PERF_100NSEC_TIMER: procent czasu
        if ($null -eq $a -or $null -eq $b) { return 0.0 }
        $dt = Get-Delta $a $b 'Timestamp_Sys100NS'
        if ($dt -le 0) { return 0.0 }
        return 100.0 * (Get-Delta $a $b $Prop) / $dt
    }
    function Get-AvgTimer($a, $b, [string]$Prop) {
        # PERF_AVERAGE_TIMER: sekundy na operację
        if ($null -eq $a -or $null -eq $b) { return 0.0 }
        $base = Get-Delta $a $b ($Prop + '_Base')
        if ($base -le 0) { return 0.0 }
        return ((Get-Delta $a $b $Prop) / [double]$b.Frequency_PerfTime) / $base
    }
    function Get-PctBase($a, $b, [string]$Prop) {
        # PERF_PRECISION_100NS_TIMER z bazą (np. % czasu bezczynności dysku)
        if ($null -eq $a -or $null -eq $b) { return $null }
        $base = Get-Delta $a $b ($Prop + '_Base')
        if ($base -le 0) { return $null }
        return 100.0 * (Get-Delta $a $b $Prop) / $base
    }
    function Get-Clamp([double]$v, [double]$lo = 0, [double]$hi = 100) { return [Math]::Min($hi, [Math]::Max($lo, $v)) }
    function Get-ByName($list, [string]$Name) { foreach ($x in $list) { if ([string]$x.Name -eq $Name) { return $x } }; return $null }

    $duration = [Math]::Max(2, [int]$P.Duration)
    $interval = [Math]::Max(1, [Math]::Min([int]$P.Interval, $duration))
    $top = [Math]::Max(1, [int]$P.Top)
    $cs = Get-CimInstance -ClassName Win32_ComputerSystem
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    $cores = [Math]::Max(1, [int]$cs.NumberOfLogicalProcessors)
    $totalMB = [Math]::Round([double]$os.TotalVisibleMemorySize / 1KB)

    $take = {
        @{
            Cpu  = @(Get-Raw 'Win32_PerfRawData_PerfOS_Processor' "Name='_Total'") | Select-Object -First 1
            Sys  = @(Get-Raw 'Win32_PerfRawData_PerfOS_System') | Select-Object -First 1
            Mem  = @(Get-Raw 'Win32_PerfRawData_PerfOS_Memory') | Select-Object -First 1
            Disk = @(Get-Raw 'Win32_PerfRawData_PerfDisk_LogicalDisk' | Where-Object { $_.Name -ne '_Total' })
            Nic  = @(Get-Raw 'Win32_PerfRawData_Tcpip_NetworkInterface' | Where-Object { $_.Name -notmatch 'isatap|teredo|6to4|loopback|pseudo' })
            Tcp  = @(Get-Raw 'Win32_PerfRawData_Tcpip_TCPv4') | Select-Object -First 1
            Tcp6 = @(Get-Raw 'Win32_PerfRawData_Tcpip_TCPv6') | Select-Object -First 1
        }
    }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $p0 = @(Get-Raw 'Win32_PerfRawData_PerfProc_Process')
    $samples = New-Object System.Collections.ArrayList
    [void]$samples.Add((& $take))
    $count = [Math]::Max(1, [int][Math]::Ceiling($duration / [double]$interval))
    for ($i = 0; $i -lt $count; $i++) {
        Start-Sleep -Seconds $interval
        [void]$samples.Add((& $take))
    }
    $p1 = @(Get-Raw 'Win32_PerfRawData_PerfProc_Process')
    $measured = [Math]::Round($sw.Elapsed.TotalSeconds, 1)
    $first = $samples[0]
    $last = $samples[$samples.Count - 1]
    $pairs = @(for ($i = 1; $i -lt $samples.Count; $i++) { , @($samples[$i - 1], $samples[$i]) })

    # --- procesor
    $cpuAvg = Get-Clamp (100 - (Get-Pct100ns $first.Cpu $last.Cpu 'PercentProcessorTime'))
    $cpuMax = 0.0
    foreach ($pr in $pairs) { $cpuMax = [Math]::Max($cpuMax, (Get-Clamp (100 - (Get-Pct100ns $pr[0].Cpu $pr[1].Cpu 'PercentProcessorTime')))) }
    $kernel = Get-Clamp (Get-Pct100ns $first.Cpu $last.Cpu 'PercentPrivilegedTime')
    $irq = Get-Clamp ((Get-Pct100ns $first.Cpu $last.Cpu 'PercentInterruptTime') + (Get-Pct100ns $first.Cpu $last.Cpu 'PercentDPCTime'))
    $queues = @($samples | ForEach-Object { if ($_.Sys) { [double]$_.Sys.ProcessorQueueLength } })
    $queueAvg = if ($queues.Count) { ($queues | Measure-Object -Average).Average } else { 0 }
    $queueMax = if ($queues.Count) { ($queues | Measure-Object -Maximum).Maximum } else { 0 }
    $ctx = Get-Rate $first.Sys $last.Sys 'ContextSwitchesPersec'

    # --- pamięć
    $avail = @($samples | ForEach-Object { if ($_.Mem) { [double]$_.Mem.AvailableMBytes } })
    $availMin = if ($avail.Count) { ($avail | Measure-Object -Minimum).Minimum } else { [double]$os.FreePhysicalMemory / 1KB }
    $mem = $last.Mem
    $commitPct = if ($mem -and [double]$mem.CommitLimit -gt 0) { 100.0 * [double]$mem.CommittedBytes / [double]$mem.CommitLimit } else { $null }
    $hardFaults = Get-Rate $first.Mem $last.Mem 'PageReadsPersec'
    $pagesPs = Get-Rate $first.Mem $last.Mem 'PagesPersec'

    # --- dyski (woluminy)
    $disks = foreach ($d1 in $last.Disk) {
        $d0 = Get-ByName $first.Disk $d1.Name
        if (-not $d0) { continue }
        $reads = Get-Rate $d0 $d1 'DiskReadsPersec'
        $writes = Get-Rate $d0 $d1 'DiskWritesPersec'
        $maxLat = 0.0
        $maxQueue = 0.0
        foreach ($pr in $pairs) {
            $a = Get-ByName $pr[0].Disk $d1.Name
            $b = Get-ByName $pr[1].Disk $d1.Name
            if ($a -and $b -and ((Get-Rate $a $b 'DiskTransfersPersec') -ge 1)) { $maxLat = [Math]::Max($maxLat, 1000 * (Get-AvgTimer $a $b 'AvgDisksecPerTransfer')) }
            if ($b) { $maxQueue = [Math]::Max($maxQueue, [double]$b.CurrentDiskQueueLength) }
        }
        $idle = Get-PctBase $d0 $d1 'PercentIdleTime'
        $dtSys = Get-Delta $d0 $d1 'Timestamp_Sys100NS'
        $freePct = if ([double]$d1.PercentFreeSpace_Base -gt 0) { 100.0 * [double]$d1.PercentFreeSpace / [double]$d1.PercentFreeSpace_Base } else { $null }
        [pscustomobject]@{
            __kind     = 'disk'
            Volume     = [string]$d1.Name
            ReadMs     = [Math]::Round(1000 * (Get-AvgTimer $d0 $d1 'AvgDisksecPerRead'), 1)
            WriteMs    = [Math]::Round(1000 * (Get-AvgTimer $d0 $d1 'AvgDisksecPerWrite'), 1)
            AvgMs      = [Math]::Round(1000 * (Get-AvgTimer $d0 $d1 'AvgDisksecPerTransfer'), 1)
            MaxMs      = [Math]::Round($maxLat, 1)
            QueueAvg   = $(if ($dtSys -gt 0) { [Math]::Round((Get-Delta $d0 $d1 'AvgDiskQueueLength') / $dtSys, 2) } else { 0 })
            QueueMax   = $maxQueue
            BusyPct    = $(if ($null -ne $idle) { [Math]::Round((Get-Clamp (100 - $idle)), 0) } else { $null })
            ReadsPs    = [Math]::Round($reads, 1)
            WritesPs   = [Math]::Round($writes, 1)
            ReadMBps   = [Math]::Round((Get-Rate $d0 $d1 'DiskReadBytesPersec') / 1MB, 2)
            WriteMBps  = [Math]::Round((Get-Rate $d0 $d1 'DiskWriteBytesPersec') / 1MB, 2)
            FreeGB     = [Math]::Round([double]$d1.FreeMegabytes / 1KB, 1)
            FreePct    = $(if ($null -ne $freePct) { [Math]::Round($freePct, 1) } else { $null })
        }
    }
    $disks = @($disks)

    # --- sieć
    $nics = foreach ($n1 in $last.Nic) {
        $n0 = Get-ByName $first.Nic $n1.Name
        if (-not $n0) { continue }
        $bw = [double]$n1.CurrentBandwidth
        $total = Get-Rate $n0 $n1 'BytesTotalPersec'
        $utilMax = 0.0
        $outQ = 0.0
        foreach ($pr in $pairs) {
            $a = Get-ByName $pr[0].Nic $n1.Name
            $b = Get-ByName $pr[1].Nic $n1.Name
            if ($a -and $b -and $bw -gt 0) { $utilMax = [Math]::Max($utilMax, 100.0 * 8 * (Get-Rate $a $b 'BytesTotalPersec') / $bw) }
            if ($b) { $outQ = [Math]::Max($outQ, [double]$b.OutputQueueLength) }
        }
        if ($bw -le 0 -and $total -le 0) { continue }
        [pscustomobject]@{
            __kind      = 'nic'
            Adapter     = [string]$n1.Name
            SpeedMbps   = [Math]::Round($bw / 1e6)
            UtilAvg     = $(if ($bw -gt 0) { [Math]::Round((Get-Clamp (100.0 * 8 * $total / $bw)), 1) } else { $null })
            UtilMax     = $(if ($bw -gt 0) { [Math]::Round((Get-Clamp $utilMax), 1) } else { $null })
            RecvMbps    = [Math]::Round(8 * (Get-Rate $n0 $n1 'BytesReceivedPersec') / 1e6, 2)
            SentMbps    = [Math]::Round(8 * (Get-Rate $n0 $n1 'BytesSentPersec') / 1e6, 2)
            OutQueueMax = $outQ
            Errors      = (Get-Delta $n0 $n1 'PacketsReceivedErrors') + (Get-Delta $n0 $n1 'PacketsOutboundErrors')
            Discards    = (Get-Delta $n0 $n1 'PacketsReceivedDiscarded') + (Get-Delta $n0 $n1 'PacketsOutboundDiscarded')
            ErrorsTotal = [double]$n1.PacketsReceivedErrors + [double]$n1.PacketsOutboundErrors
        }
    }
    $nics = @($nics)
    $segs = Get-Rate $first.Tcp $last.Tcp 'SegmentsSentPersec'
    $retr = Get-Rate $first.Tcp $last.Tcp 'SegmentsRetransmittedPersec'
    $retrPct = if ($segs -ge 20) { [Math]::Round(100.0 * $retr / $segs, 2) } else { $null }
    $tcpConn = $(if ($last.Tcp) { [int]$last.Tcp.ConnectionsEstablished } else { 0 }) + $(if ($last.Tcp6) { [int]$last.Tcp6.ConnectionsEstablished } else { 0 })

    # --- procesy (średnio w całym oknie pomiaru)
    $before = @{}
    foreach ($pc in $p0) { $before[('{0}|{1}' -f $pc.Name, $pc.IDProcess)] = $pc }
    $procs = foreach ($pc in $p1) {
        if ($pc.Name -eq '_Total' -or $pc.Name -eq 'Idle' -or [int]$pc.IDProcess -eq 0) { continue }
        $a = $before[('{0}|{1}' -f $pc.Name, $pc.IDProcess)]
        if (-not $a) { continue }
        # PERF_ELAPSED_TIME: wartość surowa to chwila startu procesu
        $elapsed = if ([double]$pc.Frequency_Object -gt 0 -and [double]$pc.ElapsedTime -gt 0) { ([double]$pc.Timestamp_Object - [double]$pc.ElapsedTime) / [double]$pc.Frequency_Object } else { -1 }
        [pscustomobject]@{
            Name       = ([string]$pc.Name -replace '#\d+$', '')
            Pid        = [int]$pc.IDProcess
            Cpu        = (Get-Pct100ns $a $pc 'PercentProcessorTime') / $cores
            PrivateMB  = [double]$pc.WorkingSetPrivate / 1MB
            CommitMB   = [double]$pc.PrivateBytes / 1MB
            ReadMBps   = (Get-Rate $a $pc 'IOReadBytesPersec') / 1MB
            WriteMBps  = (Get-Rate $a $pc 'IOWriteBytesPersec') / 1MB
            IoOps      = Get-Rate $a $pc 'IODataOperationsPersec'
            Handles    = [int]$pc.HandleCount
            Threads    = [int]$pc.ThreadCount
            Faults     = Get-Rate $a $pc 'PageFaultsPersec'
            Hours      = $(if ($elapsed -ge 0) { [Math]::Round($elapsed / 3600, 1) } else { $null })
        }
    }
    $procs = @($procs)
    $picked = [ordered]@{}
    foreach ($spec in @(@('Cpu', 'CPU'), @('PrivateMB', 'pamięć'), @('IoTotal', 'I/O'))) {
        $key = $spec[0]
        $list = if ($key -eq 'IoTotal') { @($procs | Sort-Object { $_.ReadMBps + $_.WriteMBps } -Descending) } else { @($procs | Sort-Object $key -Descending) }
        foreach ($pc in ($list | Select-Object -First $top)) {
            $value = if ($key -eq 'IoTotal') { $pc.ReadMBps + $pc.WriteMBps } else { $pc.$key }
            if ($value -le 0) { continue }
            # Klucz tekstowy: liczba w OrderedDictionary byłaby indeksem pozycji
            $pk = [string]$pc.Pid
            if ($picked.Contains($pk)) { $picked[$pk].Reasons += $spec[1] }
            else { $picked[$pk] = @{ P = $pc; Reasons = @($spec[1]) } }
        }
    }
    $services = @{}
    $details = @{}
    if ($picked.Count -gt 0) {
        try {
            foreach ($s in @(Get-CimInstance -ClassName Win32_Service -Filter "State='Running'" -ErrorAction Stop)) {
                $k = [int]$s.ProcessId
                if (-not $services.ContainsKey($k)) { $services[$k] = New-Object System.Collections.ArrayList }
                [void]$services[$k].Add([string]$s.Name)
            }
        }
        catch { }
        $filter = (@($picked.Keys | ForEach-Object { "ProcessId=$_" }) -join ' OR ')
        try {
            foreach ($wp in @(Get-CimInstance -ClassName Win32_Process -Filter $filter -ErrorAction Stop)) {
                $owner = ''
                try {
                    $o = Invoke-CimMethod -InputObject $wp -MethodName GetOwner -ErrorAction Stop
                    if ($o.User) { $owner = $(if ($o.Domain) { "$($o.Domain)\$($o.User)" } else { [string]$o.User }) }
                }
                catch { }
                $details[[int]$wp.ProcessId] = @{ Owner = $owner; Cmd = [string]$wp.CommandLine }
            }
        }
        catch { }
    }
    $procRows = foreach ($k in $picked.Keys) {
        $pc = $picked[$k].P
        $d = $details[[int]$k]
        $cmd = if ($d) { $d.Cmd } else { '' }
        [pscustomobject]@{
            __kind    = 'proc'
            Name      = $pc.Name
            Pid       = $pc.Pid
            Reasons   = ($picked[$k].Reasons -join ', ')
            Cpu       = [Math]::Round($pc.Cpu, 1)
            PrivateMB = [Math]::Round($pc.PrivateMB)
            CommitMB  = [Math]::Round($pc.CommitMB)
            ReadMBps  = [Math]::Round($pc.ReadMBps, 2)
            WriteMBps = [Math]::Round($pc.WriteMBps, 2)
            IoOps     = [Math]::Round($pc.IoOps, 1)
            Handles   = $pc.Handles
            Threads   = $pc.Threads
            Faults    = [Math]::Round($pc.Faults)
            Hours     = $pc.Hours
            Owner     = $(if ($d) { $d.Owner } else { '' })
            Services  = $(if ($services.ContainsKey([int]$k)) { (@($services[[int]$k]) -join ', ') } else { '' })
            Command   = $(if ($cmd.Length -gt 400) { $cmd.Substring(0, 400) + '…' } else { $cmd })
        }
    }
    $procRows = @($procRows)

    # --- zdarzenia świadczące o problemach (dyski, pamięć, awarie)
    $events = @()
    if ([int]$P.EventHours -gt 0) {
        $since = (Get-Date).AddHours( - [int]$P.EventHours)
        $meaning = @{
            '41'   = @('crit', 'Nieoczekiwany restart (zanik zasilania, zawieszenie, twardy reset)')
            '6008' = @('crit', 'Poprzednie zamknięcie systemu było nieoczekiwane')
            '1001' = @('crit', 'Błąd krytyczny systemu (niebieski ekran)')
            '2004' = @('crit', 'Brak pamięci wirtualnej – w treści proces, który zużywał najwięcej')
            '2013' = @('warn', 'Mało miejsca na dysku (usługa Serwer)')
            '2019' = @('crit', 'Wyczerpana pula pamięci niestronicowanej (wyciek sterownika)')
            '2020' = @('crit', 'Wyczerpana pula pamięci stronicowanej')
            '7'    = @('crit', 'Uszkodzony blok na dysku')
            '11'   = @('crit', 'Błąd kontrolera dysku')
            '51'   = @('crit', 'Błąd podczas stronicowania na dysk')
            '129'  = @('warn', 'Reset urządzenia dyskowego (dysk / kontroler / SAN nie odpowiadał)')
            '153'  = @('warn', 'Ponowione operacje I/O na dysku (opóźnienia, problemy ze ścieżką do macierzy)')
            '55'   = @('crit', 'Uszkodzenie struktury systemu plików NTFS')
            '98'   = @('warn', 'Wolumin wymaga sprawdzenia (chkdsk)')
            '140'  = @('warn', 'NTFS nie zapisał danych (błąd I/O)')
            '1000' = @('info', 'Awaria aplikacji')
            '1002' = @('info', 'Aplikacja przestała odpowiadać (zawieszenie)')
        }
        $queries = @(
            @{ LogName = 'System'; Id = @(41, 6008, 1001, 2004, 2013, 2019, 2020, 7, 11, 51, 129, 153, 55, 98, 140); StartTime = $since }
            @{ LogName = 'Application'; Id = @(1000, 1002); StartTime = $since }
        )
        $found = foreach ($q in $queries) { try { Get-WinEvent -FilterHashtable $q -MaxEvents 150 -ErrorAction Stop } catch { } }
        $events = foreach ($e in @($found | Sort-Object TimeCreated -Descending | Select-Object -First 100)) {
            $id = [string]$e.Id
            $prov = [string]$e.ProviderName
            # Te same numery mają też inni dostawcy - bierzemy tylko znane źródła
            $okSource = switch ($id) {
                '41' { $prov -like '*Kernel-Power' }
                '6008' { $prov -eq 'EventLog' }
                '1001' { $prov -like '*WER-SystemErrorReporting' -or $prov -eq 'BugCheck' }
                '2004' { $prov -like '*Resource-Exhaustion-Detector' }
                { @('2013', '2019', '2020') -contains $_ } { $prov -eq 'srv' -or $prov -like '*SMBServer*' }
                { @('7', '11', '51', '153') -contains $_ } { $prov -eq 'disk' -or $prov -like 'stor*' -or $prov -like '*Disk*' }
                '129' { $true }
                { @('55', '98', '140') -contains $_ } { $prov -like '*Ntfs*' }
                '1000' { $prov -eq 'Application Error' }
                '1002' { $prov -eq 'Application Hang' }
                default { $false }
            }
            if (-not $okSource) { continue }
            $msg = ''
            try { $msg = [string]$e.Message } catch { }
            if (-not $msg) { $msg = (@($e.Properties | ForEach-Object { [string]$_.Value } | Where-Object { $_ }) -join ' | ') }
            $msg = ($msg -replace '\s+', ' ').Trim()
            [pscustomobject]@{
                __kind  = 'event'
                Time    = $e.TimeCreated
                Log     = [string]$e.LogName
                Source  = $prov
                Id      = [int]$e.Id
                Tone    = $meaning[$id][0]
                Meaning = $meaning[$id][1]
                Message = $(if ($msg.Length -gt 400) { $msg.Substring(0, 400) + '…' } else { $msg })
            }
        }
        $events = @($events)
    }

    $topBy = {
        param($key, $fmt)
        $pc = @($procRows | Sort-Object $key -Descending | Select-Object -First 1)
        if ($pc.Count -and [double]$pc[0].$key -gt 0) { & $fmt $pc[0] } else { '' }
    }
    [pscustomobject]@{
        __kind        = 'summary'
        Cores         = $cores
        RamGB         = [Math]::Round($totalMB / 1KB, 1)
        UptimeDays    = [Math]::Round(((Get-Date) - $os.LastBootUpTime).TotalDays, 1)
        Seconds       = $measured
        Samples       = $samples.Count
        CpuAvg        = [Math]::Round($cpuAvg, 1)
        CpuMax        = [Math]::Round($cpuMax, 1)
        KernelPct     = [Math]::Round($kernel, 1)
        IrqPct        = [Math]::Round($irq, 1)
        QueuePerCore  = [Math]::Round($queueAvg / $cores, 2)
        QueueMax      = $queueMax
        CtxPerSec     = [Math]::Round($ctx)
        Processes     = $(if ($last.Sys) { [int]$last.Sys.Processes } else { $p1.Count })
        Threads       = $(if ($last.Sys) { [int]$last.Sys.Threads } else { $null })
        TotalMB       = $totalMB
        AvailMB       = [Math]::Round($availMin)
        MemUsedPct    = $(if ($totalMB -gt 0) { [Math]::Round(100 - 100.0 * $availMin / $totalMB, 1) } else { $null })
        CommitPct     = $(if ($null -ne $commitPct) { [Math]::Round($commitPct, 1) } else { $null })
        HardFaults    = [Math]::Round($hardFaults)
        PagesPs       = [Math]::Round($pagesPs)
        PoolNpMB      = $(if ($mem) { [Math]::Round([double]$mem.PoolNonpagedBytes / 1MB) } else { $null })
        TcpConn       = $tcpConn
        RetransPct    = $retrPct
        TopCpu        = (& $topBy 'Cpu' { param($pc) '{0} ({1}%)' -f $pc.Name, $pc.Cpu })
        TopMem        = (& $topBy 'PrivateMB' { param($pc) '{0} ({1:N1} GB)' -f $pc.Name, ($pc.PrivateMB / 1KB) })
        TopIo         = $(
            $io = @($procRows | Sort-Object { $_.ReadMBps + $_.WriteMBps } -Descending | Select-Object -First 1)
            if ($io.Count -and ($io[0].ReadMBps + $io[0].WriteMBps) -gt 0) { '{0} ({1:N1} MB/s)' -f $io[0].Name, ($io[0].ReadMBps + $io[0].WriteMBps) } else { '' })
        Missing       = (@($state.Missing) -join ', ')
    }
    $procRows
    $disks
    $nics
    $events
}

$script:PerfViews = @('Podsumowanie', 'Procesy', 'Dyski', 'Sieć', 'Zdarzenia')

function Get-PerfVerdict {
    <#
        Ocena wyników pomiaru jednego komputera. Zwraca @{ Tone = ok|warn|crit; Findings = @(@{ Tone; Area; Text }) }.
        Progi: typowe zalecenia dla Windows Server (np. opóźnienie dysku > 20 ms, kolejka procesora > 2 na rdzeń).
    #>
    param($Summary, [object[]]$Disks = @(), [object[]]$Nics = @(), [object[]]$Processes = @(), [object[]]$Events = @())
    $s = $Summary
    $f = New-Object System.Collections.ArrayList
    $add = { param($tone, $area, $text) [void]$f.Add(@{ Tone = $tone; Area = $area; Text = $text }) }
    $topCpu = @($Processes | Sort-Object { [double]$_.Cpu } -Descending | Select-Object -First 2 | Where-Object { [double]$_.Cpu -ge 5 } | ForEach-Object { '{0} {1}%' -f $_.Name, [Math]::Round([double]$_.Cpu) })
    $topMem = @($Processes | Sort-Object { [double]$_.PrivateMB } -Descending | Select-Object -First 2 | ForEach-Object { '{0} {1:N1} GB' -f $_.Name, ([double]$_.PrivateMB / 1KB) })
    $topIo = @($Processes | Sort-Object { [double]$_.ReadMBps + [double]$_.WriteMBps } -Descending | Select-Object -First 2 | Where-Object { ([double]$_.ReadMBps + [double]$_.WriteMBps) -ge 0.5 } | ForEach-Object { '{0} {1:N1} MB/s' -f $_.Name, ([double]$_.ReadMBps + [double]$_.WriteMBps) })
    $who = { param($list) if (@($list).Count) { ' – ' + (@($list) -join ', ') } else { '' } }

    # Procesor
    $cpuTone = if ([double]$s.CpuAvg -ge 90) { 'crit' } elseif ([double]$s.CpuAvg -ge 75 -or ([double]$s.CpuMax -ge 98 -and [double]$s.CpuAvg -ge 50)) { 'warn' } else { '' }
    $qTone = if ([double]$s.QueuePerCore -ge 5) { 'crit' } elseif ([double]$s.QueuePerCore -ge 2 -and [double]$s.CpuAvg -ge 50) { 'warn' } else { '' }
    if ($cpuTone -or $qTone) {
        $tone = if ($cpuTone -eq 'crit' -or $qTone -eq 'crit') { 'crit' } else { 'warn' }
        & $add $tone 'Procesor' ('procesor: średnio {0:N0}% (szczyt {1:N0}%), kolejka {2:N1} na rdzeń{3}' -f [double]$s.CpuAvg, [double]$s.CpuMax, [double]$s.QueuePerCore, (& $who $topCpu))
    }
    if ([double]$s.KernelPct -ge 30 -and [double]$s.CpuAvg -ge 40) { & $add 'warn' 'Procesor' ('procesor: {0:N0}% czasu w trybie jądra – sterowniki, antywirus, intensywne I/O' -f [double]$s.KernelPct) }
    if ([double]$s.IrqPct -ge 15) { & $add 'warn' 'Procesor' ('procesor: przerwania i DPC {0:N0}% – sterownik karty sieciowej / dysku albo sprzęt' -f [double]$s.IrqPct) }

    # Pamięć
    $availPct = if ([double]$s.TotalMB -gt 0) { 100.0 * [double]$s.AvailMB / [double]$s.TotalMB } else { 100 }
    $memTone = if ($availPct -lt 5 -or [double]$s.CommitPct -ge 95) { 'crit' } elseif ($availPct -lt 10 -or [double]$s.CommitPct -ge 85) { 'warn' } else { '' }
    if ($memTone) { & $add $memTone 'Pamięć' ('pamięć: dostępne {0:N0} MB ({1:N0}%), zadeklarowana {2:N0}% limitu{3}' -f [double]$s.AvailMB, $availPct, [double]$s.CommitPct, (& $who $topMem)) }
    if ([double]$s.HardFaults -ge 100 -and $availPct -lt 15) { & $add 'warn' 'Pamięć' ('pamięć: stronicowanie, {0:N0} odczytów stron/s z dysku przy małej ilości wolnej pamięci' -f [double]$s.HardFaults) }

    # Dyski
    foreach ($d in $Disks) {
        $busy = ([double]$d.ReadsPs + [double]$d.WritesPs) -ge 5
        $lat = [Math]::Max([double]$d.ReadMs, [double]$d.WriteMs)
        $parts = @()
        $tone = ''
        if ($busy -and $lat -ge 50) { $tone = 'crit'; $parts += ('opóźnienie {0:N0} ms (odczyt {1:N0} / zapis {2:N0})' -f $lat, [double]$d.ReadMs, [double]$d.WriteMs) }
        elseif ($busy -and $lat -ge 20) { $tone = 'warn'; $parts += ('opóźnienie {0:N0} ms (odczyt {1:N0} / zapis {2:N0})' -f $lat, [double]$d.ReadMs, [double]$d.WriteMs) }
        if ([double]$d.QueueAvg -ge 8) { $tone = 'crit'; $parts += ('kolejka {0:N1}' -f [double]$d.QueueAvg) }
        elseif ([double]$d.QueueAvg -ge 2) { if (-not $tone) { $tone = 'warn' }; $parts += ('kolejka {0:N1}' -f [double]$d.QueueAvg) }
        if ($parts.Count) { & $add $tone 'Dysk' ('dysk {0}: {1}{2}' -f $d.Volume, ($parts -join ', '), (& $who $topIo)) }
        if ($null -ne $d.FreePct -and [string]$d.Volume -match '^[A-Z]:$') {
            if ([double]$d.FreePct -lt 5) { & $add 'crit' 'Dysk' ('dysk {0}: wolne tylko {1:N1}% ({2:N1} GB)' -f $d.Volume, [double]$d.FreePct, [double]$d.FreeGB) }
            elseif ([double]$d.FreePct -lt 10) { & $add 'warn' 'Dysk' ('dysk {0}: wolne {1:N1}% ({2:N1} GB)' -f $d.Volume, [double]$d.FreePct, [double]$d.FreeGB) }
        }
    }

    # Sieć
    foreach ($n in $Nics) {
        $parts = @()
        $tone = ''
        if ($null -ne $n.UtilMax -and [double]$n.UtilMax -ge 90) { $tone = 'crit'; $parts += ('wykorzystanie do {0:N0}% z {1} Mb/s' -f [double]$n.UtilMax, $n.SpeedMbps) }
        elseif ($null -ne $n.UtilMax -and [double]$n.UtilMax -ge 70) { $tone = 'warn'; $parts += ('wykorzystanie do {0:N0}% z {1} Mb/s' -f [double]$n.UtilMax, $n.SpeedMbps) }
        if ([double]$n.OutQueueMax -ge 2) { if (-not $tone) { $tone = 'warn' }; $parts += ('kolejka wyjściowa {0}' -f $n.OutQueueMax) }
        if ([double]$n.Errors -gt 0 -or [double]$n.Discards -gt 0) { if (-not $tone) { $tone = 'warn' }; $parts += ('błędy {0}, odrzucone {1} w czasie pomiaru' -f $n.Errors, $n.Discards) }
        if ($parts.Count) { & $add $tone 'Sieć' ('sieć {0}: {1}' -f $n.Adapter, ($parts -join ', ')) }
    }
    if ($null -ne $s.RetransPct -and [double]$s.RetransPct -ge 5) { & $add 'crit' 'Sieć' ('sieć: retransmisje TCP {0:N1}% – utrata pakietów w sieci' -f [double]$s.RetransPct) }
    elseif ($null -ne $s.RetransPct -and [double]$s.RetransPct -ge 2) { & $add 'warn' 'Sieć' ('sieć: retransmisje TCP {0:N1}%' -f [double]$s.RetransPct) }

    # Dziennik zdarzeń
    $bad = @($Events | Where-Object { $_.Tone -eq 'crit' -or $_.Tone -eq 'warn' })
    if ($bad.Count) {
        $groups = @($bad | Group-Object Id | Sort-Object Count -Descending | ForEach-Object { '{0}× {1} ({2})' -f $_.Count, $_.Group[0].Meaning, $_.Name })
        & $add $(if (@($bad | Where-Object { $_.Tone -eq 'crit' }).Count) { 'crit' } else { 'warn' }) 'Zdarzenia' ('dziennik: ' + ((@($groups | Select-Object -First 3)) -join '; '))
    }
    $apps = @($Events | Where-Object { $_.Tone -eq 'info' })
    if ($apps.Count) { & $add 'info' 'Zdarzenia' ('dziennik: awarie / zawieszenia aplikacji: {0}' -f $apps.Count) }
    if ($s.Missing) { & $add 'warn' 'Liczniki' ('liczniki: brak {0} – odbuduj je poleceniem lodctr /r' -f $s.Missing) }

    $tone = 'ok'
    if (@($f | Where-Object { $_.Tone -eq 'crit' }).Count) { $tone = 'crit' } elseif (@($f | Where-Object { $_.Tone -eq 'warn' }).Count) { $tone = 'warn' }
    $order = @{ crit = 0; warn = 1; info = 2 }
    return @{ Tone = $tone; Findings = @($f | Sort-Object { $order[$_.Tone] }) }
}

function ConvertTo-PerfRows {
    # Wiersze tabeli dla widoku (0 Podsumowanie, 1 Procesy, 2 Dyski, 3 Sieć, 4 Zdarzenia) z danych jednego komputera
    param([hashtable]$Data, [int]$View)
    $s = $Data.Summary
    switch ($View) {
        0 {
            $v = $Data.Verdict
            $label = @{ ok = 'OK'; warn = 'Do sprawdzenia'; crit = 'Przeciążenie' }[$v.Tone]
            $text = if (@($v.Findings | Where-Object { $_.Tone -ne 'info' }).Count) { (@($v.Findings | ForEach-Object { $_.Text }) -join '; ') } elseif (@($v.Findings).Count) { 'Bez przeciążenia; ' + (@($v.Findings | ForEach-Object { $_.Text }) -join '; ') } else { 'Brak oznak przeciążenia w czasie pomiaru.' }
            $slow = @($Data.Disks | Where-Object { ([double]$_.ReadsPs + [double]$_.WritesPs) -ge 1 } | Sort-Object { [Math]::Max([double]$_.ReadMs, [double]$_.WriteMs) } -Descending | Select-Object -First 1)
            $net = @($Data.Nics | Where-Object { $null -ne $_.UtilMax } | Sort-Object { [double]$_.UtilMax } -Descending | Select-Object -First 1)
            $ev = @($Data.Events)
            return ([pscustomobject][ordered]@{
                    'Ocena'                  = $label
                    'Wnioski'                = $text
                    'CPU % śr.'              = $s.CpuAvg
                    'CPU % szczyt'           = $s.CpuMax
                    'Kolejka CPU / rdzeń'    = $s.QueuePerCore
                    'Jądro %'                = $s.KernelPct
                    'Przerwania + DPC %'     = $s.IrqPct
                    'Pamięć zajęta %'        = $s.MemUsedPct
                    'Dostępna MB'            = $s.AvailMB
                    'Zadeklarowana %'        = $s.CommitPct
                    'Odczyty stron/s'        = $s.HardFaults
                    'Najwolniejszy dysk'     = $(if ($slow.Count) { $slow[0].Volume } else { '' })
                    'Opóźnienie dysku ms'    = $(if ($slow.Count) { [Math]::Max([double]$slow[0].ReadMs, [double]$slow[0].WriteMs) } else { $null })
                    'Kolejka dysku'          = $(if ($slow.Count) { $slow[0].QueueAvg } else { $null })
                    'Sieć % szczyt'          = $(if ($net.Count) { $net[0].UtilMax } else { $null })
                    'Retransmisje TCP %'     = $s.RetransPct
                    'Połączenia TCP'         = $s.TcpConn
                    'Najwięcej CPU'          = $s.TopCpu
                    'Najwięcej pamięci'      = $s.TopMem
                    'Najwięcej I/O'          = $s.TopIo
                    'Zdarzenia'              = $(if ($ev.Count) { '{0} (krytyczne: {1})' -f $ev.Count, @($ev | Where-Object { $_.Tone -eq 'crit' }).Count } else { '' })
                    'Procesy / wątki'        = '{0} / {1}' -f $s.Processes, $s.Threads
                    'Rdzenie'                = $s.Cores
                    'RAM GB'                 = $s.RamGB
                    'Czas pracy (dni)'       = $s.UptimeDays
                    'Pomiar (s)'             = $s.Seconds
                    '__tone'                 = $v.Tone
                })
        }
        1 {
            return @($Data.Processes | Sort-Object { [double]$_.Cpu } -Descending | ForEach-Object {
                    [pscustomobject][ordered]@{
                        'Proces' = $_.Name; 'PID' = $_.Pid; 'Powód' = $_.Reasons; 'CPU %' = $_.Cpu; 'Pamięć prywatna MB' = $_.PrivateMB; 'Zadeklarowana MB' = $_.CommitMB
                        'Odczyt MB/s' = $_.ReadMBps; 'Zapis MB/s' = $_.WriteMBps; 'Operacje I/O/s' = $_.IoOps; 'Uchwyty' = $_.Handles; 'Wątki' = $_.Threads
                        'Błędy stron/s' = $_.Faults; 'Działa (h)' = $_.Hours; 'Użytkownik' = $_.Owner; 'Usługi' = $_.Services; 'Wiersz polecenia' = $_.Command
                        '__flag' = $(if ([double]$_.Cpu -ge 50) { 'crit' } elseif ([double]$_.Cpu -ge 20) { 'warn' } else { '' })
                    }
                })
        }
        2 {
            return @($Data.Disks | Sort-Object Volume | ForEach-Object {
                    $d = $_
                    $vd = Get-PerfVerdict -Summary $s -Disks @($d)
                    $own = @($vd.Findings | Where-Object { $_.Area -eq 'Dysk' })
                    [pscustomobject][ordered]@{
                        'Wolumin' = $d.Volume; 'Ocena' = $(if ($own.Count) { @{ warn = 'Uwaga'; crit = 'Problem' }[$own[0].Tone] } else { 'OK' })
                        'Odczyt ms' = $d.ReadMs; 'Zapis ms' = $d.WriteMs; 'Szczyt ms' = $d.MaxMs; 'Kolejka śr.' = $d.QueueAvg; 'Kolejka maks.' = $d.QueueMax; 'Zajętość %' = $d.BusyPct
                        'Odczyty/s' = $d.ReadsPs; 'Zapisy/s' = $d.WritesPs; 'Odczyt MB/s' = $d.ReadMBps; 'Zapis MB/s' = $d.WriteMBps; 'Wolne GB' = $d.FreeGB; 'Wolne %' = $d.FreePct
                        '__tone' = $(if ($own.Count) { $own[0].Tone } else { 'ok' })
                    }
                })
        }
        3 {
            $rows = @($Data.Nics | Sort-Object Adapter | ForEach-Object {
                    $n = $_
                    $vn = Get-PerfVerdict -Summary @{ CpuAvg = 0; CpuMax = 0; QueuePerCore = 0; KernelPct = 0; IrqPct = 0; TotalMB = 1; AvailMB = 1; CommitPct = 0; HardFaults = 0; RetransPct = $null; Missing = '' } -Nics @($n)
                    $own = @($vn.Findings | Where-Object { $_.Area -eq 'Sieć' })
                    [pscustomobject][ordered]@{
                        'Karta' = $n.Adapter; 'Ocena' = $(if ($own.Count) { @{ warn = 'Uwaga'; crit = 'Problem' }[$own[0].Tone] } else { 'OK' })
                        'Prędkość Mb/s' = $n.SpeedMbps; 'Wykorzystanie % śr.' = $n.UtilAvg; 'Wykorzystanie % szczyt' = $n.UtilMax; 'Odbiór Mb/s' = $n.RecvMbps; 'Wysyłanie Mb/s' = $n.SentMbps
                        'Kolejka wyjściowa' = $n.OutQueueMax; 'Błędy (pomiar)' = $n.Errors; 'Odrzucone (pomiar)' = $n.Discards; 'Błędy od startu' = $n.ErrorsTotal
                        '__tone' = $(if ($own.Count) { $own[0].Tone } else { 'ok' })
                    }
                })
            return $rows
        }
        4 {
            return @($Data.Events | ForEach-Object {
                    [pscustomobject][ordered]@{
                        'Czas' = $_.Time; 'Ocena' = @{ crit = 'Krytyczne'; warn = 'Ostrzeżenie'; info = 'Aplikacja' }[[string]$_.Tone]; 'Znaczenie' = $_.Meaning; 'Dziennik' = $_.Log; 'Źródło' = $_.Source; 'ID' = $_.Id; 'Komunikat' = $_.Message
                        '__tone' = $(if ($_.Tone -eq 'info') { 'info' } else { [string]$_.Tone })
                    }
                })
        }
    }
}

function Show-PerfView {
    # Przebudowuje tabelę z zapamiętanych wyników pomiaru (zmiana widoku nie wymaga ponownego pomiaru)
    param([hashtable]$Module)
    $m = $Module
    $view = [Math]::Max(0, (Get-SegmentIndex $m.ViewSwitch))
    Reset-ResultTable -Module $m
    $m.PillColumns = @('Ocena')
    foreach ($name in @($m.Data.Perf.Keys | Sort-Object)) {
        $rows = @(ConvertTo-PerfRows -Data $m.Data.Perf[$name] -View $view)
        if ($rows.Count) { Add-ResultRows -Module $m -Computer $name -Objects $rows }
    }
    foreach ($name in @($m.Data.PerfErrors.Keys | Sort-Object)) {
        # Komputer bez wyników - komunikat w pierwszej kolumnie bieżącego widoku
        $err = if ($view -eq 0) { [pscustomobject]@{ 'Ocena' = 'Błąd'; 'Wnioski' = $m.Data.PerfErrors[$name]; '__tone' = 'crit' } }
        else { [pscustomobject]@{ (@('', 'Proces', 'Wolumin', 'Karta', 'Znaczenie')[$view]) = ('Błąd pomiaru: ' + $m.Data.PerfErrors[$name]); '__flag' = 'crit' } }
        Add-ResultRows -Module $m -Computer $name -Objects @($err)
    }
    $m.ResultHint = @(
        'Jeden wiersz na komputer – kolor oceny i wnioski wskazują wąskie gardło'
        'Procesy z czołówki CPU, pamięci i I/O (średnio w czasie pomiaru; CPU w % całego komputera)'
        'Woluminy: opóźnienia odczytu/zapisu (powyżej 20 ms – wolno, 50 ms – bardzo wolno), kolejka i przepustowość'
        'Karty sieciowe: wykorzystanie łącza, kolejka wyjściowa, błędy i odrzucone pakiety'
        'Zdarzenia świadczące o problemach z dyskami, pamięcią i stabilnością (z wybranego okresu)'
    )[$view]
    if ($m.View_['resultHint']) { $m.View_['resultHint'].Text = $m.ResultHint }
    $counts = @{ ok = 0; warn = 0; crit = 0 }
    foreach ($d in $m.Data.Perf.Values) { $counts[$d.Verdict.Tone]++ }
    Set-StatTile -Module $m -Key 'ok' -Value ([string]$counts.ok) -Tone $(if ($counts.ok) { 'ok' } else { '' })
    Set-StatTile -Module $m -Key 'warn' -Value ([string]$counts.warn) -Tone $(if ($counts.warn) { 'warn' } else { '' })
    Set-StatTile -Module $m -Key 'crit' -Value ([string]($counts.crit + $m.Data.PerfErrors.Count)) -Tone $(if ($counts.crit + $m.Data.PerfErrors.Count) { 'crit' } else { '' })
}

function Start-PerfMeasurement {
    param([hashtable]$Module, [string[]]$Targets)
    $m = $Module
    $m.Data.LastTargets = @($Targets)
    $params = @{ Duration = (Get-Num $m.Duration); Interval = (Get-Num $m.Interval); Top = (Get-Num $m.Top); EventHours = (Get-Num $m.EventHours) }
    $m.Data.Perf = @{}
    $m.Data.PerfErrors = @{}
    Start-HostOperation -Module $m -Name 'Analiza wydajności' -Targets $Targets -Output None -Parameters $params -ScriptBlock $script:PerfAnalysisScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) { $m.Data.PerfErrors[$r.Target] = ((@($r.Errors | Select-Object -Unique)) -join ' | '); Show-PerfView -Module $m; return }
        $all = @($r.Data)
        $kind = { param($k) @($all | Where-Object { $_.__kind -eq $k }) }
        $summary = @(& $kind 'summary') | Select-Object -First 1
        if (-not $summary) { $m.Data.PerfErrors[$r.Target] = 'Brak wyników pomiaru.'; Show-PerfView -Module $m; return }
        $data = @{ Summary = $summary; Processes = @(& $kind 'proc'); Disks = @(& $kind 'disk'); Nics = @(& $kind 'nic'); Events = @(& $kind 'event') }
        $data.Verdict = Get-PerfVerdict -Summary $summary -Disks $data.Disks -Nics $data.Nics -Processes $data.Processes -Events $data.Events
        $m.Data.Perf[$r.Target] = $data
        $level = @{ ok = 'OK'; warn = 'WARN'; crit = 'WARN' }[$data.Verdict.Tone]
        $main = @($data.Verdict.Findings | Select-Object -First 2 | ForEach-Object { $_.Text })
        Write-Log ("[{0}] {1}" -f $r.Target, $(if ($main.Count) { $main -join '; ' } else { 'bez oznak przeciążenia' })) $level
        Show-PerfView -Module $m
    } -OnComplete {
        param($m)
        if (Test-Checked $m.Monitor) {
            if (-not $m.Data['MonitorTimer']) {
                $t = New-Object System.Windows.Threading.DispatcherTimer
                $t.Interval = [TimeSpan]::FromSeconds(1)
                $t.Tag = $m
                $t.add_Tick({
                        param($s, $e)
                        $s.Stop()
                        $mm = $s.Tag
                        if ((Test-Checked $mm.Monitor) -and -not $mm.Busy -and @($mm.Data.LastTargets).Count) { Invoke-UiAction -Module $mm -Action { param($m) Start-PerfMeasurement -Module $m -Targets $m.Data.LastTargets } }
                    })
                $m.Data.MonitorTimer = $t
            }
            $m.Data.MonitorTimer.Start()
        }
    }
}

function Initialize-PerfModule {
    param([hashtable]$Module)
    $m = $Module
    $m.PillColumns = @('Ocena')
    $m.Data.Perf = @{}
    $m.Data.PerfErrors = @{}
    $m.Data.LastTargets = @()
    $m.Data.MonitorTimer = $null
    $row = Add-ToolbarRow -Module $m -Title 'Pomiar'
    Add-Label -Parent $row -Text 'Czas (s)' | Out-Null
    $m.Duration = Add-Numeric -Parent $row -Value 10 -Minimum 2 -Maximum 600 -Width 60
    Add-Label -Parent $row -Text 'Próbka co (s)' | Out-Null
    $m.Interval = Add-Numeric -Parent $row -Value 2 -Minimum 1 -Maximum 60 -Width 50
    Add-Label -Parent $row -Text 'Procesy (czołówka)' | Out-Null
    $m.Top = Add-Numeric -Parent $row -Value 8 -Minimum 1 -Maximum 40 -Width 50
    Add-Label -Parent $row -Text 'Zdarzenia z ostatnich (h)' | Out-Null
    $m.EventHours = Add-Numeric -Parent $row -Value 24 -Minimum 0 -Maximum 720 -Width 60
    $m.Monitor = Add-CheckBox -Parent $row -Text 'Monitoruj (powtarzaj pomiar)' -ToolTip 'Po zakończeniu pomiaru od razu zaczyna następny – do odznaczenia albo «Przerwij»'
    Add-Button -Parent $row -Text 'Zmierz' -Icon 'E9D2' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-PerfMeasurement -Module $m -Targets $targets
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Widok'
    $m.ViewSwitch = Add-Segmented -Parent $row2 -Items $script:PerfViews -Module $m -OnChange { param($m) Show-PerfView -Module $m }
    Add-Label -Parent $row2 -Text 'Widok można zmieniać po pomiarze – dane nie są mierzone ponownie. CPU, dyski i sieć: średnie i szczyty z całego okna pomiaru.' -Hint -MaxWidth 560 | Out-Null
    Add-StatTile -Module $m -Key 'ok' -Label 'Bez przeciążenia' -Icon 'E73E' | Out-Null
    Add-StatTile -Module $m -Key 'warn' -Label 'Do sprawdzenia' -Icon 'E7BA' | Out-Null
    Add-StatTile -Module $m -Key 'crit' -Label 'Przeciążone / błąd' -Icon 'EA39' | Out-Null
    Add-RowAction -Module $m -Text 'Zakończ proces…' -Icon 'E711' -Danger -Action {
        param($m, $rows)
        $items = @($rows | Where-Object { (Get-ObjectValue $_ 'PID') } | ForEach-Object { '{0}: {1} (PID {2})' -f (Get-ObjectValue $_ 'Komputer'), (Get-ObjectValue $_ 'Proces'), (Get-ObjectValue $_ 'PID') })
        if ($items.Count -eq 0) { Show-Warning 'Przełącz widok na «Procesy» i zaznacz procesy do zakończenia.'; return }
        $chosen = @(Confirm-Action -Text 'Zakończyć wybrane procesy? Niezapisane dane w tych programach zostaną utracone.' -Items $items -ConfirmText 'Zakończ procesy' -Danger -Select -ReturnIndex)
        if ($chosen.Count -eq 0) { return }
        $sel = @($rows | Where-Object { (Get-ObjectValue $_ 'PID') })
        $per = @{}
        foreach ($i in $chosen) {
            $c = [string](Get-ObjectValue $sel[$i] 'Komputer')
            if (-not $per.ContainsKey($c)) { $per[$c] = @{ Pids = @() } }
            $per[$c].Pids += [int](Get-ObjectValue $sel[$i] 'PID')
        }
        Start-HostOperation -Module $m -Name 'Kończenie procesów' -Targets @($per.Keys) -PerTarget $per -Output Log -ScriptBlock {
            param($P)
            foreach ($id in $P.Pids) {
                try { $proc = Get-Process -Id $id -ErrorAction Stop; $name = $proc.ProcessName; Stop-Process -Id $id -Force -ErrorAction Stop; "Zakończono $name (PID $id)." }
                catch { "Błąd: PID $id – $($_.Exception.Message)" }
            }
        }
    }
    $m.EmptyHint = 'Zaznacz komputery i kliknij «Zmierz». Pomiar trwa tyle, ile ustawiono (domyślnie 10 s); zaznacz «Monitoruj», aby obserwować serwer na bieżąco.'
}
#endregion

#region Zarządzanie zdalne: logi aplikacji z wielu komputerów (oś czasu, porównanie, pliki)
# Blok na komputerze docelowym: znajduje pliki logów wg ścieżki/maski, czyta koniec pliku (bez blokowania pliku
# zapisywanego przez aplikację), rozpoznaje format daty w liniach, skleja linie bez daty (np. stos wywołań)
# z poprzednim wpisem i zwraca wpisy z zadanego zakresu (ostatnie N wpisów albo okno czasu).
# Wynik: __kind = 'line' (wpis) i 'file' (informacja o pliku).
$script:LogReadScript = {
    param($P)
    $ErrorActionPreference = 'Stop'
    $spec = [Environment]::ExpandEnvironmentVariables(([string]$P.Path).Trim().Trim('"'))
    $maxBytes = [long]([Math]::Max(1, [int]$P.MaxMB)) * 1MB
    $maxEntries = [Math]::Max(10, [int]$P.MaxLines)
    $dir = $spec
    $masks = @('*.log', '*.txt')
    if ($spec -match '[\*\?]') {
        $dir = Split-Path -Path $spec -Parent
        $masks = @((Split-Path -Path $spec -Leaf) -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    }
    elseif (Test-Path -LiteralPath $spec -PathType Leaf) {
        $dir = Split-Path -Path $spec -Parent
        $masks = @(Split-Path -Path $spec -Leaf)
    }
    if (-not $dir -or -not (Test-Path -LiteralPath $dir -PathType Container)) {
        return [pscustomobject]@{ __kind = 'file'; Path = $spec; SizeKB = $null; Modified = $null; Encoding = ''; Range = ''; Entries = 0; TimeFormat = ''; Note = 'Folder nie istnieje albo brak dostępu' }
    }
    $now = Get-Date
    $since = $null
    $until = $null
    switch ([string]$P.Mode) {
        'Minutes' { $since = $now.AddMinutes( - [int]$P.Value) }
        'Hours' { $since = $now.AddHours( - [int]$P.Value) }
        'Range' { if ($P.From) { $since = [datetime]$P.From }; if ($P.To) { $until = [datetime]$P.To } }
    }
    $found = @{}
    foreach ($mask in $masks) {
        foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter $mask -File -Recurse:([bool]$P.Recurse) -ErrorAction SilentlyContinue)) { $found[$f.FullName] = $f }
    }
    $files = @($found.Values | Sort-Object LastWriteTime -Descending)
    if ($since) { $files = @($files | Where-Object { $_.LastWriteTime -ge $since }) }
    if ($P.Files -eq 'Newest') { $files = @($files | Select-Object -First 1) } else { $files = @($files | Select-Object -First ([Math]::Max(1, [int]$P.MaxFiles))) }
    if ($files.Count -eq 0) {
        return [pscustomobject]@{ __kind = 'file'; Path = (Join-Path $dir ($masks -join ';')); SizeKB = $null; Modified = $null; Encoding = ''; Range = ''; Entries = 0; TimeFormat = ''; Note = $(if ($since) { 'Brak plików zmienionych w wybranym okresie' } else { 'Brak plików pasujących do maski' }) }
    }

    # Formaty dat na początku linii (w pierwszych 60 znakach); kolejność grup: rok, miesiąc, dzień, godz., min, s, ułamek
    $months = @{ jan = 1; feb = 2; mar = 3; apr = 4; may = 5; jun = 6; jul = 7; aug = 8; sep = 9; oct = 10; nov = 11; dec = 12 }
    $formats = @(
        @{ Name = 'RRRR-MM-DD gg:mm:ss'; Rx = [regex]'^.{0,60}?(?<y>\d{4})-(?<mo>\d{2})-(?<d>\d{2})[ T](?<h>\d{2}):(?<mi>\d{2}):(?<s>\d{2})(?:[\.,](?<f>\d{1,7}))?' }
        @{ Name = 'RRRR/MM/DD gg:mm:ss'; Rx = [regex]'^.{0,60}?(?<y>\d{4})/(?<mo>\d{2})/(?<d>\d{2})[ T](?<h>\d{2}):(?<mi>\d{2}):(?<s>\d{2})(?:[\.,](?<f>\d{1,7}))?' }
        @{ Name = 'DD.MM.RRRR gg:mm:ss'; Rx = [regex]'^.{0,60}?(?<d>\d{2})\.(?<mo>\d{2})\.(?<y>\d{4})[ T,]+(?<h>\d{1,2}):(?<mi>\d{2}):(?<s>\d{2})(?:[\.,](?<f>\d{1,7}))?' }
        @{ Name = 'MM/DD/RRRR gg:mm:ss'; Rx = [regex]'^.{0,60}?(?<mo>\d{1,2})/(?<d>\d{1,2})/(?<y>\d{4})[ T](?<h>\d{1,2}):(?<mi>\d{2}):(?<s>\d{2})(?:[\.,](?<f>\d{1,7}))?(?:\s*(?<ap>[AP]M))?' }
        @{ Name = 'DD/Mon/RRRR:gg:mm:ss'; Rx = [regex]'^.{0,60}?(?<d>\d{2})/(?<mon>[A-Za-z]{3})/(?<y>\d{4}):(?<h>\d{2}):(?<mi>\d{2}):(?<s>\d{2})' }
    )
    $toDate = {
        param($m)
        try {
            $mo = if ($m.Groups['mon'].Success) { $months[$m.Groups['mon'].Value.ToLowerInvariant()] } else { [int]$m.Groups['mo'].Value }
            $h = [int]$m.Groups['h'].Value
            if ($m.Groups['ap'].Success) { if ($m.Groups['ap'].Value -eq 'PM' -and $h -lt 12) { $h += 12 } elseif ($m.Groups['ap'].Value -eq 'AM' -and $h -eq 12) { $h = 0 } }
            $dt = New-Object DateTime ([int]$m.Groups['y'].Value), $mo, ([int]$m.Groups['d'].Value), $h, ([int]$m.Groups['mi'].Value), ([int]$m.Groups['s'].Value)
            if ($m.Groups['f'].Success) { $dt = $dt.AddTicks([long]($m.Groups['f'].Value.PadRight(7, '0'))) }
            return $dt
        }
        catch { return $null }
    }
    $levelOf = {
        param([string]$line)
        $head = if ($line.Length -gt 240) { $line.Substring(0, 240) } else { $line }
        if ($head -match '(?i)\b(fatal|critical|crit|krytyczn\w*)\b') { return 'Krytyczny' }
        if ($head -match '(?i)\b(error|err|exception|failed|failure|błąd|blad)\b') { return 'Błąd' }
        if ($head -match '(?i)\b(warn|warning|ostrzeżenie)\b') { return 'Ostrzeżenie' }
        if ($head -match '(?i)\b(debug|trace|verbose|dbg)\b') { return 'Debug' }
        return 'Info'
    }
    $include = [string]$P.Include
    $exclude = [string]$P.Exclude
    $test = {
        param([string]$text, [string]$level)
        if ($P.ErrorsOnly -and @('Krytyczny', 'Błąd', 'Ostrzeżenie') -notcontains $level -and $text -notmatch '(?i)exception') { return $false }
        if ($include) {
            if ($P.Regex) { if ($text -notmatch $include) { return $false } }
            elseif ($text.IndexOf($include, [StringComparison]::OrdinalIgnoreCase) -lt 0) { return $false }
        }
        if ($exclude) {
            if ($P.Regex) { if ($text -match $exclude) { return $false } }
            elseif ($text.IndexOf($exclude, [StringComparison]::OrdinalIgnoreCase) -ge 0) { return $false }
        }
        return $true
    }

    $all = New-Object System.Collections.ArrayList
    foreach ($file in $files) {
        $note = ''
        $encName = ''
        $partial = $false
        $lines = @()
        try {
            $fs = New-Object System.IO.FileStream($file.FullName, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
            try {
                $len = $fs.Length
                $headBytes = New-Object byte[] 4
                $n = $fs.Read($headBytes, 0, 4)
                $enc = $null
                $bom = 0
                if ($n -ge 3 -and $headBytes[0] -eq 0xEF -and $headBytes[1] -eq 0xBB -and $headBytes[2] -eq 0xBF) { $enc = New-Object System.Text.UTF8Encoding $false; $bom = 3 }
                elseif ($n -ge 2 -and $headBytes[0] -eq 0xFF -and $headBytes[1] -eq 0xFE) { $enc = [System.Text.Encoding]::Unicode; $bom = 2 }
                elseif ($n -ge 2 -and $headBytes[0] -eq 0xFE -and $headBytes[1] -eq 0xFF) { $enc = [System.Text.Encoding]::BigEndianUnicode; $bom = 2 }
                $start = [Math]::Max([long]$bom, $len - $maxBytes)
                $wide = ($enc -and $enc.GetByteCount('a') -eq 2)
                if ($wide -and (($start - $bom) % 2) -ne 0) { $start++ }
                $partial = ($start -gt $bom)
                $count = [int]($len - $start)
                $buf = New-Object byte[] $count
                $fs.Position = $start
                $read = 0
                while ($read -lt $count) { $r = $fs.Read($buf, $read, $count - $read); if ($r -le 0) { break }; $read += $r }
            }
            finally { $fs.Dispose() }
            # Początek od środka pliku: pomijamy niepełną pierwszą linię (do pierwszego znaku końca linii)
            $offset = 0
            if ($partial) {
                if ($wide) { for ($i = 0; $i + 1 -lt $read; $i += 2) { if (($buf[$i] -eq 10 -and $buf[$i + 1] -eq 0) -or ($buf[$i] -eq 0 -and $buf[$i + 1] -eq 10)) { $offset = $i + 2; break } } }
                else { $i = [Array]::IndexOf($buf, [byte]10); if ($i -ge 0 -and $i -lt $read) { $offset = $i + 1 } }
            }
            if (-not $enc) {
                try { $text = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($buf, $offset, $read - $offset); $encName = 'UTF-8' }
                catch {
                    $ansi = [System.Text.Encoding]::GetEncoding([System.Globalization.CultureInfo]::CurrentCulture.TextInfo.ANSICodePage)
                    $text = $ansi.GetString($buf, $offset, $read - $offset)
                    $encName = $ansi.WebName
                }
            }
            else { $text = $enc.GetString($buf, $offset, $read - $offset); $encName = $enc.WebName }
            $lines = $text -split "\r?\n"
        }
        catch {
            [void]$all.Add([pscustomobject]@{ __kind = 'file'; Path = $file.FullName; SizeKB = [Math]::Round($file.Length / 1KB); Modified = $file.LastWriteTime; Encoding = ''; Range = ''; Entries = 0; TimeFormat = ''; Note = 'Nie można odczytać: ' + $_.Exception.Message })
            continue
        }
        # Format daty: ten, który pasuje do największej liczby z pierwszych niepustych linii
        $fmt = $null
        $best = 0
        $probe = @($lines | Where-Object { $_.Trim() } | Select-Object -First 60)
        foreach ($f in $formats) {
            $hits = @($probe | Where-Object { $f.Rx.IsMatch($_) }).Count
            if ($hits -gt $best) { $best = $hits; $fmt = $f }
        }
        $entries = New-Object System.Collections.ArrayList
        $cont = New-Object System.Collections.ArrayList
        $truncated = $false
        for ($i = $lines.Count - 1; $i -ge 0; $i--) {
            $line = $lines[$i]
            if (-not $line.Trim()) { continue }
            $ts = $null
            $head = $line
            if ($fmt) {
                $mt = $fmt.Rx.Match($line)
                if ($mt.Success) {
                    $ts = & $toDate $mt
                    # Treść bez daty (jest w osobnej kolumnie) - z zachowaniem tego, co stało przed datą (np. poziom)
                    $core = @('y', 'mo', 'd', 'mon' | ForEach-Object { $mt.Groups[$_] } | Where-Object { $_.Success } | ForEach-Object { $_.Index } | Measure-Object -Minimum).Minimum
                    $head = ($line.Substring(0, [int]$core) + ' ' + $line.Substring($mt.Index + $mt.Length)) -replace '^\s*[\[\(]?\s*[\]\)]?\s*[-|:,]?\s*', ''
                }
                if ($null -eq $ts) {
                    # Linia bez daty: ciąg dalszy wpisu powyżej (stos wywołań, wielowierszowy komunikat)
                    if ($cont.Count -lt 300) { $cont.Insert(0, $line) }
                    continue
                }
            }
            $textOut = if ($cont.Count) { $line + "`n" + ((@($cont)) -join "`n") } else { $line }
            $message = if ($cont.Count) { $head + "`n" + ((@($cont)) -join "`n") } else { $head }
            $cont.Clear()
            if ($since -and $ts -and $ts -lt $since) { break }
            if ($until -and $ts -and $ts -gt $until) { continue }
            $level = & $levelOf $line
            if (-not (& $test $textOut $level)) { continue }
            if ($textOut.Length -gt 8000) { $textOut = $textOut.Substring(0, 8000) + '…' }
            if ($message.Length -gt 8000) { $message = $message.Substring(0, 8000) + '…' }
            [void]$entries.Add([pscustomobject]@{
                    __kind = 'line'; File = $file.Name; Path = $file.FullName; Line = $(if ($partial) { $null } else { $i + 1 }); Time = $ts; Level = $level; Text = $textOut; Message = $message
                })
            if ($P.Mode -eq 'Lines' -and $entries.Count -ge [int]$P.Value) { break }
            if ($entries.Count -ge $maxEntries) { $truncated = $true; break }
        }
        $entries.Reverse()
        foreach ($e in $entries) { [void]$all.Add($e) }
        $range = if ($partial) { 'ostatnie {0} MB' -f [Math]::Round($maxBytes / 1MB) } else { 'cały plik' }
        if ($truncated) { $note = "osiągnięto limit $maxEntries wpisów – pokazano najnowsze" }
        [void]$all.Add([pscustomobject]@{
                __kind = 'file'; Path = $file.FullName; SizeKB = [Math]::Round($file.Length / 1KB); Modified = $file.LastWriteTime; Encoding = $encName; Range = $range; Entries = $entries.Count
                TimeFormat = $(if ($fmt) { $fmt.Name } else { 'nie rozpoznano – kolejność z pliku' }); Note = $note
            })
    }
    # Limit na komputer: najnowsze wpisy ze wszystkich plików
    $lineObjs = @($all | Where-Object { $_.__kind -eq 'line' })
    if ($lineObjs.Count -gt $maxEntries) {
        $keep = @($lineObjs | Sort-Object @{ Expression = { if ($_.Time) { $_.Time } else { [datetime]::MinValue } } } -Descending | Select-Object -First $maxEntries)
        $lineObjs = $keep
    }
    $lineObjs
    @($all | Where-Object { $_.__kind -eq 'file' })
}

$script:LogLevelOrder = @{ 'Krytyczny' = 0; 'Błąd' = 1; 'Ostrzeżenie' = 2; 'Info' = 3; 'Debug' = 4 }
$script:LogViews = @('Oś czasu', 'Porównanie komputerów', 'Pliki')

function Get-LogPattern {
    # Wzorzec komunikatu do porównania między komputerami: bez dat, godzin, liczb, identyfikatorów GUID,
    # wartości szesnastkowych i adresów IP (te same zdarzenia z różnymi parametrami dają ten sam wzorzec)
    param([string]$Text)
    $t = ($Text -split "`n")[0]
    $t = $t -replace '(?i)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '<guid>'
    $t = $t -replace '\b\d{1,3}(\.\d{1,3}){3}(:\d+)?\b', '<ip>'
    $t = $t -replace '\d{4}[-/.]\d{2}[-/.]\d{2}[ T]?(\d{1,2}:\d{2}(:\d{2})?([\.,]\d+)?)?(Z|[+-]\d{2}:?\d{2})?', ' '
    $t = $t -replace '\d{1,2}[./]\d{1,2}[./]\d{2,4}', ' '
    $t = $t -replace '\d{1,2}:\d{2}(:\d{2})?([\.,]\d+)?\s*(AM|PM)?', ' '
    $t = $t -replace '(?i)\b0x[0-9a-f]+\b', '<hex>'
    $t = $t -replace '(?i)\b[0-9a-f]{12,}\b', '<hex>'
    $t = $t -replace '\d+', '#'
    $t = ($t -replace '\s+', ' ').Trim(' ', '-', '|', ':', '[', ']')
    if ($t.Length -gt 260) { $t = $t.Substring(0, 260) + '…' }
    return $t
}

function Get-LogFirstLine([string]$Text) {
    $first = ($Text -split "`n")[0]
    $more = @($Text -split "`n").Count - 1
    if ($more -gt 0) { return ('{0}   ⏎ +{1} linii' -f $first, $more) }
    return $first
}

function Show-LogView {
    param([hashtable]$Module)
    $m = $Module
    $view = [Math]::Max(0, (Get-SegmentIndex $m.ViewSwitch))
    Reset-ResultTable -Module $m
    $computers = @($m.Data.Logs.Keys | Sort-Object)
    $allLines = New-Object System.Collections.ArrayList
    foreach ($c in $computers) { foreach ($l in $m.Data.Logs[$c].Lines) { [void]$allLines.Add(@{ C = $c; L = $l; P = $null }) } }
    if ($view -le 1 -or $m.Data.Pattern) { foreach ($x in $allLines) { $x.P = Get-LogPattern ([string]$x.L.Message) } }
    $tones = @{ 'Krytyczny' = 'crit'; 'Błąd' = 'crit'; 'Ostrzeżenie' = 'warn'; 'Info' = ''; 'Debug' = 'info' }
    $patternActive = [bool]$m.Data.Pattern
    $m.ClearPattern.Visibility = $(if ($patternActive -and $view -eq 0) { 'Visible' } else { 'Collapsed' })
    switch ($view) {
        0 {
            $items = @($allLines)
            if ($patternActive) { $items = @($items | Where-Object { $_.P -eq $m.Data.Pattern }) }
            $sorted = @($items | Sort-Object @{ Expression = { if ($_.L.Time) { [datetime]$_.L.Time } else { [datetime]::MaxValue } } }, @{ Expression = { $_.C } })
            $rows = foreach ($x in $sorted) {
                $l = $x.L
                [pscustomobject][ordered]@{
                    'Czas'     = $(if ($l.Time) { ([datetime]$l.Time).ToString('yyyy-MM-dd HH:mm:ss.fff') } else { '' })
                    'Komputer' = $x.C
                    'Poziom'   = $l.Level
                    'Treść'    = [string]$l.Message
                    'Plik'     = $l.File
                    'Linia'    = $l.Line
                    'Ścieżka'  = $l.Path
                    '__tone'   = $tones[[string]$l.Level]
                }
            }
            $rows = @($rows)
            if ($rows.Count) { Add-ResultRows -Module $m -Objects $rows -TargetColumn '' }
            $m.ResultHint = $(if ($patternActive) { "Tylko wpisy wzorca: $($m.Data.Pattern)" } else { 'Wpisy ze wszystkich komputerów w kolejności czasu • wielowierszowe wpisy (stos wywołań) w całości w panelu szczegółów' })
        }
        1 {
            $groups = @{}
            foreach ($x in $allLines) {
                $key = [string]$x.L.Level + '|' + $x.P
                if (-not $groups.ContainsKey($key)) { $groups[$key] = @{ Level = [string]$x.L.Level; Pattern = $x.P; Per = @{}; First = $null; Last = $null; Example = [string]$x.L.Message; Total = 0 } }
                $g = $groups[$key]
                $g.Total++
                $g.Per[$x.C] = 1 + $(if ($g.Per.ContainsKey($x.C)) { $g.Per[$x.C] } else { 0 })
                if ($x.L.Time) {
                    $t = [datetime]$x.L.Time
                    if (-not $g.First -or $t -lt $g.First) { $g.First = $t }
                    if (-not $g.Last -or $t -gt $g.Last) { $g.Last = $t }
                }
            }
            $n = $computers.Count
            $ordered = @($groups.Values | Sort-Object @{ Expression = { $script:LogLevelOrder[$_.Level] } }, @{ Expression = { $_.Per.Count } }, @{ Expression = { $_.Total }; Descending = $true })
            $rows = foreach ($g in $ordered) {
                $k = $g.Per.Count
                $scope = if ($k -eq $n -and $n -gt 1) { "wszystkie ($k/$n)" } elseif ($k -eq 1) { 'tylko ' + @($g.Per.Keys)[0] } else { "część ($k/$n)" }
                            $o = [ordered]@{ 'Zasięg' = $scope; 'Poziom' = $g.Level; 'Wzorzec' = $g.Pattern; 'Razem' = $g.Total }
                foreach ($c in $computers) { $o[$c] = $(if ($g.Per.ContainsKey($c)) { $g.Per[$c] } else { 0 }) }
                $o['Pierwsze'] = $(if ($g.First) { $g.First.ToString('yyyy-MM-dd HH:mm:ss') } else { '' })
                $o['Ostatnie'] = $(if ($g.Last) { $g.Last.ToString('yyyy-MM-dd HH:mm:ss') } else { '' })
                $o['Przykład'] = $g.Example
                # Kolor: komunikat wszędzie - niebieski; błąd / ostrzeżenie nie wszędzie - czerwony / żółty; zwykłe informacje - bez koloru
                $o['__tone'] = $(if ($k -eq $n -and $n -gt 1) { 'info' } elseif (@('Krytyczny', 'Błąd') -contains $g.Level) { 'crit' } elseif ($g.Level -eq 'Ostrzeżenie') { 'warn' } else { '' })
                $o['__pattern'] = $g.Pattern
                [pscustomobject]$o
            }
            $rows = @($rows)
            if ($rows.Count) { Add-ResultRows -Module $m -Objects $rows -TargetColumn '' }
            $m.ResultHint = 'Te same komunikaty (bez dat, liczb i identyfikatorów) zliczone na każdym komputerze • «tylko …» / «część» – dzieje się nie wszędzie • prawy przycisk: wystąpienia na osi czasu'
        }
        2 {
            foreach ($c in $computers) {
                $rows = @($m.Data.Logs[$c].Files | ForEach-Object {
                        [pscustomobject][ordered]@{
                            'Plik' = $_.Path; 'Rozmiar KB' = $_.SizeKB; 'Zmieniony' = $(if ($_.Modified) { ([datetime]$_.Modified).ToString('yyyy-MM-dd HH:mm:ss') } else { '' })
                            'Wpisy' = $_.Entries; 'Odczyt' = $_.Range; 'Kodowanie' = $_.Encoding; 'Format daty' = $_.TimeFormat; 'Uwagi' = $_.Note
                            '__flag' = $(if ($_.Note -and [int]$_.Entries -eq 0) { 'warn' } else { '' })
                        }
                    })
                if ($rows.Count) { Add-ResultRows -Module $m -Computer $c -Objects $rows }
            }
            $m.ResultHint = 'Pliki przeczytane na każdym komputerze: rozmiar, data zmiany, rozpoznane kodowanie i format daty'
        }
    }
    foreach ($c in @($m.Data.LogErrors.Keys | Sort-Object)) {
        $col = @('Treść', 'Wzorzec', 'Plik')[$view]
        $o = [ordered]@{}
        if ($view -le 1) { $o['Komputer'] = $c }
        $o[$col] = 'Błąd odczytu: ' + $m.Data.LogErrors[$c]
        $o['__flag'] = 'crit'
        Add-ResultRows -Module $m -Computer $(if ($view -eq 2) { $c } else { '' }) -Objects @([pscustomobject]$o) -TargetColumn $(if ($view -eq 2) { 'Komputer' } else { '' })
    }
    if ($m.View_['resultHint']) { $m.View_['resultHint'].Text = $m.ResultHint }
    $lines = @($allLines)
    Set-StatTile -Module $m -Key 'lines' -Value ([string]$lines.Count)
    $err = @($lines | Where-Object { @('Krytyczny', 'Błąd') -contains [string]$_.L.Level }).Count
    $warn = @($lines | Where-Object { [string]$_.L.Level -eq 'Ostrzeżenie' }).Count
    Set-StatTile -Module $m -Key 'errors' -Value ([string]$err) -Tone $(if ($err) { 'crit' } else { '' })
    Set-StatTile -Module $m -Key 'warns' -Value ([string]$warn) -Tone $(if ($warn) { 'warn' } else { '' })
    $partialCount = 0
    if ($computers.Count -gt 1) {
        $seen = @{}
        foreach ($x in $lines) {
            if (@('Krytyczny', 'Błąd', 'Ostrzeżenie') -notcontains [string]$x.L.Level) { continue }
            $p = if ($x.P) { $x.P } else { Get-LogPattern ([string]$x.L.Message) }
            if (-not $seen.ContainsKey($p)) { $seen[$p] = @{} }
            $seen[$p][$x.C] = $true
        }
        $partialCount = @($seen.Values | Where-Object { $_.Count -lt $computers.Count }).Count
    }
    Set-StatTile -Module $m -Key 'partial' -Value ([string]$partialCount) -Tone $(if ($partialCount) { 'warn' } else { '' })
}

function Get-LogQuery {
    # Parametry odczytu z panelu; $null, gdy dane są niepoprawne (komunikat już pokazany)
    param([hashtable]$Module)
    $m = $Module
    $path = $m.Path.Text.Trim().Trim('"')
    if (-not $path) { Show-Warning 'Podaj ścieżkę do pliku, folderu albo maskę, np. C:\ProgramData\Firma\Aplikacja\Logs\*.log'; return $null }
    $mode = @('Lines', 'Minutes', 'Hours', 'Range')[$m.Range.SelectedIndex]
    $q = @{
        Path = $path; Recurse = (Test-Checked $m.Recurse); Files = @('Newest', 'All')[$m.Files.SelectedIndex]; Mode = $mode; Value = (Get-Num $m.Value)
        From = $null; To = $null; Include = $m.Include.Text.Trim(); Exclude = $m.Exclude.Text.Trim(); Regex = (Test-Checked $m.Regex); ErrorsOnly = (Test-Checked $m.ErrorsOnly)
        MaxLines = (Get-Num $m.MaxLines); MaxMB = 20; MaxFiles = 30
    }
    if ($mode -eq 'Range') {
        $culture = [System.Globalization.CultureInfo]::InvariantCulture
        foreach ($k in 'From', 'To') {
            $box = if ($k -eq 'From') { $m.From } else { $m.To }
            $t = $box.Text.Trim()
            if (-not $t) { continue }
            $d = [datetime]::MinValue
            if (-not [datetime]::TryParseExact($t, [string[]]@('yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm', 'yyyy-MM-dd'), $culture, 'None', [ref]$d)) { Show-Warning "Data «$t»: użyj formatu RRRR-MM-DD gg:mm, np. 2026-10-02 14:30."; return $null }
            $q[$k] = $d
        }
        if (-not $q.From -and -not $q.To) { Show-Warning 'Podaj początek i/lub koniec przedziału.'; return $null }
    }
    if ($q.Regex) {
        foreach ($rx in @($q.Include, $q.Exclude) | Where-Object { $_ }) {
            try { [void][regex]::new($rx) } catch { Show-Warning "Niepoprawne wyrażenie regularne «$rx»: $($_.Exception.Message)"; return $null }
        }
    }
    return $q
}

function Start-LogRead {
    param([hashtable]$Module, [string[]]$Targets, [hashtable]$Query)
    $m = $Module
    $m.Data.LastTargets = @($Targets)
    $m.Data.LastQuery = $Query
    $m.Data.Logs = @{}
    $m.Data.LogErrors = @{}
    $recent = @(@($Query.Path) + @(Get-ModuleSetting -Module $m -Name 'Paths' -Default @()) | Where-Object { $_ } | Select-Object -Unique | Select-Object -First 12)
    Set-ModuleSetting -Module $m -Name 'Paths' -Value $recent
    Start-HostOperation -Module $m -Name 'Logi' -Targets $Targets -Output None -Parameters $Query -ScriptBlock $script:LogReadScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) { $m.Data.LogErrors[$r.Target] = ((@($r.Errors | Select-Object -Unique)) -join ' | ') }
        else {
            $all = @($r.Data)
            $m.Data.Logs[$r.Target] = @{ Lines = @($all | Where-Object { $_.__kind -eq 'line' }); Files = @($all | Where-Object { $_.__kind -eq 'file' }) }
        }
        Show-LogView -Module $m
    } -OnComplete {
        param($m)
        $total = 0
        foreach ($v in $m.Data.Logs.Values) { $total += @($v.Lines).Count }
        Write-Log ("Logi: {0} wpisów z {1} komputer(ów)." -f $total, $m.Data.Logs.Count) 'OK'
        if (Test-Checked $m.Follow) {
            if (-not $m.Data['FollowTimer']) {
                $t = New-Object System.Windows.Threading.DispatcherTimer
                $t.Interval = [TimeSpan]::FromSeconds(15)
                $t.Tag = $m
                $t.add_Tick({
                        param($s, $e)
                        $s.Stop()
                        $mm = $s.Tag
                        if ((Test-Checked $mm.Follow) -and -not $mm.Busy -and @($mm.Data.LastTargets).Count) { Invoke-UiAction -Module $mm -Action { param($m) Start-LogRead -Module $m -Targets $m.Data.LastTargets -Query $m.Data.LastQuery } }
                    })
                $m.Data.FollowTimer = $t
            }
            $m.Data.FollowTimer.Start()
        }
    }
}

Register-Module -Workspace 'Remote' -Category 'Diagnostyka' -Key 'AppLogs' -Title 'Logi aplikacji' -Icon 'E7C3' -Badge 'nowe' `
    -Description 'Pliki logów aplikacji (np. w ProgramData) z wielu komputerów naraz: wspólna oś czasu, porównanie komunikatów między komputerami (czy dzieje się wszędzie, czy na jednym), filtrowanie i śledzenie na bieżąco.' -Build {
    param($m)
    $m.PillColumns = @('Poziom', 'Zasięg')
    $m.Data.Logs = @{}
    $m.Data.LogErrors = @{}
    $m.Data.Pattern = ''
    $m.Data.LastTargets = @()
    $m.Data.LastQuery = $null
    $m.Data.FollowTimer = $null
    $row = Add-ToolbarRow -Module $m -Title 'Pliki'
    $m.Path = Add-TextBox -Parent $row -Width 470 -Placeholder 'np. %ProgramData%\Firma\Aplikacja\Logs\*.log  albo folder / plik'
    $m.Path.Text = [string](@(Get-ModuleSetting -Module $m -Name 'Paths' -Default @()) | Select-Object -First 1)
    Add-Button -Parent $row -Text 'Przeglądaj…' -Icon 'E8B7' -Module $m -AlwaysEnabled -ToolTip 'Foldery na pierwszym zaznaczonym komputerze' -OnClick {
        param($m)
        $first = @(Get-TargetComputers) | Select-Object -First 1
        if (-not $first) { return }
        $current = $m.Path.Text.Trim()
        $dir = if ($current -match '[\*\?]') { Split-Path -Path $current -Parent } else { $current }
        $folder = Select-RemoteFolder -Computer $first -Selected $dir -Title "Folder logów na komputerze $first"
        if ($folder) { $m.Path.Text = (Join-Path $folder '*.log') }
    } | Out-Null
    Add-Button -Parent $row -Text '' -Icon 'E81C' -Module $m -AlwaysEnabled -ToolTip 'Ostatnio używane ścieżki' -OnClick {
        param($m)
        $recent = @(Get-ModuleSetting -Module $m -Name 'Paths' -Default @())
        if ($recent.Count -eq 0) { Show-Message -Text 'Brak zapamiętanych ścieżek – pojawią się po pierwszym odczycie.' -Title 'Ostatnie ścieżki'; return }
        $pick = Show-FormDialog -Title 'Ostatnie ścieżki' -Icon 'E81C' -Fields @(@{ Key = 'P'; Label = 'Ścieżka'; Type = 'Combo'; Items = $recent; Value = $recent[0] })
        if ($pick) { $m.Path.Text = $pick.P }
    } | Out-Null
    $m.Recurse = Add-CheckBox -Parent $row -Text 'Podfoldery'
    Add-Label -Parent $row -Text 'Pliki' | Out-Null
    $m.Files = Add-ComboBox -Parent $row -Items @('najnowszy', 'wszystkie pasujące') -Width 170
    $row2 = Add-ToolbarRow -Module $m -Title 'Zakres'
    $m.Range = Add-ComboBox -Parent $row2 -Items @('ostatnie wpisy (liczba)', 'ostatnie minuty', 'ostatnie godziny', 'przedział od – do') -Width 210
    $m.Value = Add-Numeric -Parent $row2 -Value 200 -Minimum 1 -Maximum 100000 -Width 80
    $m.From = Add-TextBox -Parent $row2 -Width 150 -Placeholder 'od RRRR-MM-DD gg:mm'
    $m.To = Add-TextBox -Parent $row2 -Width 150 -Placeholder 'do (puste = teraz)'
    Register-ControlHandler -Control $m.Range -EventName 'SelectionChanged' -Module $m -Action {
        param($m)
        $isRange = ($m.Range.SelectedIndex -eq 3)
        $m.From.IsEnabled = $isRange
        $m.To.IsEnabled = $isRange
        $m.Value.IsEnabled = -not $isRange
        if (-not $isRange) { $m.Value.Text = [string](@(200, 30, 4)[$m.Range.SelectedIndex]) }
    }
    $m.From.IsEnabled = $false
    $m.To.IsEnabled = $false
    Add-Label -Parent $row2 -Text '   Limit wpisów na komputer' | Out-Null
    $m.MaxLines = Add-Numeric -Parent $row2 -Value 3000 -Minimum 10 -Maximum 50000 -Width 80
    $row3 = Add-ToolbarRow -Module $m -Title 'Filtr'
    $m.Include = Add-TextBox -Parent $row3 -Width 230 -Placeholder 'zawiera (np. timeout)'
    $m.Exclude = Add-TextBox -Parent $row3 -Width 200 -Placeholder 'pomiń wpisy zawierające'
    $m.Regex = Add-CheckBox -Parent $row3 -Text 'Wyrażenia regularne'
    $m.ErrorsOnly = Add-CheckBox -Parent $row3 -Text 'Tylko błędy i ostrzeżenia'
    $row4 = Add-ToolbarRow -Module $m -Title 'Widok'
    $m.ViewSwitch = Add-Segmented -Parent $row4 -Items $script:LogViews -Module $m -OnChange { param($m) Show-LogView -Module $m }
    Add-Button -Parent $row4 -Text 'Wczytaj logi' -Icon 'E896' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $q = Get-LogQuery -Module $m
        if (-not $q) { return }
        $m.Data.Pattern = ''
        Start-LogRead -Module $m -Targets $targets -Query $q
    } | Out-Null
    $m.Follow = Add-CheckBox -Parent $row4 -Text 'Śledź (odświeżaj co 15 s)'
    $m.ClearPattern = Add-Button -Parent $row4 -Text 'Pokaż wszystkie wpisy' -Icon 'E894' -Module $m -AlwaysEnabled -ToolTip 'Usuń filtr wzorca z osi czasu' -OnClick {
        param($m)
        $m.Data.Pattern = ''
        Show-LogView -Module $m
    }
    $m.ClearPattern.Visibility = 'Collapsed'
    Add-StatTile -Module $m -Key 'lines' -Label 'Wpisy' -Icon 'E8A5' | Out-Null
    Add-StatTile -Module $m -Key 'errors' -Label 'Błędy' -Icon 'EA39' | Out-Null
    Add-StatTile -Module $m -Key 'warns' -Label 'Ostrzeżenia' -Icon 'E7BA' | Out-Null
    Add-StatTile -Module $m -Key 'partial' -Label 'Błędy nie na wszystkich' -Icon 'E9D9' | Out-Null
    Add-RowAction -Module $m -Text 'Pokaż wystąpienia na osi czasu' -Icon 'E81C' -Action {
        param($m, $rows)
        $r = $rows[0]
        $pattern = [string](Get-ObjectValue $r '__pattern')
        if (-not $pattern) { $text = [string](Get-ObjectValue $r 'Treść'); if ($text -and $text -notlike 'Błąd odczytu*') { $pattern = Get-LogPattern $text } }
        if (-not $pattern) { return }
        $m.Data.Pattern = $pattern
        Set-SegmentIndex $m.ViewSwitch 0
        Show-LogView -Module $m
    }
    $m.EmptyHint = 'Podaj ścieżkę logów (np. %ProgramData%\Firma\App\Logs\*.log), zaznacz komputery i kliknij «Wczytaj logi». «Porównanie komputerów» pokaże, czy dany komunikat występuje wszędzie, czy tylko na części maszyn.'
}
#endregion

#region Active Directory: wspólne
# Operacje AD wykonywane są lokalnie w puli wątków modułem ActiveDirectory. Blok modułu dostaje gotową
# hashtablę $ad (Server, Credential, ErrorAction = Stop) do rozwinięcia w poleceniach: Get-ADUser ... @ad
# oraz funkcje pomocnicze z $script:AdHelpers (rozpoznawanie obiektów, nazwy z DN, filtry LDAP).
$script:AdHelpers = @'
function Get-DnName([string]$Dn) { return (([regex]::Match($Dn, '^(?:\\.|[^,])+').Value -replace '^[^=]+=', '') -replace '\\(.)', '$1') }
function Get-DnParent([string]$Dn) { return ($Dn -replace '^(?:\\.|[^,])+,', '') }
function ConvertTo-LdapValue([string]$Text) {
    $sb = New-Object System.Text.StringBuilder
    foreach ($ch in $Text.ToCharArray()) {
        switch ($ch) {
            '\' { [void]$sb.Append('\5c') }
            '*' { [void]$sb.Append('\2a') }
            '(' { [void]$sb.Append('\28') }
            ')' { [void]$sb.Append('\29') }
            ([char]0) { [void]$sb.Append('\00') }
            default { [void]$sb.Append($ch) }
        }
    }
    return $sb.ToString()
}
function Get-ScopeLabel($Scope) { switch ([string]$Scope) { 'Global' { 'Globalna' } 'DomainLocal' { 'Lokalna domeny' } 'Universal' { 'Uniwersalna' } default { [string]$Scope } } }
function Get-CategoryLabel($Category) { switch ([string]$Category) { 'Security' { 'Zabezpieczeń' } 'Distribution' { 'Dystrybucyjna' } default { [string]$Category } } }
function Get-ObjectKind([string]$Class) {
    switch ($Class) {
        'user' { 'Użytkownik' } 'computer' { 'Komputer' } 'group' { 'Grupa' } 'contact' { 'Kontakt' }
        'foreignSecurityPrincipal' { 'Obcy podmiot' } 'organizationalUnit' { 'OU' } 'inetOrgPerson' { 'Użytkownik' }
        'msDS-GroupManagedServiceAccount' { 'Konto usługi (gMSA)' } 'msDS-ManagedServiceAccount' { 'Konto usługi (MSA)' }
        default { $Class }
    }
}
function Resolve-AdPrincipal {
    # Użytkownik, komputer lub grupa po: sAMAccountName, nazwie komputera, UPN, e-mail, DN, SID, nazwie albo DOMENA\login.
    # Zwraca obiekt Get-ADObject; brak lub niejednoznaczność - wyjątek z opisem po polsku.
    param([string]$Id, [string[]]$Classes = @('user', 'group', 'computer'), [string[]]$Properties = @())
    $id = ([string]$Id).Trim().Trim('"')
    if (-not $id) { throw 'Pusty identyfikator.' }
    $props = @('sAMAccountName', 'objectSid', 'userAccountControl', 'groupType', 'displayName') + @($Properties)
    $classFilter = '(|' + ((@($Classes) | ForEach-Object { "(objectClass=$_)" }) -join '') + ')'
    if ($id -match '^(CN|OU)=.+,DC=') { return (Get-ADObject -Identity $id -Properties $props @ad) }
    if ($id -match '^S-1-\d+(-\d+)+$') {
        $found = @(Get-ADObject -LDAPFilter "(&$classFilter(objectSid=$id))" -Properties $props @ad)
        if ($found.Count -ge 1) { return $found[0] }
        throw "Nie znaleziono obiektu o SID $id."
    }
    if ($id -match '^[^\\]+\\(.+)$') { $id = $Matches[1] }
    $v = ConvertTo-LdapValue $id
    $filter = if ($id.Contains('@')) { "(&$classFilter(|(userPrincipalName=$v)(mail=$v)))" }
    else { "(&$classFilter(|(sAMAccountName=$v)(sAMAccountName=$v`$)(name=$v)(displayName=$v)))" }
    $found = @(Get-ADObject -LDAPFilter $filter -Properties $props @ad)
    if ($found.Count -eq 1) { return $found[0] }
    if ($found.Count -eq 0) { throw "Nie znaleziono «$id»." }
    foreach ($pref in @($id, "$id`$")) {
        $exact = @($found | Where-Object { [string]$_.sAMAccountName -ieq $pref })
        if ($exact.Count -eq 1) { return $exact[0] }
    }
    throw ("«$id» jest niejednoznaczne ({0} obiektów) – podaj sAMAccountName lub DN." -f $found.Count)
}
function Get-GroupMemberObjects {
    # Członkowie grupy zapytaniem po memberOf (bez limitu 5000 Get-ADGroupMember). -Recursive: także zagnieżdżeni.
    # -PrimaryRid: dołącza konta, dla których grupa jest podstawowa (np. Domain Users).
    param([string]$GroupDn, [switch]$Recursive, [string[]]$Properties = @(), [int]$PrimaryRid = 0)
    $v = ConvertTo-LdapValue $GroupDn
    $rule = if ($Recursive) { 'memberOf:1.2.840.113556.1.4.1941:' } else { 'memberOf' }
    $props = @('sAMAccountName', 'objectSid', 'userAccountControl', 'displayName', 'groupType') + @($Properties)
    $list = @(Get-ADObject -LDAPFilter "($rule=$v)" -Properties $props @ad)
    if ($PrimaryRid -gt 0) { $list += @(Get-ADObject -LDAPFilter "(primaryGroupID=$PrimaryRid)" -Properties $props @ad) }
    return $list
}
'@

# Funkcje tekstowe programu (transliteracja, sAMAccountName) dostępne także w wątkach operacji AD
foreach ($fn in 'ConvertTo-AsciiText', 'ConvertTo-SamName', 'Expand-Template', 'ConvertTo-RdnValue') {
    $script:AdHelpers += "`nfunction $fn {`n" + (Get-Item "function:$fn").ScriptBlock.ToString() + "`n}"
}

# Początek każdego bloku operacji AD (funkcje pomocnicze z $script:AdHelpers dołączane w chwili uruchomienia,
# więc kolejne regiony mogą je rozszerzać)
$script:AdPrelude = @'
Import-Module ActiveDirectory -ErrorAction Stop -Verbose:$false
$ad = @{ ErrorAction = 'Stop' }
if ($Ctx.Server) { $ad.Server = $Ctx.Server }
if ($Ctx.Credential) { $ad.Credential = $Ctx.Credential }
# Odczyty z AD ponawiane przy przejściowych błędach usługi ADWS (przeciążony kontroler, wygasły kontekst wyliczania).
# Polecenia Get-AD* są tu zastępowane funkcjami o tej samej nazwie; zmiany (Set/New/Add/Remove) nie są ponawiane.
$__adTransient = 'connection to the directory on which to process the request was unavailable|invalid enumeration context|enumeration context is (not valid|invalid)|Unable to contact the server|server is busy|timeout limit was exceeded'
function Invoke-AdRead {
    param([string]$Command, [object[]]$Arguments, [object[]]$Pipe, [bool]$HasPipe)
    $delays = @(500, 1500, 3000, 6000)
    for ($i = 0; ; $i++) {
        try {
            if ($HasPipe) { return @($Pipe | & $Command @Arguments) }
            return @(& $Command @Arguments)
        }
        catch {
            if ($i -ge $delays.Count -or $_.Exception.Message -notmatch $__adTransient) { throw }
            Start-Sleep -Milliseconds ($delays[$i] + (Get-Random -Maximum 500))
        }
    }
}
$__exported = (Get-Module -Name ActiveDirectory).ExportedCommands
foreach ($__c in 'Get-ADUser', 'Get-ADComputer', 'Get-ADGroup', 'Get-ADObject', 'Get-ADOrganizationalUnit', 'Get-ADGroupMember', 'Get-ADPrincipalGroupMembership',
    'Get-ADDomain', 'Get-ADForest', 'Get-ADRootDSE', 'Get-ADDomainController', 'Search-ADAccount', 'Get-ADDefaultDomainPasswordPolicy', 'Get-ADFineGrainedPasswordPolicy',
    'Get-ADUserResultantPasswordPolicy', 'Get-ADAccountAuthorizationGroup', 'Get-ADReplicationAttributeMetadata') {
    if (-not $__exported.ContainsKey($__c)) { continue }
    Set-Item -Path "function:$__c" -Value ([scriptblock]::Create("if (`$MyInvocation.ExpectingInput) { Invoke-AdRead 'ActiveDirectory\$__c' `$args @(`$input) `$true } else { Invoke-AdRead 'ActiveDirectory\$__c' `$args `$null `$false }"))
}
'@

function Get-FriendlyAdError {
    # Typowe komunikaty błędów AD (po angielsku) -> wskazówka po polsku; nieznane bez zmian
    param([string]$Message)
    $m = ([string]$Message).ToLowerInvariant()
    if ($m -match 'already.*(exist|in use|member)|name that is already in use|not unique') { return "Obiekt już istnieje (login, UPN lub nazwa w OU są zajęte). ($Message)" }
    if ($m -match 'access is denied|insufficient access') { return "Brak uprawnień w tej jednostce organizacyjnej. ($Message)" }
    if ($m -match 'password does not meet|password.*requirement|complexity') { return "Hasło nie spełnia zasad domeny (długość, złożoność, historia). ($Message)" }
    if ($m -match 'unwilling to process') { return "Kontroler domeny odrzucił żądanie – sprawdź hasło, wymagane atrybuty i UPN. ($Message)" }
    if ($m -match 'directory object not found|no such object|cannot find an object') { return "Nie znaleziono obiektu lub jednostki organizacyjnej. ($Message)" }
    if ($m -match 'naming violation|invalid dn syntax|bad name') { return "Niedozwolona nazwa (CN) – usuń znaki specjalne. ($Message)" }
    if ($m -match 'group type cannot be changed|cannot be converted|group scope') { return "Nie można zmienić zakresu grupy – koliduje z jej członkami lub przynależnością. ($Message)" }
    if ($m -match 'unable to contact|server is not operational|cannot contact') { return "Brak połączenia z kontrolerem domeny. ($Message)" }
    return $Message
}

function Test-AdAvailable {
    if (Get-Module -ListAvailable -Name ActiveDirectory) { return $true }
    Show-Warning 'Ta funkcja wymaga modułu ActiveDirectory (RSAT: Active Directory Domain Services). Zainstaluj RSAT i uruchom program ponownie.'
    return $false
}

function Start-AdOperation {
    # Start-HostOperation w trybie lokalnym z modułem ActiveDirectory i hashtablą $ad w bloku skryptu
    param(
        [Parameter(Mandatory)][hashtable]$Module,
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Targets,
        [Parameter(Mandatory)][scriptblock]$ScriptBlock,
        [hashtable]$Parameters = @{},
        [hashtable]$PerTarget = @{},
        [ValidateSet('Grid', 'Log', 'None')][string]$Output = 'Grid',
        [string]$TargetColumn = '',
        [switch]$Append,
        [scriptblock]$OnResult,
        [scriptblock]$OnComplete
    )
    if (-not (Test-AdAvailable)) { return }
    $text = 'param($Target, $P, $Ctx)' + "`n" + $script:AdPrelude + "`n" + $script:AdHelpers + "`n" + '$__body = {' + $ScriptBlock.ToString() + "`n}`n" + '& $__body $Target $P $Ctx'
    $sp = @{
        Module       = $Module
        Name         = $Name
        Targets      = $Targets
        ScriptBlock  = [scriptblock]::Create($text)
        Local        = $true
        Parameters   = $Parameters
        PerTarget    = $PerTarget
        Output       = $Output
        TargetColumn = $TargetColumn
        Append       = $Append
        Pool         = 'AD'
    }
    if ($OnResult) { $sp.OnResult = $OnResult }
    if ($OnComplete) { $sp.OnComplete = $OnComplete }
    Start-HostOperation @sp
}

function Add-ResultsToTargets {
    # Przenosi obiekty z tabeli wyników na listę po lewej (i zaznacza je) - most między raportami a operacjami
    param([hashtable]$Module, [ValidateSet('User', 'Computer', 'Group')][string]$Kind, [string]$Column, $Rows = $null)
    $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $Module })
    if ($source.Count -le 1 -and $null -eq $Rows) { $source = @($Module.View | ForEach-Object { $_ }) }
    $names = @($source | ForEach-Object { [string](Get-ObjectValue $_ $Column) } | Where-Object { $_ } | Select-Object -Unique)
    if ($names.Count -eq 0) { Show-Warning 'Brak obiektów do przeniesienia na listę.'; return }
    if ($Kind -eq 'User') {
        $items = foreach ($drv in $source) {
            $login = [string](Get-ObjectValue $drv $Column)
            if (-not $login) { continue }
            [pscustomobject]@{
                Login      = $login
                Name       = Get-ObjectValue $drv 'Nazwa'
                Enabled    = $(switch ([string](Get-ObjectValue $drv 'Włączone')) { 'Tak' { $true } 'Nie' { $false } default { $null } })
                Department = Get-ObjectValue $drv 'Dział'
                DN         = Get-ObjectValue $drv 'DN'
            }
        }
        $panel = $script:UI.UserPanel
        Set-TargetCheck -Panel $panel -Mode UncheckAll
        $added = Import-TargetRows -Panel $panel -Items @($items) -Source 'raport' -Check
    }
    elseif ($Kind -eq 'Group') {
        $items = foreach ($drv in $source) {
            $sam = [string](Get-ObjectValue $drv $Column)
            if (-not $sam) { continue }
            [pscustomobject]@{
                Sam         = $sam
                Name        = Get-ObjectValue $drv 'Nazwa'
                Scope       = Get-ObjectValue $drv 'Zakres'
                Category    = Get-ObjectValue $drv 'Typ'
                Description = Get-ObjectValue $drv 'Opis'
                DN          = $(if ($null -ne (Get-ObjectValue $drv 'DN grupy')) { Get-ObjectValue $drv 'DN grupy' } else { Get-ObjectValue $drv 'DN' })
            }
        }
        $panel = $script:UI.GroupPanel
        Set-TargetCheck -Panel $panel -Mode UncheckAll
        $added = Import-TargetRows -Panel $panel -Items @($items) -Source 'raport' -Check
    }
    else {
        $items = foreach ($drv in $source) {
            $name = [string](Get-ObjectValue $drv $Column)
            if (-not $name) { continue }
            [pscustomobject]@{ Name = $name; OS = Get-ObjectValue $drv 'System'; DN = Get-ObjectValue $drv 'DN' }
        }
        $panel = $script:UI.ComputerPanel
        Set-TargetCheck -Panel $panel -Mode UncheckAll
        $added = Import-TargetRows -Panel $panel -Items @($items) -Source 'raport' -Check
    }
    Show-Toast ("Na liście zaznaczono {0} obiektów (nowych: {1})." -f $names.Count, $added) 'ok'
}

function Get-LdapDate {
    # Data w formacie generalizedTime/LDAP do filtrów (np. whenCreated>=...)
    param([datetime]$Date)
    return $Date.ToUniversalTime().ToString('yyyyMMddHHmmss.0Z')
}

function Register-GroupMembershipModule {
    # Członkostwo w grupach - wspólny moduł dla użytkowników, komputerów i grup (zagnieżdżanie)
    param([string]$Workspace, [ValidateSet('User', 'Computer', 'Group')][string]$Kind, [string]$Key, [string]$Category, [string]$Title = 'Członkostwo w grupach')
    $desc = switch ($Kind) {
        'User' { 'Grupy zaznaczonych kont (bezpośrednie i zagnieżdżone), dodawanie do grup, usuwanie z zaznaczonych grup i kopiowanie członkostwa z konta wzorcowego.' }
        'Computer' { 'Grupy zaznaczonych kont komputerów (bezpośrednie i zagnieżdżone), dodawanie do grup i usuwanie z zaznaczonych grup.' }
        default { 'Do jakich grup należą zaznaczone grupy (zagnieżdżanie): bezpośrednio i przez inne grupy. Dodawanie zaznaczonych grup do innych grup i usuwanie z nich.' }
    }
    $build = {
        param($m)
        $m.PillColumns = @('Członkostwo')
        $m.Data.Column = switch ($m.Target) { 'User' { 'Login' } 'Group' { 'Członek' } default { 'Komputer' } }
        $m.Actions.Targets = {
            param($m)
            if ($m.Target -eq 'User') { return @(Get-TargetUsers) }
            if ($m.Target -eq 'Group') { return @(Get-TargetGroups) }
            return @(Get-TargetComputers | ForEach-Object { ($_ -split '\.')[0] })
        }
        $m.Actions.List = {
            param($m)
            $targets = @(& $m.Actions.Targets $m)
            if (-not $targets) { return }
            Start-AdOperation -Module $m -Name 'Grupy' -Targets $targets -TargetColumn $m.Data.Column -Parameters @{ Nested = (Test-Checked $m.Nested); Kind = $m.Target } -ScriptBlock {
                $obj = switch ($P.Kind) {
                    'User' { Get-ADUser -Identity $Target -Properties memberOf, PrimaryGroupID @ad }
                    'Group' { Get-ADGroup -Identity $Target -Properties memberOf @ad }
                    default { Get-ADComputer -Identity $Target -Properties memberOf, PrimaryGroupID @ad }
                }
                $direct = @{}
                foreach ($dn in @($obj.memberOf)) { $direct[[string]$dn] = $true }
                $groups = @()
                if ($P.Nested) { $groups = @(Get-ADGroup -LDAPFilter ("(member:1.2.840.113556.1.4.1941:={0})" -f $obj.DistinguishedName) -Properties Description @ad) }
                else { $groups = @($obj.memberOf | ForEach-Object { Get-ADGroup -Identity $_ -Properties Description @ad }) }
                # Grupa podstawowa (Domain Users / Domain Computers) nie występuje w memberOf
                if ($P.Kind -ne 'Group') { try {
                    $domainSid = $obj.SID.AccountDomainSid.Value
                    $primary = Get-ADGroup -Identity ('{0}-{1}' -f $domainSid, $obj.PrimaryGroupID) -Properties Description @ad
                    if ($primary) { $groups += $primary; $direct[$primary.DistinguishedName] = $true }
                }
                catch { } }
                foreach ($g in ($groups | Sort-Object Name -Unique)) {
                    $isDirect = $direct.ContainsKey([string]$g.DistinguishedName)
                    [pscustomobject]@{
                        'Grupa'       = $g.Name
                        'Członkostwo' = $(if ($g.SID.Value -match '-(513|515)$' -and $isDirect) { 'Podstawowa' } elseif ($isDirect) { 'Bezpośrednie' } else { 'Zagnieżdżone' })
                        'Zakres'      = Get-ScopeLabel $g.GroupScope
                        'Typ'         = Get-CategoryLabel $g.GroupCategory
                        'Opis'        = $g.Description
                        'DN grupy'    = $g.DistinguishedName
                        '__tone'      = $(if ($isDirect) { 'info' } else { '' })
                    }
                }
            }
        }
        $m.Actions.Add = {
            param($m, [object[]]$Groups)
            $targets = @(& $m.Actions.Targets $m)
            if (-not $targets) { return }
            if (-not $Groups) {
                $Groups = Select-AdGroups -Title 'Dodaj do grup' -Subtitle "Zaznaczone obiekty ($($targets.Count)) zostaną dodane do wybranych grup."
                if (-not $Groups) { return }
            }
            $names = @($Groups | ForEach-Object { $_.Name })
            $targets = @(Confirm-Action -Text ("Dodać wybrane obiekty do grup: {0}?" -f ($names -join ', ')) -Items $targets -ConfirmText 'Dodaj do grup' -Select); if ($targets.Count -eq 0) { return }
            Start-AdOperation -Module $m -Name 'Dodawanie do grup' -Targets $targets -TargetColumn $m.Data.Column -Output Log -Parameters @{ Groups = @($Groups | ForEach-Object { $_.DN }); Kind = $m.Target } -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
                $obj = switch ($P.Kind) { 'User' { Get-ADUser -Identity $Target @ad } 'Group' { Get-ADGroup -Identity $Target @ad } default { Get-ADComputer -Identity $Target @ad } }
                foreach ($g in $P.Groups) {
                    try {
                        Add-ADGroupMember -Identity $g -Members $obj @ad
                        [pscustomobject]@{ 'Obiekt' = $Target; 'Grupa' = ($g -replace '^CN=((?:\\.|[^,])+),.*$', '$1'); 'Wynik' = 'Dodano' }
                    }
                    catch { [pscustomobject]@{ 'Obiekt' = $Target; 'Grupa' = ($g -replace '^CN=((?:\\.|[^,])+),.*$', '$1'); 'Wynik' = "Błąd – $($_.Exception.Message)" } }
                }
            }
        }
        $m.Actions.Remove = {
            param($m, $Rows)
            $byObj = Get-SelectedRowsByHost -Module $m -Columns @('DN grupy', 'Grupa', 'Członkostwo') -Rows $Rows -TargetColumn $m.Data.Column
            $per = @{}
            $items = @()
            foreach ($o in $byObj.Keys) {
                $groups = @($byObj[$o] | Where-Object { $_['Członkostwo'] -eq 'Bezpośrednie' })
                if ($groups.Count -eq 0) { continue }
                $per[$o] = @{ Groups = @($groups | ForEach-Object { [string]$_['DN grupy'] }); Kind = $m.Target }
                foreach ($g in $groups) { $items += ('{0}: {1}' -f $o, $g['Grupa']) }
            }
            if ($per.Count -eq 0) { Show-Warning 'Zaznacz w tabeli grupy z członkostwem bezpośrednim (zagnieżdżonego i podstawowego nie da się usunąć z tego miejsca).'; return }
            if (-not (Confirm-Action -Text 'Usunąć obiekty z wybranych grup?' -Items $items -ConfirmText 'Usuń z grup' -Danger)) { return }
            Start-AdOperation -Module $m -Name 'Usuwanie z grup' -Targets @($per.Keys) -PerTarget $per -TargetColumn $m.Data.Column -Output Log -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
                $obj = switch ($P.Kind) { 'User' { Get-ADUser -Identity $Target @ad } 'Group' { Get-ADGroup -Identity $Target @ad } default { Get-ADComputer -Identity $Target @ad } }
                foreach ($g in $P.Groups) {
                    try {
                        Remove-ADGroupMember -Identity $g -Members $obj -Confirm:$false @ad
                        [pscustomobject]@{ 'Obiekt' = $Target; 'Grupa' = ($g -replace '^CN=((?:\\.|[^,])+),.*$', '$1'); 'Wynik' = 'Usunięto' }
                    }
                    catch { [pscustomobject]@{ 'Obiekt' = $Target; 'Grupa' = ($g -replace '^CN=((?:\\.|[^,])+),.*$', '$1'); 'Wynik' = "Błąd – $($_.Exception.Message)" } }
                }
            }
        }
        $row = Add-ToolbarRow -Module $m -Title 'Lista'
        $m.Nested = Add-CheckBox -Parent $row -Text 'Uwzględnij grupy zagnieżdżone' -ToolTip 'Pełne członkostwo (także przez inne grupy) – LDAP_MATCHING_RULE_IN_CHAIN'
        Add-Button -Parent $row -Text 'Pokaż grupy' -Icon 'E902' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
        $row2 = Add-ToolbarRow -Module $m -Title 'Zmiany'
        Add-Button -Parent $row2 -Text 'Dodaj do grup…' -Icon 'E710' -Module $m -OnClick { param($m) & $m.Actions.Add $m $null } | Out-Null
        Add-Button -Parent $row2 -Text 'Usuń z zaznaczonych grup' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Remove $m $null } | Out-Null
        if ($m.Target -eq 'User') {
            Add-Button -Parent $row2 -Text 'Kopiuj grupy z konta…' -Icon 'E8C8' -Module $m -OnClick {
                param($m)
                $template = Show-InputDialog -Title 'Konto wzorcowe' -Prompt 'Login konta, którego grupy (członkostwo bezpośrednie) mają otrzymać zaznaczone konta.' -Icon 'E77B' -Validate { param($t) if ($t.Trim() -match '^[^\s"/\\\[\]:;|=,+*?<>]+$') { '' } else { 'Podaj poprawny login (sAMAccountName).' } }
                if (-not $template) { return }
                Import-AdModule
                $ad = Get-AdSplat
                $user = Invoke-WithWaitCursor { Get-ADUser -Identity $template.Trim() -Properties memberOf @ad }
                $groups = @($user.memberOf | ForEach-Object { [pscustomobject]@{ Name = (Get-RdnValue $_); DN = [string]$_ } })
                if ($groups.Count -eq 0) { Show-Warning "Konto $template nie należy bezpośrednio do żadnej grupy (poza podstawową)."; return }
                & $m.Actions.Add $m $groups
            } | Out-Null
        }
        Add-RowAction -Module $m -Text 'Usuń z grupy' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Remove $m $rows }
        if ($m.Target -eq 'Group') {
            Add-RowAction -Module $m -Text 'Zaznacz grupy nadrzędne na liście' -Icon 'E8B3' -Action {
                param($m, $rows)
                $dns = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'DN grupy') } | Where-Object { $_ } | Select-Object -Unique)
                Add-GroupNames -Module $script:UI.Modules['__groups'] -Names $dns -Source 'raport'
            }
        }
        Add-RowAction -Module $m -Text 'Kopiuj nazwy grup' -Icon 'E8C8' -Action {
            param($m, $rows)
            $names = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Grupa') } | Select-Object -Unique)
            Set-ClipboardText ($names -join [Environment]::NewLine)
            Show-Toast "Skopiowano nazw grup: $($names.Count)" 'ok'
        }
    }
    Register-Module -Workspace $Workspace -Category $Category -Key $Key -Title $Title -Icon 'E902' -Description $desc -Build $build
}
#endregion

#region Użytkownicy AD
$script:UserStateScript = {
    # Wspólna ocena stanu konta (wiersz wyniku dla modułów kont)
    param($u)
    $now = Get-Date
    $expiry = $null
    $raw = $u.'msDS-UserPasswordExpiryTimeComputed'
    if ($raw -and [int64]$raw -gt 0 -and [int64]$raw -lt [int64]::MaxValue) { try { $expiry = [datetime]::FromFileTime([int64]$raw) } catch { } }
    $state = 'Aktywne'
    $tone = 'ok'
    if ($u.LockedOut) { $state = 'Zablokowane'; $tone = 'crit' }
    elseif (-not $u.Enabled) { $state = 'Wyłączone'; $tone = '' }
    elseif ($u.AccountExpirationDate -and $u.AccountExpirationDate -lt $now) { $state = 'Wygasłe'; $tone = 'crit' }
    elseif ($u.PasswordExpired) { $state = 'Hasło wygasło'; $tone = 'warn' }
    elseif ($expiry -and $expiry -lt $now.AddDays(7)) { $state = 'Hasło wkrótce wygaśnie'; $tone = 'warn' }
    return @{ State = $state; Tone = $tone; Expiry = $expiry }
}

Register-Module -Workspace 'AdUsers' -Category 'Konta' -Key 'UserDetails' -Title 'Szczegóły konta' -Icon 'E779' `
    -Description 'Pełne informacje o zaznaczonych kontach: stan, kontakt, przełożony, logowania, hasło, wygaśnięcie, profil i jednostka organizacyjna.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $m.GoodWhenNo = @('Zablokowane', 'Hasło nigdy nie wygasa', 'Zmiana hasła przy logowaniu')
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pobierz szczegóły' -Icon 'E896' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'Szczegóły kont' -Targets $targets -TargetColumn 'Login' -Parameters @{ StateScript = $script:UserStateScript.ToString() } -ScriptBlock {
            $u = Get-ADUser -Identity $Target -Properties * @ad
            $st = & ([scriptblock]::Create($P.StateScript)) $u
            $manager = ''
            if ($u.Manager) { $manager = (([string]$u.Manager -replace '^CN=((?:\\.|[^,])+),.*$', '$1') -replace '\\(.)', '$1') }
            [pscustomobject][ordered]@{
                'Stan'                        = $st.State
                'Nazwa'                       = $u.DisplayName
                'UPN'                         = $u.UserPrincipalName
                'E-mail'                      = $u.mail
                'Stanowisko'                  = $u.Title
                'Dział'                       = $u.Department
                'Firma'                       = $u.Company
                'Biuro'                       = $u.physicalDeliveryOfficeName
                'Telefon'                     = $u.telephoneNumber
                'Komórka'                     = $u.mobile
                'Przełożony'                  = $manager
                'Włączone'                    = [bool]$u.Enabled
                'Zablokowane'                 = [bool]$u.LockedOut
                'Ostatnie logowanie'          = $u.LastLogonDate
                'Hasło ustawione'             = $u.PasswordLastSet
                'Hasło wygasa'                = $st.Expiry
                'Hasło nigdy nie wygasa'      = [bool]$u.PasswordNeverExpires
                'Zmiana hasła przy logowaniu' = ($null -ne $u.pwdLastSet -and [int64]$u.pwdLastSet -eq 0)
                'Błędne hasła'                = $u.badPwdCount
                'Konto wygasa'                = $u.AccountExpirationDate
                'Utworzono'                   = $u.whenCreated
                'Zmieniono'                   = $u.whenChanged
                'Grupy'                       = @($u.memberOf).Count
                'Opis'                        = $u.Description
                'Skrypt logowania'            = $u.ScriptPath
                'Folder domowy'               = $u.HomeDirectory
                'Profil mobilny'              = $u.ProfilePath
                'Jednostka OU'                = ($u.DistinguishedName -replace '^CN=(?:\\.|[^,])+,', '')
                'SID'                         = [string]$u.SID
                'DN'                          = $u.DistinguishedName
                '__tone'                      = $st.Tone
            }
        }
    } | Out-Null
    Add-ObjectReportRow -Module $m -Kind 'User'
    Add-RowAction -Module $m -Text 'Kopiuj DN' -Icon 'E8C8' -Action {
        param($m, $rows)
        $dns = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'DN') } | Where-Object { $_ })
        Set-ClipboardText ($dns -join [Environment]::NewLine)
        Show-Toast "Skopiowano DN: $($dns.Count)" 'ok'
    }
}

Register-Module -Workspace 'AdUsers' -Category 'Konta' -Key 'UserPassword' -Title 'Hasło i blokada' -Icon 'E8D7' `
    -Description 'Stan hasła i blokady, odblokowanie, reset hasła (losowe – inne dla każdego konta – albo wpisane), wymuszenie zmiany przy logowaniu i ustawienie «hasło nigdy nie wygasa».' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan', 'Wynik')
    $m.SecretColumns = @('Nowe hasło')
    $m.GoodWhenNo = @('Zablokowane', 'Hasło wygasło', 'Hasło nigdy nie wygasa')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'Stan haseł' -Targets $targets -TargetColumn 'Login' -Parameters @{ StateScript = $script:UserStateScript.ToString() } -ScriptBlock {
            $u = Get-ADUser -Identity $Target -Properties DisplayName, Enabled, LockedOut, AccountLockoutTime, badPwdCount, LastBadPasswordAttempt, PasswordLastSet, PasswordExpired, PasswordNeverExpires, CannotChangePassword, pwdLastSet, 'msDS-UserPasswordExpiryTimeComputed', AccountExpirationDate @ad
            $st = & ([scriptblock]::Create($P.StateScript)) $u
            [pscustomobject][ordered]@{
                'Stan'                        = $st.State
                'Nazwa'                       = $u.DisplayName
                'Zablokowane'                 = [bool]$u.LockedOut
                'Zablokowano'                 = $u.AccountLockoutTime
                'Błędne hasła'                = $u.badPwdCount
                'Ostatnie błędne hasło'       = $u.LastBadPasswordAttempt
                'Hasło ustawione'             = $u.PasswordLastSet
                'Hasło wygasa'                = $st.Expiry
                'Hasło wygasło'               = [bool]$u.PasswordExpired
                'Hasło nigdy nie wygasa'      = [bool]$u.PasswordNeverExpires
                'Zmiana hasła przy logowaniu' = ($null -ne $u.pwdLastSet -and [int64]$u.pwdLastSet -eq 0)
                'Nie może zmienić hasła'      = [bool]$u.CannotChangePassword
                '__tone'                      = $st.Tone
            }
        }
    }
    $m.Actions.Simple = {
        param($m, [string]$Op, [string[]]$Logins)
        $targets = if ($Logins) { $Logins } else { @(Get-TargetUsers) }
        if (-not $targets) { return }
        $text = @{
            Unlock      = 'Odblokować zaznaczone konta?'
            MustChange  = 'Wymusić zmianę hasła przy następnym logowaniu?'
            NeverOn     = 'Ustawić «hasło nigdy nie wygasa»? Obniża to bezpieczeństwo – stosuj tylko dla kont usług.'
            NeverOff    = 'Wyłączyć «hasło nigdy nie wygasa»? Hasła mogą od razu wygasnąć, jeśli są starsze niż zasady domeny.'
        }[$Op]
        $targets = @(Confirm-Action -Text $text -Items $targets -ConfirmText 'Wykonaj' -Danger:($Op -eq 'NeverOn') -Select); if ($targets.Count -eq 0) { return }
        Start-AdOperation -Module $m -Name "Hasła – $Op" -Targets $targets -TargetColumn 'Login' -Output Log -Parameters @{ Op = $Op } -ScriptBlock {
            switch ($P.Op) {
                'Unlock' { Unlock-ADAccount -Identity $Target @ad; 'Odblokowano.' }
                'MustChange' { Set-ADUser -Identity $Target -ChangePasswordAtLogon $true @ad; 'Wymuszono zmianę hasła przy logowaniu.' }
                'NeverOn' { Set-ADUser -Identity $Target -PasswordNeverExpires $true @ad; 'Hasło nigdy nie wygasa: włączone.' }
                'NeverOff' { Set-ADUser -Identity $Target -PasswordNeverExpires $false @ad; 'Hasło nigdy nie wygasa: wyłączone.' }
            }
        } -OnResult {
            param($m, $r)
            if ($r.Ok -and @($r.Data | Where-Object { [string]$_ -eq 'Odblokowano.' }).Count) { Update-UserRow -Login $r.Target -Values @{ Locked = $false } }
        } -OnComplete { param($m) & $m.Actions.List $m }
    }
    $m.Actions.Reset = {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        $opt = Show-PasswordDialog -Subtitle ("Konta: {0}{1}" -f (($targets | Select-Object -First 5) -join ', '), $(if ($targets.Count -gt 5) { " i $($targets.Count - 5) więcej" } else { '' })) -Count $targets.Count
        if (-not $opt) { return }
        $targets = @(Confirm-Action -Text "Zresetować hasło wybranych kont?" -Items $targets -ConfirmText 'Resetuj hasła' -Danger -Select); if ($targets.Count -eq 0) { return }
        $per = @{}
        foreach ($t in $targets) {
            $per[$t] = @{
                Plain      = $(if ($opt.Mode -eq 'Generate') { New-RandomPassword -Length $opt.Length } else { '' })
                Secure     = $(if ($opt.Mode -eq 'Manual') { $opt.Password } else { $null })
                MustChange = $opt.MustChange
                Unlock     = $opt.Unlock
            }
        }
        Write-Log ("Reset hasła: {0} kont(a), tryb {1}, zmiana przy logowaniu: {2}" -f $targets.Count, $opt.Mode, $opt.MustChange)
        Start-AdOperation -Module $m -Name 'Reset hasła' -Targets $targets -PerTarget $per -TargetColumn 'Login' -ScriptBlock {
            $secure = if ($P.Plain) { ConvertTo-SecureString -String $P.Plain -AsPlainText -Force } else { $P.Secure }
            Set-ADAccountPassword -Identity $Target -Reset -NewPassword $secure @ad
            $notes = @()
            if ($P.Unlock) { try { Unlock-ADAccount -Identity $Target @ad; $notes += 'odblokowano' } catch { $notes += 'odblokowanie: ' + $_.Exception.Message } }
            $must = $false
            if ($P.MustChange) {
                try { Set-ADUser -Identity $Target -ChangePasswordAtLogon $true @ad; $must = $true }
                catch { $notes += 'zmiana przy logowaniu: ' + $_.Exception.Message }
            }
            [pscustomobject][ordered]@{
                'Wynik'                       = 'Hasło zresetowane'
                'Nowe hasło'                  = $(if ($P.Plain) { $P.Plain } else { '(wpisane ręcznie)' })
                'Zmiana hasła przy logowaniu' = $must
                'Uwagi'                       = ($notes -join '; ')
                '__tone'                      = 'ok'
            }
        } -OnResult {
            param($m, $r)
            if ($r.Ok) { Update-UserRow -Login $r.Target -Values @{ Locked = $false } }
        } -OnComplete {
            param($m)
            Show-Toast 'Hasła zresetowane. Zaznacz wiersz i użyj «Kopiuj hasło» (schowek czyści się po 60 s).' 'ok' 6
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Stan'
    Add-Button -Parent $row -Text 'Pokaż stan haseł' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Odblokuj' -Icon 'E785' -Module $m -OnClick { param($m) & $m.Actions.Simple $m 'Unlock' $null } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Hasło'
    Add-Button -Parent $row2 -Text 'Resetuj hasło…' -Icon 'E8D7' -Module $m -Danger -OnClick $m.Actions.Reset | Out-Null
    Add-Button -Parent $row2 -Text 'Wymuś zmianę przy logowaniu' -Icon 'E777' -Module $m -OnClick { param($m) & $m.Actions.Simple $m 'MustChange' $null } | Out-Null
    Add-Button -Parent $row2 -Text 'Nigdy nie wygasa: włącz' -Module $m -OnClick { param($m) & $m.Actions.Simple $m 'NeverOn' $null } | Out-Null
    Add-Button -Parent $row2 -Text 'wyłącz' -Module $m -OnClick { param($m) & $m.Actions.Simple $m 'NeverOff' $null } | Out-Null
    Add-RowAction -Module $m -Text 'Kopiuj hasło (60 s)' -Icon 'E8C8' -Action {
        param($m, $rows)
        $secret = [string](Get-RowValue $rows[0] 'Nowe hasło')
        if (-not $secret -or $secret -like '(*') { Show-Warning 'Wiersz nie zawiera wygenerowanego hasła.'; return }
        Set-ClipboardSecret -Text $secret -Seconds 60
        Write-Log ("Skopiowano nowe hasło konta {0}; schowek zostanie wyczyszczony po 60 s." -f (Get-ObjectValue $rows[0] 'Login')) 'OK'
        Show-Toast 'Hasło w schowku – zostanie wyczyszczone po 60 s.' 'ok'
    }
    Add-RowAction -Module $m -Text 'Odblokuj konto' -Icon 'E785' -Action {
        param($m, $rows)
        & $m.Actions.Simple $m 'Unlock' @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Login') })
    }
    $m.ResultHint = 'Nowe hasła są ukryte – «Pokaż poufne» albo «Kopiuj hasło» w menu wiersza'
}

Register-Module -Workspace 'AdUsers' -Category 'Konta' -Key 'UserState' -Title 'Stan konta' -Icon 'E8D8' `
    -Description 'Włączanie i wyłączanie kont (z adnotacją w opisie i przeniesieniem do OU), data wygaśnięcia konta oraz przenoszenie do innej jednostki organizacyjnej.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'Stan kont' -Targets $targets -TargetColumn 'Login' -Parameters @{ StateScript = $script:UserStateScript.ToString() } -ScriptBlock {
            $u = Get-ADUser -Identity $Target -Properties DisplayName, Enabled, LockedOut, AccountExpirationDate, Description, LastLogonDate, PasswordExpired, 'msDS-UserPasswordExpiryTimeComputed' @ad
            $st = & ([scriptblock]::Create($P.StateScript)) $u
            [pscustomobject][ordered]@{
                'Stan'               = $st.State
                'Nazwa'              = $u.DisplayName
                'Włączone'           = [bool]$u.Enabled
                'Konto wygasa'       = $u.AccountExpirationDate
                'Ostatnie logowanie' = $u.LastLogonDate
                'Opis'               = $u.Description
                'Jednostka OU'       = ($u.DistinguishedName -replace '^CN=(?:\\.|[^,])+,', '')
                '__tone'             = $st.Tone
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        $params = @{ Op = $Op; Note = ''; MoveTo = ''; Date = $null }
        switch ($Op) {
            'Disable' {
                if (Test-Checked $m.Stamp) {
                    $reason = $m.Reason.Text.Trim()
                    $params.Note = ('Wyłączone {0:yyyy-MM-dd} przez {1}{2}' -f (Get-Date), $env:USERNAME, $(if ($reason) { ": $reason" } else { '' }))
                }
                $params.MoveTo = $m.DisabledOu.Text.Trim()
                $text = 'Wyłączyć wybrane konta?'
                if ($params.Note) { $text += "`r`nOpis zostanie poprzedzony: «$($params.Note)»" }
                if ($params.MoveTo) { $text += "`r`nKonta zostaną przeniesione do: $($params.MoveTo)" }
                $targets = @(Confirm-Action -Text $text -Items $targets -ConfirmText 'Wyłącz konta' -Danger -Select); if ($targets.Count -eq 0) { return }
            }
            'Enable' { $targets = @(Confirm-Action -Text "Włączyć wybrane konta?" -Items $targets -ConfirmText 'Włącz konta' -Select); if ($targets.Count -eq 0) { return } }
            'Expire' {
                $date = [datetime]::MinValue
                if (-not [datetime]::TryParseExact($m.ExpireDate.Text.Trim(), 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture, 'None', [ref]$date)) { Show-Warning 'Podaj datę w formacie RRRR-MM-DD, np. 2026-12-31.'; return }
                # Konto wygasa z końcem wskazanego dnia (AD przechowuje początek następnego dnia)
                $params.Date = $date.AddDays(1)
                $targets = @(Confirm-Action -Text ("Ustawić wygaśnięcie kont z końcem dnia {0:yyyy-MM-dd}?" -f $date) -Items $targets -ConfirmText 'Ustaw' -Select); if ($targets.Count -eq 0) { return }
            }
            'ClearExpire' { $targets = @(Confirm-Action -Text 'Usunąć datę wygaśnięcia kont (konta nie będą wygasać)?' -Items $targets -ConfirmText 'Usuń datę' -Select); if ($targets.Count -eq 0) { return } }
            'Move' {
                $ou = Select-OrganizationalUnit -Title 'Docelowa jednostka dla kont'
                if (-not $ou) { return }
                $params.MoveTo = $ou
                $targets = @(Confirm-Action -Text "Przenieść konta do:`r`n$ou ?" -Items $targets -ConfirmText 'Przenieś' -Select); if ($targets.Count -eq 0) { return }
            }
        }
        Start-AdOperation -Module $m -Name "Stan konta – $Op" -Targets $targets -TargetColumn 'Login' -Output Log -Parameters $params -OnComplete { param($m) & $m.Actions.List $m } -ScriptBlock {
            $u = Get-ADUser -Identity $Target -Properties Description @ad
            switch ($P.Op) {
                'Disable' {
                    Disable-ADAccount -Identity $u @ad
                    if ($P.Note) {
                        $desc = if ($u.Description) { "$($P.Note) | $($u.Description)" } else { $P.Note }
                        if ($desc.Length -gt 1024) { $desc = $desc.Substring(0, 1024) }
                        Set-ADUser -Identity $u -Description $desc @ad
                    }
                    if ($P.MoveTo) { Move-ADObject -Identity $u.DistinguishedName -TargetPath $P.MoveTo @ad; "Wyłączono i przeniesiono do $($P.MoveTo)." }
                    else { 'Wyłączono.' }
                }
                'Enable' { Enable-ADAccount -Identity $u @ad; 'Włączono.' }
                'Expire' { Set-ADAccountExpiration -Identity $u -DateTime $P.Date @ad; ('Konto wygasa {0:yyyy-MM-dd HH:mm}.' -f $P.Date) }
                'ClearExpire' { Clear-ADAccountExpiration -Identity $u @ad; 'Usunięto datę wygaśnięcia.' }
                'Move' { Move-ADObject -Identity $u.DistinguishedName -TargetPath $P.MoveTo @ad; "Przeniesiono do $($P.MoveTo)." }
            }
        } -OnResult {
            param($m, $r)
            if (-not $r.Ok) { return }
            $text = (@($r.Data) -join ' ')
            if ($text -like 'Wyłączono*') { Update-UserRow -Login $r.Target -Values @{ Enabled = $false } }
            elseif ($text -like 'Włączono*') { Update-UserRow -Login $r.Target -Values @{ Enabled = $true } }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Stan'
    Add-Button -Parent $row -Text 'Pokaż stan kont' -Icon 'E72C' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Włącz' -Icon 'E73E' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Enable' } | Out-Null
    Add-Button -Parent $row -Text 'Przenieś do OU…' -Icon 'E8DE' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Move' } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Wyłączanie'
    $m.Stamp = Add-CheckBox -Parent $row2 -Text 'Dopisz do opisu datę i autora' -Checked $true
    $m.Reason = Add-TextBox -Parent $row2 -Width 220 -Placeholder 'powód, np. numer zgłoszenia'
    $m.DisabledOu = Add-TextBox -Parent $row2 -Width 220 -Placeholder 'przenieś do OU (opcjonalnie)'
    Add-Button -Parent $row2 -Text '' -Icon 'E8B7' -Module $m -AlwaysEnabled -ToolTip 'Wybierz OU dla wyłączonych kont' -OnClick {
        param($m)
        $ou = Select-OrganizationalUnit -Title 'OU dla wyłączonych kont' -Selected $m.DisabledOu.Text.Trim()
        if ($ou) { $m.DisabledOu.Text = $ou }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Wyłącz konta' -Icon 'E8D8' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Disable' } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Wygaśnięcie'
    $m.ExpireDate = Add-TextBox -Parent $row3 -Width 130 -Text ((Get-Date).AddDays(30).ToString('yyyy-MM-dd')) -Placeholder 'RRRR-MM-DD'
    Add-Button -Parent $row3 -Text 'Ustaw datę wygaśnięcia' -Icon 'E787' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Expire' } | Out-Null
    Add-Button -Parent $row3 -Text 'Usuń datę wygaśnięcia' -Icon 'E711' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'ClearExpire' } | Out-Null
}

$script:UserAttributes = @(
    @{ Name = 'title'; Label = 'Stanowisko (title)' }
    @{ Name = 'department'; Label = 'Dział (department)' }
    @{ Name = 'company'; Label = 'Firma (company)' }
    @{ Name = 'physicalDeliveryOfficeName'; Label = 'Biuro (physicalDeliveryOfficeName)' }
    @{ Name = 'description'; Label = 'Opis (description)' }
    @{ Name = 'telephoneNumber'; Label = 'Telefon (telephoneNumber)' }
    @{ Name = 'mobile'; Label = 'Komórka (mobile)' }
    @{ Name = 'mail'; Label = 'E-mail (mail)' }
    @{ Name = 'manager'; Label = 'Przełożony (manager – login)' }
    @{ Name = 'employeeID'; Label = 'Numer pracownika (employeeID)' }
    @{ Name = 'l'; Label = 'Miasto (l)' }
    @{ Name = 'streetAddress'; Label = 'Ulica (streetAddress)' }
    @{ Name = 'postalCode'; Label = 'Kod pocztowy (postalCode)' }
    @{ Name = 'wWWHomePage'; Label = 'Strona WWW (wWWHomePage)' }
    @{ Name = 'info'; Label = 'Uwagi (info)' }
    @{ Name = 'scriptPath'; Label = 'Skrypt logowania (scriptPath)' }
) + @(1..15 | ForEach-Object { @{ Name = "extensionAttribute$_"; Label = "extensionAttribute$_" } })

Register-Module -Workspace 'AdUsers' -Category 'Konta' -Key 'UserAttributes' -Title 'Edycja atrybutów' -Icon 'E70F' `
    -Description 'Odczyt i masowa zmiana atrybutów zaznaczonych kont. Wartość może zawierać pola {login}, {imie}, {nazwisko}, {nazwa} – np. {login}@firma.pl.' -Build {
    param($m)
    $row = Add-ToolbarRow -Module $m -Title 'Atrybut'
    $m.Attr = Add-ComboBox -Parent $row -Items @($script:UserAttributes | ForEach-Object { $_.Label }) -Width 320
    Add-Button -Parent $row -Text 'Pokaż wartości' -Icon 'E72C' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        $attr = $script:UserAttributes[$m.Attr.SelectedIndex].Name
        Start-AdOperation -Module $m -Name "Atrybut $attr" -Targets $targets -TargetColumn 'Login' -Parameters @{ Attr = $attr } -ScriptBlock {
            $u = Get-ADUser -Identity $Target -Properties $P.Attr, DisplayName @ad
            $v = $u.($P.Attr)
            if ($P.Attr -eq 'manager' -and $v) { $v = ([string]$v -replace '^CN=((?:\\.|[^,])+),.*$', '$1') -replace '\\(.)', '$1' }
            [pscustomobject]@{ 'Nazwa' = $u.DisplayName; 'Atrybut' = $P.Attr; 'Wartość' = $(if ($null -eq $v) { '' } else { (@($v) -join '; ') }) }
        }
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Nowa wartość'
    $m.Value = Add-TextBox -Parent $row2 -Width 380 -Placeholder 'wartość lub szablon, np. {login}@firma.pl'
    Add-Button -Parent $row2 -Text 'Ustaw' -Icon 'E74E' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        $attr = $script:UserAttributes[$m.Attr.SelectedIndex].Name
        $value = $m.Value.Text.Trim()
        if (-not $value) { Show-Warning 'Wpisz wartość (aby usunąć wartość, użyj «Wyczyść»).'; return }
        $targets = @(Confirm-Action -Text "Ustawić atrybut $attr = «$value» dla wybranych kont?" -Items $targets -ConfirmText 'Ustaw' -Select); if ($targets.Count -eq 0) { return }
        Start-AdOperation -Module $m -Name "Zmiana $attr" -Targets $targets -TargetColumn 'Login' -Output Log -Parameters @{ Attr = $attr; Value = $value } -ScriptBlock {
            $u = Get-ADUser -Identity $Target -Properties GivenName, Surname, DisplayName @ad
            $v = $P.Value.Replace('{login}', $u.SamAccountName).Replace('{imie}', [string]$u.GivenName).Replace('{nazwisko}', [string]$u.Surname).Replace('{nazwa}', [string]$u.DisplayName)
            if ($P.Attr -eq 'manager') { $v = (Get-ADUser -Identity $v @ad).DistinguishedName }
            Set-ADUser -Identity $u -Replace @{ $P.Attr = $v } @ad
            "$($P.Attr) = $v"
        } -OnComplete { param($m) Show-Toast 'Zmieniono atrybuty – «Pokaż wartości», aby sprawdzić.' 'ok' }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Wyczyść' -Icon 'E894' -Module $m -Danger -OnClick {
        param($m)
        $targets = @(Get-TargetUsers)
        if (-not $targets) { return }
        $attr = $script:UserAttributes[$m.Attr.SelectedIndex].Name
        $targets = @(Confirm-Action -Text "Wyczyścić atrybut $attr dla wybranych kont?" -Items $targets -ConfirmText 'Wyczyść' -Danger -Select); if ($targets.Count -eq 0) { return }
        Start-AdOperation -Module $m -Name "Czyszczenie $attr" -Targets $targets -TargetColumn 'Login' -Output Log -Parameters @{ Attr = $attr } -ScriptBlock {
            Set-ADUser -Identity $Target -Clear $P.Attr @ad
            "Wyczyszczono $($P.Attr)."
        }
    } | Out-Null
}

Register-GroupMembershipModule -Workspace 'AdUsers' -Kind User -Key 'UserGroups' -Category 'Grupy'

$script:UserReports = @(
    @{ Key = 'Locked'; Name = 'Zablokowane konta' }
    @{ Key = 'Disabled'; Name = 'Wyłączone konta' }
    @{ Key = 'Inactive'; Name = 'Nieaktywne (brak logowania od N dni)' }
    @{ Key = 'NeverLogged'; Name = 'Nigdy nie logowane' }
    @{ Key = 'PwdExpiring'; Name = 'Hasło wygasa w ciągu N dni' }
    @{ Key = 'PwdExpired'; Name = 'Hasło wygasło' }
    @{ Key = 'PwdNever'; Name = 'Hasło nigdy nie wygasa' }
    @{ Key = 'AccExpiring'; Name = 'Konto wygasło lub wygasa w ciągu N dni' }
    @{ Key = 'Created'; Name = 'Utworzone w ciągu N dni' }
    @{ Key = 'Privileged'; Name = 'Konta uprzywilejowane (adminCount = 1)' }
)

Register-Module -Workspace 'AdUsers' -Category 'Raporty' -Key 'UserReports' -Title 'Raporty kont' -Icon 'E9F9' `
    -Description 'Zestawienia z całej domeny lub jednostki: zablokowane, wyłączone, nieaktywne, z wygasającym hasłem, wygasające, nowe i uprzywilejowane. Wyniki można przenieść na listę kont i wykonać na nich operacje.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $m.GoodWhenNo = @('Zablokowane', 'Hasło nigdy nie wygasa')
    $row = Add-ToolbarRow -Module $m -Title 'Raport'
    $m.Report = Add-ComboBox -Parent $row -Items @($script:UserReports | ForEach-Object { $_.Name }) -Width 340
    Add-Label -Parent $row -Text 'N (dni)' | Out-Null
    $m.Days = Add-Numeric -Parent $row -Value ([int]$script:Settings.InactiveDays) -Minimum 1 -Maximum 3650 -Width 70
    $m.OnlyEnabled = Add-CheckBox -Parent $row -Text 'Tylko włączone' -Checked $true -ToolTip 'Dotyczy raportów nieaktywności, haseł i nowych kont'
    $row2 = Add-ToolbarRow -Module $m -Title 'Zakres'
    $m.Ou = Add-TextBox -Parent $row2 -Width 420 -Placeholder 'Cała domena'
    Add-Button -Parent $row2 -Text '' -Icon 'E8B7' -Module $m -AlwaysEnabled -ToolTip 'Wybierz jednostkę organizacyjną' -OnClick {
        param($m)
        $ou = Select-OrganizationalUnit -Title 'Zakres raportu' -Selected $m.Ou.Text.Trim() -AllowDomainRoot
        if ($null -ne $ou) { $m.Ou.Text = $ou }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Generuj raport' -Icon 'E9F9' -Module $m -Primary -OnClick {
        param($m)
        $report = $script:UserReports[$m.Report.SelectedIndex]
        $params = @{ Report = $report.Key; Days = (Get-Num $m.Days); OnlyEnabled = (Test-Checked $m.OnlyEnabled); SearchBase = $m.Ou.Text.Trim(); StateScript = $script:UserStateScript.ToString() }
        Start-AdOperation -Module $m -Name $report.Name -Targets @('AD') -Parameters $params -ScriptBlock {
            $now = Get-Date
            $days = [int]$P.Days
            $enabledOnly = '(!(userAccountControl:1.2.840.113556.1.4.803:=2))'
            $base = '(objectCategory=person)(objectClass=user)'
            $cut = $now.AddDays(-$days)
            $ft = $cut.ToFileTimeUtc()
            $gen = $cut.ToUniversalTime().ToString('yyyyMMddHHmmss.0Z')
            $extra = switch ($P.Report) {
                'Locked' { '(lockoutTime>=1)' }
                'Disabled' { '(userAccountControl:1.2.840.113556.1.4.803:=2)' }
                'Inactive' { "(|(lastLogonTimestamp<=$ft)(&(!(lastLogonTimestamp=*))(whenCreated<=$gen)))" }
                'NeverLogged' { '(!(lastLogonTimestamp=*))' }
                'PwdExpiring' { '(!(userAccountControl:1.2.840.113556.1.4.803:=65536))' }
                'PwdExpired' { '(!(userAccountControl:1.2.840.113556.1.4.803:=65536))' }
                'PwdNever' { '(userAccountControl:1.2.840.113556.1.4.803:=65536)' }
                'AccExpiring' { '(accountExpires>=1)(!(accountExpires=9223372036854775807))' }
                'Created' { "(whenCreated>=$gen)" }
                'Privileged' { '(adminCount=1)' }
            }
            if ($P.OnlyEnabled -and @('Locked', 'Disabled', 'Privileged') -notcontains $P.Report) { $extra += $enabledOnly }
            $q = @{
                LDAPFilter = "(&$base$extra)"
                Properties = @('DisplayName', 'Enabled', 'LockedOut', 'LastLogonDate', 'PasswordLastSet', 'PasswordNeverExpires', 'PasswordExpired', 'msDS-UserPasswordExpiryTimeComputed', 'AccountExpirationDate', 'whenCreated', 'Department', 'Title', 'mail', 'Description', 'AccountLockoutTime')
            }
            if ($P.SearchBase) { $q.SearchBase = $P.SearchBase }
            $users = @(Get-ADUser @q @ad)
            $stateScript = [scriptblock]::Create($P.StateScript)
            foreach ($u in $users) {
                $st = & $stateScript $u
                # Uwaga: "continue" wewnątrz switch dotyczy switch, nie pętli - stąd osobna zmienna
                $include = switch ($P.Report) {
                    'Locked' { [bool]$u.LockedOut }
                    'PwdExpiring' { [bool]($st.Expiry -and $st.Expiry -ge $now -and $st.Expiry -le $now.AddDays($days)) }
                    'PwdExpired' { [bool]$u.PasswordExpired }
                    'AccExpiring' { [bool]($u.AccountExpirationDate -and $u.AccountExpirationDate -le $now.AddDays($days)) }
                    default { $true }
                }
                if (-not $include) { continue }
                [pscustomobject][ordered]@{
                    'Login'              = $u.SamAccountName
                    'Nazwa'              = $u.DisplayName
                    'Stan'               = $st.State
                    'Włączone'           = [bool]$u.Enabled
                    'Zablokowane'        = [bool]$u.LockedOut
                    'Ostatnie logowanie' = $u.LastLogonDate
                    'Dni bez logowania'  = $(if ($u.LastLogonDate) { [int]($now - $u.LastLogonDate).TotalDays } else { $null })
                    'Hasło ustawione'    = $u.PasswordLastSet
                    'Hasło wygasa'       = $st.Expiry
                    'Hasło nigdy nie wygasa' = [bool]$u.PasswordNeverExpires
                    'Konto wygasa'       = $u.AccountExpirationDate
                    'Utworzono'          = $u.whenCreated
                    'Dział'              = $u.Department
                    'Stanowisko'         = $u.Title
                    'E-mail'             = $u.mail
                    'Opis'               = $u.Description
                    'DN'                 = $u.DistinguishedName
                    '__tone'             = $st.Tone
                }
            }
        } -OnComplete {
            param($m)
            Set-StatTile -Module $m -Key 'count' -Value ([string]$m.Table.Rows.Count) -Tone $(if ($m.Table.Rows.Count) { 'warn' } else { 'ok' })
            Set-StatTile -Module $m -Key 'locked' -Value ([string]@($m.Table.Rows | Where-Object { $m.Table.Columns.Contains('Zablokowane') -and [string]$_['Zablokowane'] -eq 'Tak' }).Count)
            Set-StatTile -Module $m -Key 'disabled' -Value ([string]@($m.Table.Rows | Where-Object { $m.Table.Columns.Contains('Włączone') -and [string]$_['Włączone'] -eq 'Nie' }).Count)
        }
    } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Wyniki'
    Add-Button -Parent $row3 -Text 'Zaznacz na liście kont' -Icon 'E8B3' -Module $m -AlwaysEnabled -ToolTip 'Zaznaczone wiersze (albo wszystkie widoczne) trafią na listę kont po lewej – zaznaczone do dalszych operacji' -OnClick {
        param($m)
        Add-ResultsToTargets -Module $m -Kind User -Column 'Login'
    } | Out-Null
    Add-RowAction -Module $m -Text 'Zaznacz na liście kont' -Icon 'E8B3' -Action { param($m, $rows) Add-ResultsToTargets -Module $m -Kind User -Column 'Login' -Rows $rows }
    Add-RowAction -Module $m -Text 'Odblokuj' -Icon 'E785' -Separator -Action {
        param($m, $rows)
        $logins = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Login') } | Where-Object { $_ })
        if (-not (Confirm-Action -Text 'Odblokować wybrane konta?' -Items $logins -ConfirmText 'Odblokuj')) { return }
        Start-AdOperation -Module $m -Name 'Odblokowanie' -Targets $logins -TargetColumn 'Login' -Output Log -ScriptBlock { Unlock-ADAccount -Identity $Target @ad; 'Odblokowano.' }
    }
    Add-RowAction -Module $m -Text 'Wyłącz konto' -Icon 'E8D8' -Danger -Action {
        param($m, $rows)
        $logins = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Login') } | Where-Object { $_ })
        if (-not (Confirm-Action -Text 'Wyłączyć wybrane konta?' -Items $logins -ConfirmText 'Wyłącz' -Danger)) { return }
        Start-AdOperation -Module $m -Name 'Wyłączanie kont' -Targets $logins -TargetColumn 'Login' -Output Log -ScriptBlock { Disable-ADAccount -Identity $Target @ad; 'Wyłączono.' }
    }
    Add-StatTile -Module $m -Key 'count' -Label 'Konta w raporcie' -Icon 'E716' | Out-Null
    Add-StatTile -Module $m -Key 'locked' -Label 'Zablokowane' -Icon 'E72E' | Out-Null
    Add-StatTile -Module $m -Key 'disabled' -Label 'Wyłączone' -Icon 'E8D8' | Out-Null
    $m.EmptyHint = 'Wybierz raport i kliknij «Generuj raport» (F5). Nie trzeba zaznaczać kont na liście.'
}

Register-Module -Workspace 'AdUsers' -Category 'Raporty' -Key 'LockoutSource' -Title 'Źródło blokady konta' -Icon 'E7BA' `
    -Description 'Skąd pochodzą blokady: zdarzenia 4740 z kontrolerów domeny (komputer, z którego przyszły błędne hasła) oraz opcjonalnie nieudane uwierzytelnienia Kerberos 4771 i NTLM 4776. Bez zaznaczonych kont – wszystkie blokady.' -Build {
    param($m)
    $m.PillColumns = @('Zdarzenie')
    $row = Add-ToolbarRow -Module $m -Title 'Parametry'
    Add-Label -Parent $row -Text 'Ostatnie godziny' | Out-Null
    $m.Hours = Add-Numeric -Parent $row -Value 24 -Minimum 1 -Maximum 720 -Width 70
    $m.AllDcs = Add-CheckBox -Parent $row -Text 'Wszystkie kontrolery domeny' -ToolTip 'Domyślnie tylko emulator PDC (tam trafiają wszystkie blokady). Wszystkie DC – także zdarzenia 4771/4776 z innych kontrolerów.'
    $m.Failures = Add-CheckBox -Parent $row -Text 'Nieudane uwierzytelnienia (4771, 4776)'
    $m.Max = Add-Numeric -Parent $row -Value 500 -Minimum 10 -Maximum 10000 -Width 70
    $m.Max.ToolTip = 'Maksymalna liczba zdarzeń z jednego kontrolera'
    Add-Button -Parent $row -Text 'Szukaj źródła' -Icon 'E721' -Module $m -Primary -OnClick {
        param($m)
        if (-not (Test-AdAvailable)) { return }
        Import-AdModule
        $ad = Get-AdSplat
        $info = Invoke-WithWaitCursor {
            $domain = Get-ADDomain @ad
            $list = if (Test-Checked $m.AllDcs) { @(Get-ADDomainController -Filter * @ad | ForEach-Object { $_.HostName }) } else { @($domain.PDCEmulator) }
            @{ Dcs = $list }
        }
        $users = @(Get-TargetUsers -Quiet | Where-Object { $_ -notmatch "['""]" })
        $params = @{ Users = $users; Hours = (Get-Num $m.Hours); Failures = (Test-Checked $m.Failures); Max = (Get-Num $m.Max) }
        $scope = if ($users.Count) { "kont: $($users.Count)" } else { 'wszystkich kont' }
        Write-Log ("Szukanie blokad ({0}) na: {1}" -f $scope, ($info.Dcs -join ', '))
        Start-HostOperation -Module $m -Name 'Źródło blokady' -Targets $info.Dcs -Local -TargetColumn 'Kontroler domeny' -Parameters $params -ScriptBlock {
            param($Target, $P, $Ctx)
            $ids = @(4740)
            if ($P.Failures) { $ids += 4771; $ids += 4776 }
            $idFilter = (@($ids | ForEach-Object { "EventID=$_" }) -join ' or ')
            $ms = [int64]$P.Hours * 3600000
            $xpath = "*[System[($idFilter) and TimeCreated[timediff(@SystemTime) <= $ms]]"
            if (@($P.Users).Count -gt 0) { $xpath += ' and EventData[' + ((@($P.Users | ForEach-Object { "Data[@Name='TargetUserName']='$_'" })) -join ' or ') + ']' }
            $xpath += ']'
            $query = {
                param($XPath, $Max)
                $events = @()
                try { $events = @(Get-WinEvent -LogName Security -FilterXPath $XPath -MaxEvents $Max -ErrorAction Stop) }
                catch { if ($_.FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*') { throw } }
                foreach ($e in $events) {
                    $data = @{}
                    foreach ($d in ([xml]$e.ToXml()).Event.EventData.Data) { $data[[string]$d.Name] = [string]$d.'#text' }
                    [pscustomobject]@{ Time = $e.TimeCreated; Id = $e.Id; Data = $data }
                }
            }
            $ic = @{ ComputerName = $Target; ScriptBlock = $query; ArgumentList = @($xpath, [int]$P.Max); ErrorAction = 'Stop' }
            if ($Ctx.Credential) { $ic.Credential = $Ctx.Credential }
            if ($Ctx.SessionOption) { $ic.SessionOption = $Ctx.SessionOption }
            $events = @()
            try { $events = @(Invoke-Command @ic) }
            catch {
                # Bez WinRM na DC - odczyt zdalnego dziennika przez RPC
                $gp = @{ ComputerName = $Target; LogName = 'Security'; FilterXPath = $xpath; MaxEvents = [int]$P.Max; ErrorAction = 'Stop' }
                if ($Ctx.Credential) { $gp.Credential = $Ctx.Credential }
                try {
                    $events = @(Get-WinEvent @gp | ForEach-Object {
                            $data = @{}
                            foreach ($d in ([xml]$_.ToXml()).Event.EventData.Data) { $data[[string]$d.Name] = [string]$d.'#text' }
                            [pscustomobject]@{ Time = $_.TimeCreated; Id = $_.Id; Data = $data }
                        })
                }
                catch { if ($_.FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*') { throw } }
            }
            $dns = @{}
            foreach ($e in ($events | Sort-Object Time -Descending)) {
                $d = $e.Data
                if ([int]$e.Id -eq 4776 -and [string]$d['Status'] -eq '0x0') { continue }
                $source = ''
                $detail = ''
                $tone = 'info'
                switch ([int]$e.Id) {
                    4740 { $kind = 'Blokada konta'; $source = $d['TargetDomainName']; $tone = 'crit' }
                    4771 {
                        $kind = 'Kerberos – błąd uwierzytelnienia'
                        $ip = ([string]$d['IpAddress']) -replace '^::ffff:', ''
                        $source = $ip
                        if ($ip -and $ip -ne '::1' -and $ip -ne '-') {
                            if (-not $dns.ContainsKey($ip)) { $dns[$ip] = ''; try { $dns[$ip] = [System.Net.Dns]::GetHostEntry($ip).HostName } catch { } }
                            if ($dns[$ip]) { $source = '{0} ({1})' -f $dns[$ip], $ip }
                        }
                        $detail = switch ([string]$d['Status']) { '0x18' { 'Błędne hasło' } '0x12' { 'Konto zablokowane / wyłączone' } '0x17' { 'Hasło wygasło' } default { "Kod $($d['Status'])" } }
                        $tone = 'warn'
                    }
                    4776 {
                        $kind = 'NTLM – błąd uwierzytelnienia'
                        $source = $d['Workstation']
                        $detail = switch ([string]$d['Status']) { '0xc000006a' { 'Błędne hasło' } '0xc0000234' { 'Konto zablokowane' } '0xc0000064' { 'Nieznane konto' } '0xc0000072' { 'Konto wyłączone' } default { "Kod $($d['Status'])" } }
                        $tone = 'warn'
                    }
                }
                [pscustomobject][ordered]@{
                    'Czas'        = $e.Time
                    'Zdarzenie'   = $kind
                    'Konto'       = $d['TargetUserName']
                    'Źródło'      = $source
                    'Szczegóły'   = $detail
                    'ID'          = $e.Id
                    '__tone'      = $tone
                }
            }
        } -OnComplete {
            param($m)
            $sources = @($m.Table.Rows | Where-Object { $m.Table.Columns.Contains('Źródło') -and [string]$_['Źródło'] } | Group-Object { [string]$_['Źródło'] } | Sort-Object Count -Descending)
            if ($sources.Count -gt 0) { Show-Toast ("Najczęstsze źródło: {0} ({1} zdarzeń)" -f $sources[0].Name, $sources[0].Count) 'info' 8 }
        }
    } | Out-Null
    $m.EmptyHint = 'Zaznacz konta po lewej (albo żadnego – wszystkie blokady) i kliknij «Szukaj źródła». Wymaga uprawnień do dziennika Security na kontrolerach domeny.'
    Add-RowAction -Module $m -Text 'Odblokuj konto' -Icon 'E785' -Action {
        param($m, $rows)
        $logins = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Konto') } | Where-Object { $_ } | Select-Object -Unique)
        if (-not (Confirm-Action -Text 'Odblokować wybrane konta?' -Items $logins -ConfirmText 'Odblokuj')) { return }
        Start-AdOperation -Module $m -Name 'Odblokowanie' -Targets $logins -TargetColumn 'Login' -Output Log -ScriptBlock { Unlock-ADAccount -Identity $Target @ad; 'Odblokowano.' }
    }
}
#endregion

#region Komputery AD
function Get-AdComputerTargets {
    # Nazwy komputerów z listy po lewej bez części domenowej (FQDN -> nazwa)
    return @(Get-TargetComputers | ForEach-Object { ($_ -split '\.')[0] } | Select-Object -Unique)
}

Register-Module -Workspace 'AdComputers' -Category 'Konta komputerów' -Key 'ComputerAccount' -Title 'Konto komputera' -Icon 'E977' `
    -Description 'Obiekt komputera w AD: informacje, kanał zaufania (test i naprawa), włączanie, wyłączanie, opis, przenoszenie do OU, reset i usuwanie konta oraz tworzenie nowych kont (pre-staging).' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-AdComputerTargets)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'Konto komputera – informacje' -Targets $targets -TargetColumn 'Komputer' -ScriptBlock {
            $props = @('Enabled', 'LastLogonDate', 'PasswordLastSet', 'OperatingSystem', 'OperatingSystemVersion', 'whenCreated', 'Description', 'IPv4Address', 'ManagedBy', 'Location', 'DNSHostName')
            $c = Get-ADComputer -Identity $Target -Properties $props @ad
            $days = if ($c.LastLogonDate) { [int]((Get-Date) - $c.LastLogonDate).TotalDays } else { $null }
            $state = if (-not $c.Enabled) { 'Wyłączone' } elseif ($null -eq $days) { 'Nigdy nie logowane' } elseif ($days -gt 90) { "Nieaktywne ($days dni)" } else { 'Aktywne' }
            [pscustomobject][ordered]@{
                'Stan'                  = $state
                'Włączone'              = [bool]$c.Enabled
                'Ostatnie logowanie'    = $c.LastLogonDate
                'Dni bez logowania'     = $days
                'Hasło konta zmienione' = $c.PasswordLastSet
                'System'                = $c.OperatingSystem
                'Wersja'                = $c.OperatingSystemVersion
                'IPv4'                  = $c.IPv4Address
                'DNS'                   = $c.DNSHostName
                'Utworzono'             = $c.whenCreated
                'Opis'                  = $c.Description
                'Lokalizacja'           = $c.Location
                'Jednostka OU'          = ($c.DistinguishedName -replace '^CN=(?:\\.|[^,])+,', '')
                'DN'                    = $c.DistinguishedName
                '__tone'                = $(if (-not $c.Enabled) { '' } elseif ($state -eq 'Aktywne') { 'ok' } else { 'warn' })
            }
        }
    }
    $m.Actions.Change = {
        param($m, [string]$Op)
        $targets = @(Get-AdComputerTargets)
        if (-not $targets) { return }
        $params = @{ Op = $Op; TargetOU = ''; Description = '' }
        $danger = $false
        switch ($Op) {
            'Reset' { $question = 'Zresetować konta komputerów w AD? Komputery stracą relację zaufania i trzeba będzie ponownie dołączyć je do domeny lub naprawić kanał.'; $danger = $true }
            'Enable' { $question = 'Włączyć konta komputerów w AD?' }
            'Disable' { $question = 'Wyłączyć konta komputerów w AD? Użytkownicy nie zalogują się kontem domenowym na tych komputerach.'; $danger = $true }
            'Delete' { $question = 'USUNĄĆ konta komputerów z AD (razem z obiektami podrzędnymi, np. kluczami odzyskiwania BitLocker)? Tej operacji nie można cofnąć bez kosza AD.'; $danger = $true }
            'Describe' {
                $params.Description = $m.Description.Text.Trim()
                $question = "Ustawić opis «$($params.Description)»?"
            }
            'Move' {
                $ou = Select-OrganizationalUnit -Title 'Docelowa jednostka organizacyjna'
                if (-not $ou) { return }
                $params.TargetOU = $ou
                $question = "Przenieść konta komputerów do:`r`n$ou ?"
            }
        }
        $targets = @(Confirm-Action -Text $question -Items $targets -ConfirmText $(if ($Op -eq 'Delete') { 'Usuń konta' } else { 'Wykonaj' }) -Danger:$danger -Select); if ($targets.Count -eq 0) { return }
        $m.Data.LastOp = $Op
        Start-AdOperation -Module $m -Name "Konto komputera – $Op" -Targets $targets -TargetColumn 'Komputer' -Output Log -Parameters $params -OnComplete { param($m) if ($m.Data.LastOp -ne 'Delete') { & $m.Actions.List $m } } -ScriptBlock {
            $c = Get-ADComputer -Identity $Target @ad
            switch ($P.Op) {
                'Reset' {
                    # Odpowiednik "Resetuj konto" z konsoli ADUC: hasło = nazwa komputera małymi literami (bez $, maks. 14 znaków)
                    $plain = $c.SamAccountName.TrimEnd('$').ToLowerInvariant()
                    if ($plain.Length -gt 14) { $plain = $plain.Substring(0, 14) }
                    Set-ADAccountPassword -Identity $c -Reset -NewPassword (ConvertTo-SecureString $plain -AsPlainText -Force) @ad
                    'Konto zresetowane – dołącz komputer ponownie do domeny lub napraw kanał zaufania.'
                }
                'Enable' { Enable-ADAccount -Identity $c @ad; 'Konto włączone.' }
                'Disable' { Disable-ADAccount -Identity $c @ad; 'Konto wyłączone.' }
                'Move' { Move-ADObject -Identity $c.DistinguishedName -TargetPath $P.TargetOU @ad; "Przeniesiono do $($P.TargetOU)." }
                'Describe' {
                    if ($P.Description) { Set-ADComputer -Identity $c -Description $P.Description @ad } else { Set-ADComputer -Identity $c -Clear description @ad }
                    'Opis ustawiony.'
                }
                'Delete' { Remove-ADObject -Identity $c.DistinguishedName -Recursive -Confirm:$false @ad; 'Konto usunięte z AD.' }
            }
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Informacje'
    Add-Button -Parent $row -Text 'Informacje z AD' -Icon 'E946' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Test kanału zaufania' -Icon 'E9D9' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Start-HostOperation -Module $m -Name 'Test kanału zaufania' -Targets $targets -Parameters @{ Server = [string]$script:Settings.DomainController } -ScriptBlock {
            param($P)
            $tp = @{ ErrorAction = 'Stop' }
            if ($P.Server) { $tp.Server = $P.Server }
            $ok = Test-ComputerSecureChannel @tp
            $domain = (Get-CimInstance -ClassName Win32_ComputerSystem).Domain
            $dc = ''
            try {
                $text = (& nltest.exe "/sc_query:$domain" 2>&1) -join "`n"
                if ($text -match '\\\\([^\s\\]+)') { $dc = $Matches[1] }
            }
            catch { }
            [pscustomobject]@{
                'Stan'             = $(if ($ok) { 'Kanał poprawny' } else { 'Kanał uszkodzony' })
                'Domena'           = $domain
                'Kontroler domeny' = $dc
                '__tone'           = $(if ($ok) { 'ok' } else { 'crit' })
            }
        }
    } | Out-Null
    Add-Button -Parent $row -Text 'Napraw kanał zaufania' -Icon 'E90F' -Module $m -Danger -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $cred = Get-EffectiveCredential
        if (-not $cred) {
            $cred = Show-CredentialDialog -Message 'Naprawa kanału zaufania wymaga poświadczeń domenowych z prawem resetu konta komputera (nie przechodzą przez WinRM automatycznie).'
            if (-not $cred) { return }
        }
        $targets = @(Confirm-Action -Text "Naprawić kanał zaufania (Test-ComputerSecureChannel -Repair)?" -Items $targets -ConfirmText 'Napraw' -Select); if ($targets.Count -eq 0) { return }
        Start-HostOperation -Module $m -Name 'Naprawa kanału zaufania' -Targets $targets -Output Log -Parameters @{ Credential = $cred; Server = [string]$script:Settings.DomainController } -ScriptBlock {
            param($P)
            $tp = @{ Repair = $true; Credential = $P.Credential; ErrorAction = 'Stop' }
            if ($P.Server) { $tp.Server = $P.Server }
            if (Test-ComputerSecureChannel @tp) { 'Kanał zaufania naprawiony.' } else { 'Błąd – naprawa nie powiodła się.' }
        }
    } | Out-Null
    Add-ObjectReportRow -Module $m -Kind 'Computer'
    $row2 = Add-ToolbarRow -Module $m -Title 'Konto w AD'
    Add-Button -Parent $row2 -Text 'Włącz' -Icon 'E73E' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Enable' } | Out-Null
    Add-Button -Parent $row2 -Text 'Wyłącz' -Icon 'E8D8' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Disable' } | Out-Null
    Add-Button -Parent $row2 -Text 'Przenieś do OU…' -Icon 'E8DE' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Move' } | Out-Null
    Add-Button -Parent $row2 -Text 'Resetuj konto' -Icon 'E777' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Reset' } | Out-Null
    Add-Button -Parent $row2 -Text 'Usuń z AD' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Change $m 'Delete' } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Opis'
    $m.Description = Add-TextBox -Parent $row3 -Width 360 -Placeholder 'opis konta komputera (puste = usuń opis)'
    Add-Button -Parent $row3 -Text 'Ustaw opis' -Icon 'E70F' -Module $m -OnClick { param($m) & $m.Actions.Change $m 'Describe' } | Out-Null
    $row4 = Add-ToolbarRow -Module $m -Title 'Nowe konto'
    Add-Button -Parent $row4 -Text 'Utwórz konto komputera…' -Icon 'E710' -Module $m -OnClick {
        param($m)
        if (-not (Test-AdAvailable)) { return }
        $text = Show-InputDialog -Title 'Nowe konta komputerów' -Prompt 'Nazwy komputerów (NetBIOS, maks. 15 znaków) – po jednej w wierszu. Konta zostaną utworzone jako włączone, gotowe do dołączenia komputerów do domeny.' -Multiline -Icon 'E977' -Validate {
            param($t)
            foreach ($n in (Read-NameList $t)) { $problem = Test-NetBiosName $n; if ($problem) { return "$n`: $problem" } }
            if (@(Read-NameList $t).Count -eq 0) { return 'Wpisz co najmniej jedną nazwę.' }
            return ''
        }
        if (-not $text) { return }
        $names = @(Read-NameList $text | ForEach-Object { $_.ToUpperInvariant() })
        $ou = Select-OrganizationalUnit -Title 'Jednostka dla nowych kont komputerów'
        if (-not $ou) { return }
        $names = @(Confirm-Action -Text "Utworzyć konta komputerów w:`r`n$ou ?" -Items $names -ConfirmText 'Utwórz' -Select); if ($names.Count -eq 0) { return }
        Start-AdOperation -Module $m -Name 'Tworzenie kont komputerów' -Targets $names -TargetColumn 'Komputer' -Output Log -Parameters @{ Path = $ou } -ScriptBlock {
            New-ADComputer -Name $Target -SamAccountName "$Target`$" -Path $P.Path -Enabled $true @ad
            "Utworzono w $($P.Path)."
        } -OnComplete {
            param($m)
            Show-Toast 'Utworzono konta – możesz dodać je do listy przyciskiem «Wczytaj z AD».' 'ok'
        }
    } | Out-Null
}

Register-Module -Workspace 'AdComputers' -Category 'Hasła i klucze' -Key 'Laps' -Title 'LAPS' -Icon 'E8D7' `
    -Description 'Hasła lokalnego administratora z AD (Windows LAPS, także szyfrowane, oraz LAPS legacy), wymuszanie zmiany hasła i bezpieczne kopiowanie do schowka (czyszczonego po 60 s).' -Build {
    param($m)
    $m.SecretColumns = @('Hasło')
    $m.PillColumns = @('Rozwiązanie')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-AdComputerTargets)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'LAPS – odczyt' -Targets $targets -TargetColumn 'Komputer' -ScriptBlock {
            $toDate = {
                param($Value)
                if ($null -eq $Value -or [string]$Value -eq '' -or [string]$Value -eq '0') { return $null }
                try { return [DateTime]::FromFileTimeUtc([int64][string]$Value).ToLocalTime() } catch { return $null }
            }
            $c = Get-ADComputer -Identity $Target -Properties 'msLAPS-Password', 'msLAPS-PasswordExpirationTime', 'msLAPS-EncryptedPassword', 'ms-Mcs-AdmPwd', 'ms-Mcs-AdmPwdExpirationTime' @ad
            $row = $null
            $lapsError = ''
            if (Get-Command Get-LapsADPassword -ErrorAction SilentlyContinue) {
                try {
                    $lp = @{ Identity = $Target; AsPlainText = $true; ErrorAction = 'Stop' }
                    if ($Ctx.Server) { $lp.DomainController = $Ctx.Server }
                    if ($Ctx.Credential) { $lp.Credential = $Ctx.Credential }
                    $info = Get-LapsADPassword @lp
                    if ($info -and $info.Password) {
                        $row = [pscustomobject]@{ 'Rozwiązanie' = 'Windows LAPS'; 'Konto' = $info.Account; 'Hasło' = [string]$info.Password; 'Zmienione' = $info.PasswordUpdateTime; 'Wygasa' = $info.ExpirationTimestamp; 'Źródło' = [string]$info.Source; 'Uwagi' = ''; '__tone' = 'ok' }
                    }
                    elseif ($info) { $lapsError = "Status odszyfrowania: $($info.DecryptionStatus)" }
                }
                catch { $lapsError = $_.Exception.Message }
            }
            if (-not $row -and $c.'msLAPS-Password') {
                try {
                    $json = [string]$c.'msLAPS-Password' | ConvertFrom-Json
                    $row = [pscustomobject]@{ 'Rozwiązanie' = 'Windows LAPS'; 'Konto' = $json.n; 'Hasło' = [string]$json.p; 'Zmienione' = $null; 'Wygasa' = (& $toDate $c.'msLAPS-PasswordExpirationTime'); 'Źródło' = 'msLAPS-Password'; 'Uwagi' = ''; '__tone' = 'ok' }
                }
                catch { }
            }
            if (-not $row -and $c.'ms-Mcs-AdmPwd') {
                $row = [pscustomobject]@{ 'Rozwiązanie' = 'LAPS (legacy)'; 'Konto' = '(wg zasad GPO)'; 'Hasło' = [string]$c.'ms-Mcs-AdmPwd'; 'Zmienione' = $null; 'Wygasa' = (& $toDate $c.'ms-Mcs-AdmPwdExpirationTime'); 'Źródło' = 'ms-Mcs-AdmPwd'; 'Uwagi' = ''; '__tone' = 'info' }
            }
            if (-not $row) {
                $note = 'Brak hasła LAPS albo brak uprawnień do odczytu.'
                if ($c.'msLAPS-EncryptedPassword') { $note = 'Hasło jest zaszyfrowane – brak uprawnień do odszyfrowania lub brak modułu LAPS (RSAT).' }
                if ($lapsError) { $note += " ($lapsError)" }
                $row = [pscustomobject]@{ 'Rozwiązanie' = 'brak'; 'Konto' = ''; 'Hasło' = ''; 'Zmienione' = $null; 'Wygasa' = $null; 'Źródło' = ''; 'Uwagi' = $note; '__tone' = 'crit' }
            }
            $row
        }
    }
    $m.Actions.Copy = {
        param($m, $Rows)
        $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $m })
        $selected = $source | Select-Object -First 1
        $secret = [string](Get-RowValue $selected 'Hasło')
        if (-not $secret) { Show-Warning 'Zaznacz wiersz z hasłem.'; return }
        Set-ClipboardSecret -Text $secret -Seconds 60
        Write-Log ("Skopiowano hasło LAPS komputera {0}; schowek zostanie wyczyszczony po 60 s." -f (Get-ObjectValue $selected 'Komputer')) 'OK'
        Show-Toast 'Hasło w schowku – zostanie wyczyszczone po 60 s.' 'ok'
    }
    $row = Add-ToolbarRow -Module $m -Title 'Hasła'
    Add-Button -Parent $row -Text 'Pokaż hasła LAPS' -Icon 'E8D7' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Kopiuj hasło zaznaczonego' -Icon 'E8C8' -Module $m -AlwaysEnabled -OnClick { param($m) & $m.Actions.Copy $m $null } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Zmiana hasła'
    $m.ProcessNow = Add-CheckBox -Parent $row2 -Text 'Od razu przetwórz zasady na komputerze' -Checked $true
    Add-Button -Parent $row2 -Text 'Wymuś zmianę hasła' -Icon 'E777' -Module $m -Danger -OnClick {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        $targets = @(Confirm-Action -Text "Wymusić zmianę hasła LAPS (ustawienie wygaśnięcia na teraz)?" -Items $targets -ConfirmText 'Wymuś zmianę' -Select); if ($targets.Count -eq 0) { return }
        Start-AdOperation -Module $m -Name 'LAPS – wymuszenie zmiany' -Targets $targets -TargetColumn 'Komputer' -Output Log -Parameters @{ ProcessNow = (Test-Checked $m.ProcessNow) } -ScriptBlock {
            $name = ($Target -split '\.')[0]
            $c = Get-ADComputer -Identity $name -Properties 'msLAPS-PasswordExpirationTime', 'msLAPS-EncryptedPassword', 'msLAPS-Password', 'ms-Mcs-AdmPwdExpirationTime', 'ms-Mcs-AdmPwd' @ad
            $done = @()
            if ($c.'msLAPS-PasswordExpirationTime' -or $c.'msLAPS-EncryptedPassword' -or $c.'msLAPS-Password') {
                if (Get-Command Set-LapsADPasswordExpirationTime -ErrorAction SilentlyContinue) {
                    $sp = @{ Identity = $name; WhenEffective = (Get-Date); ErrorAction = 'Stop' }
                    if ($Ctx.Server) { $sp.DomainController = $Ctx.Server }
                    if ($Ctx.Credential) { $sp.Credential = $Ctx.Credential }
                    Set-LapsADPasswordExpirationTime @sp | Out-Null
                }
                else { Set-ADComputer -Identity $c -Replace @{ 'msLAPS-PasswordExpirationTime' = 0 } @ad }
                $done += 'Windows LAPS'
            }
            if ($c.'ms-Mcs-AdmPwdExpirationTime' -or $c.'ms-Mcs-AdmPwd') {
                Set-ADComputer -Identity $c -Replace @{ 'ms-Mcs-AdmPwdExpirationTime' = 0 } @ad
                $done += 'LAPS legacy'
            }
            if ($done.Count -eq 0) { throw 'Komputer nie ma atrybutów LAPS w AD (albo brak uprawnień do ich odczytu).' }
            $msg = 'Ustawiono natychmiastowe wygaśnięcie hasła (' + ($done -join ', ') + ')'
            if ($P.ProcessNow) {
                $ic = @{
                    ComputerName = $Target
                    ErrorAction  = 'Stop'
                    ScriptBlock  = {
                        if (Get-Command Invoke-LapsPolicyProcessing -ErrorAction SilentlyContinue) { Invoke-LapsPolicyProcessing; 'Invoke-LapsPolicyProcessing' }
                        else { & gpupdate.exe /target:computer /force | Out-Null; 'gpupdate' }
                    }
                }
                if ($Ctx.Credential) { $ic.Credential = $Ctx.Credential }
                if ($Ctx.SessionOption) { $ic.SessionOption = $Ctx.SessionOption }
                try { $msg += '; na komputerze uruchomiono ' + (Invoke-Command @ic) }
                catch { $msg += '; nie udało się wymusić przetwarzania na komputerze: ' + $_.Exception.Message }
            }
            $msg + '.'
        }
    } | Out-Null
    Add-RowAction -Module $m -Text 'Kopiuj hasło (60 s)' -Icon 'E8C8' -Action { param($m, $rows) & $m.Actions.Copy $m $rows }
    $m.RowDoubleClick = { param($m, $row) & $m.Actions.Copy $m @($row) }
    $m.ResultHint = 'Dwuklik na wierszu – kopiuje hasło do schowka (60 s)'
}

Register-Module -Workspace 'AdComputers' -Category 'Hasła i klucze' -Key 'BitLockerKeys' -Title 'Klucze BitLocker (AD)' -Icon 'E72E' `
    -Description 'Hasła odzyskiwania BitLocker zapisane w AD: dla zaznaczonych komputerów albo wyszukiwanie po identyfikatorze klucza z ekranu odzyskiwania (cała domena). Wymaga uprawnień do msFVE-RecoveryInformation.' -Build {
    param($m)
    $m.SecretColumns = @('Hasło odzyskiwania')
    $m.Actions.Copy = {
        param($m, $Rows)
        $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $m })
        $row = $source | Select-Object -First 1
        $secret = [string](Get-RowValue $row 'Hasło odzyskiwania')
        if (-not $secret) { Show-Warning 'Zaznacz wiersz z hasłem odzyskiwania.'; return }
        Set-ClipboardSecret -Text $secret -Seconds 60
        Write-Log ("Skopiowano hasło odzyskiwania BitLocker ({0}, klucz {1}); schowek zostanie wyczyszczony po 60 s." -f (Get-ObjectValue $row 'Komputer'), (Get-ObjectValue $row 'Identyfikator klucza')) 'OK'
        Show-Toast 'Hasło odzyskiwania w schowku – zostanie wyczyszczone po 60 s.' 'ok'
    }
    $row = Add-ToolbarRow -Module $m -Title 'Komputery'
    Add-Button -Parent $row -Text 'Klucze zaznaczonych komputerów' -Icon 'E72E' -Module $m -Primary -OnClick {
        param($m)
        $targets = @(Get-AdComputerTargets)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'BitLocker – klucze w AD' -Targets $targets -TargetColumn 'Komputer' -ScriptBlock {
            $computer = Get-ADComputer -Identity $Target @ad
            $keys = @(Get-ADObject -SearchBase $computer.DistinguishedName -LDAPFilter '(objectClass=msFVE-RecoveryInformation)' -Properties 'msFVE-RecoveryPassword', 'whenCreated' @ad)
            if ($keys.Count -eq 0) { return [pscustomobject]@{ 'Identyfikator klucza' = '(brak kluczy w AD albo brak uprawnień do ich odczytu)'; '__flag' = 'warn' } }
            $keys | Sort-Object whenCreated -Descending | ForEach-Object {
                $id = if ($_.Name -match '\{([0-9A-Fa-f-]{36})\}') { $Matches[1] } else { $_.Name }
                [pscustomobject]@{ 'Utworzono' = $_.whenCreated; 'Identyfikator klucza' = $id; 'Hasło odzyskiwania' = $_.'msFVE-RecoveryPassword' }
            }
        }
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Wyszukiwanie'
    $m.KeyId = Add-TextBox -Parent $row2 -Width 260 -Placeholder 'ID klucza (min. 8 znaków), np. 1A2B3C4D'
    Add-Button -Parent $row2 -Text 'Znajdź komputer po ID klucza' -Icon 'E721' -Module $m -OnClick {
        param($m)
        $id = ($m.KeyId.Text.Trim() -replace '[{}\s]', '')
        if ($id -notmatch '^[0-9A-Fa-f-]{8,36}$') { Show-Warning 'Podaj co najmniej 8 pierwszych znaków identyfikatora klucza (cyfry szesnastkowe).'; return }
        Start-AdOperation -Module $m -Name 'BitLocker – wyszukiwanie klucza' -Targets @('AD') -Parameters @{ Id = $id } -ScriptBlock {
            $keys = @(Get-ADObject -LDAPFilter ("(&(objectClass=msFVE-RecoveryInformation)(name=*{{{0}*))" -f $P.Id) -Properties 'msFVE-RecoveryPassword', 'whenCreated' @ad)
            if ($keys.Count -eq 0) { return [pscustomobject]@{ 'Komputer' = '(nie znaleziono klucza o tym identyfikatorze)'; '__flag' = 'warn' } }
            foreach ($k in $keys) {
                $parent = $k.DistinguishedName -replace '^CN=(?:\\.|[^,])+,', ''
                $id = if ($k.Name -match '\{([0-9A-Fa-f-]{36})\}') { $Matches[1] } else { $k.Name }
                [pscustomobject][ordered]@{
                    'Komputer'             = (($parent -replace '^CN=((?:\\.|[^,])+),.*$', '$1') -replace '\\(.)', '$1')
                    'Utworzono'            = $k.whenCreated
                    'Identyfikator klucza' = $id
                    'Hasło odzyskiwania'   = $k.'msFVE-RecoveryPassword'
                    'DN komputera'         = $parent
                }
            }
        }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Kopiuj hasło zaznaczonego' -Icon 'E8C8' -Module $m -AlwaysEnabled -OnClick { param($m) & $m.Actions.Copy $m $null } | Out-Null
    Add-RowAction -Module $m -Text 'Kopiuj hasło odzyskiwania (60 s)' -Icon 'E8C8' -Action { param($m, $rows) & $m.Actions.Copy $m $rows }
    $m.RowDoubleClick = { param($m, $row) & $m.Actions.Copy $m @($row) }
    $m.ResultHint = 'Dwuklik na wierszu – kopiuje hasło odzyskiwania (60 s)'
}

Register-Module -Workspace 'AdComputers' -Category 'Konta komputerów' -Key 'Rename' -Title 'Zmiana nazwy komputerów' -Icon 'E8AC' `
    -Description 'Wsadowa zmiana nazw z autonumeracją, mapowaniem z listy i walidacją (NetBIOS: maks. 15 znaków). Kolumnę «Nowa nazwa» można edytować bezpośrednio w tabeli.' -Build {
    param($m)
    $m.PillColumns = @('Walidacja')
    $m.Validate = {
        param($m)
        [void]$m.Grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $names = @{}
        foreach ($r in $m.Table.Rows) {
            $new = ([string]$r['Nowa nazwa']).Trim()
            if ($new) { $names[$new] = 1 + [int]$names[$new] }
        }
        $valid = 0
        foreach ($r in $m.Table.Rows) {
            $old = [string]$r['Komputer']
            $new = ([string]$r['Nowa nazwa']).Trim()
            $problem = Test-NetBiosName -Name $new
            if (-not $problem -and $new -eq ($old -split '\.')[0]) { $problem = 'Nazwa bez zmian' }
            if (-not $problem -and $names[$new] -gt 1) { $problem = 'Nazwa powtarza się na liście' }
            if (-not $problem -and $script:UI.HostTable.Rows.Find($new)) { $problem = 'Taki komputer jest już na liście' }
            if ($problem) { $r['Walidacja'] = $problem; $r['__tone'] = 'crit' } else { $r['Walidacja'] = 'OK'; $r['__tone'] = 'ok'; $valid++ }
        }
        return $valid
    }
    $m.Actions.Load = {
        param($m)
        $targets = @(Get-TargetComputers)
        if (-not $targets) { return }
        Reset-ResultTable -Module $m
        foreach ($t in $targets) { Add-ResultRows -Module $m -Computer $t -Objects @([pscustomobject]@{ 'Nowa nazwa' = ''; 'Walidacja' = ''; 'Wynik' = '' }) }
        $m.Grid.IsReadOnly = $false
        foreach ($c in $m.Grid.Columns) { $c.IsReadOnly = ([string]$c.SortMemberPath -ne 'Nowa nazwa') }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    Add-Button -Parent $row -Text 'Wczytaj zaznaczone komputery' -Icon 'E896' -Module $m -Primary -OnClick $m.Actions.Load | Out-Null
    Add-Button -Parent $row -Text 'Mapowanie z listy…' -Icon 'E8A5' -Module $m -OnClick {
        param($m)
        $text = Show-InputDialog -Title 'Mapowanie nazw' -Prompt 'Wklej pary «STARA NOWA» – po jednej w wierszu (rozdzielone spacją, średnikiem, przecinkiem albo tabulatorem, np. z Excela).' -Multiline -Icon 'E8AC'
        if (-not $text) { return }
        $map = [ordered]@{}
        foreach ($line in ($text -split "`r?`n")) {
            $parts = @($line.Trim() -split '[\s;,]+' | Where-Object { $_ })
            if ($parts.Count -ge 2) { $map[$parts[0]] = $parts[1].ToUpperInvariant() }
        }
        if ($map.Count -eq 0) { Show-Warning 'Nie rozpoznano par nazw.'; return }
        if ($m.Table.Rows.Count -eq 0 -or -not $m.Table.Columns.Contains('Nowa nazwa')) {
            Reset-ResultTable -Module $m
            foreach ($k in $map.Keys) { Add-ResultRows -Module $m -Computer $k -Objects @([pscustomobject]@{ 'Nowa nazwa' = ''; 'Walidacja' = ''; 'Wynik' = '' }) }
            $m.Grid.IsReadOnly = $false
            foreach ($c in $m.Grid.Columns) { $c.IsReadOnly = ([string]$c.SortMemberPath -ne 'Nowa nazwa') }
        }
        $hit = 0
        foreach ($r in $m.Table.Rows) {
            $old = ([string]$r['Komputer'] -split '\.')[0]
            foreach ($k in $map.Keys) { if ($k -eq $old -or $k -eq [string]$r['Komputer']) { $r['Nowa nazwa'] = $map[$k]; $hit++ } }
        }
        [void](& $m.Validate $m)
        Show-Toast "Dopasowano nazw: $hit z $($map.Count)" $(if ($hit -eq $map.Count) { 'ok' } else { 'warn' })
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Autonumeracja'
    Add-Label -Parent $row2 -Text 'Prefiks' | Out-Null
    $m.Prefix = Add-TextBox -Parent $row2 -Width 100 -Text 'PC-'
    Add-Label -Parent $row2 -Text 'Start' | Out-Null
    $m.Start = Add-Numeric -Parent $row2 -Value 1 -Minimum 0 -Maximum 99999 -Width 70
    Add-Label -Parent $row2 -Text 'Cyfr' | Out-Null
    $m.Pad = Add-Numeric -Parent $row2 -Value 3 -Minimum 1 -Maximum 8 -Width 50
    Add-Label -Parent $row2 -Text 'Sufiks' | Out-Null
    $m.Suffix = Add-TextBox -Parent $row2 -Width 80
    Add-Button -Parent $row2 -Text 'Numeruj' -Icon 'E8EF' -Module $m -OnClick {
        param($m)
        if ($m.Table.Rows.Count -eq 0 -or -not $m.Table.Columns.Contains('Nowa nazwa')) { Show-Warning 'Najpierw wczytaj zaznaczone komputery.'; return }
        [void]$m.Grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
        $n = Get-Num $m.Start
        $format = 'D' + (Get-Num $m.Pad)
        # Numeracja w kolejności widocznej w tabeli (z uwzględnieniem sortowania i filtra)
        foreach ($drv in @($m.Grid.Items | Where-Object { $_ -is [System.Data.DataRowView] })) {
            $drv.Row['Nowa nazwa'] = ($m.Prefix.Text.Trim() + $n.ToString($format) + $m.Suffix.Text.Trim()).ToUpperInvariant()
            $n++
        }
        [void](& $m.Validate $m)
    } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Zmiana'
    Add-Button -Parent $row3 -Text 'Sprawdź nazwy' -Icon 'E73E' -Module $m -OnClick {
        param($m)
        if ($m.Table.Rows.Count -eq 0 -or -not $m.Table.Columns.Contains('Nowa nazwa')) { Show-Warning 'Najpierw wczytaj zaznaczone komputery.'; return }
        $valid = & $m.Validate $m
        Show-Toast "Poprawnych nowych nazw: $valid z $($m.Table.Rows.Count)" $(if ($valid -eq $m.Table.Rows.Count) { 'ok' } else { 'warn' })
    } | Out-Null
    $m.Restart = Add-CheckBox -Parent $row3 -Text 'Restart po zmianie (za 30 s)' -Checked $true
    Add-Button -Parent $row3 -Text 'Zmień nazwy' -Icon 'E8AC' -Module $m -Danger -OnClick {
        param($m)
        if ($m.Table.Rows.Count -eq 0 -or -not $m.Table.Columns.Contains('Nowa nazwa')) { Show-Warning 'Najpierw wczytaj zaznaczone komputery.'; return }
        $valid = & $m.Validate $m
        if ($valid -eq 0) { Show-Warning 'Brak poprawnych nowych nazw – sprawdź kolumnę «Walidacja».'; return }
        $per = @{}
        $items = @()
        foreach ($r in $m.Table.Rows) {
            if ([string]$r['Walidacja'] -ne 'OK') { continue }
            $old = [string]$r['Komputer']
            $new = ([string]$r['Nowa nazwa']).Trim()
            $per[$old] = @{ NewName = $new; Restart = (Test-Checked $m.Restart); Credential = $null }
            $items += "$old → $new"
        }
        $cred = Get-EffectiveCredential
        if (-not $cred) {
            $cred = Show-CredentialDialog -Message 'Zmiana nazwy komputera w domenie wymaga poświadczeń domenowych z prawem zmiany obiektu komputera (nie przechodzą przez WinRM automatycznie).'
            if (-not $cred) { return }
        }
        foreach ($k in @($per.Keys)) { $per[$k].Credential = $cred }
        $skipped = $m.Table.Rows.Count - $per.Count
        $question = 'Zmienić nazwy komputerów?'
        if ($skipped -gt 0) { $question += " (pominięte z powodu walidacji: $skipped)" }
        if (-not (Confirm-Action -Text $question -Items $items -ConfirmText 'Zmień nazwy' -Danger)) { return }
        $m.Grid.IsReadOnly = $true
        Start-HostOperation -Module $m -Name 'Zmiana nazw' -Targets @($per.Keys) -PerTarget $per -Output Log -ScriptBlock {
            param($P)
            $rp = @{ NewName = $P.NewName; DomainCredential = $P.Credential; Force = $true; ErrorAction = 'Stop'; WarningAction = 'SilentlyContinue' }
            Rename-Computer @rp
            if ($P.Restart) {
                & (Join-Path $env:SystemRoot 'System32\shutdown.exe') /r /t 30 /d p:4:2 /c ('Zmiana nazwy komputera na ' + $P.NewName) | Out-Null
                "Zmieniono nazwę na $($P.NewName) – restart za 30 s."
            }
            else { "Zmieniono nazwę na $($P.NewName) – zmiana zadziała po restarcie." }
        } -OnResult {
            param($m, $r)
            $row = $null
            foreach ($x in $m.Table.Rows) { if ([string]$x['Komputer'] -eq $r.Target) { $row = $x; break } }
            if (-not $row) { return }
            if ($r.Ok) {
                Set-ResultValue -Module $m -Row $row -Column 'Wynik' -Value 'Zmieniono'
                Rename-ComputerRow -OldName $r.Target -NewName ([string]$row['Nowa nazwa']).Trim()
            }
            else {
                Set-ResultValue -Module $m -Row $row -Column 'Wynik' -Value ('Błąd – ' + ((@($r.Errors)) -join ' | '))
                $row['__flag'] = 'crit'
            }
        }
    } | Out-Null
    $m.ResultHint = 'Kliknij dwukrotnie komórkę «Nowa nazwa», aby ją edytować'
    $m.RowDoubleClick = { param($m, $row) }
}

Register-GroupMembershipModule -Workspace 'AdComputers' -Kind Computer -Key 'ComputerGroups' -Category 'Konta komputerów'

$script:ComputerReports = @(
    @{ Key = 'Inactive'; Name = 'Nieaktywne (brak logowania od N dni)' }
    @{ Key = 'Disabled'; Name = 'Wyłączone konta' }
    @{ Key = 'Created'; Name = 'Utworzone w ciągu N dni' }
    @{ Key = 'OsSummary'; Name = 'Podsumowanie systemów operacyjnych' }
    @{ Key = 'Unsupported'; Name = 'Nieobsługiwane systemy operacyjne' }
    @{ Key = 'NoLaps'; Name = 'Bez hasła LAPS w AD' }
    @{ Key = 'NoBitLocker'; Name = 'Bez klucza BitLocker w AD' }
    @{ Key = 'Servers'; Name = 'Serwery' }
    @{ Key = 'All'; Name = 'Wszystkie komputery' }
)

Register-Module -Workspace 'AdComputers' -Category 'Raporty' -Key 'ComputerReports' -Title 'Raporty komputerów' -Icon 'E9F9' `
    -Description 'Zestawienia z domeny lub jednostki: nieaktywne, wyłączone, nowe, systemy operacyjne, nieobsługiwane systemy, brak LAPS i kluczy BitLocker. Wyniki można przenieść na listę komputerów, wyłączyć, przenieść lub usunąć.' -Build {
    param($m)
    $m.ColorBools = $true
    $m.PillColumns = @('Stan')
    $row = Add-ToolbarRow -Module $m -Title 'Raport'
    $m.Report = Add-ComboBox -Parent $row -Items @($script:ComputerReports | ForEach-Object { $_.Name }) -Width 340
    Add-Label -Parent $row -Text 'N (dni)' | Out-Null
    $m.Days = Add-Numeric -Parent $row -Value ([int]$script:Settings.InactiveDays) -Minimum 1 -Maximum 3650 -Width 70
    $m.OnlyEnabled = Add-CheckBox -Parent $row -Text 'Tylko włączone' -Checked $true
    $row2 = Add-ToolbarRow -Module $m -Title 'Zakres'
    $m.Ou = Add-TextBox -Parent $row2 -Width 420 -Placeholder 'Cała domena'
    Add-Button -Parent $row2 -Text '' -Icon 'E8B7' -Module $m -AlwaysEnabled -ToolTip 'Wybierz jednostkę organizacyjną' -OnClick {
        param($m)
        $ou = Select-OrganizationalUnit -Title 'Zakres raportu' -Selected $m.Ou.Text.Trim() -AllowDomainRoot
        if ($null -ne $ou) { $m.Ou.Text = $ou }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Generuj raport' -Icon 'E9F9' -Module $m -Primary -OnClick {
        param($m)
        $report = $script:ComputerReports[$m.Report.SelectedIndex]
        $params = @{ Report = $report.Key; Days = (Get-Num $m.Days); OnlyEnabled = (Test-Checked $m.OnlyEnabled); SearchBase = $m.Ou.Text.Trim() }
        Reset-StatTiles $m
        Start-AdOperation -Module $m -Name $report.Name -Targets @('AD') -Parameters $params -ScriptBlock {
            $now = Get-Date
            $days = [int]$P.Days
            $cut = $now.AddDays(-$days)
            $ft = $cut.ToFileTimeUtc()
            $gen = $cut.ToUniversalTime().ToString('yyyyMMddHHmmss.0Z')
            $extra = switch ($P.Report) {
                'Inactive' { "(|(lastLogonTimestamp<=$ft)(&(!(lastLogonTimestamp=*))(whenCreated<=$gen)))" }
                'Disabled' { '(userAccountControl:1.2.840.113556.1.4.803:=2)' }
                'Created' { "(whenCreated>=$gen)" }
                'Servers' { '(operatingSystem=*Server*)' }
                'NoLaps' { '(!(ms-Mcs-AdmPwdExpirationTime=*))(!(msLAPS-PasswordExpirationTime=*))' }
                default { '' }
            }
            if ($P.OnlyEnabled -and $P.Report -ne 'Disabled') { $extra += '(!(userAccountControl:1.2.840.113556.1.4.803:=2))' }
            $q = @{
                LDAPFilter = "(&(objectCategory=computer)$extra)"
                Properties = @('OperatingSystem', 'OperatingSystemVersion', 'Enabled', 'LastLogonDate', 'PasswordLastSet', 'whenCreated', 'Description', 'IPv4Address')
            }
            if ($P.SearchBase) { $q.SearchBase = $P.SearchBase }
            try { $computers = @(Get-ADComputer @q @ad) }
            catch {
                # Brak schematu LAPS (atrybut nieznany) - raport bez filtra jednego z atrybutów
                if ($P.Report -eq 'NoLaps') { $q.LDAPFilter = $q.LDAPFilter -replace '\(!\(msLAPS-PasswordExpirationTime=\*\)\)', ''; $computers = @(Get-ADComputer @q @ad) } else { throw }
            }
            if ($P.Report -eq 'OsSummary') {
                $computers | Group-Object { '{0}|{1}' -f $_.OperatingSystem, $_.OperatingSystemVersion } | Sort-Object Count -Descending | ForEach-Object {
                    $parts = $_.Name -split '\|'
                    [pscustomobject][ordered]@{ 'System' = $(if ($parts[0]) { $parts[0] } else { '(nieznany)' }); 'Wersja' = $parts[1]; 'Liczba' = $_.Count; 'Włączone' = @($_.Group | Where-Object { $_.Enabled }).Count }
                }
                return
            }
            $withKey = $null
            if ($P.Report -eq 'NoBitLocker') {
                $withKey = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
                $kq = @{ LDAPFilter = '(objectClass=msFVE-RecoveryInformation)' }
                if ($P.SearchBase) { $kq.SearchBase = $P.SearchBase }
                foreach ($k in @(Get-ADObject @kq @ad)) { [void]$withKey.Add(($k.DistinguishedName -replace '^CN=(?:\\.|[^,])+,', '')) }
            }
            # Systemy bez wsparcia producenta (stan na 2026 r.): Windows 10 poza LTSC, Windows 7/8.x, Server 2003-2012 R2
            $unsupported = 'Windows (XP|Vista|7|8|8\.1)( |$)|Windows 10 (?!.*LTSC)|Windows Server (2003|2008|2012)'
            foreach ($c in $computers) {
                $include = switch ($P.Report) {
                    'Unsupported' { [string]$c.OperatingSystem -match $unsupported }
                    'NoBitLocker' { -not $withKey.Contains($c.DistinguishedName) }
                    default { $true }
                }
                if (-not $include) { continue }
                $daysIdle = if ($c.LastLogonDate) { [int]($now - $c.LastLogonDate).TotalDays } else { $null }
                $state = if (-not $c.Enabled) { 'Wyłączone' } elseif ($null -eq $daysIdle) { 'Nigdy nie logowane' } elseif ($daysIdle -gt $days) { "Nieaktywne ($daysIdle dni)" } else { 'Aktywne' }
                [pscustomobject][ordered]@{
                    'Komputer'              = $c.Name
                    'Stan'                  = $state
                    'System'                = $c.OperatingSystem
                    'Wersja'                = $c.OperatingSystemVersion
                    'Włączone'              = [bool]$c.Enabled
                    'Ostatnie logowanie'    = $c.LastLogonDate
                    'Dni bez logowania'     = $daysIdle
                    'Hasło konta zmienione' = $c.PasswordLastSet
                    'Utworzono'             = $c.whenCreated
                    'IPv4'                  = $c.IPv4Address
                    'Opis'                  = $c.Description
                    'DN'                    = $c.DistinguishedName
                    '__tone'                = $(if (-not $c.Enabled) { '' } elseif ($state -eq 'Aktywne') { 'ok' } else { 'warn' })
                }
            }
        } -OnComplete {
            param($m)
            $count = $m.Table.Rows.Count
            Set-StatTile -Module $m -Key 'count' -Value ([string]$count)
            if ($m.Table.Columns.Contains('Włączone') -and $m.Table.Columns.Contains('Komputer')) {
                Set-StatTile -Module $m -Key 'disabled' -Value ([string]@($m.Table.Rows | Where-Object { [string]$_['Włączone'] -eq 'Nie' }).Count)
                Set-StatTile -Module $m -Key 'inactive' -Value ([string]@($m.Table.Rows | Where-Object { [string]$_['Stan'] -like 'Nieaktywne*' -or [string]$_['Stan'] -eq 'Nigdy nie logowane' }).Count) -Tone 'warn'
            }
        }
    } | Out-Null
    $m.Actions.Bulk = {
        param($m, [string]$Op, $Rows)
        $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $m })
        $names = @($source | ForEach-Object { [string](Get-ObjectValue $_ 'Komputer') } | Where-Object { $_ -and $_ -notlike '(*' } | Select-Object -Unique)
        if ($names.Count -eq 0) { Show-Warning 'Zaznacz w tabeli komputery.'; return }
        $params = @{ Op = $Op; TargetOU = '' }
        switch ($Op) {
            'Disable' { if (-not (Confirm-Action -Text 'Wyłączyć konta wybranych komputerów?' -Items $names -ConfirmText 'Wyłącz' -Danger)) { return } }
            'Delete' { if (-not (Confirm-Action -Text 'USUNĄĆ konta wybranych komputerów z AD (razem z obiektami podrzędnymi)?' -Items $names -ConfirmText 'Usuń konta' -Danger)) { return } }
            'Move' {
                $ou = Select-OrganizationalUnit -Title 'Docelowa jednostka organizacyjna'
                if (-not $ou) { return }
                $params.TargetOU = $ou
                if (-not (Confirm-Action -Text "Przenieść konta do:`r`n$ou ?" -Items $names -ConfirmText 'Przenieś')) { return }
            }
        }
        Start-AdOperation -Module $m -Name "Raport – $Op" -Targets $names -TargetColumn 'Komputer' -Output Log -Parameters $params -ScriptBlock {
            $c = Get-ADComputer -Identity $Target @ad
            switch ($P.Op) {
                'Disable' { Disable-ADAccount -Identity $c @ad; 'Konto wyłączone.' }
                'Move' { Move-ADObject -Identity $c.DistinguishedName -TargetPath $P.TargetOU @ad; "Przeniesiono do $($P.TargetOU)." }
                'Delete' { Remove-ADObject -Identity $c.DistinguishedName -Recursive -Confirm:$false @ad; 'Konto usunięte z AD.' }
            }
        } -OnResult {
            param($m, $r)
            if ($r.Ok -and @($r.Data | Where-Object { [string]$_ -like 'Konto usunięte*' }).Count) {
                Remove-ResultRows -Module $m -Rows @($m.Table.Rows | Where-Object { [string]$_['Komputer'] -eq $r.Target })
            }
        }
    }
    $row3 = Add-ToolbarRow -Module $m -Title 'Wyniki'
    Add-Button -Parent $row3 -Text 'Zaznacz na liście komputerów' -Icon 'E8B3' -Module $m -AlwaysEnabled -OnClick { param($m) Add-ResultsToTargets -Module $m -Kind Computer -Column 'Komputer' } | Out-Null
    Add-Button -Parent $row3 -Text 'Wyłącz zaznaczone' -Icon 'E8D8' -Module $m -Danger -OnClick { param($m) & $m.Actions.Bulk $m 'Disable' $null } | Out-Null
    Add-Button -Parent $row3 -Text 'Przenieś zaznaczone…' -Icon 'E8DE' -Module $m -OnClick { param($m) & $m.Actions.Bulk $m 'Move' $null } | Out-Null
    Add-Button -Parent $row3 -Text 'Usuń zaznaczone z AD' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Bulk $m 'Delete' $null } | Out-Null
    Add-RowAction -Module $m -Text 'Zaznacz na liście komputerów' -Icon 'E8B3' -Action { param($m, $rows) Add-ResultsToTargets -Module $m -Kind Computer -Column 'Komputer' -Rows $rows }
    Add-RowAction -Module $m -Text 'Wyłącz konto' -Icon 'E8D8' -Separator -Action { param($m, $rows) & $m.Actions.Bulk $m 'Disable' $rows }
    Add-RowAction -Module $m -Text 'Przenieś do OU…' -Icon 'E8DE' -Action { param($m, $rows) & $m.Actions.Bulk $m 'Move' $rows }
    Add-RowAction -Module $m -Text 'Usuń z AD' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Bulk $m 'Delete' $rows }
    Add-StatTile -Module $m -Key 'count' -Label 'Pozycje raportu' -Icon 'E977' | Out-Null
    Add-StatTile -Module $m -Key 'inactive' -Label 'Nieaktywne / nigdy nie logowane' -Icon 'E916' | Out-Null
    Add-StatTile -Module $m -Key 'disabled' -Label 'Wyłączone' -Icon 'E8D8' | Out-Null
    $m.EmptyHint = 'Wybierz raport i kliknij «Generuj raport» (F5). Nie trzeba zaznaczać komputerów na liście.'
}
#endregion

#region Grupy AD: szczegóły, członkowie, członkostwo hurtowe
function Select-TargetGroups {
    # Zaznacza na liście grup tylko podane grupy (sAMAccountName) - np. przejście do innego modułu z wybranymi grupami
    param([string[]]$Sams)
    $panel = $script:UI.GroupPanel
    if (-not $panel) { return }
    Set-TargetCheck -Panel $panel -Mode UncheckAll
    $missing = @()
    foreach ($s in $Sams) {
        $row = $panel.Table.Rows.Find($s)
        if ($row) { $row['Sel'] = $true } else { $missing += $s }
    }
    if ($missing.Count -gt 0) { [void](Import-TargetRows -Panel $panel -Items @($missing | ForEach-Object { [pscustomobject]@{ Sam = $_ } }) -Source 'raport' -Check) }
    Update-TargetCount $panel
}

function Get-RowGroups {
    # Grupy, których dotyczy akcja: zaznaczone wiersze wyników (kolumna -Column) albo zaznaczenie na liście po lewej
    param([hashtable]$Module, $Rows, [string]$Column = 'Grupa')
    if ($null -ne $Rows) { return @($Rows | ForEach-Object { [string](Get-ObjectValue $_ $Column) } | Where-Object { $_ } | Select-Object -Unique) }
    return @(Get-TargetGroups)
}

$script:GroupChangeScript = {
    # Zmiany pojedynczej grupy ($Target = sAMAccountName); $P.Op wybiera operację
    $g = Get-ADGroup -Identity $Target -Properties Description, ProtectedFromAccidentalDeletion, adminCount, isCriticalSystemObject, mail @ad
    switch ($P.Op) {
        'Description' {
            $d = ([string]$P.Value).Replace('{nazwa}', $g.Name).Replace('{sam}', $g.SamAccountName).Replace('{opis}', [string]$g.Description).Trim()
            if ($d) { Set-ADGroup -Identity $g -Description $d @ad; "Opis: $d" }
            else { Set-ADGroup -Identity $g -Clear description @ad; 'Usunięto opis.' }
        }
        'ManagedBy' {
            if ($P.Value) {
                $mgr = Resolve-AdPrincipal -Id $P.Value -Classes @('user', 'group', 'contact')
                Set-ADGroup -Identity $g -ManagedBy $mgr.DistinguishedName @ad
                "Zarządca: $($mgr.Name)"
            }
            else { Set-ADGroup -Identity $g -Clear managedBy @ad; 'Usunięto zarządcę.' }
        }
        'Mail' {
            if ($P.Value) { Set-ADGroup -Identity $g -Replace @{ mail = [string]$P.Value } @ad; "E-mail: $($P.Value)" }
            else { Set-ADGroup -Identity $g -Clear mail @ad; 'Usunięto adres e-mail.' }
        }
        'Scope' {
            $notes = @()
            if ($P.Scope -and [string]$g.GroupScope -ne $P.Scope) {
                # Globalna <-> lokalna domeny tylko przez uniwersalną
                if ([string]$g.GroupScope -ne 'Universal' -and $P.Scope -ne 'Universal') { Set-ADGroup -Identity $g -GroupScope Universal @ad }
                Set-ADGroup -Identity $g -GroupScope $P.Scope @ad
                $notes += 'zakres: ' + (Get-ScopeLabel $P.Scope)
            }
            if ($P.Category -and [string]$g.GroupCategory -ne $P.Category) {
                Set-ADGroup -Identity $g -GroupCategory $P.Category @ad
                $notes += 'typ: ' + (Get-CategoryLabel $P.Category)
            }
            if ($notes.Count -eq 0) { 'Bez zmian.' } else { 'Zmieniono ' + ($notes -join ', ') + '.' }
        }
        'Move' {
            $wasProtected = [bool]$g.ProtectedFromAccidentalDeletion
            # Obiektu chronionego przed usunięciem nie da się przenieść - ochrona zdejmowana na czas przeniesienia
            if ($wasProtected) { Set-ADObject -Identity $g.DistinguishedName -ProtectedFromAccidentalDeletion $false @ad }
            Move-ADObject -Identity $g.DistinguishedName -TargetPath $P.Value @ad
            $newDn = '{0},{1}' -f ([regex]::Match($g.DistinguishedName, '^(?:\\.|[^,])+').Value), $P.Value
            if ($wasProtected) { Set-ADObject -Identity $newDn -ProtectedFromAccidentalDeletion $true @ad }
            [pscustomobject]@{ Wynik = "Przeniesiono do $($P.Value)."; DN = $newDn }
        }
        'Protect' {
            Set-ADObject -Identity $g.DistinguishedName -ProtectedFromAccidentalDeletion ([bool]$P.Value) @ad
            if ($P.Value) { 'Ochrona przed usunięciem: włączona.' } else { 'Ochrona przed usunięciem: wyłączona.' }
        }
        'Delete' {
            if ($g.isCriticalSystemObject -or $g.adminCount -eq 1) { throw 'Pominięto – grupa systemowa lub uprzywilejowana (adminCount = 1). Usuń ją ręcznie, jeśli to zamierzone.' }
            if ($g.ProtectedFromAccidentalDeletion) { throw 'Grupa jest chroniona przed przypadkowym usunięciem – najpierw wyłącz ochronę.' }
            Remove-ADObject -Identity $g.DistinguishedName -Confirm:$false @ad
            'Usunięto grupę.'
        }
        'Rename' {
            $notes = @()
            $dn = $g.DistinguishedName
            if ($P.Name -and $P.Name -cne $g.Name) {
                $wasProtected = [bool]$g.ProtectedFromAccidentalDeletion
                if ($wasProtected) { Set-ADObject -Identity $dn -ProtectedFromAccidentalDeletion $false @ad }
                Rename-ADObject -Identity $dn -NewName $P.Name @ad
                $dn = 'CN={0},{1}' -f (ConvertTo-RdnValue $P.Name), (Get-DnParent $dn)
                if ($wasProtected) { Set-ADObject -Identity $dn -ProtectedFromAccidentalDeletion $true @ad }
                $notes += "nazwa: $($P.Name)"
            }
            if ($P.Sam -and $P.Sam -ne $g.SamAccountName) { Set-ADGroup -Identity $dn -SamAccountName $P.Sam @ad; $notes += "sAMAccountName: $($P.Sam)" }
            if ($P.ContainsKey('Display')) {
                if ($P.Display) { Set-ADGroup -Identity $dn -DisplayName $P.Display @ad } else { Set-ADGroup -Identity $dn -Clear displayName @ad }
            }
            [pscustomobject]@{ Wynik = $(if ($notes.Count) { 'Zmieniono ' + ($notes -join ', ') + '.' } else { 'Bez zmian.' }); DN = $dn; Sam = $(if ($P.Sam) { $P.Sam } else { $g.SamAccountName }); Name = $(if ($P.Name) { $P.Name } else { $g.Name }) }
        }
    }
}

function Invoke-GroupChange {
    # Wspólna obsługa zmian grup (moduł szczegółów i akcje wierszy)
    param([hashtable]$Module, [string]$Op, $Rows = $null)
    $groups = @(Get-RowGroups -Module $Module -Rows $Rows)
    if ($groups.Count -eq 0) { return }
    $params = @{ Op = $Op; Value = $null }
    $confirmText = ''
    $danger = $false
    switch ($Op) {
        'Description' {
            $current = ''
            if ($groups.Count -eq 1) { $r = $script:UI.GroupTable.Rows.Find($groups[0]); if ($r) { $current = [string]$r['Description'] } }
            $v = Show-InputDialog -Title 'Opis grupy' -Prompt 'Nowy opis. Pola: {nazwa}, {sam}, {opis} (dotychczasowy opis). Puste pole usuwa opis.' -Default $current -Icon 'E70F'
            if ($null -eq $v) { return }
            $params.Value = $v
            $confirmText = $(if ($v.Trim()) { "Ustawić opis «$($v.Trim())»?" } else { 'Usunąć opis grup?' })
        }
        'ManagedBy' {
            $v = Show-InputDialog -Title 'Zarządca grupy' -Prompt 'Login użytkownika, nazwa grupy lub kontaktu (pole managedBy). Puste pole usuwa zarządcę.' -Icon 'E77B'
            if ($null -eq $v) { return }
            $params.Value = $v.Trim()
            $confirmText = $(if ($params.Value) { "Ustawić zarządcę «$($params.Value)»?" } else { 'Usunąć zarządcę grup?' })
        }
        'Mail' {
            $v = Show-InputDialog -Title 'Adres e-mail grupy' -Prompt 'Atrybut mail (np. dla grup dystrybucyjnych). Puste pole usuwa adres.' -Icon 'E715' -Validate { param($t) if (-not $t.Trim() -or $t.Trim() -match '^[^@\s]+@[^@\s]+\.[^@\s]+$') { '' } else { 'Podaj poprawny adres e-mail.' } }
            if ($null -eq $v) { return }
            $params.Value = $v.Trim()
            $confirmText = $(if ($params.Value) { "Ustawić adres e-mail «$($params.Value)»?" } else { 'Usunąć adres e-mail grup?' })
        }
        'Scope' {
            $f = Show-FormDialog -Title 'Zakres i typ grupy' -Subtitle 'Zmiana globalna ↔ lokalna domeny odbywa się przez zakres uniwersalny (dwa kroki). AD odrzuci zmianę, jeśli koliduje z członkostwem grupy.' -Icon 'E8AB' -Fields @(
                @{ Key = 'Scope'; Label = 'Zakres'; Type = 'Combo'; Items = @('bez zmian', 'Globalna', 'Lokalna domeny', 'Uniwersalna'); Value = 'bez zmian' }
                @{ Key = 'Category'; Label = 'Typ'; Type = 'Combo'; Items = @('bez zmian', 'Zabezpieczeń', 'Dystrybucyjna'); Value = 'bez zmian' }
            ) -Validate { param($v) if ($v.Scope -eq 'bez zmian' -and $v.Category -eq 'bez zmian') { 'Wybierz nowy zakres lub typ.' } else { '' } }
            if (-not $f) { return }
            $params.Scope = ConvertTo-GroupScope $f.Scope
            $params.Category = ConvertTo-GroupCategory $f.Category
            if ($params.Category -eq 'Distribution') { $danger = $true }
            $confirmText = 'Zmienić ' + ((@($(if ($params.Scope) { "zakres na «$($f.Scope)»" }), $(if ($params.Category) { "typ na «$($f.Category)»" }) | Where-Object { $_ })) -join ' i ') + '?'
            if ($params.Category -eq 'Distribution') { $confirmText += "`r`nGrupa dystrybucyjna nie nadaje uprawnień – wpisy ACL z tą grupą przestaną działać." }
        }
        'Move' {
            $ou = Select-OrganizationalUnit -Title 'Docelowa jednostka dla grup'
            if (-not $ou) { return }
            $params.Value = $ou
            $confirmText = "Przenieść grupy do:`r`n$ou ?"
        }
        'ProtectOn' { $params.Op = 'Protect'; $params.Value = $true; $confirmText = 'Włączyć ochronę przed przypadkowym usunięciem?' }
        'ProtectOff' { $params.Op = 'Protect'; $params.Value = $false; $confirmText = 'Wyłączyć ochronę przed przypadkowym usunięciem?' }
        'Delete' {
            $danger = $true
            $confirmText = "Usunąć wybrane grupy? Tej operacji nie można cofnąć – członkostwa i uprawnienia nadane grupie przepadną. Grupy systemowe, uprzywilejowane i chronione zostaną pominięte."
        }
    }
    $label = if ($Op -eq 'Delete') { 'Usuń grupy' } else { 'Wykonaj' }
    $groups = @(Confirm-Action -Text $confirmText -Items $groups -ConfirmText $label -Danger:$danger -Select); if ($groups.Count -eq 0) { return }
    $Module.Data.ChangeOp = $params.Op
    Start-AdOperation -Module $Module -Name "Grupy – $($params.Op)" -Targets $groups -TargetColumn 'Grupa' -Output Log -Parameters $params -ScriptBlock $script:GroupChangeScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) { return }
        switch ($m.Data.ChangeOp) {
            'Delete' {
                $row = $script:UI.GroupTable.Rows.Find($r.Target)
                if ($row) { $script:UI.GroupTable.Rows.Remove($row); $script:UI.GroupTable.AcceptChanges(); Update-TargetCount $script:UI.GroupPanel }
                Remove-ResultRows -Module $m -Rows @(Find-ResultRow -Module $m -Column 'Grupa' -Value $r.Target)
            }
            'Move' { $d = @($r.Data | Where-Object { $_ -isnot [string] }); if ($d.Count) { Update-GroupRow -Sam $r.Target -Values @{ DN = $d[0].DN } } }
            'Description' { Update-GroupRow -Sam $r.Target -Values @{ Description = ((@($r.Data) -join '') -replace '^Opis: ', '' -replace '^Usunięto opis\.$', '') } }
            'Mail' { Update-GroupRow -Sam $r.Target -Values @{ Mail = ((@($r.Data) -join '') -replace '^E-mail: ', '' -replace '^Usunięto adres e-mail\.$', '') } }
        }
    } -OnComplete {
        param($m)
        if ($m.Data.ChangeOp -eq 'Scope') { Write-Log 'Odśwież listę grup, aby zobaczyć nowe zakresy i typy.' }
        if ($m.Actions['List'] -and $m.Data.ChangeOp -ne 'Delete' -and $m.Table.Rows.Count -gt 0) { & $m.Actions.List $m }
    }
}

Register-Module -Workspace 'AdGroups' -Category 'Grupy' -Key 'GroupDetails' -Title 'Szczegóły grup' -Icon 'E946' `
    -Description 'Zakres, typ, opis, zarządca i liczba członków zaznaczonych grup. Zmiana opisu, zarządcy, adresu e-mail, zakresu i typu, nazwy, przeniesienie do innej OU, ochrona przed usunięciem i usuwanie grup.' -Build {
    param($m)
    $m.PillColumns = @('Typ')
    $m.ColorBools = $true
    $m.GoodWhenNo = @('Uprzywilejowana')
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetGroups)
        if (-not $targets) { return }
        Start-AdOperation -Module $m -Name 'Szczegóły grup' -Targets $targets -TargetColumn 'Grupa' -ScriptBlock {
            $g = Get-ADGroup -Identity $Target -Properties Description, mail, managedBy, info, memberOf, whenCreated, whenChanged, adminCount, ProtectedFromAccidentalDeletion, displayName @ad
            $rid = [int](([string]$g.SID.Value) -split '-')[-1]
            $primary = if (@(513, 515, 516, 521) -contains $rid) { $rid } else { 0 }
            $members = @(Get-GroupMemberObjects -GroupDn $g.DistinguishedName -PrimaryRid $primary)
            $kinds = @{}
            $disabled = 0
            foreach ($o in $members) {
                $k = [string]$o.ObjectClass
                $kinds[$k] = 1 + [int]$kinds[$k]
                if (($k -eq 'user' -or $k -eq 'computer') -and ([int64]$o.userAccountControl -band 2)) { $disabled++ }
            }
            [pscustomobject][ordered]@{
                'Nazwa'                      = $g.Name
                'Zakres'                     = Get-ScopeLabel $g.GroupScope
                'Typ'                        = Get-CategoryLabel $g.GroupCategory
                'Opis'                       = $g.Description
                'E-mail'                     = $g.mail
                'Zarządca'                   = $(if ($g.managedBy) { Get-DnName $g.managedBy } else { '' })
                'Członkowie'                 = $members.Count
                'Użytkownicy'                = [int]$kinds['user'] + [int]$kinds['inetOrgPerson']
                'Komputery'                  = [int]$kinds['computer']
                'Grupy'                      = [int]$kinds['group']
                'Wyłączone konta'            = $disabled
                'Należy do grup'             = @($g.memberOf).Count
                'Chroniona przed usunięciem' = [bool]$g.ProtectedFromAccidentalDeletion
                'Uprzywilejowana'            = ($g.adminCount -eq 1)
                'Utworzono'                  = $g.whenCreated
                'Zmieniono'                  = $g.whenChanged
                'Nazwa wyświetlana'          = $g.displayName
                'Uwagi'                      = $g.info
                'Jednostka OU'               = Get-DnParent $g.DistinguishedName
                'SID'                        = [string]$g.SID
                'DN'                         = $g.DistinguishedName
                '__tone'                     = $(if ([string]$g.GroupCategory -eq 'Security') { 'info' } else { '' })
            }
        } -OnComplete {
            param($m)
            $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Status') -ne 'Błąd' })
            Set-StatTile -Module $m -Key 'groups' -Value ([string]$rows.Count)
            $sum = 0; $dis = 0; $empty = 0
            foreach ($r in $rows) {
                if ($m.Table.Columns.Contains('Członkowie')) { $sum += [int]$r['Członkowie']; if ([int]$r['Członkowie'] -eq 0) { $empty++ } }
                if ($m.Table.Columns.Contains('Wyłączone konta')) { $dis += [int]$r['Wyłączone konta'] }
            }
            Set-StatTile -Module $m -Key 'members' -Value ([string]$sum)
            Set-StatTile -Module $m -Key 'empty' -Value ([string]$empty) -Tone $(if ($empty) { 'warn' } else { '' })
            Set-StatTile -Module $m -Key 'disabled' -Value ([string]$dis) -Tone $(if ($dis) { 'warn' } else { '' })
        }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row -Text 'Pokaż szczegóły' -Icon 'E896' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    Add-Button -Parent $row -Text 'Pokaż członków' -Icon 'E716' -Module $m -AlwaysEnabled -ToolTip 'Przejdź do modułu «Członkowie grup» dla zaznaczonych grup' -OnClick {
        param($m)
        if (-not @(Get-TargetGroups)) { return }
        Show-Module -Key 'GroupMembers'
        $gm = $script:UI.Modules['GroupMembers']
        if ($gm) { Invoke-UiAction -Module $gm -Action $gm.Actions.List }
    } | Out-Null
    Add-ObjectReportRow -Module $m -Kind 'Group'
    $row2 = Add-ToolbarRow -Module $m -Title 'Zmiany'
    Add-Button -Parent $row2 -Text 'Opis…' -Icon 'E70F' -Module $m -OnClick { param($m) Invoke-GroupChange -Module $m -Op 'Description' } | Out-Null
    Add-Button -Parent $row2 -Text 'Zarządca…' -Icon 'E77B' -Module $m -OnClick { param($m) Invoke-GroupChange -Module $m -Op 'ManagedBy' } | Out-Null
    Add-Button -Parent $row2 -Text 'E-mail…' -Icon 'E715' -Module $m -OnClick { param($m) Invoke-GroupChange -Module $m -Op 'Mail' } | Out-Null
    Add-Button -Parent $row2 -Text 'Zakres i typ…' -Icon 'E8AB' -Module $m -OnClick { param($m) Invoke-GroupChange -Module $m -Op 'Scope' } | Out-Null
    Add-Button -Parent $row2 -Text 'Przenieś do OU…' -Icon 'E8DE' -Module $m -OnClick { param($m) Invoke-GroupChange -Module $m -Op 'Move' } | Out-Null
    Add-MenuButton -Parent $row2 -Text 'Ochrona' -Icon 'E72E' -Module $m -ToolTip 'Ochrona przed przypadkowym usunięciem' -Items @(
        @{ Text = 'Włącz ochronę przed usunięciem'; Icon = 'E72E'; Action = { param($m) Invoke-GroupChange -Module $m -Op 'ProtectOn' } }
        @{ Text = 'Wyłącz ochronę przed usunięciem'; Icon = 'E785'; Action = { param($m) Invoke-GroupChange -Module $m -Op 'ProtectOff' } }
    ) | Out-Null
    Add-Button -Parent $row2 -Text 'Usuń grupy' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) Invoke-GroupChange -Module $m -Op 'Delete' } | Out-Null

    Add-RowAction -Module $m -Text 'Zmień nazwę…' -Icon 'E8AC' -Action {
        param($m, $rows)
        $sam = [string](Get-ObjectValue $rows[0] 'Grupa')
        $name = [string](Get-ObjectValue $rows[0] 'Nazwa')
        $f = Show-FormDialog -Title 'Zmiana nazwy grupy' -Subtitle "Grupa: $name" -Icon 'E8AC' -OkText 'Zmień nazwę' -Fields @(
            @{ Key = 'Name'; Label = 'Nazwa (CN)'; Value = $name }
            @{ Key = 'Sam'; Label = 'sAMAccountName (nazwa sprzed Windows 2000)'; Value = $sam; Hint = 'Zmiana sAMAccountName może wymagać aktualizacji skryptów i aplikacji, które odwołują się do grupy po nazwie.' }
            @{ Key = 'Display'; Label = 'Nazwa wyświetlana (opcjonalnie)'; Value = [string](Get-ObjectValue $rows[0] 'Nazwa wyświetlana') }
        ) -Validate {
            param($v)
            if (-not $v.Name) { return 'Podaj nazwę grupy.' }
            if ($v.Name.Length -gt 64) { return 'Nazwa (CN) może mieć najwyżej 64 znaki.' }
            return (Test-SamName $v.Sam)
        }
        if (-not $f) { return }
        Start-AdOperation -Module $m -Name 'Zmiana nazwy grupy' -Targets @($sam) -TargetColumn 'Grupa' -Output Log -Parameters @{ Op = 'Rename'; Name = $f.Name; Sam = $f.Sam; Display = $f.Display } -ScriptBlock $script:GroupChangeScript -OnResult {
            param($m, $r)
            if (-not $r.Ok) { return }
            $d = @($r.Data | Where-Object { $_ -isnot [string] })
            if ($d.Count -eq 0) { return }
            $row = $script:UI.GroupTable.Rows.Find($r.Target)
            if ($row) {
                if ($d[0].Sam -ne $r.Target -and -not $script:UI.GroupTable.Rows.Find($d[0].Sam)) { $row['Sam'] = $d[0].Sam }
                $row['Name'] = $d[0].Name
                $row['DN'] = $d[0].DN
                & $script:UI.GroupPanel.Describe $row
                $script:UI.GroupTable.AcceptChanges()
            }
            Select-TargetGroups -Sams @($d[0].Sam)
        } -OnComplete { param($m) & $m.Actions.List $m }
    }
    Add-RowAction -Module $m -Text 'Zmień opis…' -Icon 'E70F' -Action { param($m, $rows) Invoke-GroupChange -Module $m -Op 'Description' -Rows $rows }
    Add-RowAction -Module $m -Text 'Przenieś do OU…' -Icon 'E8DE' -Action { param($m, $rows) Invoke-GroupChange -Module $m -Op 'Move' -Rows $rows }
    Add-RowAction -Module $m -Text 'Kopiuj DN' -Icon 'E8C8' -Action {
        param($m, $rows)
        $dns = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'DN') } | Where-Object { $_ })
        Set-ClipboardText ($dns -join [Environment]::NewLine)
        Show-Toast "Skopiowano DN: $($dns.Count)" 'ok'
    }
    Add-RowAction -Module $m -Text 'Usuń grupę' -Icon 'E74D' -Danger -Separator -Action { param($m, $rows) Invoke-GroupChange -Module $m -Op 'Delete' -Rows $rows }
    Add-StatTile -Module $m -Key 'groups' -Label 'Grupy' -Icon 'E902' | Out-Null
    Add-StatTile -Module $m -Key 'members' -Label 'Członkowie (bezpośredni)' -Icon 'E716' | Out-Null
    Add-StatTile -Module $m -Key 'empty' -Label 'Puste grupy' -Icon 'E7BA' | Out-Null
    Add-StatTile -Module $m -Key 'disabled' -Label 'Wyłączone konta w grupach' -Icon 'E8D8' | Out-Null
}

Register-Module -Workspace 'AdGroups' -Category 'Grupy' -Key 'GroupMembers' -Title 'Członkowie grup' -Icon 'E716' `
    -Description 'Członkowie zaznaczonych grup – bezpośredni i zagnieżdżeni (bez limitu 5000 obiektów), z typem i stanem kont. Dodawanie członków, kopiowanie członków z innej grupy, usuwanie i przenoszenie kont na listę użytkowników.' -Build {
    param($m)
    $m.PillColumns = @('Członkostwo')
    $m.ColorBools = $true
    $m.Actions.List = {
        param($m)
        $targets = @(Get-TargetGroups)
        if (-not $targets) { return }
        Reset-StatTiles $m
        Start-AdOperation -Module $m -Name 'Członkowie grup' -Targets $targets -TargetColumn 'Grupa' -Parameters @{ Nested = (Test-Checked $m.Nested) } -ScriptBlock {
            $g = Get-ADGroup -Identity $Target @ad
            $rid = [int](([string]$g.SID.Value) -split '-')[-1]
            $primaryRid = if (@(513, 515, 516, 521) -contains $rid) { $rid } else { 0 }
            $direct = @(Get-GroupMemberObjects -GroupDn $g.DistinguishedName -Properties mail)
            $directSet = @{}
            foreach ($o in $direct) { $directSet[[string]$o.DistinguishedName] = $true }
            $primary = @()
            if ($primaryRid) { $primary = @(Get-ADObject -LDAPFilter "(primaryGroupID=$primaryRid)" -Properties sAMAccountName, userAccountControl, displayName, mail @ad) }
            $primarySet = @{}
            foreach ($o in $primary) { $primarySet[[string]$o.DistinguishedName] = $true }
            $all = if ($P.Nested) { @(Get-GroupMemberObjects -GroupDn $g.DistinguishedName -Recursive -Properties mail) + $primary } else { $direct + $primary }
            $seen = @{}
            foreach ($o in ($all | Sort-Object { [string]$_.Name })) {
                $dn = [string]$o.DistinguishedName
                if ($seen.ContainsKey($dn)) { continue }
                $seen[$dn] = $true
                $class = [string]$o.ObjectClass
                $isAccount = ($class -eq 'user' -or $class -eq 'computer' -or $class -eq 'inetOrgPerson')
                $enabled = if ($isAccount) { -not ([int64]$o.userAccountControl -band 2) } else { $null }
                $how = if ($directSet.ContainsKey($dn)) { 'Bezpośrednie' } elseif ($primarySet.ContainsKey($dn)) { 'Podstawowa' } else { 'Zagnieżdżone' }
                [pscustomobject][ordered]@{
                    'Członek'           = $o.Name
                    'Login'             = ([string]$o.sAMAccountName) -replace '\$$', ''
                    'Typ'               = Get-ObjectKind $class
                    'Włączone'          = $enabled
                    'Członkostwo'       = $how
                    'Nazwa wyświetlana' = $o.displayName
                    'E-mail'            = $o.mail
                    'DN'                = $dn
                    '__tone'            = $(switch ($how) { 'Bezpośrednie' { 'info' } 'Podstawowa' { 'ok' } default { '' } })
                    '__flag'            = $(if ($enabled -eq $false) { 'muted' } else { '' })
                }
            }
        } -OnComplete {
            param($m)
            $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Status') -ne 'Błąd' -and $m.Table.Columns.Contains('DN') })
            $uniq = @{}
            foreach ($r in $rows) { $uniq[[string]$r['DN']] = $r }
            $vals = @($uniq.Values)
            Set-StatTile -Module $m -Key 'all' -Value ([string]$vals.Count)
            Set-StatTile -Module $m -Key 'users' -Value ([string]@($vals | Where-Object { [string]$_['Typ'] -eq 'Użytkownik' }).Count)
            Set-StatTile -Module $m -Key 'computers' -Value ([string]@($vals | Where-Object { [string]$_['Typ'] -eq 'Komputer' }).Count)
            Set-StatTile -Module $m -Key 'groups' -Value ([string]@($vals | Where-Object { [string]$_['Typ'] -eq 'Grupa' }).Count)
            $dis = @($vals | Where-Object { [string]$_['Włączone'] -eq 'Nie' }).Count
            Set-StatTile -Module $m -Key 'disabled' -Value ([string]$dis) -Tone $(if ($dis) { 'warn' } else { '' })
        }
    }
    $m.Actions.Remove = {
        param($m, $Rows)
        $source = @(if ($null -ne $Rows) { $Rows } else { Get-SelectedResultRows -Module $m })
        $per = @{}
        $items = @()
        $skipped = 0
        foreach ($r in $source) {
            if ([string](Get-ObjectValue $r 'Członkostwo') -ne 'Bezpośrednie') { $skipped++; continue }
            $grp = [string](Get-ObjectValue $r 'Grupa')
            if (-not $per.ContainsKey($grp)) { $per[$grp] = @{ Members = New-Object System.Collections.ArrayList } }
            [void]$per[$grp].Members.Add([string](Get-ObjectValue $r 'DN'))
            $items += ('{0}  ←  {1}' -f $grp, (Get-ObjectValue $r 'Członek'))
        }
        if ($per.Count -eq 0) { Show-Warning 'Zaznacz w tabeli członków bezpośrednich (członkostwa zagnieżdżonego i podstawowego nie usuwa się z tej grupy).'; return }
        $text = 'Usunąć wybranych członków z grup?'
        if ($skipped) { $text += "`r`nPominięto $skipped wierszy (członkostwo zagnieżdżone lub podstawowe)." }
        if (-not (Confirm-Action -Text $text -Items $items -ConfirmText 'Usuń z grup' -Danger)) { return }
        foreach ($k in @($per.Keys)) { $per[$k] = @{ Members = @($per[$k].Members) } }
        Start-AdOperation -Module $m -Name 'Usuwanie członków' -Targets @($per.Keys) -PerTarget $per -TargetColumn 'Grupa' -Output Log -ScriptBlock {
            foreach ($d in $P.Members) {
                try { Remove-ADGroupMember -Identity $Target -Members $d -Confirm:$false @ad; "Usunięto: $(Get-DnName $d)" }
                catch { "Błąd – $(Get-DnName $d): $($_.Exception.Message)" }
            }
        } -OnComplete { param($m) & $m.Actions.List $m }
    }
    $row = Add-ToolbarRow -Module $m -Title 'Lista'
    $m.Nested = Add-CheckBox -Parent $row -Text 'Uwzględnij członków zagnieżdżonych' -ToolTip 'Także obiekty należące do grupy przez inne grupy (LDAP_MATCHING_RULE_IN_CHAIN)'
    [void](Add-Segmented -Parent $row -Items @('Wszyscy', 'Użytkownicy', 'Komputery', 'Grupy') -Module $m -OnChange {
            param($m, $s)
            $m.ExtraFilter = switch ([string]$s.Content) { 'Użytkownicy' { "Typ = 'Użytkownik'" } 'Komputery' { "Typ = 'Komputer'" } 'Grupy' { "Typ = 'Grupa'" } default { '' } }
            Update-ResultFilter -Module $m
        })
    Add-Button -Parent $row -Text 'Pokaż członków' -Icon 'E716' -Module $m -Primary -OnClick $m.Actions.List | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Zmiany'
    Add-Button -Parent $row2 -Text 'Dodaj członków…' -Icon 'E8FA' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetGroups)
        if (-not $targets) { return }
        $text = Show-InputDialog -Title 'Dodaj członków' -Prompt "Grupy: $($targets -join ', '). Wpisz konta, komputery lub grupy – po jednym w wierszu (login, UPN, nazwa komputera, nazwa grupy, DN albo SID)." -Multiline -Icon 'E8FA'
        if ($null -eq $text) { return }
        $ids = @(Get-TextLines $text)
        if ($ids.Count -eq 0) { return }
        if (-not (Confirm-Action -Text "Dodać $($ids.Count) obiekt(ów) do $($targets.Count) grup(y)?" -Items $ids -ConfirmText 'Dodaj')) { return }
        Start-AdOperation -Module $m -Name 'Dodawanie członków' -Targets $targets -TargetColumn 'Grupa' -Output Log -Parameters @{ Ids = $ids } -ScriptBlock {
            $g = Get-ADGroup -Identity $Target @ad
            foreach ($id in $P.Ids) {
                try {
                    $o = Resolve-AdPrincipal -Id $id -Classes @('user', 'computer', 'group', 'contact')
                    Add-ADGroupMember -Identity $g -Members $o.DistinguishedName @ad
                    "Dodano: $($o.Name)"
                }
                catch { "Błąd – ${id}: $($_.Exception.Message)" }
            }
        } -OnComplete { param($m) & $m.Actions.List $m }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Kopiuj członków z grupy…' -Icon 'E8C8' -Module $m -OnClick {
        param($m)
        $targets = @(Get-TargetGroups)
        if (-not $targets) { return }
        $src = Show-InputDialog -Title 'Grupa źródłowa' -Prompt "Bezpośredni członkowie tej grupy zostaną dodani do: $($targets -join ', ')." -Icon 'E902'
        if (-not $src) { return }
        Start-AdOperation -Module $m -Name 'Kopiowanie członków' -Targets $targets -TargetColumn 'Grupa' -Output Log -Parameters @{ Source = $src.Trim() } -ScriptBlock {
            $from = Resolve-AdPrincipal -Id $P.Source -Classes @('group')
            $srcMembers = @((Get-ADGroup -Identity $from.DistinguishedName -Properties member @ad).member)
            $existing = @{}
            foreach ($d in @((Get-ADGroup -Identity $Target -Properties member @ad).member)) { $existing[[string]$d] = $true }
            $toAdd = @($srcMembers | Where-Object { -not $existing.ContainsKey([string]$_) })
            if ($toAdd.Count -eq 0) { "Wszyscy członkowie $($from.Name) już należą do grupy."; return }
            $added = 0
            for ($i = 0; $i -lt $toAdd.Count; $i += 200) {
                $chunk = @($toAdd[$i..([Math]::Min($i + 199, $toAdd.Count - 1))])
                try { Add-ADGroupMember -Identity $Target -Members $chunk @ad; $added += $chunk.Count }
                catch {
                    foreach ($d in $chunk) {
                        try { Add-ADGroupMember -Identity $Target -Members $d @ad; $added++ }
                        catch { "Błąd – $(Get-DnName $d): $($_.Exception.Message)" }
                    }
                }
            }
            "Dodano $added z $($toAdd.Count) członków grupy $($from.Name)."
        } -OnComplete { param($m) & $m.Actions.List $m }
    } | Out-Null
    Add-Button -Parent $row2 -Text 'Usuń zaznaczonych członków' -Icon 'E74D' -Module $m -Danger -OnClick { param($m) & $m.Actions.Remove $m $null } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Wyniki'
    Add-Button -Parent $row3 -Text 'Zaznacz konta na liście użytkowników' -Icon 'E8B3' -Module $m -AlwaysEnabled -ToolTip 'Konta użytkowników z zaznaczonych wierszy (albo wszystkich widocznych) trafią na listę w przestrzeni «Użytkownicy AD»' -OnClick {
        param($m)
        $rows = @(Get-SelectedResultRows -Module $m)
        if ($rows.Count -le 1) { $rows = @($m.View | ForEach-Object { $_ }) }
        $users = @($rows | Where-Object { [string](Get-ObjectValue $_ 'Typ') -eq 'Użytkownik' })
        if ($users.Count -eq 0) { Show-Warning 'Wśród wybranych wierszy nie ma kont użytkowników.'; return }
        Add-ResultsToTargets -Module $m -Kind User -Column 'Login' -Rows $users
    } | Out-Null
    Add-RowAction -Module $m -Text 'Usuń z grupy' -Icon 'E74D' -Danger -Action { param($m, $rows) & $m.Actions.Remove $m $rows }
    Add-RowAction -Module $m -Text 'Kopiuj loginy' -Icon 'E8C8' -Separator -Action {
        param($m, $rows)
        $names = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Login') } | Where-Object { $_ } | Select-Object -Unique)
        Set-ClipboardText ($names -join [Environment]::NewLine)
        Show-Toast "Skopiowano loginów: $($names.Count)" 'ok'
    }
    Add-RowAction -Module $m -Text 'Kopiuj adresy e-mail' -Icon 'E715' -Action {
        param($m, $rows)
        $mails = @($rows | ForEach-Object { [string](Get-ObjectValue $_ 'E-mail') } | Where-Object { $_ } | Select-Object -Unique)
        if ($mails.Count -eq 0) { Show-Warning 'Wybrane obiekty nie mają adresów e-mail.'; return }
        Set-ClipboardText ($mails -join '; ')
        Show-Toast "Skopiowano adresów: $($mails.Count)" 'ok'
    }
    Add-StatTile -Module $m -Key 'all' -Label 'Członkowie (unikalni)' -Icon 'E716' | Out-Null
    Add-StatTile -Module $m -Key 'users' -Label 'Użytkownicy' -Icon 'E77B' | Out-Null
    Add-StatTile -Module $m -Key 'computers' -Label 'Komputery' -Icon 'E7F4' | Out-Null
    Add-StatTile -Module $m -Key 'groups' -Label 'Grupy' -Icon 'E902' | Out-Null
    Add-StatTile -Module $m -Key 'disabled' -Label 'Wyłączone konta' -Icon 'E8D8' | Out-Null
}

Register-GroupMembershipModule -Workspace 'AdGroups' -Kind Group -Key 'GroupMemberOf' -Category 'Grupy' -Title 'Przynależność do grup'

$script:BulkPlanScript = {
    # Plan członkostwa: rozpoznanie obiektów i grup, sprawdzenie obecnego członkostwa
    $cacheO = @{}
    $cacheG = @{}
    $members = @{}
    $resolve = {
        param([string]$Id, [string[]]$Classes, [hashtable]$Cache)
        if ($Cache.ContainsKey($Id)) { return $Cache[$Id] }
        $res = @{ Ok = $false; Obj = $null; Error = '' }
        try { $res.Obj = Resolve-AdPrincipal -Id $Id -Classes $Classes; $res.Ok = $true }
        catch { $res.Error = $_.Exception.Message }
        $Cache[$Id] = $res
        return $res
    }
    $pairs = New-Object System.Collections.ArrayList
    if ($P.Mode -eq 'pair') {
        $n = [Math]::Max(@($P.Objects).Count, @($P.Groups).Count)
        for ($i = 0; $i -lt $n; $i++) {
            $o = if ($i -lt @($P.Objects).Count) { [string]$P.Objects[$i] } else { '' }
            $gr = if ($i -lt @($P.Groups).Count) { [string]$P.Groups[$i] } else { '' }
            [void]$pairs.Add(@($o, $gr))
        }
    }
    else { foreach ($gr in $P.Groups) { foreach ($o in $P.Objects) { [void]$pairs.Add(@([string]$o, [string]$gr)) } } }
    $lp = 0
    foreach ($pair in $pairs) {
        $lp++
        $row = [ordered]@{ 'Lp' = $lp; 'Stan' = ''; 'Obiekt' = $pair[0]; 'Rozpoznany' = ''; 'Typ' = ''; 'Grupa' = $pair[1]; 'Rozpoznana grupa' = ''; 'Uwagi' = ''; '__obj' = ''; '__grp' = ''; '__tone' = 'crit' }
        if (-not $pair[0] -or -not $pair[1]) { $row['Stan'] = 'Brak pary'; $row['Uwagi'] = 'Listy obiektów i grup mają różną liczbę wierszy.'; [pscustomobject]$row; continue }
        $ro = & $resolve $pair[0] @('user', 'computer', 'group', 'contact') $cacheO
        $rg = & $resolve $pair[1] @('group') $cacheG
        if ($ro.Ok) { $row['Rozpoznany'] = $(if ($ro.Obj.sAMAccountName) { ([string]$ro.Obj.sAMAccountName) -replace '\$$', '' } else { $ro.Obj.Name }); $row['Typ'] = Get-ObjectKind ([string]$ro.Obj.ObjectClass); $row['__obj'] = [string]$ro.Obj.DistinguishedName }
        if ($rg.Ok) { $row['Rozpoznana grupa'] = [string]$rg.Obj.sAMAccountName; $row['__grp'] = [string]$rg.Obj.sAMAccountName }
        if (-not $ro.Ok) { $row['Stan'] = 'Nie znaleziono obiektu'; $row['Uwagi'] = $ro.Error; [pscustomobject]$row; continue }
        if (-not $rg.Ok) { $row['Stan'] = 'Nie znaleziono grupy'; $row['Uwagi'] = $rg.Error; [pscustomobject]$row; continue }
        $gdn = [string]$rg.Obj.DistinguishedName
        if ($gdn -eq $row['__obj']) { $row['Stan'] = 'Pominięto'; $row['Uwagi'] = 'Grupa nie może należeć do samej siebie.'; $row['__tone'] = 'warn'; [pscustomobject]$row; continue }
        if (-not $members.ContainsKey($gdn)) {
            $set = @{}
            foreach ($d in @((Get-ADGroup -Identity $gdn -Properties member @ad).member)) { $set[([string]$d).ToLowerInvariant()] = $true }
            $members[$gdn] = $set
        }
        $isMember = $members[$gdn].ContainsKey($row['__obj'].ToLowerInvariant())
        if ($P.Op -eq 'Remove') {
            if ($isMember) { $row['Stan'] = 'Do usunięcia'; $row['__tone'] = 'warn' } else { $row['Stan'] = 'Nie jest członkiem'; $row['__tone'] = '' }
        }
        else {
            if ($isMember) { $row['Stan'] = 'Już jest członkiem'; $row['__tone'] = '' } else { $row['Stan'] = 'Do dodania'; $row['__tone'] = 'info' }
        }
        [pscustomobject]$row
    }
}

Register-Module -Workspace 'AdGroups' -Category 'Grupy' -Key 'BulkMembership' -Title 'Członkostwo hurtowe' -Icon 'E8FA' -Badge 'nowe' `
    -Description 'Dodawanie lub usuwanie wielu obiektów w wielu grupach: każdy do każdej (A×B) albo wiersz do wiersza. Najpierw plan (co zostanie zmienione, co już jest), potem wykonanie z wynikiem dla każdej pary.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Data.Stale = $true
    $m.Data.PlanOp = 'Add'
    $m.Data.ThenExecute = $false
    $boxes = Add-TextColumns -Module $m -Title 'Dane' -Height 150 -Columns @(
        @{ Caption = 'Obiekty: konta, komputery, grupy (po jednym w wierszu)'; Placeholder = "jan.kowalski`nanna.nowak@firma.pl`nPC-01`nGG_Helpdesk" }
        @{ Caption = 'Grupy (po jednej w wierszu)'; Placeholder = "GG_VPN`nCN=GG_Finanse,OU=Grupy,DC=firma,DC=local" }
    )
    $m.Objects = $boxes[0]
    $m.Groups = $boxes[1]
    foreach ($b in $boxes) { Register-ControlHandler -Control $b -EventName 'TextChanged' -Module $m -Action { param($m) $m.Data.Stale = $true } }
    $row = Add-ToolbarRow -Module $m -Title 'Wypełnij'
    Add-Button -Parent $row -Text 'Konta z listy użytkowników' -Icon 'E716' -Module $m -AlwaysEnabled -ToolTip 'Dopisuje konta zaznaczone w przestrzeni «Użytkownicy AD»' -OnClick {
        param($m)
        $users = @(Get-TargetUsers -Quiet)
        if ($users.Count -eq 0) { Show-Warning 'Na liście w przestrzeni «Użytkownicy AD» nie zaznaczono kont.'; return }
        $current = @(Get-TextLines $m.Objects)
        $m.Objects.Text = ((@($current) + @($users | Where-Object { $current -notcontains $_ })) -join "`r`n")
    } | Out-Null
    Add-Button -Parent $row -Text 'Zaznaczone grupy z listy' -Icon 'E902' -Module $m -AlwaysEnabled -ToolTip 'Dopisuje grupy zaznaczone na liście po lewej' -OnClick {
        param($m)
        $groups = @(Get-TargetGroups)
        if ($groups.Count -eq 0) { return }
        $current = @(Get-TextLines $m.Groups)
        $m.Groups.Text = ((@($current) + @($groups | Where-Object { $current -notcontains $_ })) -join "`r`n")
    } | Out-Null
    Add-Button -Parent $row -Text 'Wklej pary ze schowka' -Icon 'E77F' -Module $m -AlwaysEnabled -ToolTip 'Dwie kolumny z Excela: obiekt [TAB] grupa – wypełnia oba pola i ustawia tryb «wiersz do wiersza»' -OnClick {
        param($m)
        $t = ConvertFrom-PastedTable -Text (Get-ClipboardText) -Headers @{ O = @('obiekt', 'login', 'konto', 'user', 'uzytkownik', 'member', 'czlonek'); G = @('grupa', 'group') } -Order @('O', 'G')
        $rows = @($t.Rows | Where-Object { (Get-PastedValue $_ $t.Map 'O') -and (Get-PastedValue $_ $t.Map 'G') })
        if ($rows.Count -eq 0) { Show-Warning 'Schowek nie zawiera dwóch kolumn (obiekt, grupa).'; return }
        $m.Objects.Text = (@($rows | ForEach-Object { Get-PastedValue $_ $t.Map 'O' }) -join "`r`n")
        $m.Groups.Text = (@($rows | ForEach-Object { Get-PastedValue $_ $t.Map 'G' }) -join "`r`n")
        Set-SegmentIndex $m.Mode 1
        Show-Toast "Wklejono par: $($rows.Count)" 'ok'
    } | Out-Null
    $row2 = Add-ToolbarRow -Module $m -Title 'Tryb'
    $m.Mode = Add-Segmented -Parent $row2 -Items @('Każdy do każdej grupy (A×B)', 'Wiersz do wiersza') -Module $m -OnChange { param($m) $m.Data.Stale = $true }
    $m.Op = Add-Segmented -Parent $row2 -Items @('Dodaj do grup', 'Usuń z grup') -Module $m -OnChange { param($m) $m.Data.Stale = $true }
    $m.Actions.Plan = {
        param($m, [bool]$ThenExecute = $false)
        $objects = @(Get-TextLines $m.Objects)
        $groups = @(Get-TextLines $m.Groups)
        if ($objects.Count -eq 0 -or $groups.Count -eq 0) { Show-Warning 'Wpisz obiekty i grupy (po jednym w wierszu).'; return }
        $mode = if ((Get-SegmentIndex $m.Mode) -eq 1) { 'pair' } else { 'cross' }
        $count = if ($mode -eq 'pair') { [Math]::Max($objects.Count, $groups.Count) } else { $objects.Count * $groups.Count }
        if ($count -gt 20000) { Show-Warning "Plan obejmowałby $count par – podziel dane na mniejsze części."; return }
        $m.Data.ThenExecute = $ThenExecute
        $m.Data.PlanOp = if ((Get-SegmentIndex $m.Op) -eq 1) { 'Remove' } else { 'Add' }
        Start-AdOperation -Module $m -Name 'Plan członkostwa' -Targets @('AD') -Parameters @{ Objects = $objects; Groups = $groups; Mode = $mode; Op = $m.Data.PlanOp } -ScriptBlock $script:BulkPlanScript -OnComplete {
            param($m)
            $m.Data.Stale = $false
            & $m.Actions.Stats $m
            Request-ResultSpace -Module $m
            if ($m.Data.ThenExecute) { Invoke-Deferred -Module $m -Action { param($m) & $m.Actions.Execute $m } }
        }
    }
    $m.Actions.Stats = {
        param($m)
        $rows = @(Get-ResultRowsAll -Module $m)
        $todo = @($rows | Where-Object { @('Do dodania', 'Do usunięcia') -contains [string](Get-ObjectValue $_ 'Stan') }).Count
        $done = @($rows | Where-Object { @('Dodano', 'Usunięto') -contains [string](Get-ObjectValue $_ 'Stan') }).Count
        $noop = @($rows | Where-Object { @('Już jest członkiem', 'Nie jest członkiem', 'Pominięto') -contains [string](Get-ObjectValue $_ 'Stan') }).Count
        $bad = @($rows | Where-Object { [string](Get-ObjectValue $_ '__tone') -eq 'crit' }).Count
        Set-StatTile -Module $m -Key 'todo' -Value ([string]$todo) -Tone $(if ($todo) { 'info' } else { '' })
        Set-StatTile -Module $m -Key 'done' -Value ([string]$done) -Tone $(if ($done) { 'ok' } else { '' })
        Set-StatTile -Module $m -Key 'noop' -Value ([string]$noop)
        Set-StatTile -Module $m -Key 'bad' -Value ([string]$bad) -Tone $(if ($bad) { 'crit' } else { '' })
    }
    $m.Actions.Execute = {
        param($m)
        if ($m.Data.Stale -or -not $m.Table -or $m.Table.Rows.Count -eq 0) { & $m.Actions.Plan $m $true; return }
        $op = $m.Data.PlanOp
        $state = if ($op -eq 'Remove') { 'Do usunięcia' } else { 'Do dodania' }
        $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq $state })
        if ($rows.Count -eq 0) { Show-Message -Text 'Plan nie zawiera zmian do wykonania – wszystkie pary są już w docelowym stanie albo zawierają błędy.' -Title 'Brak zmian'; return }
        $per = @{}
        foreach ($r in $rows) {
            $g = [string]$r['__grp']
            if (-not $per.ContainsKey($g)) { $per[$g] = @{ Members = New-Object System.Collections.ArrayList; Op = $op } }
            [void]$per[$g].Members.Add([string]$r['__obj'])
        }
        foreach ($k in @($per.Keys)) { $per[$k] = @{ Members = @($per[$k].Members); Op = $op } }
        $items = @($rows | ForEach-Object { '{0}  →  {1}' -f $_['Rozpoznany'], $_['Rozpoznana grupa'] })
        $verb = if ($op -eq 'Remove') { 'Usunąć' } else { 'Dodać' }
        if (-not (Confirm-Action -Text "$verb członkostwo: $($rows.Count) par(y) w $($per.Count) grup(ach)?" -Items $items -ConfirmText $(if ($op -eq 'Remove') { 'Usuń z grup' } else { 'Dodaj do grup' }) -Danger:($op -eq 'Remove'))) { return }
        Start-AdOperation -Module $m -Name 'Członkostwo hurtowe' -Targets @($per.Keys) -PerTarget $per -Output None -ScriptBlock {
            $all = @($P.Members)
            $ok = $false
            try {
                if ($P.Op -eq 'Remove') { Remove-ADGroupMember -Identity $Target -Members $all -Confirm:$false @ad } else { Add-ADGroupMember -Identity $Target -Members $all @ad }
                $ok = $true
            }
            catch { }
            foreach ($d in $all) {
                if ($ok) { [pscustomobject]@{ Dn = $d; Ok = $true; Message = '' }; continue }
                try {
                    if ($P.Op -eq 'Remove') { Remove-ADGroupMember -Identity $Target -Members $d -Confirm:$false @ad } else { Add-ADGroupMember -Identity $Target -Members $d @ad }
                    [pscustomobject]@{ Dn = $d; Ok = $true; Message = '' }
                }
                catch { [pscustomobject]@{ Dn = $d; Ok = $false; Message = $_.Exception.Message } }
            }
        } -OnResult {
            param($m, $r)
            $rows = @(Find-ResultRow -Module $m -Column '__grp' -Value $r.Target)
            if (-not $r.Ok) {
                foreach ($row in $rows) { if (@('Do dodania', 'Do usunięcia') -contains [string]$row['Stan']) { Set-RowState -Module $m -Row $row -State 'Błąd' -Tone 'crit' -Note ((@($r.Errors)) -join ' ') } }
                return
            }
            $done = if ($m.Data.PlanOp -eq 'Remove') { 'Usunięto' } else { 'Dodano' }
            foreach ($d in @($r.Data)) {
                foreach ($row in @($rows | Where-Object { [string]$_['__obj'] -eq [string]$d.Dn })) {
                    if ($d.Ok) { Set-RowState -Module $m -Row $row -State $done -Tone 'ok' -Note '' }
                    else { Set-RowState -Module $m -Row $row -State 'Błąd' -Tone 'crit' -Note $d.Message }
                }
            }
        } -OnComplete { param($m) $m.Data.Stale = $true; & $m.Actions.Stats $m }
    }
    $row3 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row3 -Text 'Sprawdź plan' -Icon 'E9D5' -Module $m -Primary -OnClick { param($m) & $m.Actions.Plan $m $false } | Out-Null
    Add-Button -Parent $row3 -Text 'Wykonaj' -Icon 'E768' -Module $m -OnClick { param($m) & $m.Actions.Execute $m } | Out-Null
    Add-Label -Parent $row3 -Text 'Plan nic nie zmienia w AD – pokazuje, co zostanie zrobione (tryb próbny).' -Hint | Out-Null
    Add-StatTile -Module $m -Key 'todo' -Label 'Do wykonania' -Icon 'E9D5' | Out-Null
    Add-StatTile -Module $m -Key 'done' -Label 'Wykonane' -Icon 'E73E' | Out-Null
    Add-StatTile -Module $m -Key 'noop' -Label 'Bez zmian' -Icon 'E73A' | Out-Null
    Add-StatTile -Module $m -Key 'bad' -Label 'Błędy' -Icon 'E7BA' | Out-Null
    $m.EmptyHint = 'Wpisz obiekty i grupy, wybierz tryb i kliknij «Sprawdź plan» (F5). «Wykonaj» zmieni tylko pary oznaczone jako «Do dodania» / «Do usunięcia».'
}
#endregion

#region Grupy AD: tworzenie i duplikowanie
$script:GroupPasteHeaders = [ordered]@{
    Name        = @('nazwa', 'name', 'cn', 'grupa', 'nazwa grupy', 'group')
    Description = @('opis', 'description', 'desc')
    Scope       = @('zakres', 'scope', 'groupscope')
    Category    = @('typ', 'kategoria', 'category', 'groupcategory', 'type')
    Mail        = @('email', 'e-mail', 'mail', 'adres e-mail')
    Sam         = @('samaccountname', 'sam', 'nazwa sprzed windows 2000')
    MemberOf    = @('członek grup', 'memberof', 'należy do', 'grupy nadrzędne', 'nadrzędne')
    ManagedBy   = @('zarządca', 'managedby', 'właściciel', 'owner')
    Ou          = @('ou', 'ścieżka', 'path', 'jednostka', 'jednostka organizacyjna')
}

$script:GroupCheckScript = {
    # Sprawdzenie planowanych grup w AD: OU, zajętość sAMAccountName i nazwy w OU, grupy nadrzędne, zarządca
    $ouCache = @{}
    foreach ($r in $P.Rows) {
        $issues = @()
        $exists = $false
        if (-not $ouCache.ContainsKey($r.Ou)) {
            $ok = $true
            try { [void](Get-ADObject -Identity $r.Ou @ad) } catch { $ok = $false }
            $ouCache[$r.Ou] = $ok
        }
        if (-not $ouCache[$r.Ou]) { $issues += "Nie ma jednostki $($r.Ou)" }
        else {
            $v = ConvertTo-LdapValue $r.Sam
            $bySam = @(Get-ADObject -LDAPFilter "(sAMAccountName=$v)" @ad)
            $byName = @(Get-ADObject -LDAPFilter "(name=$(ConvertTo-LdapValue $r.Name))" -SearchBase $r.Ou -SearchScope OneLevel @ad)
            if ($bySam.Count -gt 0) {
                if ([string]$bySam[0].ObjectClass -eq 'group' -and (Get-DnName ([string]$bySam[0].DistinguishedName)) -eq $r.Name) { $exists = $true }
                else { $issues += "sAMAccountName «$($r.Sam)» jest zajęty przez $(Get-DnName ([string]$bySam[0].DistinguishedName))" }
            }
            elseif ($byName.Count -gt 0) { $issues += "W tej OU istnieje już obiekt o nazwie «$($r.Name)»" }
        }
        foreach ($p in @($r.MemberOf)) {
            if (-not $p) { continue }
            try { [void](Resolve-AdPrincipal -Id $p -Classes @('group')) } catch { $issues += "Grupa nadrzędna: $($_.Exception.Message)" }
        }
        if ($r.ManagedBy) { try { [void](Resolve-AdPrincipal -Id $r.ManagedBy -Classes @('user', 'group', 'contact')) } catch { $issues += "Zarządca: $($_.Exception.Message)" } }
        [pscustomobject]@{ Id = $r.Id; Exists = $exists; Issues = @($issues) }
    }
}

$script:GroupCreateScript = {
    # Tworzenie jednej grupy ($P: Name, Sam, Scope, Category, Ou, Description, Mail, MemberOf, ManagedBy, Protect)
    $params = @{ Name = $P.Name; SamAccountName = $P.Sam; GroupScope = $P.Scope; GroupCategory = $P.Category; Path = $P.Ou; PassThru = $true }
    if ($P.Description) { $params.Description = $P.Description }
    if ($P.Mail) { $params.OtherAttributes = @{ mail = $P.Mail } }
    if ($P.ManagedBy) { $params.ManagedBy = (Resolve-AdPrincipal -Id $P.ManagedBy -Classes @('user', 'group', 'contact')).DistinguishedName }
    $g = New-ADGroup @params @ad
    $notes = @()
    $warn = $false
    foreach ($p in @($P.MemberOf)) {
        if (-not $p) { continue }
        try {
            $parent = Resolve-AdPrincipal -Id $p -Classes @('group')
            Add-ADGroupMember -Identity $parent.DistinguishedName -Members $g.DistinguishedName @ad
            $notes += "dodano do $($parent.Name)"
        }
        catch { $notes += "członkostwo w ${p}: $($_.Exception.Message)"; $warn = $true }
    }
    if ($P.Protect) {
        try { Set-ADObject -Identity $g.DistinguishedName -ProtectedFromAccidentalDeletion $true @ad; $notes += 'chroniona przed usunięciem' }
        catch { $notes += "ochrona: $($_.Exception.Message)"; $warn = $true }
    }
    [pscustomobject]@{ Dn = $g.DistinguishedName; Notes = ($notes -join '; '); Warn = $warn }
}

function ConvertTo-GroupPlanRow {
    # Wiersz podglądu tworzenia grupy z pól tekstowych; sprawdza poprawność danych (bez AD)
    param([hashtable]$Module, [hashtable]$Values)
    $issues = @()
    $name = ([string]$Values.Name).Trim()
    if (-not $name) { $issues += 'brak nazwy' }
    elseif ($name.Length -gt 64) { $issues += 'nazwa (CN) dłuższa niż 64 znaki' }
    $scope = ConvertTo-GroupScope $Values.Scope
    if (-not $scope) { $issues += "nieznany zakres «$($Values.Scope)»" }
    $cat = ConvertTo-GroupCategory $Values.Category
    if (-not $cat) { $issues += "nieznany typ «$($Values.Category)»" }
    $samIssue = Test-SamName $Values.Sam
    if ($samIssue) { $issues += $samIssue }
    if (-not ([string]$Values.Ou -match '^(OU|CN|DC)=')) { $issues += 'brak jednostki organizacyjnej (OU)' }
    if ($Values.Mail -and $Values.Mail -notmatch '^[^@\s]+@[^@\s]+\.[^@\s]+$') { $issues += 'niepoprawny adres e-mail' }
    $note = @($issues) -join '; '
    if (-not $issues -and $cat -eq 'Distribution' -and -not $Values.Mail) { $note = 'Grupa dystrybucyjna bez adresu e-mail' }
    return [ordered]@{
        'Stan'            = $(if ($issues) { 'Błąd danych' } else { 'Sprawdzanie…' })
        'Nazwa'           = $name
        'sAMAccountName'  = [string]$Values.Sam
        'Opis'            = [string]$Values.Description
        'Zakres'          = $(if ($scope) { Get-GroupScopeLabel $scope } else { [string]$Values.Scope })
        'Typ'             = $(if ($cat) { Get-GroupCategoryLabel $cat } else { [string]$Values.Category })
        'OU'              = [string]$Values.Ou
        'E-mail'          = [string]$Values.Mail
        'Członek grup'    = [string]$Values.MemberOf
        'Zarządca'        = [string]$Values.ManagedBy
        'Uwagi'           = $note
        '__tone'          = $(if ($issues) { 'crit' } else { '' })
    }
}

function Start-GroupPlanCheck {
    # Sprawdzenie wierszy podglądu tworzenia grup w AD (moduł Tworzenie grup); -ThenCreate tworzy po sprawdzeniu
    param([hashtable]$Module, [switch]$ThenCreate)
    $m = $Module
    $rows = @(Get-ResultRowsAll -Module $m)
    # Ponowna walidacja danych (po edycji komórek) i duplikaty w obrębie listy
    $seenSam = @{}
    $seenName = @{}
    $toCheck = @()
    foreach ($r in $rows) {
        $vals = @{
            Name = [string]$r['Nazwa']; Sam = ([string]$r['sAMAccountName']).Trim(); Description = ([string]$r['Opis']).Trim(); Scope = [string]$r['Zakres']
            Category = [string]$r['Typ']; Mail = ([string]$r['E-mail']).Trim(); MemberOf = [string]$r['Członek grup']; ManagedBy = ([string]$r['Zarządca']).Trim(); Ou = ([string]$r['OU']).Trim()
        }
        $plan = ConvertTo-GroupPlanRow -Module $m -Values $vals
        foreach ($k in 'Zakres', 'Typ') { if ([string]$r[$k] -cne $plan[$k]) { Set-ResultValue -Module $m -Row $r -Column $k -Value $plan[$k] } }
        $samKey = $vals.Sam.ToLowerInvariant()
        $nameKey = ($vals.Name + '|' + $vals.Ou).ToLowerInvariant()
        if ($plan['Stan'] -ne 'Błąd danych') {
            if ($seenSam.ContainsKey($samKey)) { $plan['Stan'] = 'Błąd danych'; $plan['Uwagi'] = "sAMAccountName powtarza się w wierszu $($seenSam[$samKey])"; $plan['__tone'] = 'crit' }
            elseif ($seenName.ContainsKey($nameKey)) { $plan['Stan'] = 'Błąd danych'; $plan['Uwagi'] = "nazwa powtarza się w tej samej OU (wiersz $($seenName[$nameKey]))"; $plan['__tone'] = 'crit' }
        }
        $seenSam[$samKey] = $r['Lp']
        $seenName[$nameKey] = $r['Lp']
        Set-RowState -Module $m -Row $r -State $plan['Stan'] -Tone $plan['__tone'] -Note $plan['Uwagi']
        if ($plan['Stan'] -ne 'Błąd danych') {
            $toCheck += @{ Id = [string]$r['__id']; Name = $vals.Name; Sam = $vals.Sam; Ou = $vals.Ou; MemberOf = @(Split-ListText $vals.MemberOf); ManagedBy = $vals.ManagedBy }
        }
    }
    $m.Data.Stale = $false
    if ($toCheck.Count -eq 0) { & $m.Actions.Stats $m; Show-Warning 'Wszystkie wiersze zawierają błędy danych – popraw je w tabeli (kolumny z ołówkiem).'; return }
    $m.Data.ThenCreate = [bool]$ThenCreate
    Start-AdOperation -Module $m -Name 'Sprawdzanie grup' -Targets @('AD') -Output None -Parameters @{ Rows = $toCheck } -ScriptBlock $script:GroupCheckScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) {
            foreach ($row in @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Sprawdzanie…' })) { Set-RowState -Module $m -Row $row -State 'Nie sprawdzono' -Tone 'warn' -Note ((@($r.Errors)) -join ' ') }
            return
        }
        foreach ($res in @($r.Data)) {
            foreach ($row in @(Find-ResultRow -Module $m -Column '__id' -Value ([string]$res.Id))) {
                $note = [string]$row['Uwagi']
                if (@($res.Issues).Count -gt 0) { Set-RowState -Module $m -Row $row -State 'Konflikt' -Tone 'crit' -Note ((@($res.Issues)) -join '; ') }
                elseif ($res.Exists) { Set-RowState -Module $m -Row $row -State 'Istnieje' -Tone 'warn' -Note 'Grupa o tej nazwie i sAMAccountName już istnieje – zostanie pominięta.' }
                else { Set-RowState -Module $m -Row $row -State 'Gotowe do utworzenia' -Tone 'info' -Note $note }
            }
        }
    } -OnComplete {
        param($m)
        & $m.Actions.Stats $m
        if ($m.Data.ThenCreate) { Invoke-Deferred -Module $m -Action { param($m) & $m.Actions.Create $m } }
    }
}

Register-Module -Workspace 'AdGroups' -Category 'Tworzenie' -Key 'GroupCreate' -Title 'Tworzenie grup' -Icon 'E710' -Badge 'nowe' `
    -Description 'Wiele grup naraz z tabeli wklejonej z Excela (nazwa, opis, zakres, typ, e-mail, sAMAccountName, grupy nadrzędne, zarządca, OU). Podgląd z edycją komórek i sprawdzeniem w AD, potem utworzenie z wynikiem dla każdej grupy.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.EditableColumns = @('Nazwa', 'sAMAccountName', 'Opis', 'Zakres', 'Typ', 'E-mail', 'Członek grup', 'Zarządca', 'OU')
    $m.Data.Stale = $true
    $m.Data.ThenCreate = $false
    $m.OnCellEdit = {
        param($m, $row, $column)
        if ($column -eq 'Nazwa' -and [string]$row['__auto'] -eq '1') {
            Set-ResultValue -Module $m -Row $row -Column 'sAMAccountName' -Value (ConvertTo-SamName ([string]$row['Nazwa']))
        }
        if ($column -eq 'sAMAccountName') { Set-ResultValue -Module $m -Row $row -Column '__auto' -Value '' }
        if (@('Utworzono', 'Istnieje') -notcontains [string]$row['Stan']) { Set-RowState -Module $m -Row $row -State 'Zmieniono – sprawdź' -Tone 'warn' }
        $m.Data.Stale = $true
    }
    $row = Add-ToolbarRow -Module $m -Title 'Miejsce'
    $m.Ou = Add-OuField -Parent $row -Module $m -Width 460 -Placeholder 'OU, w której powstaną grupy (gdy tabela nie podaje innej)' -DialogTitle 'Jednostka dla nowych grup' -Remember 'Ou'
    $row2 = Add-ToolbarRow -Module $m -Title 'Domyślnie'
    Add-Label -Parent $row2 -Text 'Zakres' | Out-Null
    $m.Scope = Add-ComboBox -Parent $row2 -Items @('Globalna', 'Lokalna domeny', 'Uniwersalna') -Width 150
    Add-Label -Parent $row2 -Text 'Typ' | Out-Null
    $m.Category = Add-ComboBox -Parent $row2 -Items @('Zabezpieczeń', 'Dystrybucyjna') -Width 150
    $m.AutoSam = Add-CheckBox -Parent $row2 -Text 'sAMAccountName z nazwy (bez polskich znaków)' -Checked $true -ToolTip 'Gdy tabela nie podaje sAMAccountName: nazwa bez znaków diakrytycznych, spacje i znaki specjalne zamienione na «-»'
    $m.Protect = Add-CheckBox -Parent $row2 -Text 'Chroń przed usunięciem'
    $m.Input = Add-StretchTextBox -Module $m -Title 'Dane' -Multiline -Height 130 -Placeholder "Nazwa [TAB] Opis [TAB] Zakres [TAB] Typ [TAB] E-mail [TAB] sAMAccountName [TAB] Członek grup [TAB] Zarządca [TAB] OU`r`nWklej z Excela (z nagłówkiem lub bez) albo wpisz nazwy grup – po jednej w wierszu."
    $m.Actions.Stats = {
        param($m)
        $rows = @(Get-ResultRowsAll -Module $m)
        Set-StatTile -Module $m -Key 'ready' -Value ([string]@($rows | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Gotowe do utworzenia' }).Count) -Tone 'info'
        Set-StatTile -Module $m -Key 'done' -Value ([string]@($rows | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Utworzono' }).Count) -Tone 'ok'
        Set-StatTile -Module $m -Key 'exists' -Value ([string]@($rows | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Istnieje' }).Count)
        $bad = @($rows | Where-Object { [string](Get-ObjectValue $_ '__tone') -eq 'crit' }).Count
        Set-StatTile -Module $m -Key 'bad' -Value ([string]$bad) -Tone $(if ($bad) { 'crit' } else { '' })
    }
    $m.Actions.Preview = {
        param($m)
        $text = $m.Input.Text
        if (-not $text.Trim()) { Show-Warning 'Wklej lub wpisz dane grup w polu «Dane».'; return }
        $defOu = $m.Ou.Text.Trim()
        $t = ConvertFrom-PastedTable -Text $text -Headers $script:GroupPasteHeaders -Order @('Name', 'Description', 'Scope', 'Category', 'Mail', 'Sam', 'MemberOf', 'ManagedBy', 'Ou')
        Reset-ResultTable -Module $m
        $lp = 0
        $objects = foreach ($r in $t.Rows) {
            $name = Get-PastedValue $r $t.Map 'Name'
            if (-not $name) { continue }
            $lp++
            $sam = Get-PastedValue $r $t.Map 'Sam'
            $auto = ''
            if (-not $sam) { $sam = if (Test-Checked $m.AutoSam) { ConvertTo-SamName $name } else { $name }; $auto = '1' }
            $vals = @{
                Name = $name; Sam = $sam; Description = (Get-PastedValue $r $t.Map 'Description')
                Scope = $(if (Get-PastedValue $r $t.Map 'Scope') { Get-PastedValue $r $t.Map 'Scope' } else { [string]$m.Scope.SelectedItem })
                Category = $(if (Get-PastedValue $r $t.Map 'Category') { Get-PastedValue $r $t.Map 'Category' } else { [string]$m.Category.SelectedItem })
                Mail = (Get-PastedValue $r $t.Map 'Mail'); MemberOf = (Get-PastedValue $r $t.Map 'MemberOf'); ManagedBy = (Get-PastedValue $r $t.Map 'ManagedBy')
                Ou = $(if (Get-PastedValue $r $t.Map 'Ou') { Get-PastedValue $r $t.Map 'Ou' } else { $defOu })
            }
            $o = [ordered]@{ 'Lp' = $lp }
            $plan = ConvertTo-GroupPlanRow -Module $m -Values $vals
            foreach ($k in $plan.Keys) { $o[$k] = $plan[$k] }
            $o['__id'] = [guid]::NewGuid().ToString('N')
            $o['__auto'] = $auto
            [pscustomobject]$o
        }
        $objects = @($objects)
        if ($objects.Count -eq 0) { Show-Warning 'Nie rozpoznano żadnej grupy w danych.'; return }
        Add-ResultRows -Module $m -Objects $objects
        Request-ResultSpace -Module $m
        Write-Log ("Podgląd: {0} grup{1}." -f $objects.Count, $(if ($t.HasHeader) { ' (rozpoznano nagłówek)' } else { '' }))
        Start-GroupPlanCheck -Module $m
    }
    $m.Actions.Create = {
        param($m)
        if (-not $m.Table -or $m.Table.Rows.Count -eq 0) { & $m.Actions.Preview $m; return }
        if ($m.Data.Stale) { Start-GroupPlanCheck -Module $m -ThenCreate; return }
        $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Gotowe do utworzenia' })
        if ($rows.Count -eq 0) { Show-Message -Text 'Brak grup gotowych do utworzenia. Popraw wiersze z błędami lub konfliktami i sprawdź ponownie.' -Title 'Brak zmian'; return }
        $items = @($rows | ForEach-Object { '{0}  ({1}, {2})' -f $_['Nazwa'], $_['Zakres'], (Get-RdnValue ([string]$_['OU'])) })
        $chosen = @(Confirm-Action -Text 'Utworzyć wybrane grupy?' -Items $items -ConfirmText 'Utwórz grupy' -Select -ReturnIndex)
        if ($chosen.Count -eq 0) { return }
        $rows = @($chosen | ForEach-Object { $rows[$_] })
        $per = @{}
        foreach ($r in $rows) {
            $per[[string]$r['__id']] = @{
                Name = [string]$r['Nazwa']; Sam = ([string]$r['sAMAccountName']).Trim(); Scope = (ConvertTo-GroupScope ([string]$r['Zakres'])); Category = (ConvertTo-GroupCategory ([string]$r['Typ']))
                Ou = ([string]$r['OU']).Trim(); Description = ([string]$r['Opis']).Trim(); Mail = ([string]$r['E-mail']).Trim(); MemberOf = @(Split-ListText ([string]$r['Członek grup']))
                ManagedBy = ([string]$r['Zarządca']).Trim(); Protect = (Test-Checked $m.Protect)
            }
        }
        foreach ($r in $rows) { Set-RowState -Module $m -Row $r -State 'Tworzenie…' -Tone '' }
        Start-AdOperation -Module $m -Name 'Tworzenie grup' -Targets @($per.Keys) -PerTarget $per -Output None -ScriptBlock $script:GroupCreateScript -OnResult {
            param($m, $r)
            foreach ($row in @(Find-ResultRow -Module $m -Column '__id' -Value $r.Target)) {
                if ($r.Ok) {
                    $d = @($r.Data)[0]
                    Set-RowState -Module $m -Row $row -State 'Utworzono' -Tone $(if ($d.Warn) { 'warn' } else { 'ok' }) -Note $d.Notes
                    Set-ResultValue -Module $m -Row $row -Column 'DN' -Value $d.Dn
                }
                else { Set-RowState -Module $m -Row $row -State 'Błąd' -Tone 'crit' -Note (Get-FriendlyAdError ((@($r.Errors)) -join ' ')) }
            }
        } -OnComplete {
            param($m)
            & $m.Actions.Stats $m
            $created = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Utworzono' } | ForEach-Object { [string]$_['sAMAccountName'] })
            if ($created.Count -gt 0) {
                Set-TargetCheck -Panel $script:UI.GroupPanel -Mode UncheckAll
                Add-GroupNames -Module $script:UI.Modules['__groups'] -Names $created -Source 'utworzone'
                Write-Log "Utworzone grupy ($($created.Count)) zostaną zaznaczone na liście grup." 'OK'
            }
        }
    }
    $row3 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row3 -Text 'Wklej ze schowka' -Icon 'E77F' -Module $m -AlwaysEnabled -OnClick {
        param($m)
        $clip = Get-ClipboardText
        if (-not $clip.Trim()) { Show-Warning 'Schowek nie zawiera tekstu.'; return }
        $m.Input.Text = $clip
        & $m.Actions.Preview $m
    } | Out-Null
    Add-Button -Parent $row3 -Text 'Podgląd i sprawdzenie' -Icon 'E9D5' -Module $m -Primary -OnClick $m.Actions.Preview | Out-Null
    Add-Button -Parent $row3 -Text 'Sprawdź ponownie' -Icon 'E72C' -Module $m -ToolTip 'Sprawdza wiersze tabeli po edycji (bez ponownego wczytywania pola «Dane»)' -OnClick {
        param($m)
        if (-not $m.Table -or $m.Table.Rows.Count -eq 0) { & $m.Actions.Preview $m; return }
        Start-GroupPlanCheck -Module $m
    } | Out-Null
    Add-Button -Parent $row3 -Text 'Utwórz grupy' -Icon 'E710' -Module $m -OnClick $m.Actions.Create | Out-Null
    Add-MenuButton -Parent $row3 -Text 'Ustaw w zaznaczonych' -Icon 'E70F' -Module $m -ToolTip 'Zmienia kolumnę w zaznaczonych wierszach (albo we wszystkich, gdy nic nie zaznaczono)' -Items @(
        @{ Text = 'Zakres: globalna'; Value = @('Zakres', 'Globalna'); Action = { param($m, $v) Set-GridColumnValue -Module $m -Column $v[0] -Value $v[1] } }
        @{ Text = 'Zakres: lokalna domeny'; Value = @('Zakres', 'Lokalna domeny'); Action = { param($m, $v) Set-GridColumnValue -Module $m -Column $v[0] -Value $v[1] } }
        @{ Text = 'Zakres: uniwersalna'; Value = @('Zakres', 'Uniwersalna'); Action = { param($m, $v) Set-GridColumnValue -Module $m -Column $v[0] -Value $v[1] } }
        '-'
        @{ Text = 'Typ: zabezpieczeń'; Value = @('Typ', 'Zabezpieczeń'); Action = { param($m, $v) Set-GridColumnValue -Module $m -Column $v[0] -Value $v[1] } }
        @{ Text = 'Typ: dystrybucyjna'; Value = @('Typ', 'Dystrybucyjna'); Action = { param($m, $v) Set-GridColumnValue -Module $m -Column $v[0] -Value $v[1] } }
        '-'
        @{ Text = 'OU: wartość z pola «Miejsce»'; Value = @('OU', ''); Action = { param($m, $v) Set-GridColumnValue -Module $m -Column 'OU' -Value $m.Ou.Text.Trim() } }
        @{ Text = 'Opis…'; Value = @('Opis', ''); Action = {
                param($m)
                $d = Show-InputDialog -Title 'Opis' -Prompt 'Opis dla wybranych wierszy. Pole {nazwa} zostanie zastąpione nazwą grupy.' -Icon 'E70F'
                if ($null -ne $d) { Set-GridColumnValue -Module $m -Column 'Opis' -Value $d -Template }
            }
        }
    ) | Out-Null
    Add-RowAction -Module $m -Text 'Usuń wiersze z podglądu' -Icon 'E74D' -Action { param($m, $rows) Remove-ResultRows -Module $m -Rows $rows; & $m.Actions.Stats $m }
    Add-StatTile -Module $m -Key 'ready' -Label 'Gotowe do utworzenia' -Icon 'E9D5' | Out-Null
    Add-StatTile -Module $m -Key 'done' -Label 'Utworzone' -Icon 'E73E' | Out-Null
    Add-StatTile -Module $m -Key 'exists' -Label 'Już istnieją' -Icon 'E73A' | Out-Null
    Add-StatTile -Module $m -Key 'bad' -Label 'Błędy i konflikty' -Icon 'E7BA' | Out-Null
    $m.EmptyHint = 'Wklej tabelę z Excela (Wklej ze schowka) albo wpisz nazwy grup w polu «Dane» i kliknij «Podgląd i sprawdzenie» (F5). Komórki z ołówkiem można poprawić przed utworzeniem.'
}

function Set-GridColumnValue {
    # Ustawia wartość kolumny w zaznaczonych wierszach podglądu (albo we wszystkich, gdy nic nie zaznaczono)
    param([hashtable]$Module, [string]$Column, [string]$Value, [switch]$Template)
    Complete-GridEdit -Module $Module
    $rows = @(Get-SelectedResultRows -Module $Module | ForEach-Object { $_.Row })
    if ($rows.Count -le 1) { $rows = @($Module.View | ForEach-Object { $_.Row }) }
    $Module.Loading = $true
    try {
        foreach ($r in $rows) {
            if (@('Utworzono', 'Istnieje') -contains [string]$r['Stan']) { continue }
            $v = if ($Template) { $Value.Replace('{nazwa}', [string]$r['Nazwa']) } else { $Value }
            Set-ResultValue -Module $Module -Row $r -Column $Column -Value $v
            Set-RowState -Module $Module -Row $r -State 'Zmieniono – sprawdź' -Tone 'warn'
        }
    }
    finally { $Module.Loading = $false }
    $Module.Data.Stale = $true
    Show-Toast ("Zmieniono kolumnę «{0}» w {1} wierszach – sprawdź ponownie przed utworzeniem." -f $Column, $rows.Count) 'info'
}

$script:GroupDuplicatePlanScript = {
    # Podgląd kopii grupy źródłowej ($Target): nowa nazwa wg reguł, sprawdzenie zajętości
    $src = Get-ADGroup -Identity $Target -Properties Description, member, memberOf, managedBy @ad
    $values = @($P.Replace)
    if ($values.Count -eq 0) { $values = @('') }
    foreach ($repl in $values) {
        $conv = {
            param([string]$Text)
            $t = $Text
            if ($P.Find) { $t = [regex]::Replace($t, [regex]::Escape($P.Find), $repl.Replace('$', '$$'), 'IgnoreCase') }
            return ($P.Prefix + $t + $P.Suffix)
        }
        $name = & $conv $src.Name
        $sam = ConvertTo-SamName (& $conv $src.SamAccountName)
        $desc = [string]$src.Description
        if ($P.ReplaceInDescription) { $desc = & $conv $desc; if (-not $src.Description) { $desc = '' } }
        $ou = if ($P.Ou) { $P.Ou } else { Get-DnParent $src.DistinguishedName }
        $issues = @()
        if ($sam -ieq $src.SamAccountName) { $issues += 'sAMAccountName kopii jest taki sam jak oryginału – ustaw zamianę tekstu, przedrostek lub przyrostek albo popraw w tabeli' }
        elseif (@(Get-ADObject -LDAPFilter "(sAMAccountName=$(ConvertTo-LdapValue $sam))" @ad).Count -gt 0) { $issues += "sAMAccountName «$sam» jest zajęty" }
        try {
            if (@(Get-ADObject -LDAPFilter "(name=$(ConvertTo-LdapValue $name))" -SearchBase $ou -SearchScope OneLevel @ad).Count -gt 0) { $issues += "w OU istnieje już obiekt «$name»" }
        }
        catch { $issues += "nie ma jednostki $ou" }
        [pscustomobject][ordered]@{
            'Stan'                = $(if ($issues) { 'Konflikt' } else { 'Do utworzenia' })
            'Nowa nazwa'          = $name
            'Nowy sAMAccountName' = $sam
            'Opis'                = $desc
            'OU'                  = $ou
            'Zakres'              = Get-ScopeLabel $src.GroupScope
            'Typ'                 = Get-CategoryLabel $src.GroupCategory
            'Członkowie'          = @($src.member).Count
            'Należy do'           = @($src.memberOf).Count
            'Uwagi'               = ($issues -join '; ')
            '__tone'              = $(if ($issues) { 'crit' } else { 'info' })
            '__id'                = [guid]::NewGuid().ToString('N')
            '__src'               = $src.DistinguishedName
        }
    }
}

$script:GroupDuplicateScript = {
    # Utworzenie kopii grupy ($P: SrcDn, Name, Sam, Description, Ou, Copy*)
    $src = Get-ADGroup -Identity $P.SrcDn -Properties Description, member, memberOf, managedBy, info, mail, ProtectedFromAccidentalDeletion, displayName @ad
    $params = @{ Name = $P.Name; SamAccountName = $P.Sam; GroupScope = $src.GroupScope; GroupCategory = $src.GroupCategory; Path = $P.Ou; PassThru = $true }
    if ($P.Description) { $params.Description = $P.Description }
    $other = @{}
    if ($P.CopyInfo -and $src.info) { $other.info = [string]$src.info }
    if ($P.CopyMail -and $src.mail) { $other.mail = [string]$src.mail }
    if ($other.Count) { $params.OtherAttributes = $other }
    if ($P.CopyManager -and $src.managedBy) { $params.ManagedBy = [string]$src.managedBy }
    $new = New-ADGroup @params @ad
    $notes = @()
    $warn = $false
    if ($P.CopyMembers) {
        $members = @($src.member)
        $added = 0
        for ($i = 0; $i -lt $members.Count; $i += 200) {
            $chunk = @($members[$i..([Math]::Min($i + 199, $members.Count - 1))])
            try { Add-ADGroupMember -Identity $new.DistinguishedName -Members $chunk @ad; $added += $chunk.Count }
            catch {
                foreach ($d in $chunk) {
                    try { Add-ADGroupMember -Identity $new.DistinguishedName -Members $d @ad; $added++ }
                    catch { $notes += "członek $(Get-DnName $d): $($_.Exception.Message)"; $warn = $true }
                }
            }
        }
        $notes += "członkowie: $added z $($members.Count)"
    }
    if ($P.CopyMemberOf) {
        $ok = 0
        foreach ($parent in @($src.memberOf)) {
            try { Add-ADGroupMember -Identity $parent -Members $new.DistinguishedName @ad; $ok++ }
            catch { $notes += "przynależność do $(Get-DnName $parent): $($_.Exception.Message)"; $warn = $true }
        }
        $notes += "przynależność: $ok z $(@($src.memberOf).Count)"
    }
    if ($P.CopyProtect -and $src.ProtectedFromAccidentalDeletion) { Set-ADObject -Identity $new.DistinguishedName -ProtectedFromAccidentalDeletion $true @ad; $notes += 'chroniona' }
    [pscustomobject]@{ Dn = $new.DistinguishedName; Notes = ($notes -join '; '); Warn = $warn }
}

Register-Module -Workspace 'AdGroups' -Category 'Tworzenie' -Key 'GroupDuplicate' -Title 'Duplikowanie grup' -Icon 'E8C8' -Badge 'nowe' `
    -Description 'Kopie zaznaczonych grup z nową nazwą (zamiana tekstu, przedrostek, przyrostek – także wiele kopii naraz, np. WAW → KRK; GDA) i opcjonalnie z członkami, przynależnością do grup, zarządcą i ochroną. Podgląd z edycją przed utworzeniem.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.EditableColumns = @('Nowa nazwa', 'Nowy sAMAccountName', 'Opis', 'OU')
    $m.Data.Stale = $false
    $m.Data.SameInput = ''
    $m.OnCellEdit = {
        param($m, $row, $column)
        if ([string]$row['Stan'] -ne 'Utworzono') { Set-RowState -Module $m -Row $row -State 'Zmieniono – sprawdź' -Tone 'warn' -Note 'Kliknij «Podgląd», aby sprawdzić zmienione wartości w AD (bez zmiany reguł nazwy poprawki w tabeli zostaną zachowane).' }
        $m.Data.Stale = $true
    }
    $row = Add-ToolbarRow -Module $m -Title 'Nowa nazwa'
    Add-Label -Parent $row -Text 'Zamień' | Out-Null
    $m.Find = Add-TextBox -Parent $row -Width 140 -Placeholder 'np. WAW'
    Add-Label -Parent $row -Text 'na' | Out-Null
    $m.Replace = Add-TextBox -Parent $row -Width 220 -Placeholder 'np. KRK; GDA (kilka kopii)'
    Add-Label -Parent $row -Text 'Przedrostek' | Out-Null
    $m.Prefix = Add-TextBox -Parent $row -Width 100
    Add-Label -Parent $row -Text 'Przyrostek' | Out-Null
    $m.Suffix = Add-TextBox -Parent $row -Width 100 -Placeholder 'np. _kopia'
    $row2 = Add-ToolbarRow -Module $m -Title 'Miejsce'
    $m.Ou = Add-OuField -Parent $row2 -Module $m -Width 460 -Placeholder 'Ta sama OU co grupa źródłowa' -DialogTitle 'Jednostka dla kopii grup'
    $row3 = Add-ToolbarRow -Module $m -Title 'Kopiuj'
    $m.CopyMembers = Add-CheckBox -Parent $row3 -Text 'Członków' -Checked $true
    $m.CopyMemberOf = Add-CheckBox -Parent $row3 -Text 'Przynależność do grup' -Checked $true -ToolTip 'Kopia zostanie dodana do tych samych grup nadrzędnych co oryginał'
    $m.CopyManager = Add-CheckBox -Parent $row3 -Text 'Zarządcę' -Checked $true
    $m.CopyInfo = Add-CheckBox -Parent $row3 -Text 'Uwagi (info)' -Checked $true
    $m.CopyMail = Add-CheckBox -Parent $row3 -Text 'Adres e-mail' -ToolTip 'Zwykle niewskazane – adres e-mail grupy powinien być unikalny'
    $m.CopyProtect = Add-CheckBox -Parent $row3 -Text 'Ochronę przed usunięciem' -Checked $true
    $m.ReplaceDesc = Add-CheckBox -Parent $row3 -Text 'Zamieniaj tekst także w opisie' -Checked $true
    $m.Actions.Preview = {
        param($m)
        $targets = @(Get-TargetGroups)
        if (-not $targets) { return }
        $replace = @(([string]$m.Replace.Text) -split ';' | ForEach-Object { $_.Trim() })
        if (-not $m.Find.Text.Trim()) { $replace = @('') }
        elseif (@($replace | Where-Object { $_ }).Count -eq 0) { $replace = @('') } else { $replace = @($replace | Where-Object { $_ }) }
        $params = @{ Find = $m.Find.Text.Trim(); Replace = $replace; Prefix = $m.Prefix.Text; Suffix = $m.Suffix.Text; Ou = $m.Ou.Text.Trim(); ReplaceInDescription = (Test-Checked $m.ReplaceDesc) }
        # Wiersze zmienione ręcznie w tabeli zostają - sprawdzane są ponownie z nowymi wartościami
        $edited = @{}
        foreach ($r in @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Zmieniono – sprawdź' })) {
            $edited[[string]$r['__src'] + '|' + [string]$r['__id']] = $r
        }
        if ($edited.Count -gt 0 -and $m.Data.SameInput -eq ($params | ConvertTo-Json -Compress)) {
            & $m.Actions.Recheck $m
            return
        }
        $m.Data.SameInput = ($params | ConvertTo-Json -Compress)
        Start-AdOperation -Module $m -Name 'Podgląd kopii' -Targets $targets -TargetColumn 'Źródło' -Parameters $params -ScriptBlock $script:GroupDuplicatePlanScript -OnComplete { param($m) $m.Data.Stale = $false }
    }
    $m.Actions.Recheck = {
        param($m)
        # Sprawdzenie wierszy edytowanych w tabeli (nazwa, sAMAccountName, OU) bez ponownego generowania nazw
        $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Zmieniono – sprawdź' })
        $check = @($rows | ForEach-Object { @{ Id = [string]$_['__id']; Name = ([string]$_['Nowa nazwa']).Trim(); Sam = ([string]$_['Nowy sAMAccountName']).Trim(); Ou = ([string]$_['OU']).Trim(); MemberOf = @(); ManagedBy = '' } })
        Start-AdOperation -Module $m -Name 'Sprawdzanie kopii' -Targets @('AD') -Output None -Parameters @{ Rows = $check } -ScriptBlock $script:GroupCheckScript -OnResult {
            param($m, $r)
            foreach ($res in @($r.Data)) {
                foreach ($row in @(Find-ResultRow -Module $m -Column '__id' -Value ([string]$res.Id))) {
                    $samIssue = Test-SamName ([string]$row['Nowy sAMAccountName'])
                    if ($samIssue) { Set-RowState -Module $m -Row $row -State 'Konflikt' -Tone 'crit' -Note $samIssue }
                    elseif (@($res.Issues).Count -gt 0) { Set-RowState -Module $m -Row $row -State 'Konflikt' -Tone 'crit' -Note ((@($res.Issues)) -join '; ') }
                    elseif ($res.Exists) { Set-RowState -Module $m -Row $row -State 'Konflikt' -Tone 'crit' -Note 'Grupa o tej nazwie już istnieje.' }
                    else { Set-RowState -Module $m -Row $row -State 'Do utworzenia' -Tone 'info' -Note '' }
                }
            }
        } -OnComplete { param($m) $m.Data.Stale = $false }
    }
    $m.Actions.Create = {
        param($m)
        if ($m.Data.Stale -and @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Zmieniono – sprawdź' }).Count -gt 0) {
            Show-Warning 'Część wierszy zmieniono w tabeli – kliknij «Podgląd», aby je sprawdzić przed utworzeniem kopii.'
            return
        }
        $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Do utworzenia' })
        if ($rows.Count -eq 0) { Show-Message -Text 'Brak kopii gotowych do utworzenia. Kliknij «Podgląd» (F5) dla zaznaczonych grup.' -Title 'Brak zmian'; return }
        $per = @{}
        foreach ($r in $rows) {
            $per[[string]$r['__id']] = @{
                SrcDn = [string]$r['__src']; Name = ([string]$r['Nowa nazwa']).Trim(); Sam = ([string]$r['Nowy sAMAccountName']).Trim(); Description = ([string]$r['Opis']).Trim(); Ou = ([string]$r['OU']).Trim()
                CopyMembers = (Test-Checked $m.CopyMembers); CopyMemberOf = (Test-Checked $m.CopyMemberOf); CopyManager = (Test-Checked $m.CopyManager)
                CopyInfo = (Test-Checked $m.CopyInfo); CopyMail = (Test-Checked $m.CopyMail); CopyProtect = (Test-Checked $m.CopyProtect)
            }
        }
        $items = @($rows | ForEach-Object { '{0}  →  {1}' -f $_['Źródło'], $_['Nowa nazwa'] })
        if (-not (Confirm-Action -Text "Utworzyć $($rows.Count) kopi(i) grup?" -Items $items -ConfirmText 'Utwórz kopie')) { return }
        Start-AdOperation -Module $m -Name 'Duplikowanie grup' -Targets @($per.Keys) -PerTarget $per -Output None -ScriptBlock $script:GroupDuplicateScript -OnResult {
            param($m, $r)
            foreach ($row in @(Find-ResultRow -Module $m -Column '__id' -Value $r.Target)) {
                if ($r.Ok) {
                    $d = @($r.Data)[0]
                    Set-RowState -Module $m -Row $row -State 'Utworzono' -Tone $(if ($d.Warn) { 'warn' } else { 'ok' }) -Note $d.Notes
                }
                else { Set-RowState -Module $m -Row $row -State 'Błąd' -Tone 'crit' -Note (Get-FriendlyAdError ((@($r.Errors)) -join ' ')) }
            }
        } -OnComplete {
            param($m)
            $created = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Stan') -eq 'Utworzono' } | ForEach-Object { [string]$_['Nowy sAMAccountName'] })
            if ($created.Count -gt 0) { Add-GroupNames -Module $script:UI.Modules['__groups'] -Names $created -Source 'kopie' }
        }
    }
    $row4 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row4 -Text 'Podgląd' -Icon 'E9D5' -Module $m -Primary -OnClick $m.Actions.Preview | Out-Null
    Add-Button -Parent $row4 -Text 'Utwórz kopie' -Icon 'E8C8' -Module $m -OnClick $m.Actions.Create | Out-Null
    Add-RowAction -Module $m -Text 'Usuń wiersze z podglądu' -Icon 'E74D' -Action { param($m, $rows) Remove-ResultRows -Module $m -Rows $rows }
    $m.EmptyHint = 'Zaznacz grupy na liście po lewej, ustaw regułę nowej nazwy i kliknij «Podgląd» (F5). Nazwy, sAMAccountName, opis i OU można poprawić w tabeli.'
}
#endregion

#region Struktura OU: plan zmian (OU, grupy, członkostwa), drzewo OU, klonowanie OU, lokalizacje i role
# Plan = lista pozycji (hashtabli) Kind = 'OU' | 'Grupa' | 'Członkostwo' z polami: Key, Name, Sam, Parent (DN kontenera), Dn,
# Scope, Category, Description, Info, Protect, GpLink, GpOptions, Group (DN), Member (DN), Source (opis źródła).
# Test-AdPlanItems (w wątku AD) uzupełnia State/Note/Tone, $script:AdPlanExecuteScript wykonuje plan po kolei.
$script:AdHelpers += @'

function Test-AdPlanItems {
    # Sprawdza pozycje planu w AD: istniejące obiekty, brakujące OU nadrzędne, zajęte sAMAccountName (opcjonalnie z sufiksem -1, -2...)
    param([object[]]$Items, [switch]$UniqueSam, [int]$SamMax = 0)
    $planned = @{}
    $samPlanned = @{}
    $memberCache = @{}
    $existsCache = @{}
    $exists = {
        param([string]$Dn)
        $k = $Dn.ToLowerInvariant()
        if (-not $existsCache.ContainsKey($k)) {
            $o = $null
            try { $o = Get-ADObject -Identity $Dn -Properties member @ad } catch { }
            $existsCache[$k] = $o
        }
        return $existsCache[$k]
    }
    $parentOk = {
        param([string]$Dn)
        if ($planned.ContainsKey($Dn.ToLowerInvariant())) { return (@('Do utworzenia', 'Istnieje') -contains $planned[$Dn.ToLowerInvariant()].State) }
        return ($null -ne (& $exists $Dn))
    }
    foreach ($it in $Items) {
        $it.Note = [string]$it.Note
        switch ($it.Kind) {
            'OU' {
                $o = & $exists $it.Dn
                if ($o) { $it.State = 'Istnieje'; $it.Tone = ''; if (-not $it.Note) { $it.Note = 'Jednostka już istnieje – zostanie użyta.' } }
                elseif (-not (& $parentOk $it.Parent)) { $it.State = 'Konflikt'; $it.Tone = 'crit'; $it.Note = "Brak jednostki nadrzędnej $($it.Parent)" }
                elseif ($it.Name.Length -gt 64) { $it.State = 'Konflikt'; $it.Tone = 'crit'; $it.Note = 'Nazwa OU dłuższa niż 64 znaki' }
                else { $it.State = 'Do utworzenia'; $it.Tone = 'info' }
            }
            'Grupa' {
                $o = & $exists $it.Dn
                if ($o) {
                    if ([string]$o.ObjectClass -eq 'group') { $it.State = 'Istnieje'; $it.Tone = ''; $it.Note = 'Grupa już istnieje – zostanie użyta.'; $it.Sam = [string](Get-ADGroup -Identity $it.Dn @ad).SamAccountName }
                    else { $it.State = 'Konflikt'; $it.Tone = 'crit'; $it.Note = "W OU istnieje inny obiekt o nazwie «$($it.Name)»" }
                }
                elseif (-not (& $parentOk $it.Parent)) { $it.State = 'Konflikt'; $it.Tone = 'crit'; $it.Note = "Brak jednostki $($it.Parent)" }
                elseif ($it.Name.Length -gt 64) { $it.State = 'Konflikt'; $it.Tone = 'crit'; $it.Note = 'Nazwa grupy (CN) dłuższa niż 64 znaki' }
                else {
                    $base = [string]$it.Sam
                    $sam = $base
                    $i = 0
                    while ($true) {
                        $taken = $samPlanned.ContainsKey($sam.ToLowerInvariant()) -or @(Get-ADObject -LDAPFilter "(sAMAccountName=$(ConvertTo-LdapValue $sam))" @ad).Count -gt 0
                        if (-not $taken) { break }
                        if (-not $UniqueSam) { break }
                        $i++
                        $suffix = "-$i"
                        $stem = if ($SamMax -gt 0 -and $base.Length + $suffix.Length -gt $SamMax) { $base.Substring(0, $SamMax - $suffix.Length) } else { $base }
                        $sam = $stem + $suffix
                    }
                    if ($taken) { $it.State = 'Konflikt'; $it.Tone = 'crit'; $it.Note = (@("sAMAccountName «$sam» jest zajęty", $it.Note) | Where-Object { $_ }) -join ' – ' }
                    else {
                        if ($sam -ne $base) { $it.Note = (@($it.Note, "sAMAccountName zajęty – użyto «$sam»") | Where-Object { $_ }) -join '; ' }
                        $it.Sam = $sam
                        $it.State = 'Do utworzenia'; $it.Tone = 'info'
                    }
                }
                $samPlanned[([string]$it.Sam).ToLowerInvariant()] = $true
            }
            'Członkostwo' {
                $gState = if ($planned.ContainsKey($it.Group.ToLowerInvariant())) { $planned[$it.Group.ToLowerInvariant()].State } elseif (& $exists $it.Group) { 'Istnieje' } else { 'Brak' }
                $mState = if ($planned.ContainsKey($it.Member.ToLowerInvariant())) { $planned[$it.Member.ToLowerInvariant()].State } elseif (& $exists $it.Member) { 'Istnieje' } else { 'Brak' }
                if (@('Do utworzenia', 'Istnieje') -notcontains $gState -or @('Do utworzenia', 'Istnieje') -notcontains $mState) {
                    $it.State = 'Pominięto'; $it.Tone = 'warn'; $it.Note = 'Grupa lub członek nie zostanie utworzony (konflikt).'
                }
                elseif ($gState -eq 'Istnieje' -and $mState -eq 'Istnieje') {
                    $k = $it.Group.ToLowerInvariant()
                    if (-not $memberCache.ContainsKey($k)) {
                        $set = @{}
                        foreach ($d in @((& $exists $it.Group).member)) { $set[([string]$d).ToLowerInvariant()] = $true }
                        $memberCache[$k] = $set
                    }
                    if ($memberCache[$k].ContainsKey($it.Member.ToLowerInvariant())) { $it.State = 'Istnieje'; $it.Tone = ''; $it.Note = 'Już jest członkiem.' }
                    else { $it.State = 'Do dodania'; $it.Tone = 'info' }
                }
                else { $it.State = 'Do dodania'; $it.Tone = 'info' }
            }
        }
        if ($it.Dn) { $planned[([string]$it.Dn).ToLowerInvariant()] = $it }
    }
    return , $Items
}
'@

$script:AdPlanCheckScript = {
    $items = @($P.Items | ForEach-Object { $h = @{}; foreach ($k in $_.Keys) { $h[$k] = $_[$k] }; $h })
    $checked = Test-AdPlanItems -Items $items -UniqueSam:([bool]$P.UniqueSam) -SamMax ([int]$P.SamMax)
    foreach ($it in $checked) { [pscustomobject]$it }
}

$script:AdPlanExecuteScript = {
    # Wykonanie planu po kolei (najpierw elementy nadrzędne - kolejność pozycji jest kolejnością planu)
    $failed = @{}
    foreach ($src in $P.Items) {
        $it = @{}
        foreach ($k in $src.Keys) { $it[$k] = $src[$k] }
        if (@('Do utworzenia', 'Do dodania') -notcontains $it.State) { continue }
        $result = @{ Key = $it.Key; Ok = $true; State = ''; Note = '' }
        try {
            if ($it.Parent -and $failed.ContainsKey(([string]$it.Parent).ToLowerInvariant())) { throw 'Nie utworzono elementu nadrzędnego.' }
            switch ($it.Kind) {
                'OU' {
                    $params = @{ Name = $it.Name; Path = $it.Parent; ProtectedFromAccidentalDeletion = [bool]$it.Protect }
                    if ($it.Description) { $params.Description = $it.Description }
                    $other = @{}
                    if ($it.GpLink) { $other.gPLink = [string]$it.GpLink }
                    if ($null -ne $it.GpOptions -and [string]$it.GpOptions -ne '' -and [int]$it.GpOptions -ne 0) { $other.gPOptions = [int]$it.GpOptions }
                    if ($other.Count) { $params.OtherAttributes = $other }
                    New-ADOrganizationalUnit @params @ad
                    $result.State = 'Utworzono'
                    if ($it.GpLink) { $result.Note = 'połączono zasady grupy' }
                }
                'Grupa' {
                    $params = @{ Name = $it.Name; SamAccountName = $it.Sam; GroupScope = $it.Scope; GroupCategory = $it.Category; Path = $it.Parent }
                    if ($it.Description) { $params.Description = $it.Description }
                    if ($it.Info) { $params.OtherAttributes = @{ info = [string]$it.Info } }
                    New-ADGroup @params @ad
                    if ($it.Protect) { Set-ADObject -Identity $it.Dn -ProtectedFromAccidentalDeletion $true @ad }
                    $result.State = 'Utworzono'
                }
                'Członkostwo' {
                    if ($failed.ContainsKey(([string]$it.Group).ToLowerInvariant()) -or $failed.ContainsKey(([string]$it.Member).ToLowerInvariant())) { throw 'Nie utworzono grupy lub członka.' }
                    Add-ADGroupMember -Identity $it.Group -Members $it.Member @ad
                    $result.State = 'Dodano'
                }
            }
        }
        catch {
            $result.Ok = $false
            $result.State = 'Błąd'
            $result.Note = $_.Exception.Message
            if ($it.Dn) { $failed[([string]$it.Dn).ToLowerInvariant()] = $true }
        }
        [pscustomobject]$result
    }
}

function ConvertTo-PlanRow {
    # Pozycja planu -> wiersz tabeli podglądu
    param($Item, [int]$Index)
    $kind = [string]$Item.Kind
    $target = switch ($kind) {
        'Członkostwo' { '{0}  →  {1}' -f (Get-RdnValue ([string]$Item.Member)), (Get-RdnValue ([string]$Item.Group)) }
        default { [string]$Item.Dn }
    }
    $indent = ''
    if ($Item['Level']) { $indent = ('    ' * [int]$Item['Level']) }
    return [pscustomobject][ordered]@{
        'Lp'             = $Index
        'Stan'           = [string]$Item.State
        'Typ'            = $kind
        'Nazwa'          = $(if ($kind -eq 'Członkostwo') { Get-RdnValue ([string]$Item.Member) } else { $indent + [string]$Item.Name })
        'sAMAccountName' = [string]$Item['Sam']
        'Opis'           = [string]$Item['Description']
        'Cel'            = $target
        'Źródło'         = [string]$Item['Source']
        'Uwagi'          = [string]$Item.Note
        '__tone'         = [string]$Item.Tone
        '__key'          = [string]$Item.Key
    }
}

function Show-AdPlan {
    # Wyświetla plan w tabeli modułu i zapamiętuje go do wykonania
    param([hashtable]$Module, [object[]]$Items)
    $Module.Data.Plan = @($Items)
    Reset-ResultTable -Module $Module
    $i = 0
    $rows = foreach ($it in $Items) { $i++; ConvertTo-PlanRow -Item $it -Index $i }
    if (@($rows).Count -gt 0) { Add-ResultRows -Module $Module -Objects @($rows); Request-ResultSpace -Module $Module }
    Update-AdPlanStats -Module $Module
}

function Update-AdPlanStats {
    param([hashtable]$Module)
    $plan = @($Module.Data['Plan'])
    $count = { param([string[]]$States, [string]$Kind) @($plan | Where-Object { $_ -and $States -contains [string]$_.State -and (-not $Kind -or $_.Kind -eq $Kind) }).Count }
    Set-StatTile -Module $Module -Key 'ou' -Value ([string](& $count @('Do utworzenia') 'OU')) -Tone 'info' -Label 'Nowe OU'
    Set-StatTile -Module $Module -Key 'groups' -Value ([string](& $count @('Do utworzenia') 'Grupa')) -Tone 'info' -Label 'Nowe grupy'
    Set-StatTile -Module $Module -Key 'members' -Value ([string](& $count @('Do dodania') 'Członkostwo')) -Tone 'info' -Label 'Nowe członkostwa'
    Set-StatTile -Module $Module -Key 'done' -Value ([string](& $count @('Utworzono', 'Dodano') '')) -Tone 'ok' -Label 'Wykonane'
    $bad = & $count @('Konflikt', 'Błąd') ''
    Set-StatTile -Module $Module -Key 'bad' -Value ([string]$bad) -Tone $(if ($bad) { 'crit' } else { '' }) -Label 'Konflikty i błędy'
}

function Add-PlanTiles {
    param([hashtable]$Module, [switch]$NoGroups)
    Add-StatTile -Module $Module -Key 'ou' -Label 'Nowe OU' -Icon 'ED41' | Out-Null
    if (-not $NoGroups) {
        Add-StatTile -Module $Module -Key 'groups' -Label 'Nowe grupy' -Icon 'E902' | Out-Null
        Add-StatTile -Module $Module -Key 'members' -Label 'Nowe członkostwa' -Icon 'E8FA' | Out-Null
    }
    Add-StatTile -Module $Module -Key 'done' -Label 'Wykonane' -Icon 'E73E' | Out-Null
    Add-StatTile -Module $Module -Key 'bad' -Label 'Konflikty i błędy' -Icon 'E7BA' | Out-Null
}

function Start-AdPlanCheck {
    # Sprawdzenie planu w AD i wyświetlenie wyniku (-UniqueSam: zajęty sAMAccountName dostaje sufiks)
    param([hashtable]$Module, [object[]]$Items, [switch]$UniqueSam, [int]$SamMax = 0)
    if (@($Items).Count -eq 0) { Show-Warning 'Plan jest pusty.'; return }
    Show-AdPlan -Module $Module -Items @($Items | ForEach-Object { $_.State = 'Sprawdzanie…'; $_.Tone = ''; $_ })
    Start-AdOperation -Module $Module -Name 'Sprawdzanie planu' -Targets @('AD') -Output None -Parameters @{ Items = @($Items); UniqueSam = [bool]$UniqueSam; SamMax = $SamMax } -ScriptBlock $script:AdPlanCheckScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) { Invoke-Deferred -Module $m -Action { param($m) Show-Error 'Nie udało się sprawdzić planu w Active Directory.' $m.Data.LastError }; $m.Data.LastError = (@($r.Errors)) -join "`r`n"; return }
        $items = @($r.Data | ForEach-Object { $h = @{}; foreach ($p in $_.PSObject.Properties) { $h[$p.Name] = $p.Value }; $h })
        Show-AdPlan -Module $m -Items $items
        Write-Log ("Plan: {0} pozycji." -f $items.Count)
    }
}

function Start-AdPlanExecute {
    # Wykonanie planu z potwierdzeniem; statusy wracają do tabeli
    param([hashtable]$Module, [string]$Title = 'Wykonać plan?')
    $plan = @($Module.Data['Plan'])
    $todo = @($plan | Where-Object { $_ -and @('Do utworzenia', 'Do dodania') -contains [string]$_.State })
    if ($todo.Count -eq 0) { Show-Message -Text 'Plan nie zawiera zmian do wykonania. Kliknij «Podgląd», aby go przygotować.' -Title 'Brak zmian'; return }
    $items = @($todo | ForEach-Object { '{0}: {1}' -f $_.Kind, $(if ($_.Kind -eq 'Członkostwo') { '{0} → {1}' -f (Get-RdnValue $_.Member), (Get-RdnValue $_.Group) } else { $_.Name }) })
    $ou = @($todo | Where-Object { $_.Kind -eq 'OU' }).Count
    $gr = @($todo | Where-Object { $_.Kind -eq 'Grupa' }).Count
    $mb = @($todo | Where-Object { $_.Kind -eq 'Członkostwo' }).Count
    $text = "$Title`r`nNowe OU: $ou, nowe grupy: $gr, członkostwa: $mb."
    if (-not (Confirm-Action -Text $text -Items $items -ConfirmText 'Wykonaj plan')) { return }
    Start-AdOperation -Module $Module -Name 'Wykonywanie planu' -Targets @('AD') -Output None -Parameters @{ Items = $plan } -ScriptBlock $script:AdPlanExecuteScript -OnResult {
        param($m, $r)
        if (-not $r.Ok) { Write-Log ('Plan przerwany: ' + ((@($r.Errors)) -join ' ')) 'ERROR'; return }
        $byKey = @{}
        foreach ($p in @($m.Data.Plan)) { $byKey[[string]$p.Key] = $p }
        foreach ($res in @($r.Data)) {
            $p = $byKey[[string]$res.Key]
            if ($p) { $p.State = $res.State; $p.Tone = $(if ($res.Ok) { 'ok' } else { 'crit' }); $p.Note = $(if ($res.Ok) { $res.Note } else { Get-FriendlyAdError $res.Note }) }
            foreach ($row in @(Find-ResultRow -Module $m -Column '__key' -Value ([string]$res.Key))) {
                Set-RowState -Module $m -Row $row -State $res.State -Tone $(if ($res.Ok) { 'ok' } else { 'crit' }) -Note $(if ($res.Ok) { $res.Note } else { Get-FriendlyAdError $res.Note })
            }
        }
    } -OnComplete { param($m) Update-AdPlanStats -Module $m }
}

function Get-DomainRootDn {
    # DN domeny (dla pola OU pozostawionego pustego)
    Import-AdModule
    $ad = Get-AdSplat
    return [string](Invoke-WithWaitCursor { (Get-ADDomain @ad).DistinguishedName })
}

function ConvertFrom-OuTreeText {
    <#
        Tekst ze strukturą OU -> pozycje planu. Obsługiwane formy wierszy:
          wcięcia (spacje/tabulatory, także znaki drzewa ├─ └─ │), ścieżki «Firma/Biuro/Komputery» albo «Firma\Biuro»,
          opcjonalny opis po znaku «|», komentarze od «#».
    #>
    param([string]$Text, [string]$BaseDn, [bool]$Protect, [string]$DescriptionTemplate = '')
    $items = New-Object System.Collections.ArrayList
    $known = @{}
    $stack = New-Object System.Collections.ArrayList
    $errors = @()
    $lineNo = 0
    foreach ($raw in ([string]$Text -split "\r?\n")) {
        $lineNo++
        $line = $raw.TrimEnd()
        if (-not $line.Trim() -or $line.Trim().StartsWith('#')) { continue }
        $desc = ''
        $bar = $line.IndexOf('|')
        if ($bar -ge 0) { $desc = $line.Substring($bar + 1).Trim(); $line = $line.Substring(0, $bar).TrimEnd() }
        $m = [regex]::Match($line, '^[\s│├└─\-\*•]*')
        $indent = ($m.Value -replace "`t", '    ').Length
        $body = $line.Substring($m.Length).Trim()
        if (-not $body) { continue }
        if ($body -match '[/\\]') {
            $path = @($body -split '[/\\]' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
        }
        else {
            while ($stack.Count -gt 0 -and $stack[$stack.Count - 1].Indent -ge $indent) { $stack.RemoveAt($stack.Count - 1) }
            $path = @($stack | ForEach-Object { $_.Name }) + @($body)
            [void]$stack.Add(@{ Indent = $indent; Name = $body })
        }
        $parent = $BaseDn
        for ($i = 0; $i -lt $path.Count; $i++) {
            $name = $path[$i]
            if ($name.Length -gt 64) { $errors += "Wiersz ${lineNo}: nazwa «$name» ma więcej niż 64 znaki" }
            $dn = 'OU={0},{1}' -f (ConvertTo-RdnValue $name), $parent
            $key = $dn.ToLowerInvariant()
            $isLast = ($i -eq $path.Count - 1)
            if (-not $known.ContainsKey($key)) {
                $d = if ($isLast -and $desc) { $desc } elseif ($DescriptionTemplate) { Expand-Template $DescriptionTemplate @{ nazwa = $name; sciezka = ($path[0..$i] -join '/'); ścieżka = ($path[0..$i] -join '/') } } else { '' }
                $item = @{ Key = 'ou:' + $key; Kind = 'OU'; Name = $name; Parent = $parent; Dn = $dn; Description = $d; Protect = $Protect; Level = $i; State = ''; Note = ''; Tone = ''; Source = "wiersz $lineNo" }
                [void]$items.Add($item)
                $known[$key] = $item
            }
            elseif ($isLast -and $desc) { $known[$key].Description = $desc }
            $parent = $dn
        }
    }
    return @{ Items = @($items); Errors = @($errors) }
}

Register-Module -Workspace 'AdGroups' -Category 'Struktura OU' -Key 'OuTree' -Title 'Drzewo OU' -Icon 'ED41' -Badge 'nowe' `
    -Description 'Całe drzewo jednostek organizacyjnych z wcięć lub ścieżek w tekście (np. Firma/Warszawa/Komputery), z opisami i ochroną przed usunięciem. Istniejącą strukturę można wczytać jako tekst, zmienić i utworzyć w innym miejscu.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Data.Plan = @()
    $row = Add-ToolbarRow -Module $m -Title 'Miejsce'
    $m.Base = Add-OuField -Parent $row -Module $m -Width 460 -Placeholder 'Korzeń domeny' -DialogTitle 'OU nadrzędna dla nowego drzewa' -AllowDomainRoot -Remember 'Base'
    $m.Input = Add-StretchTextBox -Module $m -Title 'Struktura' -Multiline -Height 190 -Placeholder "Firma`r`n    Warszawa | Oddział w Warszawie`r`n        Komputery`r`n        Użytkownicy`r`n    Kraków`r`nalbo ścieżki: Firma/Gdańsk/Komputery"
    $m.Input.Text = [string](Get-ModuleSetting -Module $m -Name 'Text' -Default '')
    $row2 = Add-ToolbarRow -Module $m -Title 'Opcje'
    $m.Protect = Add-CheckBox -Parent $row2 -Text 'Chroń przed przypadkowym usunięciem' -Checked $true
    Add-Label -Parent $row2 -Text 'Opis nowych OU' | Out-Null
    $m.DescTpl = Add-TextBox -Parent $row2 -Width 260 -Placeholder 'np. Oddział {nazwa} (pola: {nazwa}, {sciezka})'
    $m.Actions.Preview = {
        param($m)
        $base = $m.Base.Text.Trim()
        if (-not $base) { $base = Get-DomainRootDn }
        Set-ModuleSetting -Module $m -Name 'Text' -Value $m.Input.Text
        $parsed = ConvertFrom-OuTreeText -Text $m.Input.Text -BaseDn $base -Protect (Test-Checked $m.Protect) -DescriptionTemplate $m.DescTpl.Text.Trim()
        if (@($parsed.Errors).Count -gt 0) { Show-Warning ((@($parsed.Errors) | Select-Object -First 15) -join "`r`n"); return }
        if (@($parsed.Items).Count -eq 0) { Show-Warning 'Wpisz strukturę jednostek organizacyjnych (jedna w wierszu, wcięcia oznaczają zagnieżdżenie).'; return }
        Start-AdPlanCheck -Module $m -Items @($parsed.Items)
    }
    $row3 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row3 -Text 'Podgląd' -Icon 'E9D5' -Module $m -Primary -OnClick $m.Actions.Preview | Out-Null
    Add-Button -Parent $row3 -Text 'Utwórz OU' -Icon 'ED41' -Module $m -OnClick { param($m) Start-AdPlanExecute -Module $m -Title 'Utworzyć jednostki organizacyjne?' } | Out-Null
    Add-Button -Parent $row3 -Text 'Wczytaj istniejącą strukturę…' -Icon 'E8B7' -Module $m -ToolTip 'Wstawia do pola tekst z drzewem OU wybranej jednostki – do edycji i utworzenia w innym miejscu' -OnClick {
        param($m)
        $src = Select-OrganizationalUnit -Title 'Struktura do wczytania' -Selected $m.Base.Text.Trim()
        if (-not $src) { return }
        Start-AdOperation -Module $m -Name 'Wczytywanie struktury OU' -Targets @('AD') -Output None -Parameters @{ Source = $src } -ScriptBlock {
            $root = Get-ADOrganizationalUnit -Identity $P.Source -Properties Description @ad
            $all = @(Get-ADOrganizationalUnit -SearchBase $P.Source -SearchScope Subtree -LDAPFilter '(objectClass=organizationalUnit)' -Properties Description @ad)
            foreach ($o in $all) {
                $rel = ([string]$o.DistinguishedName).Substring(0, ([string]$o.DistinguishedName).Length - ([string]$root.DistinguishedName).Length).TrimEnd(',')
                $parts = @(if ($rel) { $rel -split '(?<!\\),' | ForEach-Object { Get-DnName $_ } })
                [array]::Reverse($parts)
                [pscustomobject]@{ Path = (@($root.Name) + $parts); Description = [string]$o.Description }
            }
        } -OnResult {
            param($m, $r)
            if (-not $r.Ok) { return }
            $lines = foreach ($o in (@($r.Data) | Sort-Object { ($_.Path -join [string][char]1) })) {
                $path = @($o.Path)
                ('    ' * ($path.Count - 1)) + $path[$path.Count - 1] + $(if ($o.Description) { ' | ' + $o.Description } else { '' })
            }
            $m.Input.Text = (@($lines) -join "`r`n")
            Show-Toast ("Wczytano {0} jednostek – zmień nazwy i miejsce, potem «Podgląd»." -f @($r.Data).Count) 'ok' 6
        }
    } | Out-Null
    Add-PlanTiles -Module $m -NoGroups
    $m.EmptyHint = 'Wpisz strukturę (wcięcia albo ścieżki) i kliknij «Podgląd» (F5). Istniejące jednostki zostaną użyte, brakujące – utworzone po kliknięciu «Utwórz OU».'
}

$script:OuClonePlanScript = {
    # Plan klonowania jednostki $P.Source: OU, grupy, zagnieżdżenia i członkostwa z zamianą tekstu w nazwach
    $src = Get-ADOrganizationalUnit -Identity $P.Source -Properties Description, gPLink, gPOptions, ProtectedFromAccidentalDeletion @ad
    $srcDn = [string]$src.DistinguishedName
    $destParent = if ($P.Dest) { [string]$P.Dest } else { [string](Get-ADDomain @ad).DistinguishedName }
    if ($destParent -ieq $srcDn -or $destParent.EndsWith(",$srcDn", [StringComparison]::OrdinalIgnoreCase)) { throw 'Nie można klonować jednostki do jej własnego wnętrza.' }
    $pairs = @($P.Replace)
    $conv = {
        param([string]$Text)
        $t = $Text
        foreach ($pr in $pairs) { if ($pr[0]) { $t = [regex]::Replace($t, [regex]::Escape([string]$pr[0]), ([string]$pr[1]).Replace('$', '$$'), 'IgnoreCase') } }
        return $t
    }
    $rootName = if ($P.NewName) { [string]$P.NewName } else { & $conv $src.Name }
    $newRoot = 'OU={0},{1}' -f (ConvertTo-RdnValue $rootName), $destParent
    if ($newRoot -ieq $srcDn) { throw 'Kopia miałaby tę samą nazwę i miejsce co źródło – podaj nową nazwę, inne miejsce albo zamianę tekstu.' }
    $depth0 = @($srcDn -split '(?<!\\),').Count
    $map = @{}
    $items = New-Object System.Collections.ArrayList
    $ous = @(Get-ADOrganizationalUnit -SearchBase $srcDn -SearchScope Subtree -LDAPFilter '(objectClass=organizationalUnit)' -Properties Description, gPLink, gPOptions, ProtectedFromAccidentalDeletion @ad |
            Sort-Object { @(([string]$_.DistinguishedName) -split '(?<!\\),').Count })
    foreach ($o in $ous) {
        $dn = [string]$o.DistinguishedName
        $isRoot = ($dn -ieq $srcDn)
        $parentNew = if ($isRoot) { $destParent } else { $map[(Get-DnParent $dn).ToLowerInvariant()] }
        $name = if ($isRoot) { $rootName } else { & $conv $o.Name }
        $newDn = 'OU={0},{1}' -f (ConvertTo-RdnValue $name), $parentNew
        $map[$dn.ToLowerInvariant()] = $newDn
        [void]$items.Add(@{
                Key = "ou:$newDn"; Kind = 'OU'; Name = $name; Parent = $parentNew; Dn = $newDn; Level = (@($dn -split '(?<!\\),').Count - $depth0)
                Description = $(if ($P.CopyDescription) { & $conv ([string]$o.Description) } else { '' })
                Protect = $(if ($P.CopyProtect) { [bool]$o.ProtectedFromAccidentalDeletion } else { $false })
                GpLink = $(if ($P.CopyGpo) { [string]$o.gPLink } else { '' }); GpOptions = $(if ($P.CopyGpo) { $o.gPOptions } else { $null })
                Source = $o.Name; State = ''; Note = $(if ($P.CopyGpo -and $o.gPLink) { 'z linkami GPO' } else { '' }); Tone = ''
            })
    }
    if ($P.CopyGroups) {
        $groups = @(Get-ADGroup -SearchBase $srcDn -SearchScope Subtree -LDAPFilter '(objectClass=group)' -Properties Description, member, memberOf, info @ad)
        $gmap = @{}
        foreach ($g in $groups) {
            $name = & $conv $g.Name
            $sam = ConvertTo-SamName (& $conv $g.SamAccountName)
            $parentNew = $map[(Get-DnParent ([string]$g.DistinguishedName)).ToLowerInvariant()]
            $newDn = 'CN={0},{1}' -f (ConvertTo-RdnValue $name), $parentNew
            $gmap[([string]$g.DistinguishedName).ToLowerInvariant()] = $newDn
            [void]$items.Add(@{
                    Key = "grp:$newDn"; Kind = 'Grupa'; Name = $name; Sam = $sam; Parent = $parentNew; Dn = $newDn; Scope = [string]$g.GroupScope; Category = [string]$g.GroupCategory
                    Description = $(if ($P.CopyDescription) { & $conv ([string]$g.Description) } else { '' }); Info = $(if ($P.CopyDescription) { [string]$g.info } else { '' })
                    Protect = $false; Source = $g.Name; State = ''; Note = $(if ($sam -ieq $g.SamAccountName) { 'sAMAccountName bez zmian – dodaj zamianę tekstu, np. WAW=KRK' } else { '' }); Tone = ''
                })
        }
        foreach ($g in $groups) {
            $newG = $gmap[([string]$g.DistinguishedName).ToLowerInvariant()]
            foreach ($mem in @($g.member)) {
                $k = ([string]$mem).ToLowerInvariant()
                if ($gmap.ContainsKey($k)) {
                    if ($P.CopyNesting) { [void]$items.Add(@{ Key = "mem:$newG|$($gmap[$k])"; Kind = 'Członkostwo'; Group = $newG; Member = $gmap[$k]; Source = 'zagnieżdżenie'; State = ''; Note = ''; Tone = '' }) }
                }
                elseif ($P.CopyMembers -and $mem) { [void]$items.Add(@{ Key = "mem:$newG|$k"; Kind = 'Członkostwo'; Group = $newG; Member = [string]$mem; Source = 'członek spoza OU'; State = ''; Note = ''; Tone = '' }) }
            }
            if ($P.CopyMemberOf) {
                foreach ($parent in @($g.memberOf)) {
                    if ($parent -and -not $gmap.ContainsKey(([string]$parent).ToLowerInvariant())) { [void]$items.Add(@{ Key = "mem:$parent|$newG"; Kind = 'Członkostwo'; Group = [string]$parent; Member = $newG; Source = 'grupa nadrzędna spoza OU'; State = ''; Note = ''; Tone = '' }) }
                }
            }
        }
    }
    $checked = Test-AdPlanItems -Items @($items)
    foreach ($it in $checked) { [pscustomobject]$it }
}

function ConvertFrom-ReplacePairs {
    # "WAW=KRK; Warszawa=Kraków" -> @(@('WAW','KRK'), @('Warszawa','Kraków'))
    param([string]$Text)
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($part in ([string]$Text -split ';')) {
        $p = $part.Trim()
        if (-not $p) { continue }
        $i = $p.IndexOf('=')
        if ($i -lt 1) { throw "Niepoprawna zamiana «$p» – użyj formy STARY=NOWY." }
        $list.Add([object[]]@($p.Substring(0, $i).Trim(), $p.Substring($i + 1).Trim()))
    }
    return , $list.ToArray()
}

Register-Module -Workspace 'AdGroups' -Category 'Struktura OU' -Key 'OuClone' -Title 'Klonowanie OU' -Icon 'E8C8' -Badge 'nowe' `
    -Description 'Kopia całej jednostki organizacyjnej w nowe miejsce: podjednostki, grupy (z zamianą tekstu w nazwach, np. WAW=KRK), zagnieżdżenia między nimi, opcjonalnie członkowie i grupy nadrzędne, linki zasad grupy (GPO), opisy i ochrona. Konta użytkowników i komputerów nie są kopiowane.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Data.Plan = @()
    $row = Add-ToolbarRow -Module $m -Title 'Źródło'
    $m.Source = Add-OuField -Parent $row -Module $m -Width 460 -Placeholder 'Jednostka do skopiowania' -DialogTitle 'Jednostka źródłowa' -Remember 'Source'
    $row2 = Add-ToolbarRow -Module $m -Title 'Cel'
    $m.Dest = Add-OuField -Parent $row2 -Module $m -Width 360 -Placeholder 'Korzeń domeny' -DialogTitle 'Gdzie utworzyć kopię' -AllowDomainRoot -Remember 'Dest'
    Add-Label -Parent $row2 -Text 'Nowa nazwa' | Out-Null
    $m.NewName = Add-TextBox -Parent $row2 -Width 200 -Placeholder 'z zamiany tekstu'
    $row3 = Add-ToolbarRow -Module $m -Title 'Zamiana tekstu'
    $m.Replace = Add-TextBox -Parent $row3 -Width 360 -Placeholder 'np. WAW=KRK; Warszawa=Kraków'
    Add-Label -Parent $row3 -Text 'Dotyczy nazw OU i grup, sAMAccountName oraz opisów (bez rozróżniania wielkości liter).' -Hint | Out-Null
    $row4 = Add-ToolbarRow -Module $m -Title 'Kopiuj'
    $m.CopyGroups = Add-CheckBox -Parent $row4 -Text 'Grupy' -Checked $true
    $m.CopyNesting = Add-CheckBox -Parent $row4 -Text 'Zagnieżdżenia między grupami' -Checked $true
    $m.CopyMembers = Add-CheckBox -Parent $row4 -Text 'Członków spoza OU' -ToolTip 'Konta i grupy spoza klonowanej jednostki, które należą do grup źródłowych, zostaną dodane także do kopii'
    $m.CopyMemberOf = Add-CheckBox -Parent $row4 -Text 'Przynależność do grup spoza OU'
    $m.CopyGpo = Add-CheckBox -Parent $row4 -Text 'Linki GPO' -Checked $true
    $m.CopyDesc = Add-CheckBox -Parent $row4 -Text 'Opisy' -Checked $true
    $m.CopyProtect = Add-CheckBox -Parent $row4 -Text 'Ochronę przed usunięciem' -Checked $true
    $m.Actions.Preview = {
        param($m)
        $src = $m.Source.Text.Trim()
        if (-not $src) { Show-Warning 'Wybierz jednostkę źródłową.'; return }
        $pairs = ConvertFrom-ReplacePairs $m.Replace.Text
        if (-not $m.NewName.Text.Trim() -and @($pairs).Count -eq 0 -and -not $m.Dest.Text.Trim()) { Show-Warning 'Podaj nową nazwę, miejsce docelowe albo zamianę tekstu – kopia musi różnić się od źródła.'; return }
        $params = @{
            Source = $src; Dest = $m.Dest.Text.Trim(); NewName = $m.NewName.Text.Trim(); Replace = $pairs
            CopyGroups = (Test-Checked $m.CopyGroups); CopyNesting = (Test-Checked $m.CopyNesting); CopyMembers = (Test-Checked $m.CopyMembers); CopyMemberOf = (Test-Checked $m.CopyMemberOf)
            CopyGpo = (Test-Checked $m.CopyGpo); CopyDescription = (Test-Checked $m.CopyDesc); CopyProtect = (Test-Checked $m.CopyProtect)
        }
        Show-AdPlan -Module $m -Items @()
        Start-AdOperation -Module $m -Name 'Plan klonowania' -Targets @('AD') -Output None -Parameters $params -ScriptBlock $script:OuClonePlanScript -OnResult {
            param($m, $r)
            if (-not $r.Ok) { $m.Data.LastError = (@($r.Errors)) -join "`r`n"; Invoke-Deferred -Module $m -Action { param($m) Show-Error 'Nie udało się przygotować planu klonowania.' $m.Data.LastError }; return }
            $items = @($r.Data | ForEach-Object { $h = @{}; foreach ($p in $_.PSObject.Properties) { $h[$p.Name] = $p.Value }; $h })
            Show-AdPlan -Module $m -Items $items
        }
    }
    $row5 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row5 -Text 'Podgląd' -Icon 'E9D5' -Module $m -Primary -OnClick $m.Actions.Preview | Out-Null
    Add-Button -Parent $row5 -Text 'Klonuj' -Icon 'E8C8' -Module $m -OnClick { param($m) Start-AdPlanExecute -Module $m -Title 'Utworzyć kopię jednostki?' } | Out-Null
    Add-PlanTiles -Module $m
    $m.EmptyHint = 'Wybierz jednostkę źródłową, miejsce i zamianę tekstu, a potem «Podgląd» (F5). Pozycje z konfliktem (np. zajęty sAMAccountName) zostaną pominięte.'
}

function Read-NameCodeLines {
    # Wiersze «Nazwa;KOD» (lub tabulator); brak kodu = pierwsze trzy litery nazwy bez polskich znaków
    param([string]$Text, [string]$What)
    $list = New-Object System.Collections.Generic.List[object]
    $codes = @{}
    foreach ($line in (Get-TextLines $Text)) {
        $parts = @($line -split '[;\t]' | ForEach-Object { $_.Trim() })
        $name = $parts[0]
        if (-not $name) { continue }
        $code = if ($parts.Count -gt 1 -and $parts[1]) { $parts[1] } else { ((ConvertTo-AsciiText $name) -replace '[^A-Za-z0-9]', '') }
        if ($code.Length -gt 3 -and -not ($parts.Count -gt 1 -and $parts[1])) { $code = $code.Substring(0, 3) }
        $code = $code.ToUpperInvariant()
        if ($codes.ContainsKey($code)) { throw "$What`: skrót «$code» powtarza się ($($codes[$code]) i $name) – podaj skróty po średniku, np. $name;KOD." }
        $codes[$code] = $name
        $list.Add(@{ Name = $name; Code = $code })
    }
    # Bez przecinka: wywołujący zbiera wynik w @(...)
    return $list.ToArray()
}

function New-LocationPlan {
    # Plan modułu «Lokalizacje i role»: OU lokalizacji, grupy ról, grupy zbiorcze ALL i członkostwa
    param([hashtable]$Module)
    $m = $Module
    $base = $m.Base.Text.Trim()
    if (-not $base) { throw 'Wybierz jednostkę bazową (OU, w której powstaną lokalizacje).' }
    $cities = @(Read-NameCodeLines -Text $m.Cities.Text -What 'Lokalizacje')
    $roles = @(Read-NameCodeLines -Text $m.Roles.Text -What 'Role')
    if ($cities.Count -eq 0 -or $roles.Count -eq 0) { throw 'Podaj co najmniej jedną lokalizację i jedną rolę.' }
    $prefix = $m.Prefix.Text.Trim()
    $sep = [string]$m.Sep.SelectedItem
    $nameTpl = if ($m.NameTpl.Text.Trim()) { $m.NameTpl.Text.Trim() } else { '{PREFIKS}{SEP}{KOD_LOK}{SEP}{KOD_ROLI}' }
    $descTpl = $m.DescTpl.Text.Trim()
    $scope = ConvertTo-GroupScope ([string]$m.Scope.SelectedItem)
    $cat = ConvertTo-GroupCategory ([string]$m.Category.SelectedItem)
    $samMax = if (Test-Checked $m.Sam20) { 20 } else { 0 }
    $subOu = $m.SubOu.Text.Trim()
    $items = New-Object System.Collections.ArrayList
    $vals = {
        param($City, $CityCode, $Role, $RoleCode)
        @{ PREFIKS = $prefix; PREFIX = $prefix; SEP = $sep; LOKALIZACJA = $City; CITY_FULL = $City; KOD_LOK = $CityCode; CITY_CODE = $CityCode; ROLA = $Role; ROLE = $Role; KOD_ROLI = $RoleCode; ROLE_CODE = $RoleCode }
    }
    $newGroup = {
        param([hashtable]$V, [string]$Path, [string]$Source)
        $name = Expand-Template $nameTpl $V
        $dn = 'CN={0},{1}' -f (ConvertTo-RdnValue $name), $Path
        $g = @{ Key = "grp:$dn"; Kind = 'Grupa'; Name = $name; Sam = (ConvertTo-SamName $name -MaxLength $samMax); Parent = $Path; Dn = $dn; Scope = $scope; Category = $cat
            Description = $(if ($descTpl) { Expand-Template $descTpl $V } else { '' }); Protect = $false; Source = $Source; State = ''; Note = ''; Tone = '' }
        [void]$items.Add($g)
        return $g
    }
    $member = { param($Group, $Member) [void]$items.Add(@{ Key = "mem:$($Group.Dn)|$($Member.Dn)"; Kind = 'Członkostwo'; Group = $Group.Dn; Member = $Member.Dn; Source = 'grupa zbiorcza'; State = ''; Note = ''; Tone = '' }) }
    $roleGroups = @{}
    $globalMembers = New-Object System.Collections.ArrayList
    foreach ($c in $cities) {
        $cityDn = 'OU={0},{1}' -f (ConvertTo-RdnValue $c.Name), $base
        [void]$items.Add(@{ Key = "ou:$cityDn"; Kind = 'OU'; Name = $c.Name; Parent = $base; Dn = $cityDn; Description = ''; Protect = (Test-Checked $m.Protect); Level = 0; Source = 'lokalizacja'; State = ''; Note = ''; Tone = '' })
        $path = $cityDn
        if ($subOu) {
            $path = 'OU={0},{1}' -f (ConvertTo-RdnValue $subOu), $cityDn
            [void]$items.Add(@{ Key = "ou:$path"; Kind = 'OU'; Name = $subOu; Parent = $cityDn; Dn = $path; Description = ''; Protect = (Test-Checked $m.Protect); Level = 1; Source = 'OU na grupy'; State = ''; Note = ''; Tone = '' })
        }
        $cityGroups = @()
        foreach ($r in $roles) {
            $g = & $newGroup (& $vals $c.Name $c.Code $r.Name $r.Code) $path "$($c.Name) / $($r.Name)"
            $cityGroups += $g
            if (-not $roleGroups.ContainsKey($r.Code)) { $roleGroups[$r.Code] = @{ Role = $r; Groups = New-Object System.Collections.ArrayList } }
            [void]$roleGroups[$r.Code].Groups.Add($g)
        }
        if (Test-Checked $m.CityAll) {
            $all = & $newGroup (& $vals $c.Name $c.Code 'ALL' 'ALL') $path "$($c.Name) / wszystkie role"
            foreach ($g in $cityGroups) { & $member $all $g }
            [void]$globalMembers.Add($all)
        }
        else { foreach ($g in $cityGroups) { [void]$globalMembers.Add($g) } }
    }
    if (Test-Checked $m.RoleAll) {
        foreach ($code in @($roleGroups.Keys | Sort-Object)) {
            $entry = $roleGroups[$code]
            $all = & $newGroup (& $vals 'WSZYSTKIE' 'ALL' $entry.Role.Name $code) $base "wszystkie lokalizacje / $($entry.Role.Name)"
            foreach ($g in $entry.Groups) { & $member $all $g }
        }
    }
    if (Test-Checked $m.GlobalAll) {
        $all = & $newGroup (& $vals 'WSZYSTKIE' 'ALL' 'ALL' 'ALL') $base 'grupa globalna'
        foreach ($g in $globalMembers) { & $member $all $g }
    }
    return @($items)
}

Register-Module -Workspace 'AdGroups' -Category 'Tworzenie' -Key 'LocationGroups' -Title 'Lokalizacje i role' -Icon 'E707' -Badge 'nowe' `
    -Description 'Jednostki dla lokalizacji (np. miast) i w każdej te same grupy ról według szablonu nazwy, z grupami zbiorczymi ALL: dla lokalizacji, dla roli i globalną. Unikalne sAMAccountName (opcjonalnie najwyżej 20 znaków), podgląd przed utworzeniem.' -Build {
    param($m)
    $m.PillColumns = @('Stan')
    $m.Data.Plan = @()
    $row = Add-ToolbarRow -Module $m -Title 'Miejsce'
    $m.Base = Add-OuField -Parent $row -Module $m -Width 360 -Placeholder 'OU, w której powstaną lokalizacje' -DialogTitle 'Jednostka bazowa' -Remember 'Base'
    Add-Label -Parent $row -Text 'OU na grupy' | Out-Null
    $m.SubOu = Add-TextBox -Parent $row -Width 150 -Placeholder 'opcjonalnie, np. Grupy'
    $m.SubOu.ToolTip = 'Gdy wypełnione: grupy ról trafią do tej podjednostki w każdej lokalizacji (zamiast bezpośrednio do OU lokalizacji)'
    $boxes = Add-TextColumns -Module $m -Title 'Dane' -Height 110 -Columns @(
        @{ Caption = 'Lokalizacje (OU) – nazwa;skrót'; Placeholder = "Warszawa;WAW`nKraków;KRK`nGdańsk"; Text = [string](Get-ModuleSetting -Module $m -Name 'Cities' -Default '') }
        @{ Caption = 'Role (grupy) – nazwa;skrót'; Placeholder = "Rejestracja;REJ`nDiagnostyka;DIA`nInne"; Text = [string](Get-ModuleSetting -Module $m -Name 'Roles' -Default '') }
    )
    $m.Cities = $boxes[0]
    $m.Roles = $boxes[1]
    $row2 = Add-ToolbarRow -Module $m -Title 'Nazwy grup'
    Add-Label -Parent $row2 -Text 'Prefiks' | Out-Null
    $m.Prefix = Add-TextBox -Parent $row2 -Width 110 -Text ([string](Get-ModuleSetting -Module $m -Name 'Prefix' -Default 'GG-COMP'))
    Add-Label -Parent $row2 -Text 'Separator' | Out-Null
    $m.Sep = Add-ComboBox -Parent $row2 -Items @('-', '_', '.') -Width 60
    Add-Label -Parent $row2 -Text 'Szablon' | Out-Null
    $m.NameTpl = Add-TextBox -Parent $row2 -Width 300 -Text ([string](Get-ModuleSetting -Module $m -Name 'NameTpl' -Default '{PREFIKS}{SEP}{KOD_LOK}{SEP}{KOD_ROLI}'))
    $m.NameTpl.ToolTip = 'Pola: {PREFIKS}, {SEP}, {LOKALIZACJA}, {KOD_LOK}, {ROLA}, {KOD_ROLI} (działają też dawne {PREFIX}, {CITY_FULL}, {CITY_CODE}, {ROLE}, {ROLE_CODE})'
    $row3 = Add-ToolbarRow -Module $m -Title 'Opis i typ'
    $m.DescTpl = Add-TextBox -Parent $row3 -Width 300 -Text ([string](Get-ModuleSetting -Module $m -Name 'DescTpl' -Default 'Grupa komputerów: {ROLA} ({LOKALIZACJA})'))
    Add-Label -Parent $row3 -Text 'Zakres' | Out-Null
    $m.Scope = Add-ComboBox -Parent $row3 -Items @('Globalna', 'Lokalna domeny', 'Uniwersalna') -Width 135
    Add-Label -Parent $row3 -Text 'Typ' | Out-Null
    $m.Category = Add-ComboBox -Parent $row3 -Items @('Zabezpieczeń', 'Dystrybucyjna') -Width 130
    $row4 = Add-ToolbarRow -Module $m -Title 'Opcje'
    $m.CityAll = Add-CheckBox -Parent $row4 -Text 'Grupa ALL lokalizacji' -Checked $true -ToolTip 'W każdej lokalizacji grupa zawierająca wszystkie jej grupy ról'
    $m.RoleAll = Add-CheckBox -Parent $row4 -Text 'Grupa ALL roli' -Checked $true -ToolTip 'W jednostce bazowej grupa roli zawierająca tę rolę ze wszystkich lokalizacji'
    $m.GlobalAll = Add-CheckBox -Parent $row4 -Text 'Grupa ALL globalna' -Checked $true
    $m.Protect = Add-CheckBox -Parent $row4 -Text 'Chroń OU przed usunięciem' -Checked $true
    $m.Sam20 = Add-CheckBox -Parent $row4 -Text 'sAMAccountName maks. 20 znaków' -Checked $true -ToolTip 'Zgodność z nazwami sprzed Windows 2000; zajęte nazwy dostaną sufiks -1, -2…'
    $m.Actions.Preview = {
        param($m)
        foreach ($pair in @(@('Cities', $m.Cities), @('Roles', $m.Roles), @('Prefix', $m.Prefix), @('NameTpl', $m.NameTpl), @('DescTpl', $m.DescTpl))) { Set-ModuleSetting -Module $m -Name $pair[0] -Value $pair[1].Text }
        $items = New-LocationPlan -Module $m
        Start-AdPlanCheck -Module $m -Items $items -UniqueSam -SamMax $(if (Test-Checked $m.Sam20) { 20 } else { 0 })
    }
    $row5 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row5 -Text 'Podgląd' -Icon 'E9D5' -Module $m -Primary -OnClick $m.Actions.Preview | Out-Null
    Add-Button -Parent $row5 -Text 'Utwórz' -Icon 'E710' -Module $m -OnClick { param($m) Start-AdPlanExecute -Module $m -Title 'Utworzyć jednostki, grupy i członkostwa?' } | Out-Null
    Add-PlanTiles -Module $m
    $m.EmptyHint = 'Wpisz lokalizacje i role (nazwa;skrót), ustaw szablon nazw i kliknij «Podgląd» (F5). Istniejące OU i grupy zostaną użyte, a nie utworzone ponownie.'
}
#endregion

#region Grupy AD: drzewo zagnieżdżeń i raporty
$script:GroupTreeScript = {
    # Drzewo zagnieżdżeń: w dół (zawartość grup) albo w górę (przynależność); korzenie: $P.Roots albo grupy najwyższego poziomu
    $roots = @($P.Roots)
    if ($roots.Count -eq 0) {
        $q = @{ LDAPFilter = '(&(objectCategory=group)(!(memberOf=*)))' }
        if ($P.SearchBase) { $q.SearchBase = $P.SearchBase }
        $roots = @(Get-ADGroup @q @ad | Sort-Object Name | ForEach-Object { [string]$_.DistinguishedName })
    }
    $info = @{}
    $getInfo = {
        param([string]$Dn)
        $k = $Dn.ToLowerInvariant()
        if (-not $info.ContainsKey($k)) {
            $o = $null
            try { $o = Get-ADObject -Identity $Dn -Properties member, memberOf, description, sAMAccountName, groupType, userAccountControl @ad } catch { }
            $info[$k] = $o
        }
        return $info[$k]
    }
    $children = {
        param([string]$Dn)
        $v = ConvertTo-LdapValue $Dn
        if ($P.Up) {
            $o = & $getInfo $Dn
            return @(@($o.memberOf) | Where-Object { $_ } | ForEach-Object { & $getInfo ([string]$_) } | Where-Object { $_ } | Sort-Object { [string]$_.Name })
        }
        $filter = if ($P.ShowMembers) { "(memberOf=$v)" } else { "(&(memberOf=$v)(objectClass=group))" }
        $list = @(Get-ADObject -LDAPFilter $filter -Properties description, sAMAccountName, groupType, userAccountControl @ad)
        # Najpierw grupy, potem pozostali członkowie - alfabetycznie
        return @($list | Sort-Object @{ Expression = { if ([string]$_.ObjectClass -eq 'group') { 0 } else { 1 } } }, @{ Expression = { [string]$_.Name } })
    }
    $scopeOf = {
        param($o)
        if ([string]$o.ObjectClass -ne 'group') { return '' }
        $gt = [int64]$o.groupType
        if ($gt -lt 0) { $gt += 4294967296 }
        if ($gt -band 2) { 'Globalna' } elseif ($gt -band 4) { 'Lokalna domeny' } elseif ($gt -band 8) { 'Uniwersalna' } else { '' }
    }
    $emit = {
        param($o, [int]$Level, [string]$Prefix, [string]$RootName, [string]$PathText, [string]$Note)
        $class = [string]$o.ObjectClass
        $isGroup = ($class -eq 'group')
        [pscustomobject][ordered]@{
            'Drzewo'       = $Prefix + [string]$o.Name
            'Typ'          = Get-ObjectKind $class
            'Poziom'       = $Level
            'Zakres'       = (& $scopeOf $o)
            'Członków'     = $(if ($isGroup) { @((& $getInfo ([string]$o.DistinguishedName)).member).Count } else { $null })
            'Opis'         = $(if ($P.ShowDescription) { [string]$o.description } else { '' })
            'Uwagi'        = $Note
            'Grupa główna' = $RootName
            'Ścieżka'      = $PathText
            'Login'        = ([string]$o.sAMAccountName) -replace '\$$', ''
            'DN'           = [string]$o.DistinguishedName
            '__tone'       = $(if ($Note) { 'crit' } elseif ($isGroup) { 'info' } else { '' })
            '__flag'       = $(if (-not $isGroup -and ([int64]$o.userAccountControl -band 2)) { 'muted' } else { '' })
        }
    }
    $walk = $null
    $walk = {
        param($o, [int]$Level, [string]$Indent, [string]$RootName, [string[]]$Path, [hashtable]$OnPath)
        $kids = @(& $children ([string]$o.DistinguishedName))
        for ($i = 0; $i -lt $kids.Count; $i++) {
            $k = $kids[$i]
            $last = ($i -eq $kids.Count - 1)
            $prefix = $Indent + $(if ($last) { '└─ ' } else { '├─ ' })
            $nextIndent = $Indent + $(if ($last) { '    ' } else { '│   ' })
            $dnKey = ([string]$k.DistinguishedName).ToLowerInvariant()
            $pathText = ((@($Path) + @([string]$k.Name)) -join ' › ')
            if ($OnPath.ContainsKey($dnKey)) { & $emit $k ($Level + 1) $prefix $RootName $pathText 'Zapętlenie – grupa zawiera samą siebie (pośrednio)'; continue }
            if ($Level + 1 -ge $P.MaxDepth) { & $emit $k ($Level + 1) $prefix $RootName $pathText 'Osiągnięto maksymalną głębokość'; continue }
            & $emit $k ($Level + 1) $prefix $RootName $pathText ''
            if ([string]$k.ObjectClass -eq 'group') {
                $OnPath[$dnKey] = $true
                & $walk $k ($Level + 1) $nextIndent $RootName (@($Path) + @([string]$k.Name)) $OnPath
                [void]$OnPath.Remove($dnKey)
            }
        }
    }
    foreach ($r in $roots) {
        $o = & $getInfo ([string]$r)
        if (-not $o) { try { $o = Get-ADGroup -Identity $r -Properties member, memberOf, description @ad; $o = & $getInfo ([string]$o.DistinguishedName) } catch { Write-Error "Nie znaleziono grupy $r"; continue } }
        & $emit $o 0 '' ([string]$o.Name) ([string]$o.Name) ''
        & $walk $o 0 '' ([string]$o.Name) @([string]$o.Name) @{ ([string]$o.DistinguishedName).ToLowerInvariant() = $true }
    }
}

function Export-GroupTreeHtml {
    # Zapis raportu HTML drzewa do pliku wybranego przez użytkownika
    param([hashtable]$Module)
    $rows = @(Get-ResultRowsAll -Module $Module | Where-Object { $Module.Table.Columns.Contains('Poziom') -and $_['Poziom'] -isnot [System.DBNull] })
    if ($rows.Count -eq 0) { Show-Warning 'Najpierw zbuduj drzewo.'; return }
    $dlg = New-Object Microsoft.Win32.SaveFileDialog
    $dlg.Filter = 'Raport HTML (*.html)|*.html'
    $dlg.FileName = 'Drzewo_grup_{0:yyyyMMdd_HHmm}.html' -f (Get-Date)
    $answer = if ($script:UI.Window) { $dlg.ShowDialog($script:UI.Window) } else { $dlg.ShowDialog() }
    if ($answer -ne $true) { return }
    [System.IO.File]::WriteAllText($dlg.FileName, (ConvertTo-GroupTreeHtml -Rows $rows), (New-Object System.Text.UTF8Encoding($true)))
    Write-Log "Zapisano raport drzewa grup: $($dlg.FileName)" 'OK' -Module $Module.Title
    Show-Toast "Zapisano raport: $([System.IO.Path]::GetFileName($dlg.FileName))" 'ok'
    try { Start-Process -FilePath $dlg.FileName } catch { }
}

function ConvertTo-GroupTreeHtml {
    # Raport HTML drzewa (rozwijane gałęzie, wyszukiwanie, kopiowanie i otwieranie gałęzi w osobnym oknie)
    # z wierszy tabeli w kolejności drzewa; wspólne style i skrypt raportów - 32-htmlreport.ps1
    param([object[]]$Rows)
    $treeRows = @($Rows)
    $enc = { param($t) ConvertTo-HtmlText $t }
    $acts = '<span class="acts"><button data-act="copy-node" title="Kopiuj gałąź (wcięty tekst)">⧉</button><button data-act="open-node" title="Otwórz gałąź w osobnym oknie">↗</button></span>'
    $leafActs = '<span class="acts"><button data-act="copy-node" title="Kopiuj">⧉</button></span>'
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append((Get-ReportHead -Title 'Drzewo zagnieżdżeń grup' -Meta ('Domain Ops {0} • {1:yyyy-MM-dd HH:mm} • {2} • wierszy: {3}' -f $script:AppVersion, (Get-Date), $env:USERNAME, $treeRows.Count)))
    $roots = @($treeRows | Where-Object { [int]$_['Poziom'] -eq 0 }).Count
    [void]$sb.Append((Get-ReportBar -Mode 'tree' -Placeholder 'Szukaj grupy lub konta…' -Buttons @('expand', 'collapse', 'print') -Count $roots))
    [void]$sb.Append('<div class="tree">')
    $open = 0
    for ($i = 0; $i -lt $treeRows.Count; $i++) {
        $r = $treeRows[$i]
        $level = [int]$r['Poziom']
        $nextLevel = if ($i + 1 -lt $treeRows.Count) { [int]$treeRows[$i + 1]['Poziom'] } else { 0 }
        while ($open -gt $level) { [void]$sb.Append('</details>'); $open-- }
        $name = (& $enc ([string]$r['Drzewo'] -replace '^[\s│├└─]+', ''))
        $extra = ''
        if ([string]$r['Typ'] -ne 'Grupa') { $extra += '<span class="k">' + (& $enc $r['Typ']) + '</span>' }
        elseif ([string]$r['Zakres']) { $extra += '<span class="k">' + (& $enc $r['Zakres']) + ' • ' + (& $enc $r['Członków']) + '</span>' }
        if ([string]$r['Opis']) { $extra += '<span class="d">' + (& $enc $r['Opis']) + '</span>' }
        if ([string]$r['Uwagi']) { $extra += '<span class="w">⚠ ' + (& $enc $r['Uwagi']) + '</span>' }
        if ($nextLevel -gt $level) {
            $cls = if ($level -eq 0) { ' class="root"' } else { '' }
            [void]$sb.Append("<details$cls><summary>").Append($name).Append($extra).Append($acts).Append('</summary>')
            $open = $level + 1
        }
        else {
            if ($level -eq 0) { [void]$sb.Append('<details class="root"><summary>').Append($name).Append($extra).Append(' <span class="m">(bez zagnieżdżeń)</span>').Append($acts).Append('</summary></details>') }
            else { [void]$sb.Append('<div class="leaf">').Append($name).Append($extra).Append($leafActs).Append('</div>') }
        }
    }
    while ($open -gt 0) { [void]$sb.Append('</details>'); $open-- }
    [void]$sb.Append('</div>')
    [void]$sb.Append((Get-ReportTail))
    return $sb.ToString()
}

Register-Module -Workspace 'AdGroups' -Category 'Raporty' -Key 'GroupNesting' -Title 'Drzewo zagnieżdżeń' -Icon 'E8EC' -Badge 'nowe' `
    -Description 'Drzewo grup zawartych w zaznaczonych grupach (w dół) albo grup, do których należą (w górę), z wykrywaniem zapętleń. Bez zaznaczenia – wszystkie grupy najwyższego poziomu. Raport HTML z rozwijanymi gałęziami i wyszukiwaniem.' -Build {
    param($m)
    $m.PillColumns = @('Typ')
    $row = Add-ToolbarRow -Module $m -Title 'Kierunek'
    $m.Direction = Add-Segmented -Parent $row -Items @('Zawartość grup (w dół)', 'Przynależność (w górę)')
    $m.ShowMembers = Add-CheckBox -Parent $row -Text 'Także użytkownicy i komputery' -ToolTip 'Tylko dla kierunku «w dół» – wolniejsze przy dużych grupach'
    $m.ShowDesc = Add-CheckBox -Parent $row -Text 'Opisy' -Checked $true
    Add-Label -Parent $row -Text 'Maks. głębokość' | Out-Null
    $m.Depth = Add-Numeric -Parent $row -Value 15 -Minimum 1 -Maximum 50 -Width 60
    $row2 = Add-ToolbarRow -Module $m -Title 'Bez zaznaczenia'
    $m.Ou = Add-OuField -Parent $row2 -Module $m -Width 380 -Placeholder 'Cała domena' -DialogTitle 'Zakres grup najwyższego poziomu' -AllowDomainRoot -Remember 'Ou'
    Add-Label -Parent $row2 -Text 'Gdy na liście nie zaznaczono grup: wszystkie grupy, które nie należą do innych grup.' -Hint | Out-Null
    $m.Actions.Build = {
        param($m)
        $roots = @(Get-TargetGroups -Quiet)
        $up = ((Get-SegmentIndex $m.Direction) -eq 1)
        if ($roots.Count -eq 0) {
            if ($up) { Show-Warning 'Dla kierunku «w górę» zaznacz grupy na liście po lewej.'; return }
            $scope = if ($m.Ou.Text.Trim()) { $m.Ou.Text.Trim() } else { 'całej domeny' }
            if (-not (Confirm-Action -Text "Na liście nie zaznaczono grup. Zbudować drzewo wszystkich grup najwyższego poziomu z ${scope}? Przy dużej domenie może to potrwać." -ConfirmText 'Buduj drzewo')) { return }
        }
        $params = @{ Roots = $roots; Up = $up; ShowMembers = ((Test-Checked $m.ShowMembers) -and -not $up); ShowDescription = (Test-Checked $m.ShowDesc); MaxDepth = (Get-Num $m.Depth); SearchBase = $m.Ou.Text.Trim() }
        Start-AdOperation -Module $m -Name 'Drzewo grup' -Targets @('AD') -Parameters $params -ScriptBlock $script:GroupTreeScript -OnComplete {
            param($m)
            $rows = @(Get-ResultRowsAll -Module $m)
            $cycles = @($rows | Where-Object { [string](Get-ObjectValue $_ 'Uwagi') -like 'Zapętlenie*' }).Count
            Set-StatTile -Module $m -Key 'roots' -Value ([string]@($rows | Where-Object { [string](Get-ObjectValue $_ 'Poziom') -eq '0' }).Count)
            Set-StatTile -Module $m -Key 'rows' -Value ([string]$rows.Count)
            $maxLevel = 0
            foreach ($r in $rows) { $lv = Get-ObjectValue $r 'Poziom'; if ($null -ne $lv -and [int]$lv -gt $maxLevel) { $maxLevel = [int]$lv } }
            Set-StatTile -Module $m -Key 'depth' -Value ([string]$maxLevel)
            Set-StatTile -Module $m -Key 'cycles' -Value ([string]$cycles) -Tone $(if ($cycles) { 'crit' } else { 'ok' })
        }
    }
    $row3 = Add-ToolbarRow -Module $m -Title 'Akcje'
    Add-Button -Parent $row3 -Text 'Buduj drzewo' -Icon 'E8EC' -Module $m -Primary -OnClick $m.Actions.Build | Out-Null
    Add-Button -Parent $row3 -Text 'Raport HTML…' -Icon 'E8A5' -Module $m -OnClick { param($m) Export-GroupTreeHtml -Module $m } | Out-Null
    Add-RowAction -Module $m -Text 'Zaznacz grupy na liście' -Icon 'E8B3' -Action {
        param($m, $rows)
        $groups = @($rows | Where-Object { [string](Get-ObjectValue $_ 'Typ') -eq 'Grupa' } | ForEach-Object { [string](Get-ObjectValue $_ 'Login') } | Where-Object { $_ } | Select-Object -Unique)
        if ($groups.Count -eq 0) { Show-Warning 'Wybierz wiersze z grupami.'; return }
        Set-TargetCheck -Panel $script:UI.GroupPanel -Mode UncheckAll
        Add-GroupNames -Module $script:UI.Modules['__groups'] -Names $groups -Source 'drzewo'
    }
    Add-RowAction -Module $m -Text 'Kopiuj ścieżkę' -Icon 'E8C8' -Action {
        param($m, $rows)
        Set-ClipboardText ((@($rows | ForEach-Object { [string](Get-ObjectValue $_ 'Ścieżka') })) -join [Environment]::NewLine)
        Show-Toast 'Skopiowano ścieżki.' 'ok'
    }
    Add-StatTile -Module $m -Key 'roots' -Label 'Grupy główne' -Icon 'E902' | Out-Null
    Add-StatTile -Module $m -Key 'rows' -Label 'Węzły drzewa' -Icon 'E8EC' | Out-Null
    Add-StatTile -Module $m -Key 'depth' -Label 'Największa głębokość' -Icon 'E74A' | Out-Null
    Add-StatTile -Module $m -Key 'cycles' -Label 'Zapętlenia' -Icon 'E7BA' | Out-Null
    $m.EmptyHint = 'Zaznacz grupy po lewej (albo żadnej – grupy najwyższego poziomu) i kliknij «Buduj drzewo» (F5). Sortowanie kolumn zmienia kolejność – raport HTML zawsze zachowuje układ drzewa.'
}

$script:GroupReports = @(
    @{ Key = 'Empty'; Name = 'Puste grupy (bez członków)' }
    @{ Key = 'Single'; Name = 'Grupy z jednym członkiem' }
    @{ Key = 'Large'; Name = 'Duże grupy (co najmniej N członków)' }
    @{ Key = 'NoDescription'; Name = 'Grupy bez opisu' }
    @{ Key = 'NoManager'; Name = 'Grupy bez zarządcy' }
    @{ Key = 'Disabled'; Name = 'Grupy z wyłączonymi kontami' }
    @{ Key = 'Privileged'; Name = 'Grupy uprzywilejowane (adminCount = 1)' }
    @{ Key = 'Distribution'; Name = 'Grupy dystrybucyjne' }
    @{ Key = 'Created'; Name = 'Utworzone w ciągu N dni' }
    @{ Key = 'Changed'; Name = 'Zmienione w ciągu N dni' }
    @{ Key = 'Cycles'; Name = 'Zapętlone zagnieżdżenia' }
)

Register-Module -Workspace 'AdGroups' -Category 'Raporty' -Key 'GroupReports' -Title 'Raporty grup' -Icon 'E9F9' -Badge 'nowe' `
    -Description 'Zestawienia grup z domeny lub jednostki: puste, z jednym członkiem, duże, bez opisu lub zarządcy, z wyłączonymi kontami, uprzywilejowane, dystrybucyjne, nowe i zmienione oraz zapętlone zagnieżdżenia. Wyniki można zaznaczyć na liście grup.' -Build {
    param($m)
    $m.PillColumns = @('Typ')
    $row = Add-ToolbarRow -Module $m -Title 'Raport'
    $m.Report = Add-ComboBox -Parent $row -Items @($script:GroupReports | ForEach-Object { $_.Name }) -Width 340
    Add-Label -Parent $row -Text 'N' | Out-Null
    $m.N = Add-Numeric -Parent $row -Value 30 -Minimum 1 -Maximum 100000 -Width 80
    $m.N.ToolTip = 'Liczba dni (nowe/zmienione) albo liczba członków (duże grupy)'
    $row2 = Add-ToolbarRow -Module $m -Title 'Zakres'
    $m.Ou = Add-OuField -Parent $row2 -Module $m -Width 420 -Placeholder 'Cała domena' -DialogTitle 'Zakres raportu' -AllowDomainRoot -Remember 'Ou'
    Add-Button -Parent $row2 -Text 'Generuj raport' -Icon 'E9F9' -Module $m -Primary -OnClick {
        param($m)
        $report = $script:GroupReports[$m.Report.SelectedIndex]
        $params = @{ Report = $report.Key; N = (Get-Num $m.N); SearchBase = $m.Ou.Text.Trim(); Protected = @($script:Settings.ProtectedGroups) }
        Start-AdOperation -Module $m -Name $report.Name -Targets @('AD') -Parameters $params -ScriptBlock {
            $now = Get-Date
            $base = '(objectCategory=group)'
            $gen = $now.AddDays( - [int]$P.N).ToUniversalTime().ToString('yyyyMMddHHmmss.0Z')
            $extra = switch ($P.Report) {
                'Empty' { '(!(member=*))' }
                'NoDescription' { '(!(description=*))' }
                'NoManager' { '(!(managedBy=*))' }
                'Privileged' { '(adminCount=1)' }
                'Distribution' { '(!(groupType:1.2.840.113556.1.4.803:=2147483648))' }
                'Created' { "(whenCreated>=$gen)" }
                'Changed' { "(whenChanged>=$gen)" }
                default { '' }
            }
            $q = @{ LDAPFilter = "(&$base$extra)"; Properties = @('Description', 'member', 'memberOf', 'managedBy', 'mail', 'whenCreated', 'whenChanged', 'adminCount', 'isCriticalSystemObject') }
            if ($P.SearchBase) { $q.SearchBase = $P.SearchBase }
            $groups = @(Get-ADGroup @q @ad)
            $notes = @{}
            switch ($P.Report) {
                'Single' { $groups = @($groups | Where-Object { @($_.member).Count -eq 1 }) }
                'Large' { $groups = @($groups | Where-Object { @($_.member).Count -ge [int]$P.N } | Sort-Object { @($_.member).Count } -Descending) }
                'Disabled' {
                    $counts = @{}
                    foreach ($u in @(Get-ADObject -LDAPFilter '(&(|(objectClass=user)(objectClass=computer))(userAccountControl:1.2.840.113556.1.4.803:=2))' -Properties memberOf @ad)) {
                        foreach ($g in @($u.memberOf)) { $k = ([string]$g).ToLowerInvariant(); $counts[$k] = 1 + [int]$counts[$k] }
                    }
                    $groups = @($groups | Where-Object { $counts.ContainsKey(([string]$_.DistinguishedName).ToLowerInvariant()) })
                    foreach ($g in $groups) { $notes[[string]$g.DistinguishedName] = 'wyłączonych kont: ' + $counts[([string]$g.DistinguishedName).ToLowerInvariant()] }
                }
                'Empty' {
                    # Grupy podstawowe (Domain Users itp.) mają członków przez primaryGroupID, nie przez atrybut member
                    $groups = @($groups | Where-Object { @(513, 514, 515, 516, 521) -notcontains [int](([string]$_.SID.Value) -split '-')[-1] })
                    foreach ($g in $groups) { if ($g.isCriticalSystemObject) { $notes[[string]$g.DistinguishedName] = 'grupa systemowa' } }
                }
                'Cycles' {
                    $parents = @{}
                    foreach ($g in $groups) { $parents[([string]$g.DistinguishedName).ToLowerInvariant()] = @($g.memberOf | ForEach-Object { ([string]$_).ToLowerInvariant() }) }
                    $inCycle = @{}
                    foreach ($start in @($parents.Keys)) {
                        $stack = New-Object System.Collections.Stack
                        $stack.Push(@($start, @($start)))
                        $seen = @{}
                        while ($stack.Count -gt 0) {
                            $cur = $stack.Pop()
                            foreach ($p in @($parents[$cur[0]])) {
                                if ($p -eq $start) { $inCycle[$start] = ((@($cur[1]) + @($p)) | ForEach-Object { Get-DnName $_ }) -join ' › '; break }
                                if (-not $seen.ContainsKey($p) -and $parents.ContainsKey($p)) { $seen[$p] = $true; $stack.Push(@($p, (@($cur[1]) + @($p)))) }
                            }
                            if ($inCycle.ContainsKey($start)) { break }
                        }
                    }
                    $groups = @($groups | Where-Object { $inCycle.ContainsKey(([string]$_.DistinguishedName).ToLowerInvariant()) })
                    foreach ($g in $groups) { $notes[[string]$g.DistinguishedName] = $inCycle[([string]$g.DistinguishedName).ToLowerInvariant()] }
                }
            }
            foreach ($g in ($groups | Sort-Object Name)) {
                [pscustomobject][ordered]@{
                    'Grupa'          = $g.SamAccountName
                    'Nazwa'          = $g.Name
                    'Zakres'         = Get-ScopeLabel $g.GroupScope
                    'Typ'            = Get-CategoryLabel $g.GroupCategory
                    'Członków'       = @($g.member).Count
                    'Należy do grup' = @($g.memberOf).Count
                    'Opis'           = $g.Description
                    'Zarządca'       = $(if ($g.managedBy) { Get-DnName $g.managedBy } else { '' })
                    'E-mail'         = $g.mail
                    'Utworzono'      = $g.whenCreated
                    'Zmieniono'      = $g.whenChanged
                    'Uwagi'          = [string]$notes[[string]$g.DistinguishedName]
                    'Jednostka OU'   = Get-DnParent $g.DistinguishedName
                    'DN'             = $g.DistinguishedName
                    '__tone'         = $(if ([string]$g.GroupCategory -eq 'Security') { 'info' } else { '' })
                }
            }
        } -OnComplete {
            param($m)
            $rows = @(Get-ResultRowsAll -Module $m | Where-Object { [string](Get-ObjectValue $_ 'Status') -ne 'Błąd' })
            Set-StatTile -Module $m -Key 'count' -Value ([string]$rows.Count) -Tone $(if ($rows.Count) { 'warn' } else { 'ok' })
            $members = 0
            foreach ($r in $rows) { $v = Get-ObjectValue $r 'Członków'; if ($null -ne $v) { $members += [int]$v } }
            Set-StatTile -Module $m -Key 'members' -Value ([string]$members)
            Set-StatTile -Module $m -Key 'security' -Value ([string]@($rows | Where-Object { [string](Get-ObjectValue $_ 'Typ') -eq 'Zabezpieczeń' }).Count)
        }
    } | Out-Null
    $row3 = Add-ToolbarRow -Module $m -Title 'Wyniki'
    Add-Button -Parent $row3 -Text 'Zaznacz na liście grup' -Icon 'E8B3' -Module $m -AlwaysEnabled -ToolTip 'Zaznaczone wiersze (albo wszystkie widoczne) trafią na listę grup po lewej – zaznaczone do dalszych operacji' -OnClick {
        param($m)
        Add-ResultsToTargets -Module $m -Kind Group -Column 'Grupa'
    } | Out-Null
    Add-RowAction -Module $m -Text 'Zaznacz na liście grup' -Icon 'E8B3' -Action { param($m, $rows) Add-ResultsToTargets -Module $m -Kind Group -Column 'Grupa' -Rows $rows }
    Add-RowAction -Module $m -Text 'Zmień opis…' -Icon 'E70F' -Separator -Action { param($m, $rows) Invoke-GroupChange -Module $m -Op 'Description' -Rows $rows }
    Add-RowAction -Module $m -Text 'Usuń grupy' -Icon 'E74D' -Danger -Action { param($m, $rows) Invoke-GroupChange -Module $m -Op 'Delete' -Rows $rows }
    Add-StatTile -Module $m -Key 'count' -Label 'Grupy w raporcie' -Icon 'E902' | Out-Null
    Add-StatTile -Module $m -Key 'members' -Label 'Członkowie (suma)' -Icon 'E716' | Out-Null
    Add-StatTile -Module $m -Key 'security' -Label 'Grupy zabezpieczeń' -Icon 'E72E' | Out-Null
    $m.EmptyHint = 'Wybierz raport i kliknij «Generuj raport» (F5). Nie trzeba zaznaczać grup na liście.'
}
#endregion

#region Użytkownicy AD: tworzenie kont (profile, podgląd z edycją, sprawdzenie w AD, utworzenie, synchronizacja Entra ID)
